window.JASTROW_CHUNKS[79]={"31600":{"h":"שָׁלֵם ²","r":"U01352","html":"<div class=\"sense\">; pl. <span dir=\"rtl\">שַׁלְמִין</span>; <span dir=\"rtl\">שַׁלְמַן</span>, v. <a href=\"#\" data-headword=\"שְׁלִים\">שְׁלִים</a>.</div>","alt":["שְׁלֵמָא"]},"31601":{"h":"שַׁלָּמָא","r":"U01353","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁלְמָנָא\">שַׁלמָנָא</a></div>","alt":[]},"31602":{"h":"שַׁלְמָאָה","r":"U01354","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Shalmaite</i>, an Arabic tribe. <span class=\"citation\">Targ. O. Num. XXIV, 21</span> (Y. <a href=\"#\" data-headword=\"שַׁלְמָיָא\">שַׁלְמַיָּא</a>, read: <span dir=\"rtl\">מָיָא …</span>; h. text <span dir=\"rtl\">קיני</span>). <span class=\"citation\">Targ. I Sam. XV, 6</span>. <span class=\"citation\">Targ. Jud. IV, 17</span>; a. e.—Y. Shebi. VI, 36ᵇ bot. (= <span dir=\"rtl\">קנזי</span>, <span class=\"citation\">Gen. XV, 19</span>); <span class=\"citation\">Y. Kidd. I, 61ᵈ</span> top <a href=\"#\" data-headword=\"שמלאי\">שמלאי</a> (corr. acc.; = <span dir=\"rtl\">קיני</span>); <span class=\"citation\">Gen. R. s. 44</span> (= <span dir=\"rtl\">קנזי</span>); <span class=\"citation\">B. Bath. 56ᵃ</span> (= <span dir=\"rtl\">קדמני</span>).—Pl. <span dir=\"rtl\">שַׁלְמָאֵי</span>. <span class=\"citation\">Targ. O. Gen. XV, 19</span> (h. text <span dir=\"rtl\">הקיני</span>; Y. <a href=\"#\" data-headword=\"שַׁלְמָיָא\">שַׁלְמַיָּא</a>, read: <a href=\"#\" data-headword=\"שַׁלְמָיָא\">שַׁלְמָיָא</a> <i>sing</i>.).</div>","alt":["שַׁלְמָיָיא"]},"31603":{"h":"שַׂלְמָה","r":"U01355","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"שִׂמְלָה\">שִׂמְלָה</a>) <i>cloak, garment</i>. <span class=\"citation\">Gen. R. s. 3</span> <span dir=\"rtl\">נתעטף בה הקב&quot;ה כש׳</span> the Lord wrapped himself in it (the light) as in a cloak; <span class=\"citation\">Yalk. Ps. 862</span> <span dir=\"rtl\">נתעטף הקב&quot;ה בשמלה</span>; <span class=\"citation\">Ex. R. s. 50</span>. <span class=\"citation\">Snh. 102ᵃ</span>; a. fr.</div>","alt":[]},"31604":{"h":"שְׁלֹמֹה","r":"U01356","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Solomon</i>, king of Israel. <span class=\"citation\">Ber. 10ᵃ</span> <span dir=\"rtl\">כנגד מי אמר ש׳ וכ׳</span> with reference to whom did Solomon say that verse (<span class=\"citation\">Prov. XXXI, 26</span>)? <span class=\"citation\">Snh. 20ᵇ</span> בתחלה מלך ש׳ על העליונים וכ׳ Solomon ruled first over those on high &amp;c. Y. ib. II, 20ᶜ <span dir=\"rtl\">ירד מלאך … ש׳ וכ׳</span> an angel came down in the image of S. and made him rise from his throne &amp;c.; <span class=\"citation\">Koh. R. to II, 2</span>. <span class=\"citation\">Pes. 36ᵇ</span> <span dir=\"rtl\">אפי׳ כמצות של ש׳</span> even unleavened cakes like those of Solomon (of the finest flour) may be used on the Passover; Y. ib. II, 29ᵇ bot. <span dir=\"rtl\">מצה שלמה</span> (insert <span dir=\"rtl\">של</span>, or read: <a href=\"#\" data-headword=\"מָצַת\">מַצַּת</a>).</div>","alt":[]},"31605":{"h":"שַׁלְמוּתָא","r":"U01357","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁלִימוּתָא\">שְׁלֵימוּתָא</a></div>","alt":[]},"31606":{"h":"שֶׁלֶמְיָא","r":"U01358","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Shelemia</i>, father of <span dir=\"rtl\">חיננא</span>. <span class=\"citation\">B. Bath. 111ᵃ</span></div>","alt":[]},"31607":{"h":"שַׁלְמָיָא","r":"U01359","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁלְמָאָה\">שַׁלְמָאָה</a></div>","alt":["שַׁלְמָיָיא"]},"31608":{"h":"שְׁלָמִים","r":"U01360","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"שָׁלוֹם I\">שָׁלוֹם</a>; sub. <span dir=\"rtl\">זבח</span>) <i>peace-offering</i>. Sifra Vayikra, N’dabah, Par. 13, ch. XVI, v. <a href=\"#\" data-headword=\"שָׁלֵם II\"><span dir=\"rtl\">שָׁלֵם</span> II</a>. <span class=\"citation\">Zeb. I, 2</span> <span dir=\"rtl\">שׂשחטן לשם ש׳</span> which were killed as peace-offerings. <span class=\"citation\">Ib. V, 5</span> <span dir=\"rtl\">זבחי שַׁלְמֵי ציבור</span> congregational peace-offerings; a. v. fr.</div>","alt":[]},"31609":{"h":"שַׁלְמָנָא","r":"U01361","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁלֵים\">שְׁלֵם</a>) <i>perfect, righteous, honest</i>. <span class=\"citation\">Snh. 7ᵃ</span>, v. <a href=\"#\" data-headword=\"בֵּיר\">בֵּיר</a>; <span class=\"citation\">Yalk. Prov. 960</span>. <span class=\"citation\">Snh. 22ᵃ</span> בש׳ נקיט Ms. M. (ed. <span dir=\"rtl\">לשַׁלָּמָא</span>), v. <a href=\"#\" data-headword=\"גַּנָּבָא\">גַּנָּבָא</a>; <span class=\"citation\">Yalk. Kings 166</span> <a href=\"#\" data-headword=\"בִּשְׁלָמָא\">בשלמא</a>.</div>","alt":[]},"31610":{"h":"שְׁלַמְצָה","r":"U01362","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"> (abbrev. of <span dir=\"rtl\">שלם ציון</span>) <i>Sh’lamtsa, Sh’lamtsu</i> (Salome Alexandra), wife and successor of king Alexander Jannai. <span class=\"citation\">Lev. R. s. 35</span>; Sifra B’huck. ch. I; <span class=\"citation\">Taan. 23ᵃ</span> quoted in Tosaf. to <span class=\"citation\">Sabb. 16ᵇ</span> <a href=\"#\" data-headword=\"שַׁל ²\">של ציון</a>. <span class=\"citation\">Sabb. 16ᵇ</span> <a href=\"#\" data-headword=\"שַׁל ²\">של ציון</a> (Ms. M. <a href=\"#\" data-headword=\"שַׁלְצִיּוֹן\">שלציון</a>, in one wd.). <span class=\"citation\">Koh. R. to VII, 11</span> <a href=\"#\" data-headword=\"שלמתו\">שלמתו</a> (corr. acc.).</div>","alt":["שְׁלַמְצוּ"]},"31611":{"h":"שְׁלֵמְתָּא","r":"U01363","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁלִים\">שְׁלִים</a>, <a href=\"#\" data-headword=\"שְׁלִימוּתָא\"><a href=\"#\" data-headword=\"שְׁלִימוּתָא\">שְׁלֵימוּתָא</a>.</a></div>","alt":["שְׁלֶמְתָּא"]},"31612":{"h":"שלמתו","r":"U01364","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁלַמְצָה\">שְׁלַמְצָה</a></div>","alt":[]},"31613":{"h":"שְׁלָנָא","r":"U01365","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (שְׁלֵי II) <i>thoughtless, unsuspecting</i>. <span class=\"citation\">Targ. Jud. V, 27</span> ed. Ven. I (missing in eds.).</div>","alt":[]},"31614":{"h":"שְׁלַנְיָא","r":"U01366","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Sh’lanya</i> in Babylonia. <span class=\"citation\">M. Kat. 12ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"שׁילִינְיָא\">שִׁילִינְיָא</a>).</div>","alt":["שְׁלַנְיָיא"]},"31615":{"h":"שֶׁלַע","r":"U01367","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שֶׁלַע\">שלע</a> = <span dir=\"rtl\">שלו</span>; v. letter <a href=\"#\" data-headword=\"ו\">ו</a>) <i>sediment</i>; <span dir=\"rtl\">ש׳ טיט</span> <i>muddy alluvium</i>. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> <a href=\"#\" data-headword=\"שלעטוט\">שלעטיט</a> (some ed. <a href=\"#\" data-headword=\"שלעטוט\">שלעטוט</a>, corr. acc.). V. <a href=\"#\" data-headword=\"שֵׂרָטוֹן\">שֵׂרָטוֹן</a>.</div>","alt":[]},"31616":{"h":"שלעטוט","r":"U01368","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שֶׁלַע\">preced.</a></div>","alt":["שֶׁלַעְטִיט"]},"31617":{"h":"שלעל","r":"U01369","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ḥull. I, 15</span> <span dir=\"rtl\">מששלעלו</span>, v. <span dir=\"rtl\">עִלְעֵל II</span></div>","alt":[]},"31618":{"h":"שָׁלַף","r":"U01370","html":"<div class=\"sense\"><b>1)</b> <i>to be lax, hang down, be loose, slip</i>. Denom. <a href=\"#\" data-headword=\"שָׁלִיף\">שָׁלִיף</a>.</div><div class=\"sense\"><b>—2)</b> <i>to loosen, take off, pull, draw a sword</i>. <span class=\"citation\">Lev. R. s. 34</span> יִשְׁלוֹף Ar. (ed. <span dir=\"rtl\">ישמוט</span>) may he loosen (release), v. <a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a>. <span class=\"citation\">Y. Kidd. I, 60ᶜ</span> top (ref. to <span class=\"citation\">Ruth IV, 7</span>) <span dir=\"rtl\">מי ש׳</span> which took the shoe off (the buyer or the seller)? <span class=\"citation\">Num. R. s. 14</span><sup>4</sup> <span dir=\"rtl\">מסמר … נוח לִשְׁלוֹף</span> a nail with a big head is easily pulled; <span class=\"citation\">Pesik. R. s. 3</span>. <span class=\"citation\">Midr. Till. to Ps. CXX</span> <span dir=\"rtl\">אם יִשְׁלוֹף האדם וכ׳</span> if a man draws the sword which he has in his hand to slay his neighbor &amp;c.; a. e.</div><div class=\"sense\"><b>Nif. נִשְׁלַף</b> <div class=\"sense\"><i>to be loosened, drawn</i>. <span class=\"citation\">Gen. R. s. 93</span>; <span class=\"citation\">Yalk. ib. 150</span> <span dir=\"rtl\">ואינה נִשְׁלֶפֶת</span>, v. <a href=\"#\" data-headword=\"תַּעַר\">תַּעַר</a>.</div></div><div class=\"sense\"><b>Hif. הִשְׁלִיף</b> <div class=\"sense\"><i>to pull, pluck the last growth</i>. <span class=\"citation\">Gen. R. s. 20</span>; <span class=\"citation\">Yalk. ib. 32</span> <span dir=\"rtl\">על … שאדם מַשְׁלִיף שדהו אוכלה וכ׳</span> this (<span class=\"citation\">Gen. III, 18</span>) was said with reference to these days, when one plucks his field over and again and eats it (the aftermath) &amp;c., v. <span class=\"citation\">Pes. 118ᵃ</span></div></div>","alt":[]},"31619":{"h":"שְׁלַף","r":"U01371","html":"<div class=\"sense\">, <i>to loosen, pull, draw</i>. <span class=\"citation\">Targ. Hos. IV, 11</span>. <span class=\"citation\">Targ. Y. Num. XXXI, 8</span>. <span class=\"citation\">Targ. Jud. III, 22</span>. <span class=\"citation\">Targ. Y. Ex. III, 5</span>; a. fr.—<span class=\"citation\">Targ. I Chr. I, 20</span> (play on <span dir=\"rtl\">שלף</span>, ib.) <span dir=\"rtl\">ש׳ … לתחומיה</span> (not <span dir=\"rtl\">לתחומיא</span>) he drew the rivers into his domain.—Part. pass. <a href=\"#\" data-headword=\"שְׁלִיף\">שְׁלִיף</a>. <span class=\"citation\">Targ. Y. I Deut. XXV, 10</span> (Y. II שְׁלוּפֵי Hebraism, pl., h. text <a href=\"#\" data-headword=\"חִלּוּץ\">חלוץ</a>).—V. <a href=\"#\" data-headword=\"שְׁלִיף ²\"><span dir=\"rtl\">שְׁלִיף</span> II</a>.—<span class=\"citation\">Yeb. 102ᵇ</span> <span dir=\"rtl\">ממאי דהאי וחלצה … מִישְׁלַף הוא</span> how do we know that this <i>v’ḥal’tsah</i> (<span class=\"citation\">Deut. XXV, 9</span>) means taking off? Y. ib. XII, 13ᵃ top <span dir=\"rtl\">ושַׁלְפַת סיניה</span> and she took off his shoe. <span class=\"citation\">Sabb. 59ᵇ</span> <span dir=\"rtl\">דילמא שָׁלְפָא וכ׳</span> she might take off (her jewelry) and show it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מְשַׁלְּפָא</span> (<i>Pa.</i>). <span class=\"citation\">Ib. 82ᵃ</span> <span dir=\"rtl\">ולא שליף ירקא וכ׳</span> and that no vegetable will be pulled, and eaten by you, out of the bunch &amp;c. <span class=\"citation\">Shebu. 31ᵃ</span> <span dir=\"rtl\">שְׁלוֹפוּ</span>, v. <a href=\"#\" data-headword=\"פּוּזְמְקֵי\">פּוּזְמְקֵי</a>. <span class=\"citation\">Erub. 11ᵇ</span> <span dir=\"rtl\">זיל שְׁלוֹף וכ׳</span> go and pull (the reeds) out, and throw them away; a. fr.—Trnsf. (cmp. <a href=\"#\" data-headword=\"נָתַר I\">נתר</a>, <a href=\"#\" data-headword=\"שרי\">שרי</a>) <i>to untie, annul</i>. <span class=\"citation\">Gitt. 33ᵇ</span> <span dir=\"rtl\">מילתא … למִישְׁלְפָהּ</span> an act performed in the presence of ten persons, requires ten for revoking it; a. e.—<span class=\"citation\">Yeb. 109ᵇ</span> <span dir=\"rtl\">ערבי שלציון דעבדי שְׁלוֹף דוץ</span> the guarantors of Shaltsiyon, where they practice ‘pull and stick in’, release the debtor and seize the guarantor.—<span class=\"citation\">Sabb. 90ᵃ</span>, a. e. <span dir=\"rtl\">שלוף דוץ</span>, v. <a href=\"#\" data-headword=\"שְׁלוֹף\">שְׁלוֹף</a>.—[<span class=\"citation\">Sabb. 98ᵇ</span>; Yalk. Ex. 370, v. <a href=\"#\" data-headword=\"שַׁלְחֵף\">שַׁלְחֵף</a>.]</div><div class=\"sense\"><b>Pa. שַׁלֵּיף</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"שָׁלַף\">same</a>. <span class=\"citation\">Targ. O. Lev. XIV, 40</span> (h. text <span dir=\"rtl\">חלץ</span>). <span class=\"citation\">Ib. 43</span> (some ed. <i>Pe.</i>).—<span class=\"citation\">Yeb. 102ᵇ</span> (ref. to <span dir=\"rtl\">החלצו</span>, <span class=\"citation\">Num. XXXI, 3</span>) <span dir=\"rtl\">שַׁלּוּפֵי מביתא וכ׳</span> it means tearing away from home to war. <span class=\"citation\">M. Kat. 4ᵇ</span>, v. <a href=\"#\" data-headword=\"דָּלַל\">דָּלַל</a>. <span class=\"citation\">Sabb. 59ᵇ</span>, v. supra; a. e.</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתַּלֵּיף</b> </div><div class=\"sense\"><b>Ithpe. אִשְׁתְּלִיף</b> <div class=\"sense\"><i>to be drawn; to be loosened, to slip</i>. <span class=\"citation\">Targ. Ez. XXI, 15</span> (h. text <span dir=\"rtl\">הוחדה</span>). <span class=\"citation\">Targ. II Kings VI, 5</span>. <span class=\"citation\">Targ. Is. XXXIII, 20</span> (h. text <span dir=\"rtl\">יסע</span>); a. e.</div></div>","alt":[]},"31620":{"h":"שֶׁלֶף","r":"U01372","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁלַף\">preced.</a>) [<i>that which is pulled out,</i>] <i>stubble field</i>. <span class=\"citation\">Tosef. B. Mets. IX, 29</span> <span dir=\"rtl\">אינו … נירה למניחה לפניו ש׳</span> it is not the same when he surrenders the land tilled (cleared), as when he surrenders it with the stubbles.—Pl. <a href=\"#\" data-headword=\"שְׁלָמִים\">שְׁלָפִים</a>. <span class=\"citation\">Cant. R. to VI, 12</span> <span dir=\"rtl\">מלקטת בש׳</span> picked up (ears) among the stubbles.—Trnsf. constr. <a href=\"#\" data-headword=\"שִׁלְפֵי\">שִׁלְפֵי</a>, <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁי׳</a> <i>the end</i> of a period. <span class=\"citation\">Yeb. 116ᵇ</span> <span dir=\"rtl\">ש׳ קציר חטים היו</span> it was towards the end of the wheat harvest. <span class=\"citation\">Sabb. 60ᵃ</span> <span dir=\"rtl\">ש׳ הגזירה היו</span> (Ar. <a href=\"#\" data-headword=\"הַשְׁמֵד\">השמד</a>; Ms. M. <span dir=\"rtl\">שליפי</span>, corr. acc.; Ms. O. <a href=\"#\" data-headword=\"שַׁלְהֵי I\">שלהי</a>, v. Rabb. D. S. a. l. note) it was the end of the period of persecution; <span class=\"citation\">Cant. R. to II, 5</span> <span dir=\"rtl\">בש׳ השמד</span>.</div>","alt":[]},"31621":{"h":"שִׁלְפּוּחָא","r":"U01373","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁילְפּוּחָא\">שִׁילְפּוּחָא</a></div>","alt":[]},"31622":{"h":"שלפוחות","r":"U01374","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁלְפּוּחִית\">next w.</a></div>","alt":[]},"31623":{"h":"שַׁלְפּוּחִית","r":"U01375","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Shaf. of <span dir=\"rtl\">נ־פח</span>, with anorg. <a href=\"#\" data-headword=\"ל\">ל</a>) [<i>a saclike </i><i>organ</i>,] </div><div class=\"sense\"><b>1)</b> <i>womb</i>. <span class=\"citation\">Ḥull. 55ᵇ</span>, v. <a href=\"#\" data-headword=\"טַרְפַּחַת\">טַרְפַּחַת</a>. <span class=\"citation\">Ib. 48ᵃ</span> top; <span class=\"citation\">Tosef. ib. III, 10</span> <a href=\"#\" data-headword=\"שלפוחות\">שלפוחות</a> (corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>the</i> (<i>bladderlike</i>) <i>gullet of a bird</i>. Pesik. Vattom., p. 132ᵇ מביאה ש׳ של תרנגולת וכ׳ Ar. (ed. Bub. <span dir=\"rtl\">שלוט׳</span>, corr. acc.; v. Bub. note 57) she took the gullet of a hen and filled it with balsam &amp;c.; <span class=\"citation\">Lev. R. s. 16</span>, beg. Ar. (ed. <span dir=\"rtl\">שפופרת של ביצה</span>); <span class=\"citation\">Lam. R. to IV, 15</span> <span dir=\"rtl\">זפק</span>; <span class=\"citation\">Yalk. ib. 1032</span> <span dir=\"rtl\">שלחופ׳</span> (corr. acc.).</div>","alt":[]},"31624":{"h":"שַׁלְפּוּפֵי","r":"U01376","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"שָׁלִיף\">שָׁלִיף</a>) [<i>pouch-like buds,</i>] <i>undeveloped dates</i>. <span class=\"citation\">Bekh. 52ᵇ</span> <span dir=\"rtl\">ש׳ והוו תמרי</span> if (at the father’s death) they were <i>shalpufé</i>, and afterwards became full-grown dates; <span class=\"citation\">B. Bath. 124ᵃ</span> <a href=\"#\" data-headword=\"שְׁלוֹפָאפֵי\">שְׁלוֹפָפֵי</a> (Ms. M. <span dir=\"rtl\">שלפפי</span>; Ms. H. <a href=\"#\" data-headword=\"שַׁלְפּוּפֵי\">שַׁלְפּוּפָאֵי</a>; Alf. Ms. <a href=\"#\" data-headword=\"שְׁלוֹפָאפֵי\">שְׁלוֹפָאפֵי</a>; Ms. R. <span dir=\"rtl\">שלחופי</span> = <span dir=\"rtl\">שלפוחי</span>, v. <a href=\"#\" data-headword=\"שַׁלְפּוּחִית\">preced.</a>); <span class=\"citation\">Yalk. Deut. 928</span>.</div>","alt":[]},"31625":{"h":"שַׁלִפּוּקִין","r":"U01377","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁלְבּוּקִין\">שַׁלְבּוּקִין</a></div>","alt":[]},"31626":{"h":"שִׁלְפֵי","r":"U01378","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שֶׁלֶף\">שֶׁלֶף</a></div>","alt":[]},"31627":{"h":"שַׁלְצִיּוֹן","r":"U01379","html":"<div class=\"sense\"> (abbrev. of <span dir=\"rtl\">שלום ציון</span>) </div><div class=\"sense\"><b>1)</b>  pr. n. f. <i>Shaltsiyon, Salome Alexandra</i>, v. <a href=\"#\" data-headword=\"שְׁלַמְצָה\">שְׁלַמְצָה</a>.</div><div class=\"sense\"><b>—2)</b>  (supposed to be) pr. n. pl. <i>Shaltsiyon</i>. <span class=\"citation\">Yeb. 109ᵇ</span>, v. <a href=\"#\" data-headword=\"שְׁלַף\">שְׁלַף</a>.—[</div><div class=\"sense\"><b>3)</b>  surname of Ḥama bar Ada, an habitual pilgrim to Palestine (cmp. <span class=\"citation\">Ps. CXXII, 6</span>). <span class=\"citation\">Bets. 25ᵇ</span> Ar. (ed. <span dir=\"rtl\">שליח ציון</span> a messenger to Zion)].</div>","alt":[]},"31628":{"h":"שָׁלַק","r":"U01380","html":"<div class=\"sense\"> (Shaf. of <span dir=\"rtl\">חלק</span>, as <span dir=\"rtl\">שנק</span> of <span dir=\"rtl\">חנק</span>) </div><div class=\"sense\"><b>1)</b>  (cmp. Assyr. <span dir=\"rtl\">שלק</span>, Del. Assyr. Handw. 666) <i>to dissect</i>. <span class=\"citation\">Bekh. 45ᵃ</span> <span dir=\"rtl\">מעשה … שׁשָׁלְקוּ זונה וכ׳</span></div><div class=\"sense\"><b>—2)</b>  [<i>to make smooth,</i>] <i>to boil thoroughly, boil to a pulp, seethe</i>. <span class=\"citation\">Maasr. IV, 1</span> <span dir=\"rtl\">הכובש חשׁוֹלֵק וכ׳</span> he who presses, boils, or salts (vegetables, olives &amp;c.) … is bound to give tithes. <span class=\"citation\">Tosef. Bets. II, 15</span> <span dir=\"rtl\">ש׳ הימנו וכ׳</span> if he seethed a small portion of the Passover lamb, contrad. to <a href=\"#\" data-headword=\"בָּשַׁל\">בישל</a>. <span class=\"citation\">Naz. VI, 9</span> (<span class=\"citation\">45ᵇ</span>) <span dir=\"rtl\">היה מבשל … או שׁוֹלְקָן</span> Y. ed. a. Bab. (Mish. ed. <span dir=\"rtl\">שְׁלָקָן</span>) having cooked or seethed the peace-offering; a. fr.—Part. pass. <a href=\"#\" data-headword=\"שָׁלוּק\">שָׁלוּק</a>; f. <span dir=\"rtl\">שְלוּקָה</span>. Y. ib. 55ᶜ top <span dir=\"rtl\">מתני׳ אמרה הש׳ קרוי מבושל</span> this Mishnah indicates that ‘seethed’ is called cooked. <span class=\"citation\">Ned. VI, 1</span> <span dir=\"rtl\">הנודר מן המבושל מותר בצלי ובש׳</span> he who vows abstinence from ‘what is cooked’ is permitted to eat what is roasted or seethed. <span class=\"citation\">Ukts. II, 6</span> <span dir=\"rtl\">ביצה ש׳</span> a hard-boiled egg; <span class=\"citation\">Tosef. ib. II, 15</span>; <span dir=\"rtl\">ביצה ש׳ וביצה טרמיסא</span> (read: <a href=\"#\" data-headword=\"*טְרוֹמִיטָא\">טרומיטא</a>) a hard-boiled egg, or an egg boiled down to a pill, v. <a href=\"#\" data-headword=\"*טְרוֹמִיטָא\">טְרוֹמִיטָא</a>; a. fr.</div><div class=\"sense\"><b>Pi. שִׁילֵּק</b> <div class=\"sense\"><b>1)</b> <i>to make smooth</i>, (of melons) <i>to trim and rub</i>. <span class=\"citation\">Maasr. I, 5</span> <span dir=\"rtl\">אבטיח משׁיְשַׁלֵּק</span> melons are subject to tithes as soon as the gardener trims them; <span dir=\"rtl\">ואם אינו מְשַׁלֵּק וכ׳</span> and if he does not trim them (before storing) &amp;c.; Tosef. ib. I, 6 <span dir=\"rtl\">תורמין … אע&quot;פ שלא ש׳</span> you must give T’rumah of cucumbers and gourds, even if you do not trim them; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to boil</i>. Tanḥ. Bresh. 7 <span dir=\"rtl\">אין לך … ואתה שוקד לשַׁלְּקוֹ וכ׳</span> there is nothing more bitter than the lupine, but thou takest pains to boil and sweeten it &amp;c. Tanḥ. Vaëra 14 <span dir=\"rtl\">נקבץ ונְשַׁלֵּק מהן</span> we will collect them (the locusts) and boil (and preserve) them in casks.</div></div><div class=\"sense\"><b>Nif. נִשְׁלַק</b> <div class=\"sense\"><i>to be boiled</i>. <span class=\"citation\">Neg. XI, 8</span> <span dir=\"rtl\">השתי משׁיִשָּׁלֵק</span> warp is susceptible of uncleanness when it is boiled (Var. <span dir=\"rtl\">משׁיִשָּׁלֶה</span> when it is taken out of the water); Sifra Thazr., Neg., Par. 5, ch. XIII.</div></div>","alt":[]},"31629":{"h":"שְׁלַק","r":"U01381","html":"<div class=\"sense\"><b>1)</b>  (cmp. <span dir=\"rtl\">בשל</span>) <i>to be overheated, blasted</i> (by a hot wind). <span class=\"citation\">Targ. II Kings XIX, 26</span> <span dir=\"rtl\">דִּישְׁלוֹק</span> (not <a href=\"#\" data-headword=\"דִּשְׁתָּאָה\">דְּיִשְׁ׳</a>); <span class=\"citation\">Targ. Is. XXXVII, 27</span> (h. text <span dir=\"rtl\">שדפה</span>).</div><div class=\"sense\"><b>—2)</b> <i>to boil thoroughly</i>. <span class=\"citation\">Y. Ber. VI, 10ᵇ</span> top <span dir=\"rtl\">בההוא דשָׁלֵיק</span> in the case of one that boils (rice), contrad. to <span dir=\"rtl\">דטריף</span>. <span class=\"citation\">Y. Gitt. I, 43ᶜ</span>; <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> top <span dir=\"rtl\">שָׁלְקִין</span>, v. <a href=\"#\" data-headword=\"לְתַת\">לְתַת</a>; a. e.—Part. pass. <span dir=\"rtl\">שָׁלִיק</span>, <a href=\"#\" data-headword=\"שְׁלִיקָה\">שְׁלִיקָא</a>; f. <a href=\"#\" data-headword=\"שְׁלִיקְתָּא\">שְׁלִיקְתָּא</a>. <span class=\"citation\">Ab. Zar. 38ᵇ</span> <span dir=\"rtl\">מישחא ש׳</span> boiled oil. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אהיני שְׁלִיקֵי</span> seethed dates (v. <a href=\"#\" data-headword=\"אֲהִינָא\">אֲהִינָא</a>). <span class=\"citation\">Gitt. 68ᵇ</span>; <span class=\"citation\">Pes. 34ᵃ</span>, v. <a href=\"#\" data-headword=\"סְלַק\">סְלַק</a>.</div>","alt":[]},"31630":{"h":"שֶׁלֶק","r":"U01382","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁלַק\">preced.</a>) <i>seething, overboiled matter</i>. <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> top <span dir=\"rtl\">מי ש׳ של ביצים</span> water in which eggs have been boiled; <span class=\"citation\">Y. Gitt. I, 43ᶜ</span>. <span class=\"citation\">Ber. VI, 8</span> <span dir=\"rtl\">אפי׳ אכל ש׳ וכ׳</span> even if one eats overboiled vegetable, and he makes a meal of it. <span class=\"citation\">Ib. 44ᵇ</span> <span dir=\"rtl\">ומי איכא מידי דהוי ש׳ מזונו</span> (not <span dir=\"rtl\">מזוני</span>) is there a thing which a person makes a meal of when it is boiled to a pulp?; a. e.—Pl. <span dir=\"rtl\">שְׁלָקִין</span>, <a href=\"#\" data-headword=\"שַׁלְקוּת\">שְׁלָקוֹת</a>. <span class=\"citation\">Tosef. Ter. VII, 13</span>; Y, <span class=\"citation\">ib. VIII</span>, 45ᵈ. <span class=\"citation\">Ab. Zar. II, 6</span> <span dir=\"rtl\">ש׳ וכבשין</span> things preserved by boiling or by pressing (by gentiles); a. e.</div>","alt":[]},"31631":{"h":"שלקונדית","r":"U01383","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַלְקוּנְדְרִית\">סַלְקוּנְדְּרִית</a></div>","alt":[]},"31632":{"h":"שַׁלְקוּקַיָּה","r":"U01384","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"שָׁלַק\">שָׁלַק</a><i>Pi.</i>) <i>trimmings, coiled and hairy substances covering gourds</i> &amp;c. <span class=\"citation\">Y. Maasr. I, 49ᵃ</span> (expl. <span dir=\"rtl\">משישלק</span>, ib. I, 5) <span dir=\"rtl\">מאן דו ירים ש׳</span> when he removes the trimmings; cmp. <a href=\"#\" data-headword=\"פַּקְסוּסַיָּה\">פַּקְסוּסַיָּה</a>.</div>","alt":[]},"31633":{"h":"שַׁלְקוּת","r":"U01385","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ben-Shalkuth</i> (<i>Shalḳith</i>). <span class=\"citation\">Nidd. 52ᵇ</span>; <span class=\"citation\">Tosef. ib. VI, 5</span>.</div>","alt":["שַׁלְקִית","בֶּן שַׁ׳"]},"31634":{"h":"שָׁלשׁ","r":"U01386","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁלשָׁה\">שְׁלשָׁה</a></div>","alt":[]},"31635":{"h":"שָׁלַשׁ","r":"U01387","html":"<div class=\"sense\"><b>1)</b> <i>to do</i> or <i>come for the third time</i>. <span class=\"citation\">Num. R. s. 4</span><sup>20</sup> <span dir=\"rtl\">לא יצאת אותה שנה ולא שינתה ולא שִׁילְּשָׁה וכ׳</span> not that year passed, nor the second, nor the third, when &amp;c., i.e. within three years these things occurred; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to go back to the third generation</i>. <span class=\"citation\">B. Bath. X, 7</span> <span dir=\"rtl\">יְשַׁלְּשׁוּ</span> they should write the grandfather’s name in the document.</div><div class=\"sense\"><b>—3)</b> <i>to divide into three parts</i>. Ib. III, 4 <span dir=\"rtl\">מְשַׁלְּשִׁין ביניהם</span> the fine is divided between them (the three sets of witnesses convicted of an alibi); <span class=\"citation\">Macc. I, 3</span>. Ib. <span dir=\"rtl\">משלשין בממון ואין מש׳ במכות</span> the monetary fine is divided, but not the punishment (but every one has to undergo the full punishment). <span class=\"citation\">Ab. Zar. 19ᵇ</span> <span dir=\"rtl\">לעולם יְשַׁלִּשׁ אדם שנותיו שליש וכ׳</span> a man should always divide his years (his time) into three parts, devoting one third to Bible, one to Mishnah &amp;c.; <span class=\"citation\">Kidd. 30ᵃ</span> <span dir=\"rtl\">יַשְׁלִישׁ</span> (<i>Hif.</i>). <span class=\"citation\">Ex. R. s. 15</span><sup>27</sup> הריני מְשַׁלְּשָׁם I will divide them among us three; a. fr.—<i>Part. pass.</i> <a href=\"#\" data-headword=\"מְשׁוּלָּשׁ\">מְשׁוּלָּשׁ</a>; f. <span dir=\"rtl\">מְשׁוּלֶּשֶׁת</span>; pl. <span dir=\"rtl\">מְשׁוּלָּשִׁים</span>, <span dir=\"rtl\">מְשׁוּלָּשִׁין</span>; <span dir=\"rtl\">מְשׁוּלָּשׁוֹת</span> <i>a</i>) <i>done for the third time</i>. Ab. Zar. l. c., <span dir=\"rtl\">כתוב … ומש׳ בכתובים</span> stated in the Torah, a second time in the Prophets, and a third time in Hagiographa; <span class=\"citation\">Meg. 31ᵃ</span>; a. fr.—<i>b</i>) <i>divided into three, arranged in three classes, threefold</i>. <span class=\"citation\">Deut. R. s. 2</span><sup>33</sup> (ref. to <span dir=\"rtl\">והשלשית</span>, <span class=\"citation\">Zech. XIII, 8</span>) <span dir=\"rtl\">אלו ישראל אנקראו שלישין שהם מש׳ וכ׳</span> that means Israel, who are called ‘thirds’, for they are divided into three classes, priests &amp;c. <span class=\"citation\">Midr. Prov. to XXII, 20</span> (ref. to <span dir=\"rtl\">שלשים</span>, ib.) <span dir=\"rtl\">כל מעשי תורה מש׳ היא מש׳ ואותיותיה מש׳ … שבט מש׳ וכ׳</span> all affairs of the Torah are threefold; itself is threefold: Torah, Prophets, and Hagiographa, and its signs are threefold: <a href=\"#\" data-headword=\"אֱמֶת\">אמת</a> (Truth); and it was given through a tribe third in order: Reuben, Shimeon, and Levi; <span dir=\"rtl\">משה מש׳</span> Moses the third born &amp;c. <span class=\"citation\">Cant. R. to I, 1</span> <span dir=\"rtl\">כל מעשיו … מש׳ היו</span> all the events of that man’s (Solomon’s) life were marked by three stages (rise, fall, and rise).—<span class=\"citation\">B. Bath. X, 7</span> <span dir=\"rtl\">ואם היו מש׳</span> and if the names are alike up to the grandfather (v. supra); a. fr.—<span class=\"citation\">Y. Shebi. I, 33ᵇ</span>, v. <a href=\"#\" data-headword=\"מְשׁוּלָּשׁ\">מְשׁוּלָּשׁ</a>.—<i>c</i>) <i>developed to one third of the full growth</i>, v. <a href=\"#\" data-headword=\"מְשׁוּלָּשׁ\">מְשׁוּלָּשׁ</a>.</div><div class=\"sense\"><b>—4)</b>  (apocop. of <a href=\"#\" data-headword=\"שִׁלְשֵׁל\">שִׁלְשֵׁל</a>) <i>to let down</i>, v. <a href=\"#\" data-headword=\"שַׁלְשֵׁל I\"><span dir=\"rtl\">שִׁלְשֵׁל</span> I</a>.</div><div class=\"sense\"><b>Hif. הִשְׁלִישׁ</b> <div class=\"sense\"><b>1)</b> <i>to divide into three parts</i>. Kidd. l. c., v. supra. <span class=\"citation\">B. Mets. 42ᵃ</span> <span dir=\"rtl\">לעולם יַשְׁלִישׁ … שליש וכ׳</span> a man should always have his capital divided into three parts, one-third invested in land, one in merchandise, and one in ready money; <span class=\"citation\">Yalk. Deut. 897</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"שָׁלִישׁ\">שָׁלִישׁ</a>) <i>to deposit</i>. <span class=\"citation\">Keth. VI, 7</span> <span dir=\"rtl\">המַשְׁלִישׁ מעות לבתו … מה שׁהוּשְׁלַשׁ בידו</span> if a father deposits money for the benefit of his daughter, and she says, I trust my husband (and want it to be given to him), the trustee must do that with it for which it was deposited with him; <span class=\"citation\">ib. 69ᵇ</span> <span dir=\"rtl\">המשליש … לחתנו וכ׳</span> if one deposits money with his son-in-law to buy with it &amp;c.; <span class=\"citation\">Tosef. ib. VI, 9</span>; a. e.</div></div><div class=\"sense\"><b>Hof. הוּשְׁלַשׁ</b> <div class=\"sense\"><i>to be deposited</i>, v. supra.</div></div><div class=\"sense\"><b>Nithpa. נִשְׁתַּלֵּשׁ</b> <div class=\"sense\"><i>to have been at a thing for the third time</i>. <span class=\"citation\">Num. R. s. 9</span>, v. <a href=\"#\" data-headword=\"מוּעָד\">מוּעָד</a>.</div></div>","alt":["שִׁלֵּשׁ I"]},"31636":{"h":"שָׁלַשׁ ²","r":"U01388","html":"<div class=\"sense\"><i>to let down, suspend</i>, v. <a href=\"#\" data-headword=\"שַׁלְשֵׁל I\"><span dir=\"rtl\">שִׁלְשֵׁל</span> I</a>.</div>","alt":["שִׁלִּשׁ II"]},"31637":{"h":"שַׁלְשָׁא","r":"U01389","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">שַׁלְשָׁוָון</span>, v. <a href=\"#\" data-headword=\"שַׁלְשֶׁלְתָּא\">שַׁלְשֶׁלְתָּא</a>.</div>","alt":[]},"31638":{"h":"שְׁלשָׁה","r":"U01390","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>three</i>; constr. <a href=\"#\" data-headword=\"שְׁלשֶׁת\">שְׁלשֶׁת</a>; <a href=\"#\" data-headword=\"שָׁלַשׁ\">שְׁלשׁ</a>. <span class=\"citation\">Shebi. IX, 2</span>, v. <a href=\"#\" data-headword=\"אֶרֶץ\">אֶרֶץ</a>. <span class=\"citation\">Erub. 40ᵇ</span>, a. fr. <span dir=\"rtl\">ש׳ רגלים</span>, v. <a href=\"#\" data-headword=\"רֶגֶל\">רֶגֶל</a>. <span class=\"citation\">Ib. 41ᵇ</span> <span dir=\"rtl\">ש׳ דברים מעבירין וכ׳</span>, v. <a href=\"#\" data-headword=\"עָבַר\">עָבַר</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ש׳ אין רואין וכ׳</span> three classes of men will not see the face of Gehenna (having expiated their sins in this world): those afflicted with extreme poverty &amp;c. <span class=\"citation\">R. Hash. 10ᵃ</span>, a. fr. <a href=\"#\" data-headword=\"שַׁלְקוּת\">בן ש׳</a> three years old (in its third year). <span class=\"citation\">Y. Succ. I, end, 52ᶜ</span> <span dir=\"rtl\">שְׁלָשְׁתָּן</span> all three of them. <span class=\"citation\">Ex. R. s. 15</span><sup>27</sup> <span dir=\"rtl\">שְׁלָשְׁתּנוּ</span> all three of us; a. v. fr.—Pl. <a href=\"#\" data-headword=\"שְׁלשִׁית\">שְׁלשִׁים</a> <i>thirty</i>. R. Hash. l. c. <span dir=\"rtl\">בן עשרים … וש׳ יום</span> twenty-four months and thirty days old. <span class=\"citation\">Nidd. 45ᵃ</span> <span dir=\"rtl\">ש׳ יום בשנה וכ׳</span> thirty days of a year count for an entire year; a. v. fr.—Esp. <i>sh’loshim, thirty days of mourning observances for a deceased relative</i>. <span class=\"citation\">M. Kat. 20ᵃ</span> <span dir=\"rtl\">נוהגת שבעה וש׳</span> the laws of mourning observances of seven days and of thirty days apply to it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ישב עליו שבעה וש׳</span> he observed for him <i>shibʿah</i> and <i>sh’loshim</i>; a. fr.</div>","alt":["שָׁלשׁ"]},"31639":{"h":"שִׁלְשׁוּל","r":"U01391","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (שִׁלְשֵׁל I) <i>letting down on a rope</i>. <span class=\"citation\">Erub. 83ᵇ</span> <span dir=\"rtl\">לזה בש׳ ולזה בש׳</span> if both neighbors can use the wall by letting things down; Y. ib. VIII, beg. 25ᵃ; a. e.</div>","alt":["שִׁי׳ I"]},"31640":{"h":"שִׁלְשׁוּל ²","r":"U01392","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (שִׁלְשֵׁל II) <i>forming chains, curls</i>. <span class=\"citation\">Y. Shebi. IV, end, 35ᶜ</span> <span dir=\"rtl\">שִׁילְשׁוּלָן וכ׳</span>, v. <a href=\"#\" data-headword=\"חֶנֶט\">חֶנֶט</a>.</div>","alt":["שִׁי׳ II"]},"31641":{"h":"שִׁלְשׁוּל ³","r":"U01393","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שׁוּל\">שול</a>, cmp. <a href=\"#\" data-headword=\"שַׁבְּלוּל\">שַׁבְּלוּל</a>; v. <a href=\"#\" data-headword=\"שַׁלְשֵׁל III\"><span dir=\"rtl\">שַׁלְשֵׁל</span> III</a>) [<i>slimy substance</i>,] </div><div class=\"sense\"><b>1)</b> <i>slimy abdominal secretion</i>. <span class=\"citation\">Gen. R. s. 51</span>, beg. <span dir=\"rtl\">כש׳ הזה שהוא נמחה בצואה</span> like the secretion which is dissolved in the excrements, v. <a href=\"#\" data-headword=\"כִּילּוּיָא\">כִּילּוּיָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>snail, worm</i>. <span class=\"citation\">R. Hash. 24ᵇ</span> מתחת לרבות ש׳ קטן ‘beneath’ (<span class=\"citation\">Ex. XX, 4</span>) this includes the smallest earth-worms. <span class=\"citation\">Tosef. Ḥull. II, 18</span>; <span class=\"citation\">Ḥull. 40ᵃ</span> <span dir=\"rtl\">השוחט … לשום ש׳ וכ׳</span> if one kills an animal in the name of mountains … or even of a small worm, such are ‘sacrifices of the dead.’ <span class=\"citation\">Ib. 67ᵇ</span> כל לרבות הש׳ והרומה לש׳ ‘whatsoever’ goes up on the belly (<span class=\"citation\">Lev. XI, 42</span>), this includes the snail and whatever is like it (worms); Sifra Sh’mini, Par. 10, ch. XII <span dir=\"rtl\">השִׁלְשׁוּלִים</span> (pl.). <span class=\"citation\">Gen. R. s. 8</span>; <span class=\"citation\">Lev. R. s. 14</span> <span dir=\"rtl\">ש׳ קדמך</span> the worm has been created before thee (man); a. e.—Pl. <span dir=\"rtl\">שִׁלְשׁוּלִים</span>, <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁי׳</a>, v. supra.</div>","alt":["שׁי׳ III"]},"31642":{"h":"שִׁלְשׁוּשִׁית","r":"U01394","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לְשִׁישִׁית\">לְשִׁישִׁית</a></div>","alt":[]},"31643":{"h":"שְׁלשִׁית","r":"U01395","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁלשׁ\">שָׁלשׁ</a>) <i>three years old, in its third year</i>. <span class=\"citation\">Par. I, 1</span>, v. <a href=\"#\" data-headword=\"שְׁלִישִׁי\">שְׁלִישִׁי</a>.</div>","alt":[]},"31644":{"h":"שִׁלְשֵׁל","r":"U01396","html":"<div class=\"sense\"> (שָׁלַל I) <i>to let down</i>. <span class=\"citation\">Y. Ber. IV, 7ᵇ</span> top <span dir=\"rtl\">היו מְשַׁלְשְׁלִין וכ׳</span> in (ed. Lehm. <span dir=\"rtl\">מְשׁלְּשִׁין</span>) they lowered for them (the besiegers) two basketfuls of gold &amp;c.; <span dir=\"rtl\">פעם שִׁילְשְׁלוּ וכ׳</span> once they let down &amp;c.; <span class=\"citation\">Sot. 49ᵇ</span>; <span class=\"citation\">Men. 64ᵇ</span>; <span class=\"citation\">B. Kam. 82ᵇ</span> <span dir=\"rtl\">מְשַׁלְּשִׁין</span>. <span class=\"citation\">Sabb. I, 11</span> <span dir=\"rtl\">משלשלין את הפסח וכ׳</span> the Passover lamb is let down into the stove &amp;c.; <span class=\"citation\">Tosef. Pes. VII, 1</span>. <span class=\"citation\">Tosef. Bets. IV, 3</span> <span dir=\"rtl\">אין משלשלין אותן וכ׳</span> you must not let them down from the window, but you may let them slide down on ladders (v. ed. Zuck. note). <span class=\"citation\">Lev. R. s. 19</span> <span dir=\"rtl\">נטלוהו ושִׁלְשְׁלוּהוּ</span> (<span dir=\"rtl\">לו</span>) they seized him and let him down the wall; <span class=\"citation\">Gen. R. s. 94</span>, end. <span class=\"citation\">Yeb. XVI, 4</span> (<span class=\"citation\">121ᵃ</span>) <span dir=\"rtl\">מעשה שׁשִׁלְשְׁלוּהוּ לים וכ׳</span> it happened at ʿAsia with one whom they let down into the sea (as diver), and (in hauling him up) they brought up nothing but his leg.; Y. ib. 15ᵈ top <span dir=\"rtl\">ששלשלהו הים</span> (corr. acc.). <span class=\"citation\">Erub. 87ᵃ</span> <span dir=\"rtl\">מְשַׁלְשֵׁל דלי וכ׳</span> he may let the bucket down and fill &amp;c.; Tosef. ib. IX (VI), 24. <span class=\"citation\">Gen. R. s. 11</span> <span dir=\"rtl\">צריך לְשַׁלְשֵׁל</span> (on the Sabbath) one must let his cloak hang down (not tuck up as for travel). Ib. <span dir=\"rtl\">ושִׁילְשְׁלָהּ ר׳ זעירא</span> R. Z. pulled it down; a. fr.—<i>Part. pass.</i> <span dir=\"rtl\">מְשׁוּלְשָׁל</span>; f. <span dir=\"rtl\">מְשׁוּלְשֶׁלֶת</span> <i>hanging down</i>. <span class=\"citation\">Men. 41ᵇ</span> כמה תהא מש׳ Ms. M. (ed. <span dir=\"rtl\">מְשׁוּלֶּשֶׁת</span>, v. Rabb. D. S. a. l. note) how far must the threads of the show-fringes hang down (beyond the border)?; <span class=\"citation\">Yalk. Num. 750</span>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">מְשׁוּלְשָׁלוֹת ארבע</span> (Men. l. c. sing.) hanging down four finger-breadths.</div>","alt":["שִׁילְ׳","שִׁלֵּשׁ"]},"31645":{"h":"שִׁלְשֵׁל II","r":"U01397","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"שָׁלַל I\"><span dir=\"rtl\">שָׁלַל</span> I</a>)</div><div class=\"sense\"><b>1)</b> <i>to chain, couple</i>. <span class=\"citation\">Tosef. Ber. VI (V), 6</span>; <span class=\"citation\">Pes. 105ᵇ</span> <span dir=\"rtl\">ומְשַׁלְשְׁלָן כולן לאחרין</span> and combines all of them (the benedictions) in the prayer after the meal. <span class=\"citation\">Y. Kidd. I, 61ᵃ</span> bot.; <span class=\"citation\">Y. Sabb. I, 3ᵃ</span> <span dir=\"rtl\">אם יכול את לשַׁלְשֵׁל … שַׁלְשְׁלָהּ וכ׳</span> if thou canst couple a tradition by quoting authorities up to Moses, do so; if not, quote either the very first or the very last authority; a. e.—<i>Part. pass.</i> מְשׁוּלְשָׁל <i>knotted</i>. <span class=\"citation\">Num. R. s. 9</span><sup>7</sup> <span dir=\"rtl\">שהיה … לחבל מש׳ זה בזה וכ׳</span> his (Israel’s) offspring was like a rope knotted together, one part to the other, for all could trace their descent in uninterrupted succession.</div><div class=\"sense\"><b>—2)</b> <i>to form chains, curls</i>. <span class=\"citation\">Shebi. IV, 10</span> <span dir=\"rtl\">החרובין משׁיְשַׁלְשְׁלוּ</span> (Ar. <span dir=\"rtl\">משׁיְשַׁרְשְׁרוּ</span>) carob-trees (must not be cut down in the Sabbatical year) from the time that they form chains, v. <a href=\"#\" data-headword=\"שִׁלְשׁוּל ²\"><span dir=\"rtl\">שִׁלְשׁוּל</span> II</a>.</div>","alt":[]},"31646":{"h":"שַׁלְשֵׁל I","r":"U01398","html":"<div class=\"sense\"><b>Ithpalp. אִשְׁתַּלְשֵׁל</b> <div class=\"sense\"><i>to be chained</i>. <span class=\"citation\">Targ. Job XII, 17</span> (h. text <span dir=\"rtl\">שׁוֹלָל</span>).</div></div>","alt":[]},"31647":{"h":"שַׁלְשֵׁל II","r":"U01399","html":"<div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שַׁלְשֵׁל I\"><span dir=\"rtl\">שִׁלְשֵׁל</span> I</a>, <i>to let down</i>. <span class=\"citation\">Targ. I Sam. XIX, 12</span>. <span class=\"citation\">Targ. Josh. II, 15</span>; <span class=\"citation\">18</span>.—<span class=\"citation\">Y. Snh. II, 20ᵇ</span> bot. <span dir=\"rtl\">הוה חמי ליה מְשַׁלְשֵׁל וכ׳</span> he saw him let his clothes down a little, and take them up a little; <span class=\"citation\">Y. Succ. V, 55ᶜ</span> top, <span class=\"citation\">Num. R. s. 4</span>, end <span dir=\"rtl\">משולשל</span> (corr. acc.).</div><div class=\"sense\"><b>Ithpa. אִשְׁתַּלְשֵׁל</b> <div class=\"sense\"><i>to let one’s self down</i>. Y. Ter. VIII, 45ᵈ bot. <span dir=\"rtl\">דהוא מִשְׁתַּלְשֵׁל</span> for it (the serpent) can let itself down (on the string).</div></div>","alt":[]},"31648":{"h":"שַׁלְשֵׁל III","r":"U01400","html":"<div class=\"sense\"> (v.<a href=\"#\" data-headword=\"שִׁלְשׁוּל ²\"><span dir=\"rtl\">שִׁלְשׁוּל</span> III</a>) <i>to relax, loosen the bowels</i>. <span class=\"citation\">Keth. 10ᵇ</span>; <span class=\"citation\">Gitt. 70ᵃ</span> <span dir=\"rtl\">מְשַׁלְשְׁלָן</span> they (dates) act as a laxative.</div>","alt":[]},"31649":{"h":"שַׁלְשֶׁלֶת","r":"U01401","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (שִׁלְשֵׁל II) <i>chain</i>. <span class=\"citation\">Kel. XIV, 3</span>. <span class=\"citation\">Y. Taan. II, 65ᵈ</span> הריני עושה לה ש׳ … השַׁלֶּשֶׁת וכ׳ I will make a chain for it (the key), so that if its gets lost, the chain will point it out. <span class=\"citation\">Y. Succ. V, end, 55ᵈ</span>; <span class=\"citation\">Cant. R. to V, 5</span> <span dir=\"rtl\"><span dir=\"rtl\">יוחסין</span>(<a href=\"#\" data-headword=\"ה\">ה</a>) <a href=\"#\" data-headword=\"ש׳\">ש׳</a></span>, v. <a href=\"#\" data-headword=\"יוֹחָס\">יוֹחָס</a>; ib. introd. <span dir=\"rtl\">שלשת יוחסין</span>. <span class=\"citation\">Num. R. s. 9</span><sup>7</sup> <span dir=\"rtl\">והש׳ באה כך</span> thus the genealogical chain is continued. <span class=\"citation\">Num. R. s. 4</span><sup>8</sup> <span dir=\"rtl\">צפה נח</span> (<a href=\"#\" data-headword=\"ש\">ש</a>)ש׳ האבות וכ׳ Noah foresaw that the genealogical chain of the patriarchs would begin with him (Shem); a. fr.—Pl. <span dir=\"rtl\">שַׁלְשְׁלָאוֹת</span>, <span dir=\"rtl\">שַׁלְשְׁלָיוֹת</span>. <span class=\"citation\">Sabb. 89ᵇ</span>, v. <a href=\"#\" data-headword=\"רָאָה I\"><span dir=\"rtl\">רָאָה</span> I</a>. <span class=\"citation\">Y. Keth. II, 26ᵈ</span>; <span class=\"citation\">Y. Gitt. III, 45ᵃ</span> top (among the appurtenances of a siege). <span class=\"citation\">Erub. 58ᵃ</span>; a. fr.</div>","alt":[]},"31650":{"h":"שַׁלְשֶׁלְתָּא","r":"U01402","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XII, 18</span> שולשיל׳ Ms. (ed. <span dir=\"rtl\">שוש׳</span>). Targ. II Esth. I, 2 <span dir=\"rtl\">שוש׳</span>; a. e.—<span class=\"citation\">Keth. 27ᵃ</span> <span dir=\"rtl\">מהדר ליה למתא שושיל׳ וכ׳</span> they place around the town a chain and a dog &amp;c. (to guard against surprise). <span class=\"citation\">Gitt. 68ᵃ</span>, v. <a href=\"#\" data-headword=\"שַׁסְתֵּם\">שַׁסְתֵּם</a>. <span class=\"citation\">Ib. 56ᵇ</span> <span dir=\"rtl\">תן לי … וש׳ וכ׳</span> grant me (spare) Jabneh and her scholars and the chain (the family of scholars) of Rabban G.; a. fr.—Pl. <span dir=\"rtl\">שַׁלְשְׁלָוָון</span>, <span dir=\"rtl\">שַׁלְשְׁלָוָותָא</span>, <span dir=\"rtl\">שׁוּלְשְׁ׳</span>, <span dir=\"rtl\">שׁוּשְׁ׳</span>, <span dir=\"rtl\">שַׁלְשְׁלָן</span>, <a href=\"#\" data-headword=\"שִׁלְיְתָא\">שִׁילְ׳</a>. <span class=\"citation\">Targ. I Kings VI, 21</span> (ed. Lag. <span dir=\"rtl\">שִׁישְׁלָן</span>). <span class=\"citation\">Targ. Ez. VII, 23</span> <span dir=\"rtl\">שִׁלְשְׁ׳</span> (ed. Lag. <a href=\"#\" data-headword=\"שַׁלְשֶׁלְתָּא\">שִׁישְׁ׳</a>). <span class=\"citation\">Targ. Jud. XVI, 21</span>. <span class=\"citation\">Targ. Is. XL, 19</span> (some ed. <span dir=\"rtl\">שילשלין</span>, corr. acc.). <span class=\"citation\">Targ. Ps. CXVIII, 27</span> <span dir=\"rtl\">שִׁלְשְׁלָוָן</span> ed. Wil. (ed. Lag. <span dir=\"rtl\">שושלוון</span>). <span class=\"citation\">Ib. CVII, 14</span> <span dir=\"rtl\">שַׁלְשָׁלְוָתְהוֹן</span> (Ms. <span dir=\"rtl\">שׁוּלְשְׁלָוַות׳</span>). Targ. II Esth. I, 2, end <span dir=\"rtl\">שלשלוון</span> (some ed. <span dir=\"rtl\">שַׁלְשָׁוָון</span>); a. fr.</div>","alt":["שׁוּלְשֶׁילְ׳","שׁוֹשֶׁלְ׳","שִׁישֶׁ׳"]},"31651":{"h":"שַׁלֶּשֶׁת","r":"U01403","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁלְשֶׁלֶת\">שַׁלְשֶׁלֶת</a></div>","alt":[]},"31652":{"h":"שְׁלשֶׁת","r":"U01404","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁלשָׁה\">שְׁלשָׁה</a></div>","alt":[]},"31653":{"h":"שָׁם","r":"U01405","html":"<div class=\"sense\"> (b. h.) <i>there, thither</i>. <span class=\"citation\">Macc. II, 7</span> <span dir=\"rtl\">אינו יוצא מִשָּׁם לעולם</span> he dare not go away from there (the city of refuge) all his life time; <span dir=\"rtl\">שם תהא דירתו שם וכ׳</span> there he must live, there he must die &amp;c.; Tosef. ib. III (II), 5. <span class=\"citation\">Macc. 4ᵃ</span> <span dir=\"rtl\">שנפל שם</span> which fell thereinto. <span class=\"citation\">Ber. V, 4</span> <span dir=\"rtl\">אם אין שם כהן וכ׳</span> if no priest besides him is present; a. v. fr.—<span class=\"citation\">Cant. R. to VIII, 9</span> <a href=\"#\" data-headword=\"שָׁמָּה\">שָׁמָּה</a>, v. <a href=\"#\" data-headword=\"רְגַז I\">רגָּז</a>.—לְשָׁם <i>thither</i>. <span class=\"citation\">Ex. R. s. 18</span>; a. fr.</div>","alt":[]},"31654":{"h":"שֵׁם I","r":"U01406","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Shem</i>, son of Noah. <span class=\"citation\">Meg. 9ᵇ</span> (ref. to <span class=\"citation\">Gen. IX, 27</span>) <span dir=\"rtl\">דבריו … באהלי שם</span> let the speech of Japheth (Greek) dwell in the tents of Shem; v. <a href=\"#\" data-headword=\"יָפְיוּת\">יָפְיוּת</a>. <span class=\"citation\">Gen. R. s. 63</span>, v. <a href=\"#\" data-headword=\"עֵבֶר I\"><span dir=\"rtl\">עֵבֶר</span> I</a>. <span class=\"citation\">Snh. 69ᵇ</span>. <span class=\"citation\">Ex. R. s. 18</span> the Lord said, <span dir=\"rtl\">חייב אני לשם אביהם וכ׳</span> I am indebted to their (the Assyrians’) father Shem, because he and Japheth took their cloaks and covered with it &amp;c.; a. fr.</div>","alt":[]},"31655":{"h":"שֵׁם II","r":"U01407","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"שׁוּם\">שׁוּם</a> a. <i>mark, name, title, nature, denomination</i>. <span class=\"citation\">Pes. III, 3</span> <span dir=\"rtl\">לא תקרא לה שם וכ׳</span> she must not name it (declare it to be Ḥallah) until it is baked. <span class=\"citation\">Ter. III, 5</span> <span dir=\"rtl\">האומר … קרא שם</span> if one says, the priest’s portion of this pile is in it …, he has named it (designated it as T’rumah). <span class=\"citation\">Gen. R. s. 25</span> (ref. to <span class=\"citation\">Gen. V, 29</span>) <span dir=\"rtl\">לא השם הוא המדרש … הוא השם וכ׳</span> the name (<a href=\"#\" data-headword=\"נֹחַ\">נח</a>) and the interpretation (<span dir=\"rtl\">ינחמנו</span>) do not correspond; it ought to be either &amp;c. <span class=\"citation\">Ber. II, 8</span> <span dir=\"rtl\">ליטול … השם</span>, v. <a href=\"#\" data-headword=\"נָטַל\">נָטַל</a>. <span class=\"citation\">Macc. I, 2</span> <span dir=\"rtl\">לא השם המביאו וכ׳</span> the title (the legal text) under which the false witness is doomed to lashes, is not the one under which he is bound to pay indemnity. <span class=\"citation\">Kinn. I, 3</span> <span dir=\"rtl\">משם אחד</span> sacrificial birds of the same denomination (intended for the same class of cases), opp. <span dir=\"rtl\">משני שמות</span> of different denominations. <span class=\"citation\">Sabb. XII, 3</span> <span dir=\"rtl\">משם אחד</span> two letters of the alphabet of the same name (<span dir=\"rtl\">אא</span>, <a href=\"#\" data-headword=\"בָּב\">בב</a> &amp;c.), opp. <span dir=\"rtl\">משתי שמות</span> two different letters (אב &amp;c.). Ib. <span dir=\"rtl\">שם קטן משם גדול וכ׳</span> a small name or word as a part (or abbreviation) of a larger one, as <a href=\"#\" data-headword=\"שֵׁם I\">שם</a> as a part of <a href=\"#\" data-headword=\"שִׁמְעוֹן\">שמעון</a>, of <a href=\"#\" data-headword=\"שְׁמוּאֵל\">שמואל</a> &amp;c. Ib. 103ᵇ <span dir=\"rtl\">שתי אותיות והן שם אחד</span> two identical letters which represent a word, (as <a href=\"#\" data-headword=\"שֵׁשׁ\">שש</a>, which may stand for <a href=\"#\" data-headword=\"שֵׁשׁ\">שֵׁשׁ</a> or <a href=\"#\" data-headword=\"שֵׁשׁ\">שָׂשׂ</a>) &amp;c. <span class=\"citation\">Shebu. 3ᵇ</span>, a. fr. <span dir=\"rtl\">לא מן השם הוא זה וכ׳</span> this comes not under this title (this is not the real reason), but it is because &amp;c. <span class=\"citation\">Ker. III, 4</span> <span dir=\"rtl\">אינו מן השם</span> the offence is not of the same class. <span class=\"citation\">Macc. 4ᵇ</span>, a. fr. <span dir=\"rtl\">(<span dir=\"rtl\">על חבירו</span>) <span dir=\"rtl\">מוציא שם רע</span></span> who spreads an evil report about his neighbor (injures his reputation). <span class=\"citation\">Ber. 17ᵃ</span> <span dir=\"rtl\">גדל בשם טוב וכ׳</span> who has grown up with a good name, and departed life with a good name; a. v. fr.—Esp. <a href=\"#\" data-headword=\"שָׁמֵם\">הַשֵּׁם</a> or <a href=\"#\" data-headword=\"שֵׁם\">שֵׁם</a> <i>the Divine Name, the Tetragrammaton</i>, contradist. to <a href=\"#\" data-headword=\"כִּינּוּי\">כינוי</a> attribute; in gen. <i>the Lord</i>. <span class=\"citation\">Snh. VII, 5</span> <span dir=\"rtl\">המגדף … שיפרש השם</span> the blasphemer is not punishable, unless he uses the Name explicitly. <span class=\"citation\">Ib. 8</span> <span dir=\"rtl\">המקלל … בַּשֵּׁם</span> he that curses his father or his mother is not punishable, unless he curses them with the Name. <span class=\"citation\">Ib. 56ᵃ</span> <span dir=\"rtl\">בידך את השם בכינוי</span> (not <span dir=\"rtl\">בכינויים</span>) if he curses God by using a divine attribute. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עד שיברך שם בשם</span> unless he curses God and pronounces the Name. <span class=\"citation\">Yoma III, 8</span>; <span class=\"citation\">IV, 2</span>; <span class=\"citation\">VI, 2</span> (<span dir=\"rtl\">בשם</span>) <span dir=\"rtl\">אנא השם</span> I pray, O Lord (pronouncing the Tetragrammaton). Ib. <span dir=\"rtl\">כשהיו שומעים שם המפורש שהוא יוצא וכ׳</span> when they heard the Tetragrammaton pronounced &amp;c., v. <a href=\"#\" data-headword=\"פָּרַשׁ\">פָּרַשׁ</a>. Ib. IV, 1 <span dir=\"rtl\">אחד … לַשֵּׁם</span> on one of the lots was written ‘unto the Lord’; <span dir=\"rtl\">של שם</span> the lot bearing the inscription ‘unto the Lord’; a. v. fr.; v. <a href=\"#\" data-headword=\"שָׁמַיִם\">שָׁמַיִם</a>.—Especial uses: <span dir=\"rtl\">כְּשֵׁם שֶׁ־</span> <i>the same as, as well as</i>. <span class=\"citation\">Ber. IX, 5</span> <span dir=\"rtl\">חייב אדם … כשם שמברך וכ׳</span> a man is bound to bless God for what is evil as well as he blesses for what is good. <span class=\"citation\">Ib. 62ᵃ</span> <span dir=\"rtl\">כשם שנפרעין וכ׳</span> as well as the dead are called to account &amp;c., v. <a href=\"#\" data-headword=\"סַפְדָּן\">סַפְדָּן</a>. <span class=\"citation\">Sot. V, 1</span> <span dir=\"rtl\">כשם שהמים … כך וכ׳</span> as the waters test her, so do they test him. Ib. <span dir=\"rtl\">כשם שאסורה וכ׳</span>, v. <a href=\"#\" data-headword=\"בָּעַל\">בָּעַל</a>; a. v. fr.—<span dir=\"rtl\">בְּשֵׁם</span>, <a href=\"#\" data-headword=\"מָשַׁל I\">מִשֵּׁם</a> <i>in the name of, in behalf of</i>. <span class=\"citation\">Meg. 15ᵃ</span> <span dir=\"rtl\">כל האומר דכר בשם אומרו וכ׳</span> he who relates a thing in the name of him who said it (gives credit to authority), brings redemption into the world. <span class=\"citation\">Peah II, 4</span> <span dir=\"rtl\">מִשְּׁמוֹ</span> in his own name (as his individual opinion). <span class=\"citation\">Y. Taan. I, 64ᵃ</span> <span dir=\"rtl\">הלכה … שאמר משם וכ׳</span> the rule follows the opinion of …, who said in behalf of &amp;c.; a. v. fr.—לְשֵׁם <i>for the purpose of, for the sake of, as; with reference to</i>. <span class=\"citation\">Gitt. 24ᵇ</span> <span dir=\"rtl\">כתב רחמנא לה לִשְׁמָהּ</span> the text (<span class=\"citation\">Deut. XXIV, 3</span>) says, ‘unto her’, that means, that it must be written especially for her. <span class=\"citation\">Yeb. 47ᵇ</span>, v. <a href=\"#\" data-headword=\"שׁוּם II\"><span dir=\"rtl\">שׁוּם</span> II</a>.—<span class=\"citation\">Snh. 99ᵇ</span> <span dir=\"rtl\">העוסק בתורה לשמה</span> who studies the Law for its own sake (for no selfish ends). <span class=\"citation\">Pes. 50ᵇ</span> <span dir=\"rtl\">לעולם יעסוק … אע&quot;פ שלא לשמה … בא לשמה</span> by all means let a man engage in the study of the Law and in good deeds, even if not for their own sake, for through the work for a selfish purpose he will arrive at the stage of doing good for its own sake. <span class=\"citation\">Ib. 13ᵇ</span>, a. e. <span dir=\"rtl\">שחטן לִשְׁמָן וכ׳</span> if he slaughtered them as such (as festive sacrifices) &amp;c.; <span dir=\"rtl\">זרק דמן שלא לשמן</span> if he sprinkled their blood, having in mind another purpose (another class of sacrifices). <span class=\"citation\">Gen. R. s. 25</span> <span dir=\"rtl\">לשם קרבנו נקרא</span> he was named (<a href=\"#\" data-headword=\"נֹחַ\">נח</a>) with reference to his sacrifice (<span dir=\"rtl\">ניחח</span>, <span class=\"citation\">Gen. VIII, 21</span>) ; <span dir=\"rtl\">לשם נחת וכ׳</span> he was named (<a href=\"#\" data-headword=\"נֹחַ\">נח</a>) with reference to the rest of the ark (<span dir=\"rtl\">ותנח</span>, <span class=\"citation\">Gen. VIII, 4</span>); Yalk. ib. 42 <span dir=\"rtl\">על שם וכ׳</span>; a. v. fr.—<span dir=\"rtl\">עַל שֵׁם</span> (abbrev. <span dir=\"rtl\">ע&quot;ש</span>) <i>with reference to, because</i>. <span class=\"citation\">Y. Taan. II, beg. 65ᵃ</span> <span dir=\"rtl\">על שם ואנכי וכ׳</span> as a reference to (what Abraham said,) ‘and I am but dust and ashes’ (<span class=\"citation\">Gen. XVIII, 27</span>). <span class=\"citation\">Gen. R. s. 23</span>, v. <a href=\"#\" data-headword=\"טְבַרְיָא\">טְבַרְיָא</a>; a. fr.; v. <a href=\"#\" data-headword=\"שׁוּם II\"><span dir=\"rtl\">שׁוּם</span> II</a>.—Pl. <span dir=\"rtl\">שֵׁמוֹת</span>, constr. <span dir=\"rtl\">שְׁמוֹת</span>. Kinn. l. c. <span class=\"citation\">Gen. R. s. 26</span> <span dir=\"rtl\">כל הש׳ הללו וכ׳</span> all these names indicate rebellion &amp;c., v. <a href=\"#\" data-headword=\"מַרְדּוּת I\"><span dir=\"rtl\">מַרְדּוּת</span> I</a>. <span class=\"citation\">B. Mets. 114ᵇ</span> <span dir=\"rtl\">עובר בכל הש׳ הללו</span> is guilty under all these titles (texts). <span class=\"citation\">Shebu. 35ᵃ</span> <span dir=\"rtl\">יש ש׳ שנמחקין ויש ש׳ וכ׳</span> there are divine names which may be erased, and such as may not be erased. <span class=\"citation\">Y. R. Hash. I, 56ᵈ</span> bot. <span dir=\"rtl\">שְׁ׳ המלאכים</span>, v. <a href=\"#\" data-headword=\"מַלְאָךְ\">מַלְאָךְ</a>; a. fr.</div>","alt":[]},"31656":{"h":"שֵׁם","r":"U01408","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. II, Ex. XXXI, 2</span>. <span class=\"citation\">Targ. Ps. CXLVII, 4</span>. <span class=\"citation\">Targ. O. Gen. VI, 4</span>; a. fr.—<span class=\"citation\">Sot. 49ᵃ</span> <span dir=\"rtl\">יהא שְׁמֵיה רבא</span> (abbrev. <span dir=\"rtl\">יה&quot;ש&quot;ר</span>), v. <a href=\"#\" data-headword=\"אֲגַדְתָּא\">אֲגַדְתָּא</a>. <span class=\"citation\">Ab. I, 13</span>, v. <a href=\"#\" data-headword=\"נְגַד\">נְגַד</a>. <span class=\"citation\">Yoma 83ᵇ</span>, v. <a href=\"#\" data-headword=\"דּוּק\">דּוּק</a>. <span class=\"citation\">Ber. 7ᵇ</span>, v. <a href=\"#\" data-headword=\"גְּרַם I\"><span dir=\"rtl\">גְּרַם</span> I</a>. <span class=\"citation\">Sabb. 8ᵇ</span> (in Hebr. dict.) <span dir=\"rtl\">שמיה הילוך</span> comes under the category of ‘walking’; <span dir=\"rtl\">לא שמיה תשמיש</span> does not come under the category of ‘use.’ <span class=\"citation\">Ḥull. 48ᵃ</span> <span dir=\"rtl\">משמיה רר׳ וכ׳</span> in behalf of &amp;c.; <span class=\"citation\">Y. Taan. I, 64ᵃ</span> bot. <span dir=\"rtl\">מן שמיה</span>. <span class=\"citation\">Sabb. 145ᵇ</span> <a href=\"#\" data-headword=\"שַׁמַּאי\">שְׁמָאִי</a> my name, v. <a href=\"#\" data-headword=\"מָתָא\">מָתָא</a>; a. v. fr.—<span class=\"citation\">Y. Orl. I, 61ᵃ</span> bot. <span dir=\"rtl\">אית בני נש שְׁמוֹן בריכה וכ׳</span> there are persons whose name is B’rikah (meaning blessing), as one says, come thou, blessed of the Lord.—Pl. <a href=\"#\" data-headword=\"שְׁמָהָן\">שְׁמָהָן</a>, <a href=\"#\" data-headword=\"שְׁמָהָן\">שְׁמָהָתָא</a>; <a href=\"#\" data-headword=\"שְׁמַיָּיא\">שְׁמַיָּיא</a>, <a href=\"#\" data-headword=\"שְׁמֵי\">שְׁמֵי</a>. <span class=\"citation\">Targ. Gen. II, 20</span>. <span class=\"citation\">Ib. XXVI, 18</span>. <span class=\"citation\">Targ. O. Num. I, 5</span> <a href=\"#\" data-headword=\"שְׁמָהָן\">שְׁמָהַת</a> constr.; Y. <span dir=\"rtl\">שְׁמָהָיַית</span>; a. fr.—<span class=\"citation\">Gitt. 11ᵇ</span> <span dir=\"rtl\">שמהתא … בשְׁמָהָתַיְיהוּ</span> other names which Jews frequently adopt for their own, v. <a href=\"#\" data-headword=\"נְסַק\">נְסַק</a>. <span class=\"citation\">Meg. 14ᵇ</span> <span dir=\"rtl\">סניין שְׁמַיְיהוּ</span>, v. <a href=\"#\" data-headword=\"סְנֵי\">סְנֵי</a>; a. fr.</div>","alt":["שְׁמָא"]},"31657":{"h":"שֶׁמָּא","r":"U01409","html":"<div class=\"sense\"> (= <span dir=\"rtl\">שַׁלָּמָּה</span>, v. <a href=\"#\" data-headword=\"דִּילְמָא ²\"><span dir=\"rtl\">דִּילְמָא</span> I</a>) [<i>for why</i>,] </div><div class=\"sense\"><b>1)</b> <i>lest, perhaps</i>. <span class=\"citation\">Ab. II, 4</span>, v. <a href=\"#\" data-headword=\"פָּנָה\">פָּנָה</a>. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> top [read:] <span dir=\"rtl\">אי לי ש׳ מי שכתוב … עקב יבוא לנשכיני</span> woe is me, (I am afraid,) lest he of whom it is written (<span class=\"citation\">Gen. III, 15</span>) … come to bite me; Bab. <span class=\"citation\">Ab. Zar. 8ᵃ</span> <span dir=\"rtl\">אוי לי ש׳ בשביל וכ׳</span> woe is me, lest the world grow dark around me, because I have sinned. <span class=\"citation\">Keth. 12ᵃ</span> <span dir=\"rtl\">וניחוש ש׳ תחתיו וכ׳</span> but must we not consider the possibility that she may have prostituted herself while she was engaged to him?; a. fr.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">שמא</span> m. <i>apprehension, doubt, possibility</i>. Ib. 14ᵃ <span dir=\"rtl\">התם ברי הכא ש׳</span> there she asserts a certainty, here a possibility (as she cannot be certain about it herself). Ib. <span dir=\"rtl\">וקיל ליה ש׳ וכ׳</span> and he regards this statement of a possibility so lightly that &amp;c. Ib. <span dir=\"rtl\">אפי׳ בש׳ נמי מכשיר</span> even with her uncertain assertion he declares her fit for marriage. Ib. 12ᵇ, a. fr. <span dir=\"rtl\">ברי וש׳</span>, v. <a href=\"#\" data-headword=\"בָּרִי\">בָּרִי</a>; a. fr.</div>","alt":[]},"31658":{"h":"שַׁמַּאי","r":"U01410","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Shammai</i> (abbrev. of <a href=\"#\" data-headword=\"שְׁמַעְיָא\">שמעיה</a>), </div><div class=\"sense\"><b>1)</b>  (<span dir=\"rtl\">הזקן</span>) <a href=\"#\" data-headword=\"ש׳\">ש׳</a> Sh., the colleague of Hillel in the Sanhedrin under king Herod. <span class=\"citation\">Ḥag. II, 2</span>. <span class=\"citation\">B. Bath. 133ᵇ</span>; <span class=\"citation\">Y. Ned. V, end, 39ᵇ</span>. <span class=\"citation\">Succ. II, 8</span>, a. e. <span dir=\"rtl\">ש׳ הזקן</span>. <span class=\"citation\">Eduy. I, 1</span> sq. (differences between Sh. and Hillel). <span class=\"citation\">Ib. 4</span>; a. v. fr.—<a href=\"#\" data-headword=\"שְׁאָן\">בֵּית שַׁ׳</a> (abbrev. <span dir=\"rtl\">ב&quot;ש</span>) the school of Sh., the disciples of Sh. <span class=\"citation\">Ib. 7</span>. <span class=\"citation\">Bets. I, 1</span>; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  name of an Amora. <span class=\"citation\">Y. Sabb. III, 5ᵈ</span> bot.; a. fr. V. Fr. M’bo, p. 124ᵇ</div>","alt":["שַׁמַּי","שַׁמַּיי"]},"31659":{"h":"שִׁמָּאָה","r":"U01411","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁימָּאָה\">שִׁימָּאָה</a></div>","alt":[]},"31660":{"h":"שְׂמֹאל","r":"U01412","html":"<div class=\"sense\"> c. (b. h.) <i>left side, left hand</i>. <span class=\"citation\">Yoma IV, 1</span> <span dir=\"rtl\">הסגן … מִשְּׂמאֹלוֹ</span> the Sagan to his right, and the chief of the priests’ division to his left. Ib. <span dir=\"rtl\">אם של שם עלה בשמאלו</span> if the lot marked ‘unto the Lord’ came up in his left hand; <span dir=\"rtl\">הגבה שְׂמֹאלְךָ</span> raise thy right hand. Ib. V, 1 <span dir=\"rtl\">מהלך לשמאלו</span> walks to the left. <span class=\"citation\">Snh. 107ᵇ</span>, v. <a href=\"#\" data-headword=\"דָּחָה\">דָּחָה</a>. <span class=\"citation\">Sifré Deut. 154</span> (ref. to <span class=\"citation\">Deut. XVII, 11</span>) <span dir=\"rtl\">אפי׳ … על ש׳ שהוא ימין וכ׳</span> even if they show it before thy eyes that left is right and right is left, listen to them; a. v. fr.</div>","alt":[]},"31661":{"h":"שמאל","r":"U01413","html":"<div class=\"sense\">, <i>Hif.</i> <a href=\"#\" data-headword=\"יָמַן\">הִשְׂמְאִיל</a> (b. h.) <i>to go to the left; to be on the left side, go wrong</i>. <span class=\"citation\">Sabb. 63ᵃ</span> <span dir=\"rtl\">למַשְׂמְאִילִים בה</span> to those who make the wrong use of it, v. <a href=\"#\" data-headword=\"יָמַן\">יָמַן</a>. <span class=\"citation\">Ib. 88ᵇ</span> <span dir=\"rtl\">למשמאילים בה</span> (Ms. M. <span dir=\"rtl\">דלא איימין ליה</span>, v. <span dir=\"rtl\">וְמַן</span>). <span class=\"citation\">Cant. R. to I, 9</span> <span dir=\"rtl\">אלו … ואלו משמאילים</span> those (pleading in favor of the accused) stand to the right, and those (against the accused) to the left; a. e.</div>","alt":[]},"31662":{"h":"שמאל ²","r":"U01414","html":"<div class=\"sense\">, Af. <span dir=\"rtl\">אַשְׂמְאִיל</span> ch. same. <span class=\"citation\">Koh. R. to X, 2</span> (ref. to <span class=\"citation\">Gen. XIII, 9</span>) (Abraham said,) <span dir=\"rtl\">אפי׳ את מחצף אנא מַשְׂמְאִיל לך</span> even if thou shalt act irreverently (towards me), I shall show thee the left side (that thou art wrong). Ib. <span dir=\"rtl\">הוה אמר … אַשְׂמְאִיל ליה וכ׳</span> he said to one of his household, show him the left side, and he showed him a cutting movement in that direction, v. <a href=\"#\" data-headword=\"קְטִיף\">קְטִיף</a></div>","alt":[]},"31663":{"h":"שְׂמָאלָא","r":"U01415","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"שְׂמֹאל\">שְׂמֹאל</a>. <span class=\"citation\">Targ. Num. XXII, 26</span>; a. e., v. <a href=\"#\" data-headword=\"סְמָלָא\">סְמָלָא</a>.—<span class=\"citation\">Y. Ned. I, 37ᵃ</span> top <span dir=\"rtl\">ש׳ הרי זו שבועה</span> if one swears ‘by my left hand,’ it is a binding oath.</div>","alt":[]},"31664":{"h":"שְׂמָאלִיתָא","r":"U01416","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׂמָאלָא\">preced.</a>) <i>the left</i>. <span class=\"citation\">Targ. Y. Deut. XI, 18</span>.</div>","alt":[]},"31665":{"h":"שַׁמְגַּז","r":"U01417","html":"<div class=\"sense\"> (prob.) pr. n. pl. <i>Shamgaz</i>; <span dir=\"rtl\">חלא ש׳</span> Sh. vinegar, a very pungent vinegar used as a restorative. <span class=\"citation\">Ab. Zar. 12ᵇ</span> (Ms. M. <span dir=\"rtl\">שמגן</span>). <span class=\"citation\">Gitt. 70ᵃ</span> Ar. (ed. <a href=\"#\" data-headword=\"שמזג\">שמזג</a>).—[<span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">כש׳ מריגז</span> ed. (Ms. M. <span dir=\"rtl\">בְּשֵׁם מוריגן</span>; Ms. O. <span dir=\"rtl\">בשם מרגיז</span>, v. <a href=\"#\" data-headword=\"מוֹרִיגַן\">מוֹרִיגַן</a>.]</div>","alt":[]},"31666":{"h":"שַׁמְגַּר","r":"U01418","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Shamgar</i>, one of the Judges of Israel. <span class=\"citation\">Ruth R. to I, 1</span>. Tanḥ. Aḥăré 12; a. e.</div>","alt":[]},"31667":{"h":"שָׁמַד","r":"U01419","html":"<div class=\"sense\"><i>Hif.</i>; cmp. <span dir=\"rtl\">שמם</span>, <i>to be waste</i>.</div><div class=\"sense\"><b>Pi. שִׁימֵּד</b> <div class=\"sense\"> [<i>to destroy,</i>] <i>to persecute; to force to apostasy</i>. <span class=\"citation\">Gen. R. s. 82</span> <span dir=\"rtl\">ואם לאו הרי אני מְשַׁמֵּד אתכם</span> and if you cannot answer, I will force you to forswear your religion; <span class=\"citation\">Yalk. Is. 263</span> <span dir=\"rtl\">אַשְׁמִיד</span> (Hif.).—Part. pass. <a href=\"#\" data-headword=\"מְשׁוּמָּד\">מְשׁוּמָּד</a> <i>converted to heathenism</i>, q. v.</div></div><div class=\"sense\"><b>Hif. הִשְׁמִיד</b> <div class=\"sense\"><b>1)</b> <i>to destroy</i>. <span class=\"citation\">Esth. R. to III, 6</span> אני אמרתי להַשְׁמִידָם … להַשְׁמִיד וכ׳ I (the Lord) intended to destroy them, and, as it were, could not …, and thou wilt destroy, slay &amp;c.? <span class=\"citation\">Ib. to III, 12</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to force to apostasy</i>, v. supra.</div></div><div class=\"sense\"><b>Nithpa. נִשְׁתַּמֵּד</b> <div class=\"sense\"><b>1)</b> <i>to be destroyed, cut off</i>. <span class=\"citation\">Yalk. Lev. 558</span> דואג נ׳ מעולם וכ׳ Doeg was cut off from this and from the other world; (Tanḥ. M’tsorʿa 2 <a href=\"#\" data-headword=\"שָׁרַשׁ\">נשתרש</a>).</div><div class=\"sense\"><b>—2)</b> <i>to apostatize</i>. Y. Gitt. VII, beg. 48ᶜ. Y. Hor. I, 45ᵈ bot. Y. Succ. V, end, 55ᶜ מרים … שׁנִשְׁתַּמְּדָה וכ׳ Miriam … who renounced her religion, and married a Roman officer; <span class=\"citation\">Tosef. Succ. IV</span>, 28ᵈ; Bab. <span class=\"citation\">Succ. 56ᵇ</span> Ms. M. (ed. <span dir=\"rtl\">שהמירה דתה</span>).</div></div>","alt":[]},"31668":{"h":"שְׁמַד","r":"U01420","html":"<div class=\"sense\"><b>Pa. שַׁמֵּד</b> <div class=\"sense\"><i>to force to apostasy</i>. Y. Shebi. IV, 35ᵃ bot. <span dir=\"rtl\">לא מתכוון מְשַמַּדְתְּכוֹן</span> he has no intention to make you abandon your religion (to persecute you for your religion’s sake), but only to collect taxes &amp;c.; Y. Snh. III, 21ᵇ top <span dir=\"rtl\">משמדתהון</span> (corr. acc.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא אתכוון מְשַׁמַּדְתְּהוֹן וכ׳</span> he had no intention to force them to violate their religious laws, but merely wanted to eat fresh bread; Y. Shebi. l. c. <span dir=\"rtl\">מְשַׁמַּדְתּוֹן</span>.</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתַּמַּד</b> <div class=\"sense\"><i>to renounce one’s religion, apostatize</i>. <span class=\"citation\">Targ. O. Ex. XII, 43</span> (h. text <span dir=\"rtl\">בן נכר</span>).—<span class=\"citation\">Kidd. 72ᵃ</span> שמתינהו … ואִישְׁתַּמּוּד R. A. excommunicated them, and they renounced Judaism.</div></div>","alt":[]},"31669":{"h":"שְׁמָד","r":"U01421","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמַד\">preced.</a>) [<i>attempt at destruction,</i>] <i>religious persecution</i>. <span class=\"citation\">Tosef. Ab. Zar. V</span> (<span class=\"citation\">VI), 6</span> <span dir=\"rtl\">בי מוסייאות … שעת הש׳ אע&quot;פ שעבר הש׳ וכ׳</span> altars which gentiles have put up at a time of religious persecution are forbidden (as to the use of the materials) even after the persecution is over; Y. ib. V, 45ᵃ top; Bab. <span class=\"citation\">ib. 54ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">בשעת הגזירה</span>). <span class=\"citation\">Tosef. Sabb. XV</span> (<span class=\"citation\">XVI), 17</span> <span dir=\"rtl\">במה דברים אמורים שלא בשעת הש׳ אבל בשעת הש׳ וכ׳</span> this (that one may violate religious laws to save his life) is said only when there is no general religious persecution, but during a persecution one must give up his life even for the least essential law; <span class=\"citation\">Snh. 74ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">גזירת המלכות</span>). <span class=\"citation\">Cant. R. to II, 5</span> <span dir=\"rtl\">שלפי הש׳</span>, v. <a href=\"#\" data-headword=\"שֶׁלֶף\">שֶׁלֶף</a>; <span class=\"citation\">Sabb. 60ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">הגזרה</span>); a. fr.—Pl. <a href=\"#\" data-headword=\"שֶׁמֶר\">שְׁמָדִים</a>, <a href=\"#\" data-headword=\"שֶׁמֶר\">שְׁמָדִין</a>. <span class=\"citation\">Gen. R. s. 67</span> (ref. to <span class=\"citation\">Gen. XXVII, 40</span>) <span dir=\"rtl\">אם ראית … גזור עליו ש׳ וכ׳</span> when thou (Esau-Rome) seest thy brother (Jacob) cast off the yoke of the Law, decree persecutions over him, and thou shalt have power over him. <span class=\"citation\">Midr. Till. to Ps. XVIII, 5</span> <span dir=\"rtl\">שכמה ש׳ גזרו עלינו בימיה</span> for they decreed many persecutions over us in her (Rome’s) days; a. e.</div>","alt":[]},"31670":{"h":"שְׁמָדָא","r":"U01422","html":"<div class=\"sense\"><span class=\"citation\">Ḥull. 101ᵇ</span> ש׳ הוא דהוה וכ׳ Ms. M. it was a time of persecution (when Jews were forbidden to observe their festive days), and they sent word from there (Palestine) that this year’s Day of Atonement should be observed on a Sabbath day. <span class=\"citation\">Gen. R. s. 79</span> <span dir=\"rtl\">הוו טמירין … ביומא דש׳</span> were hidden in a cave for thirteen years during the (Hadrianic) persecution; <span class=\"citation\">Koh. R. to X, 8</span>. <span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> top <span dir=\"rtl\">בשעת שׁוּמְדָּא</span>; a. e.</div>","alt":["שְׁמָדָה"]},"31671":{"h":"שְׁמָדוֹן","r":"U01423","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמָדָא\">preced.</a>) <i>Sh’madon</i>, name of a demon. <span class=\"citation\">Gen. R. s. 36</span> <span dir=\"rtl\">שידא ש׳</span> (not <span dir=\"rtl\">שמר׳</span>; Ar. <span dir=\"rtl\">אשמדון</span>; cmp. <a href=\"#\" data-headword=\"אַשְׁמְדַאי\">אַשְׁמְדַאי</a>); Yalk. ib. 61.</div>","alt":[]},"31672":{"h":"שָׁמָּה","r":"U01424","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁם\">שָׁם</a></div>","alt":[]},"31673":{"h":"שַׁמָּה","r":"U01425","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>desolation</i>. <span class=\"citation\">M. Kat. 17ᵃ</span> Ms. M., v. <a href=\"#\" data-headword=\"שַׁמְתָּא\">שַׁמְתָּא</a>.</div>","alt":[]},"31674":{"h":"שְׁמָהָן","r":"U01426","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שֵׁם\">שְׁמָא</a></div>","alt":["שְׁמָהָתָא"]},"31675":{"h":"שְׁמוּאֵל","r":"U01427","html":"<div class=\"sense\"> (b. h.) <i>Samuel</i>, </div><div class=\"sense\"><b>1)</b>  S. the prophet. <span class=\"citation\">Ber. 10ᵇ</span> <span dir=\"rtl\">כש׳ הרמתי</span> as Samuel the Ramathite (who declined all offers of hospitality). <span class=\"citation\">Naz. 5ᵃ</span>. <span class=\"citation\">Sabb. 55ᵇ</span> sq. <span dir=\"rtl\">כל האומר בני ש׳ חטאו וכ׳</span> whoever says that the sons of S. sinned, errs. <span class=\"citation\">Gen. R. s. 85</span> <span dir=\"rtl\">בבית דינו של ש׳</span> in Samuel’s court of justice; a. fr.</div><div class=\"sense\"><b>—2)</b>  ש׳ הקטן S. the Little, a Tannai. <span class=\"citation\">Ber. 28ᵇ</span> עמד ש׳ הק׳ וכ׳ Samuel the Little arose and arranged it (the benediction concerning the Minim, v. <a href=\"#\" data-headword=\"מִין III\"><span dir=\"rtl\">מִין</span> III</a>). <span class=\"citation\">Y. Hor. III, end, 48ᶜ</span>; <span class=\"citation\">Y. Sot. IX, 24ᵇ</span>. <span class=\"citation\">Snh. 11ᵃ</span>. <span class=\"citation\">Ab. IV, 19</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>Samuel</i>, the Babylonian, contemporary of Rab, and founder of the college of Nehardea. <span class=\"citation\">Keth. 43ᵇ</span> (surnamed <i>Shaḳud</i>); Y. ib. IV, 28ᵇ bot. (<i>Shoḳed</i>). <span class=\"citation\">Y. Taan. IV, 68ᵃ</span> ש׳ ואילין וכ׳ S. and those of the house of Shila &amp;c. <span class=\"citation\">B. Mets. 85ᵇ</span>, v. <a href=\"#\" data-headword=\"יַרְחִינָאָה\">יַרְחִינָאָה</a>. <span class=\"citation\">R. Hash. 20ᵇ</span>. <span class=\"citation\">Snh. 17ᵇ</span>; <span class=\"citation\">Shebu. 47ᵃ</span>, v. <a href=\"#\" data-headword=\"רַב II\"><span dir=\"rtl\">רַב</span> II</a>. <span class=\"citation\">Sabb. 53ᵃ</span>, v. <a href=\"#\" data-headword=\"אַרְיוֹךְ\">אַרְיוֹךְ</a>; a. v. fr.</div><div class=\"sense\"><b>—4)</b>  name of several Amoraim. <span class=\"citation\">Y. Snh. II, 20ᵇ</span> top <span dir=\"rtl\">ש׳ הזקן</span>. <span class=\"citation\">Sot. 10ᵇ</span> <span dir=\"rtl\">ש׳ סבא</span>.—<span class=\"citation\">Y. Kil. II, 28ᵃ</span>; ib. IV, 29ᶜ; a. fr.—S. bar Naḥmani or Naḥman. <span class=\"citation\">Y. Ter. VIII, end, 46ᶜ</span>. Ber. l. c.; a. fr.—S. bar Imi or Ammi. <span class=\"citation\">Y. Kidd. III, 63ᵈ</span> bot. Sot. l. c.; a. fr.; and several others. V. Fr. M’bo, p. 125ᵃ, sq.</div>","alt":[]},"31676":{"h":"שְׁמוֹדַע","r":"U01428","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִשְׁתְּמוֹדַע I\"><span dir=\"rtl\">אִשְׁתְּמוֹדַע</span> I</a></div>","alt":[]},"31677":{"h":"שִׁמּוּט","r":"U01429","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁימּוּט\">שִׁימּוּט</a></div>","alt":[]},"31678":{"h":"שָׁמוּט","r":"U01430","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁמַט\">שָׁמַט</a>) <i>nimble, long and thin</i>. <span class=\"citation\">Tosef. Bekh. V, 1</span>; <span class=\"citation\">Bekh. 43ᵇ</span> <span dir=\"rtl\">צוארו שקוט וש׳</span> one whose neck is sunk (very short), or <i>shamuṭ</i>, expl. <span dir=\"rtl\">דאריך וש׳</span> long and nimble.</div>","alt":[]},"31679":{"h":"שְׁמוּטָא","r":"U01431","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">שְׁמוּטֵי</span>. <span class=\"citation\">Keth. 60ᵇ</span> <span dir=\"rtl\">הוו לה בני ש׳</span> will have children with long necks.</div>","alt":[]},"31680":{"h":"שָׁמוֹטָא","r":"U01432","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמוּטָא\">preced.</a>) <i>long stretched</i>, name of a species of <i>locusts</i>. <span class=\"citation\">Targ. I Kings VIII, 37</span> (ed. Wil. <a href=\"#\" data-headword=\"שְׁמוּעָא\">שְׁמוֹ׳</a>; h. text <span dir=\"rtl\">חסיל</span>); <span class=\"citation\">Targ. II Chr. VI, 28</span>. <span class=\"citation\">Targ. Joel I, 4</span>.—[<span class=\"citation\">Targ. Ez. XXIII, 20</span> <a href=\"#\" data-headword=\"שְׁמוּטָא\">שְׁמוֹטָא</a>, read with ed. Lag. <span dir=\"rtl\">שמשא</span>; v. Kimḥi a. l.]</div>","alt":["שָׁמוּ׳"]},"31681":{"h":"שְׁמוֹן","r":"U01433","html":"<div class=\"sense\">, <span class=\"citation\">Y. Orl. I, 61ᵃ</span> bot., v. <a href=\"#\" data-headword=\"שֵׁם\">שְׁמָא</a></div>","alt":[]},"31682":{"h":"שְׁמוֹנֶה","r":"U01434","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁמֹנֶה\">שְׁמֹנֶה</a></div>","alt":["שְׁמוֹנָה"]},"31683":{"h":"שִׁמּוּעַ","r":"U01435","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁימּוּעַ\">שִׁימּוּעַ</a></div>","alt":[]},"31684":{"h":"שַׁמּוּעַ","r":"U01436","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Shammua</i>, father of R. Eleazar. <span class=\"citation\">Yeb. 62ᵇ</span>. <span class=\"citation\">Erub. 53ᵃ</span>; a. fr.</div>","alt":[]},"31685":{"h":"שָׁמוּעַ","r":"U01437","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁמַע\">שָׁמַע</a>) = <a href=\"#\" data-headword=\"מִשְׁמָע\">מִשְׁמָע</a>, <i>sense, understanding</i>. <span class=\"citation\">Y. Snh. X, 29ᵇ</span> bot. (ref. to <span class=\"citation\">Ps. LX, 9</span>) <span dir=\"rtl\">מנשה כשְׁמוּעוֹ</span> Manasseh is to be taken in its ordinary sense (as referring to king Manasseh; (<span class=\"citation\">Num. R. s. 14</span> beg. <span dir=\"rtl\">כמשמעו</span>). <span class=\"citation\">Y. Yoma II, end, 40ᵃ</span> <span dir=\"rtl\">כל ששמועו מרובה ושמועו וכ׳</span> wherever a Biblical text may be understood as comprising a larger or a smaller number, you must adopt the smaller number; Sifra M’tsorʿa, Zab., ch. VII, Par. 5 (Tosaf. to <span class=\"citation\">Succ. 5ᵇ</span> quotes <span dir=\"rtl\">שמשמעו</span>).</div>","alt":[]},"31686":{"h":"שְׁמוּעָא","r":"U01438","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"שְׁמוּעֲתָא\">שְׁמוּעֲתָא</a>, a. <a href=\"#\" data-headword=\"שֵׁמַע\">שֵׁמַע</a> ch.</div>","alt":["שְׁמוֹ׳"]},"31687":{"h":"שָׁמוֹעָא","r":"U01439","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמַע I\">שְׁמַע</a>) </div><div class=\"sense\"><b>1)</b> <i>listening, attentive</i>. <span class=\"citation\">Targ. Prov. XXI, 28</span> (some ed. <a href=\"#\" data-headword=\"שָׁמוּעָה\">שָׁמוּעָה</a>).</div><div class=\"sense\"><b>—2)</b> <i>one that surrenders himself to the enemy, deserter.</i> <i>—</i> Pl. <span dir=\"rtl\">שָׁמוֹעַיָּא</span>. <span class=\"citation\">Targ. II Kings XXV, 11</span>; <span class=\"citation\">Targ. Jer. LII, 15</span> Kimḥi (ed. <a href=\"#\" data-headword=\"שְׁמִיעָא\">שְׁמִיעיָּא</a>; h. text <span dir=\"rtl\">הנפלים</span>).</div><div class=\"sense\"><b>—3)</b> <i>reporter of a tradition.</i> <i>—</i> Pl. <span dir=\"rtl\">שָׁמוֹעִין</span>. <span class=\"citation\">Y. Ber. V, 9ᵇ</span> bot. <span dir=\"rtl\">לא בגין … ש׳ וכ׳</span></div>","alt":[]},"31688":{"h":"שָׁמוּעָה","r":"U01440","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁמוֹעָא\">preced.</a></div>","alt":[]},"31689":{"h":"שְׁמוּעָה","r":"U01441","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>report, news</i>. <span class=\"citation\">R. Hash. 3ᵃ</span> (ref. to <span class=\"citation\">Num. XXI, 1</span>) <span dir=\"rtl\">מה ש׳ שמע וכ׳</span> what was the report he heard? He heard that Aaron was dead. Ib. 18ᵇ <span dir=\"rtl\">שבו באת ש׳ וכ׳</span> on it (the fifth of Tebeth) came the report to the captivity that the city was taken (<span class=\"citation\">Ez. XXXIII, 21</span>); <span dir=\"rtl\">עשו יום ש׳ וכ׳</span> they observed mourning on the day they heard the news, as they would have done on the day when the Temple was burnt. <span class=\"citation\">Keth. 62ᵃ</span> <span dir=\"rtl\">ש׳ דבית המקדש</span> the news of the destruction of the Temple. <span class=\"citation\">M. Kat. 20ᵇ</span>, a. fr. <span dir=\"rtl\">ש׳ רחוקה</span> the news of the death of a relative received after thirty days from the time of death; <span dir=\"rtl\">ש׳ קרובה</span> news received within thirty days. <span class=\"citation\">Snh. 110ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">שְׁמוּעוֹת</span>. <span class=\"citation\">Ber. IX, 2</span>, v. <a href=\"#\" data-headword=\"בְּשׂוֹרָה\">בְּשׂוֹרָה</a>. <span class=\"citation\">M. Kat. 26ᵃ</span> <span dir=\"rtl\">ש׳ הרעות</span> bad news; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>tradition, traditional decision, legal discussion</i> <a href=\"#\" data-headword=\"הֲלָכָה\">(הֲלָכָה</a>). Ib. 23ᵃ <span dir=\"rtl\">אין אומרים ש׳ והגדה וכ׳</span> you must not speak of legal subjects or homiletical interpretations in the house of mourning. <span class=\"citation\">Snh. 88ᵃ</span> <span dir=\"rtl\">הוא אומר מפי הש׳</span> if he says, I gave my decision on the basis of a tradition, opp. <span dir=\"rtl\">כך הוא בעיני</span> it is my own opinion. <span class=\"citation\">Eduy. V, 7</span> אני עמדתי בשְׁמוּעָתִי … בשְׁמוּעָתָן I stood by my tradition, and they by theirs. <span class=\"citation\">Erub. 64ᵃ</span> <span dir=\"rtl\">כל האומר ש׳ זו וכ׳</span> he who says, this traditional decision is good, the other is not &amp;c. <span class=\"citation\">Men. 18ᵃ</span> <span dir=\"rtl\">כמדומה אני שלא כיווננו שְׁמוּעָתֵינוּ וכ׳</span> it seems to me that until now our traditions did not correspond; <span class=\"citation\">Tosef. Zeb. II, 17</span> <span dir=\"rtl\">שמועתן</span> (corr. acc.); a. fr.—<i>Pl.</i> as ab. <span class=\"citation\">Ḥag. 14ᵃ</span> גבור בעל ש׳ ‘a mighty man’ (<span class=\"citation\">Is. III, 2</span>) that means a man knowing many legal traditions.—[<a href=\"#\" data-headword=\"שְׁמוּעָה\">שְׁמוּעָה</a> in Chald. dict., v. next w.]</div>","alt":[]},"31690":{"h":"שְׁמוּעֲתָא","r":"U01442","html":"<div class=\"sense\"><b>1)</b> <i>hearing</i>. <span class=\"citation\">Targ. Y. II, Deut. XXXII, 1</span>, v. <a href=\"#\" data-headword=\"שְׁמִיעָא\">שְׁמִיעָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>report, news</i>. <span class=\"citation\">Targ. I Sam. II, 24</span>. <span class=\"citation\">Targ. Ps. CXII, 7</span>; a. fr.</div><div class=\"sense\"><b>—3)</b> (also h. form <a href=\"#\" data-headword=\"שְׁמוּעָה\">שְׁמוּעָה</a>) <i>tradition, traditional decision, law</i>. <span class=\"citation\">Y. Succ. I, 52ᵇ</span> ר׳ חייא … עביד לה ש׳ וכ׳ R. Ḥ.… decided the matter by referring to a tradition &amp;c. <span class=\"citation\">Y. Maas. Sh. II, 53ᶜ</span> top <span dir=\"rtl\">ולא ידעינן אם מן ש׳ אם מן מתניתא</span> and we do not know whether he quoted a tradition (of Amoraim) or a Mishnah. <span class=\"citation\">Y. Peah III, 17ᵈ</span> top <span dir=\"rtl\">ש׳ כן וכ׳</span> the traditional law is this: he that &amp;c. <span class=\"citation\">Y. Gitt. IX, beg. 50ᵃ</span> <span dir=\"rtl\">ש׳ רובא ממתניתא</span> the traditional law goes farther than the Mishnah. <span class=\"citation\">Y. R. Hash. II, 58ᵇ</span> top <span dir=\"rtl\">מרה דש׳</span> the authority for that tradition; (<span class=\"citation\">Y. Snh. I, 18ᶜ</span> bot. <span dir=\"rtl\">דשמעתא</span>); a. fr.—Pl. <span dir=\"rtl\">שְׁמוּעֲיָין</span>, <a href=\"#\" data-headword=\"שְׁמוּעֲתָא\">שְׁמוּעָתָא</a>. <span class=\"citation\">Targ. Cant. V, 10</span> <span dir=\"rtl\">שמועיין חדתין</span> ed. Lag. (ed. Vien. <span dir=\"rtl\">שְׁמוּעִין</span>).—Y. Ter. VIII, 45ᵈ top <span dir=\"rtl\">מרי ש׳</span> = <span dir=\"rtl\">בעל שמועות</span>, v. <a href=\"#\" data-headword=\"שְׁמוּעָה\">preced.</a></div>","alt":[]},"31691":{"h":"שִׁמּוּר","r":"U01443","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁימּוּר\">שִׁימּוּר</a></div>","alt":[]},"31692":{"h":"שְׁמוּרַת","r":"U01444","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁמִירָה II\"><span dir=\"rtl\">שְׁמִירָה</span> II</a></div>","alt":[]},"31693":{"h":"שִׁמּוּשׁ","r":"U01445","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"שִׁמְצָא\">שׁימּ׳</a>.</div>","alt":["שִׁמּוּשָׁא"]},"31694":{"h":"שַׁמּוּתִי","r":"U01446","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"שַׁמְתָּא\">שַׁמְּתָא</a>) <i>one that is under the ban</i> and cannot be quoted as an authority. <span class=\"citation\">Nidd. 7ᵇ</span> <span dir=\"rtl\">בחייו … דר׳ אליעזר ש׳ הוא וכ׳</span> why did he not reinstate the practice in agreement with R. Eliezers’s opinion in his (R. Eliezer’s) life-time? Because R. El. was under the ban, and it was thought, if we act according to his opinion in one thing, we (people) might do so in other things, and out of respect for R. El. we should be unable to interfere &amp;c. <span class=\"citation\">Sabb. 130ᵇ</span> <span dir=\"rtl\">חדא דר׳ אל׳ ש׳ וכ׳</span> first of all, R. El. being under the ban dare not be quoted as an authority, and secondly one against many &amp;c. <span class=\"citation\">Y. Bets. I, 60ᶜ</span> top <span dir=\"rtl\">ור׳ ליעזר לא ש׳ הוא</span> but is not R. Liezer under the ban? (how can you quote him as an authority?); <span class=\"citation\">Y. Ter. V, 43ᶜ</span> bot.</div>","alt":["שַׁמָּתִי"]},"31695":{"h":"שַׁמּוּתִית","r":"U01447","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁחַמְתִּית\">שְׁחַמְתִּית</a></div>","alt":[]},"31696":{"h":"שמזג","r":"U01448","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁמְגַּז\">שַׁמְגַּז</a></div>","alt":[]},"31697":{"h":"שָׂמַח","r":"U01449","html":"<div class=\"sense\"> (b. h.) <i>to be merry, rejoice</i>. <span class=\"citation\">Meg. 13ᵇ</span> <span dir=\"rtl\">ש׳ שמחה גדולה</span> he rejoiced exceedingly. <span class=\"citation\">M. Kat. 18ᵇ</span> <span dir=\"rtl\">ראה … וש׳</span> he saw others do wrong and rejoiced over it; a. fr.</div><div class=\"sense\"><b>Pi. שִׂימֵּחַ</b> <div class=\"sense\"><i>to make glad, cheer</i>. <span class=\"citation\">B. Bath. 10ᵇ</span> יְשַׂמֵּחַ את אשתו בדבר מצוה Ms. M. (v. Rabb. D. S. a. l.) let him make his wife cheerful by means of a good deed. <span class=\"citation\">R. Hash. 6ᵇ</span> <span dir=\"rtl\">אשה בעלה מְשַׂמְּחָהּ</span> as to a woman’s festive joy, her husband must rejoice her (with dresses &amp;c.); <span class=\"citation\">Kidd. 34ᵇ</span>. <span class=\"citation\">Pes. 109ᵃ</span> <span dir=\"rtl\">חייב אדם לְשַׂמֵּחַ וכ׳</span> man is bound to gladden his children and the members of his household on the festival; <span dir=\"rtl\">במה מְשַׂמְּחָם</span> wherewith should he gladden them? <span class=\"citation\">Keth. 8ᵃ</span> (in marriage benedictions) <span dir=\"rtl\">מְשַׂמֵּחַ ציון בבניה</span> who gladdens Zion through (restoring to her) her children; <span dir=\"rtl\">משמח חתן וכלה</span> who gladdens bridegroom and bride; <span dir=\"rtl\">מש׳ חתן עם הכלה</span> who gladdens the bridegroom with the bride; <span dir=\"rtl\">שַׂמֵּח תְּשַׂמַּח … כשַׂמֵּחֲךָ וכ׳</span> mayest thou gladden the beloved friends, as thou didst gladden thy creature (Adam) &amp;c.; a. fr.</div></div>","alt":[]},"31698":{"h":"שָׂמֵחַ","r":"U01450","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שָׂמַח\">preced.</a>) <i>bright, joyful, joyous</i>. <span class=\"citation\">Kidd. 66ᵃ</span> <span dir=\"rtl\">היה ש׳ שמחה וכ׳</span> he rejoiced greatly (prepared a great festival), and invited &amp;c. <span class=\"citation\">Ber. 5ᵃ</span>, v. <a href=\"#\" data-headword=\"עָצֵב\">עָצֵב</a>. <span class=\"citation\">Ib. 9ᵇ</span> <span dir=\"rtl\">אדם … וש׳ במצות</span> he is a great man and glad when he can do good. <span class=\"citation\">Meg. 10ᵇ</span> <span dir=\"rtl\">אין הקב&quot;ה ש׳ וכ׳</span> the Lord does not rejoice over the downfall of the wicked; a. v. fr.—Pl. <span dir=\"rtl\">שְׂמֵחִים</span>, <span dir=\"rtl\">שְׂמֵחִין</span>, <a href=\"#\" data-headword=\"שָׁמֵן\">שְׂמֵי׳</a>. <span class=\"citation\">Sabb. 145ᵇ</span>, v. <a href=\"#\" data-headword=\"מוֹעֵד\">מוֹעֵד</a>. <span class=\"citation\">Yoma 21ᵇ</span> <span dir=\"rtl\">עניים ש׳ … עצבין</span> the poor are glad (because provisions will be cheap), and the property owners are sorry; <span class=\"citation\">B. Bath. 147ᵃ</span>. <span class=\"citation\">Cant. R. to I, 10</span>; <span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> bot. <span dir=\"rtl\">והיו הדברים ש׳ וכ׳</span> and the words (of the Law which they quoted at the festive board) were as bright as when they were delivered from Sinai; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"שִׂמְחָה\">שְׂמֵחָה</a>, <a href=\"#\" data-headword=\"שָׁמֵן\">שְׂמֵי׳</a>. <span class=\"citation\">Pesik. R. s. 20</span> <span dir=\"rtl\">כשנתן … ארץ ש׳ ושמים בוכין</span> when the Lord gave Israel the Law, the earth was glad, and the heavens wept; a. fr.—Pl. <span dir=\"rtl\">שְׂמֵחוֹת</span>, <a href=\"#\" data-headword=\"שָׁמֵן\">שְׂמֵי׳</a>. <span class=\"citation\">Pesik. R. s. 21</span> <span dir=\"rtl\">בפנים ש׳</span> with a cheerful contenance; a. e.</div>","alt":[]},"31699":{"h":"שִׂמְחָה","r":"U01451","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שָׂמֵחַ\">preced.</a>) <i>joy, rejoicing, festive occasion</i>. <span class=\"citation\">Keth. 8ᵃ</span> (in Chald. dict.) <span dir=\"rtl\">אפושי ש׳ בעלמא הוא</span> it is merely an extension of the wedding joy (not a new festive occasion). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מברך שהש׳ במעונו</span> he says the benediction containing the words, ‘in whose dwelling there is joy.’ <span class=\"citation\">Y. B. Bath. IX, 16ᵈ</span> bot. <span dir=\"rtl\">שִׂמְחַת זכר</span> the joy over the birth of a male child. <span class=\"citation\">Gen. R. s. 70</span>; <span class=\"citation\">M. Kat. 8ᵇ</span> <span dir=\"rtl\">ש׳ בש׳</span>, v. <a href=\"#\" data-headword=\"עָרַב I\"><span dir=\"rtl\">עָרב</span> I</a>; a. fr.—Esp. <span dir=\"rtl\">שמחת יום טוב</span>, or <a href=\"#\" data-headword=\"ש׳\">ש׳</a> <i>the rejoicing on the festival</i> (<span class=\"citation\">Deut. XVI, 11</span>; <span class=\"citation\">14</span>). <span class=\"citation\">R. Hash. 6ᵇ</span> <span dir=\"rtl\">איתה בש׳</span> she (woman) is included in the commandment to observe the festival with joy. <span class=\"citation\">Ḥag. 6ᵃ</span> <span dir=\"rtl\">חנה … מיחייבא בש׳</span> was not Hannah herself bound to visit the Temple in order to rejoice? <span class=\"citation\">Pes. 109ᵃ</span> <span dir=\"rtl\">בזמן … אין ש׳ אלא בבשר … אין ש׳ אלא ביין</span> as long as the Temple stood, the festive rejoicing consisted in eating meat (of the peace-offering), … but now … the festive celebration consists in partaking of wine; a. fr.—Pl. <span dir=\"rtl\">שְׂמָחוֹת</span>. <span class=\"citation\">Zeb. 102ᵃ</span> חמש ש׳ היתה וכ׳ Elisheba had five joys (distinctions) more than ordinary daughters of Israel: her brother-in-law (Moses) was king &amp;c.; a. e.—<a href=\"#\" data-headword=\"ש׳\">ש׳</a> (<a href=\"#\" data-headword=\"מַסֶּכֶת\">מסכת</a>) <i>S’maḥoth</i>, one of the small treatises of Talmud Babli, euphem. for <span dir=\"rtl\">אבל רבתי</span>, v. <a href=\"#\" data-headword=\"אֵבֶל\">אֵבֶל</a>.</div>","alt":[]},"31700":{"h":"שַׁמְחַזָּאִי","r":"U01452","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Shamhazzai</i>, name of a fallen angel. <span class=\"citation\">Targ. Y. Gen. VI, 4</span>.—<span class=\"citation\">Nidd. 61ᵃ</span> סיחון … בר ש׳ הוו Sihon and Og were the sons of Aḥiah son of Sh.</div>","alt":[]},"31701":{"h":"שָׁמַט","r":"U01453","html":"<div class=\"sense\"><i>to slip</i>; (act. verb) <i>to loosen, detach; to carry off, steal</i>. <span class=\"citation\">Num. R. s. 4</span><sup>20</sup> (ref. to <span class=\"citation\">II Sam. VI, 6</span>) <span dir=\"rtl\">למה שָׁמְטוּ</span> why did they slip (turn off)? <span class=\"citation\">M. Kat. 24ᵃ</span> <span dir=\"rtl\">שמטו חזירים וכ׳</span> swine dragged his body off. <span class=\"citation\">Y. Ber. III, 5ᵈ</span> bot., a. e. <span dir=\"rtl\">שׁוֹמֵט וכ׳</span>, v. <a href=\"#\" data-headword=\"*קְלִיבִּינִטִירִין\">קְלִבִּנְטִירִין</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מטה … שׁוֹמְטָן ודיו</span> in the case of a bed the poles of which are movable, one (in mourning) detaches them, and that is sufficient; <span class=\"citation\">Y. Ned. VII, end, 40ᶜ</span> <span dir=\"rtl\">שומטו</span> (corr. acc.). <span class=\"citation\">B. Mets. 104ᵃ</span> <span dir=\"rtl\">שׁוֹמְטוֹ מעל גבי בניו</span> he may take it (the pledge) from the back of his (the debtor’s) sons. <span class=\"citation\">Ex. R. s. 43</span> <span dir=\"rtl\">והם שׁוֹמְטִים וכ׳</span>, v. <a href=\"#\" data-headword=\"טֶטְרָאמוּלִי\">טֶטְרָאמוּלִי</a>. <span class=\"citation\">Y. Keth. V, 30ᵇ</span> <span dir=\"rtl\">היתה שׁוֹמֶטֶת עצמה וכ׳</span> she slipped away from under him; <span class=\"citation\">Sot. 9ᵇ</span> <span dir=\"rtl\">נִשְׁמְטָה</span> (<i>Nif.</i>). <span class=\"citation\">Gen. R. s. 14</span> <span dir=\"rtl\">שׁוֹמְטָהּ</span>, v. <a href=\"#\" data-headword=\"צָרַר I\"><span dir=\"rtl\">צָרַר</span> I</a>. <span class=\"citation\">Pesik. R. s. 20</span> <span dir=\"rtl\">נִשְׁמוֹט אותה</span> let us abandon her (that she may not find her way home); <span dir=\"rtl\">מיד שְׁמָטוּהָ</span> (not <span dir=\"rtl\">שמוטה</span>) and so they abandoned her. <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">יִשְׁמוֹט</span>, v. <a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a>. <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">שומט גידין וכ׳</span> it (the serpent) draws out fibres (v. <a href=\"#\" data-headword=\"גִּיד\">גִּיד</a>) and eats them. <span class=\"citation\">Midr. Till. to Ps. CXIV</span> (ref. to <span class=\"citation\">Deut. IV, 34</span> <span dir=\"rtl\">גוי מקרב גוי</span>) <span dir=\"rtl\">כאדם ששומט את העובר וכ׳</span> as a man draws an embryo out of its mother’s womb. Ib. <span dir=\"rtl\">למדנו צער לנִשְׁמָט לשומט מנין</span> we learn here that there was pain for the body drawn out (Israel), whence do we learn that it was painful for him that drew out (for the Lord who redeemed them)?; a. fr.—Part. pass. <a href=\"#\" data-headword=\"שָׁמוּט\">שָׁמוּט</a>; f. <a href=\"#\" data-headword=\"שְׁמוּטָא\">שְׁמוּטָה</a>. <span class=\"citation\">Ḥull. 54ᵃ</span> <span dir=\"rtl\">ש׳ ושחוטה וכ׳</span> if the trachea was found detached, yet cut through, the animal is <i>kasher</i>; <span dir=\"rtl\">שא&quot;א לש׳ וכ׳</span> for it is impossible that a loose trachea should be cut through (therefore the detachment must have taken place after the ritual cutting). Ib. 57ᵃ, a. e. <span dir=\"rtl\">שְׁמוּטַת ורך</span> an animal with a dislocated thigh-bone; <span dir=\"rtl\">שמוטת וד</span> with a dislocated foreleg; a. e.—V. <a href=\"#\" data-headword=\"שָׁמוּט\">שָׁמוּט</a>.</div><div class=\"sense\"><b>Nif. נִשְׁמַט</b> <div class=\"sense\"><i>to be detached, slip away</i>. Midr. Till. l. c., v. supra. Sot. l. c., v. supra. <span class=\"citation\">Num. R. s. 1</span><sup>8</sup> <span dir=\"rtl\">הר חורב שעליו נִשִׁמְטָה החרב וכ׳</span> it is named mount Horeb, because on it the sword (of judgment) was unsheathed (for crimes); (Yalk. ib. 684 <span dir=\"rtl\">נמשכה</span>; <span class=\"citation\">Yalk. Ps. 796</span> <span dir=\"rtl\">נמתחה</span>). <span class=\"citation\">Macc. II, 1</span>, v. <a href=\"#\" data-headword=\"קַתְּ\">קַתְּ</a>. Sifra Emor, ch. II, Par. 3 (expl. <span dir=\"rtl\">שרוע</span>, <span class=\"citation\">Lev. XXI, 18</span>) <span dir=\"rtl\">שנשמטה יריכו</span> (Rabad <span dir=\"rtl\">שנשתרבבה</span>) whose hip is dislocated. <span class=\"citation\">Cant. R. to V, 16</span> <span dir=\"rtl\">(<span dir=\"rtl\">ממנו</span>) <span dir=\"rtl\">נשמטה נפשו</span></span> his soul slipped away (from him), he fainted; a. fr.—[Tosef. ‘<span class=\"citation\">Uktsin I, 2</span> (Tbul Yom III) <span dir=\"rtl\">נשמטין</span>, read with ed. Zuck. <span dir=\"rtl\">נִכְסָסִין</span>.]</div></div><div class=\"sense\"><b>Pi. שִׁמֵּט</b> <div class=\"sense\"><b>1)</b> <i>to loosen, pluck</i>, esp. <i>to thin</i> a thicket of reeds. <span class=\"citation\">Tosef. Shebi. I, 7</span>; Y. ib. II, 33ᵈ top <span dir=\"rtl\">מְשַׁמְּטִין בקנים</span> you may thin reeds (in the Sabbatical year); <span dir=\"rtl\">מקום … ולְשַׁמֵּט וכ׳</span> where it is customary to clear vines and to thin reeds before &amp;c.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to drag forth</i>. <span class=\"citation\">Pesik. R. s. 17</span> <span dir=\"rtl\">ומְשַׁמְּטִים הבכורות מבין וכ׳</span> and the dogs dragged the dead bodies of the first-born out of the burial caves; <span class=\"citation\">Yalk. Ex. 186</span>; a. e.</div><div class=\"sense\"><b>—3)</b>  (v. <a href=\"#\" data-headword=\"שְׁמִטָּה\">שְׁמִטָּה</a>) <i>to cause release from debt; to cause cessation of field labor</i>; (neut. verb) <i>to come under the law of limitation of the Sabbatical year</i>; (of the ground) <i>to rest</i>. <span class=\"citation\">Shebi. X, 1</span> <span dir=\"rtl\">שביעית מְשַׁמֶּטֶת את המלוה וכ׳</span> the Sabbatical year causes cancellation of (cash) debts, whether verbal or written; <span dir=\"rtl\">הקפת … אינה משמטת</span>, v. <a href=\"#\" data-headword=\"הַקָּפָה\">הַקָּפָה</a>; <span dir=\"rtl\">שכר שכיר אינו מְשַׁמֵּט</span> a hired man’s wages do not come under the law of <i>sh’miṭṭah</i>; ib. 2 <span dir=\"rtl\">המוסר … אינן משמטין</span> (not <a href=\"#\" data-headword=\"אינו\">אינו</a>) if one hands his notes over to the court, they are not subject to the law of limitation; ib. <span dir=\"rtl\">האונס … וכל מעשה ב&quot;ד אינן משמטין</span> fines for outrage …, and all obligations arising from legal procedures do not come under the law &amp;c.; ib. 3, v. <a href=\"#\" data-headword=\"פְּרוֹזְבֹּול\">פְּרוֹזְבּוֹל</a>; [Y. ed. <span dir=\"rtl\">מַשְׁמִיט</span>, <span dir=\"rtl\">מַשְׁמִיטִין</span> &amp;c. <i>Hif.</i> interch. with <i>Pi</i>.]. Sifra B’ḥuck., Par. 2, ch. VII אני אמרתי … ומשמטים לי אחת וכ׳ I have told you that you may sow six years, and let the ground rest for me one year, that you may know &amp;c.; <span dir=\"rtl\">עמדו וגלו והיא תְשַׁמֵּט מאליה כל שמיטים וכ׳</span> go ye and be carried into exile, and it (the land) will rest of itself (making up for) all the Sabbatical years &amp;c.; <span class=\"citation\">Yalk. Lev. 675</span> <span dir=\"rtl\">והיא תַשְׁמִיט מאיליה עד שתרצה לפני כל שמיטין וכ׳</span>. <span class=\"citation\">Ab. d’R. N. ch. XXXVIII</span> <span dir=\"rtl\">הואיל ואין אתם משמיטין אותה היא תְשַׁמֵּט אתכם</span> (ed. Schechter <span dir=\"rtl\">ואי אתם משמטים את הארץ</span>) because you do not let the earth rest, she will abandon you; <span dir=\"rtl\">ומספר ירחים שאי אתם משמיטין אותה היא תשמט מאליה</span> (ed. Schechter <span dir=\"rtl\">שאין אתם משמטים</span>) and according to the number of months that you fail to let her rest, she will rest of herself. <span class=\"citation\">Gitt. 36ᵃ</span> <span dir=\"rtl\">בזמן שאתה משמט … משמט כספים</span> when thou art bound to let the ground rest, thou art bound to cancel debts; a. fr.—<span class=\"citation\">Snh. 97ᵃ</span> <span dir=\"rtl\">כשם שהשביעית משמטת … כך העולם משמט וכ׳</span> as the Sabbatical year causes cessation of field work once every seven years, so shall the world rest (be waste) one millennium in every seven millenniums.</div><div class=\"sense\"><b>—4)</b> <i>to remit a debt</i>. <span class=\"citation\">Gitt. 37ᵇ</span> <span dir=\"rtl\">המחזיר חוב … יאמר לו משמט אני וכ׳</span> if a person pays a debt in the Sabbatical year, he (the creditor) must say, ‘I remit’ (and have no claim): but if he (the debtor) says, ‘nevertheless’, he may accept; <span class=\"citation\">Sabb. 148ᵇ</span>; <span class=\"citation\">Sifré Deut. 112</span>; a. e.</div><div class=\"sense\"><b>—5)</b> <i>to abandon, send away</i>. Ab. d’R. N. l. c., v. supra.</div></div><div class=\"sense\"><b>Hif. הִשְׁמִיט</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"שַׁמְחַזָּאִי\">same</a>, v. supra.</div></div><div class=\"sense\"><b>Hithpa. הִשְׁתַּמֵּט</b> <div class=\"sense\"><i>to slide, fall off</i>. <span class=\"citation\">Midr. Till. to Ps. XVIII, 11</span> <span dir=\"rtl\">מִשְׁתַּמְּטוֹת</span>, v. <a href=\"#\" data-headword=\"טֶלֶף\">טֶלֶף</a>.</div></div>","alt":[]},"31702":{"h":"שְׁמַט","r":"U01454","html":"<div class=\"sense\"><b>1)</b> <i>to loosen, detach, break loose, take away</i>. <span class=\"citation\">Targ. Y. Lev. XIV, 40</span> (h. text <span dir=\"rtl\">חלץ</span>). <span class=\"citation\">Ib. 43</span>. Targ. II Esth. III, 8.—<span class=\"citation\">Ned. 48ᵇ</span> <span dir=\"rtl\">דהיה שָׁמֵיט וכ׳</span> who was in the habit of stealing flax balls. <span class=\"citation\">B. Bath. 28ᵇ</span> <span dir=\"rtl\">מִשְׁמַט הוא דקא שמיט ואכיל</span> he plucks and eats (as the fruits grow, but does not harvest); a. e.—Part. pass. <a href=\"#\" data-headword=\"שְׁמַט\">שָׁמִיט</a>; f. <a href=\"#\" data-headword=\"שְׁמִיטָא\">שְׁמִיטָא</a>. <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">דין עיניה ש׳</span> (some ed. <a href=\"#\" data-headword=\"שְׁמִיטָא\">שְׁמִיטָה</a>; oth. <a href=\"#\" data-headword=\"שְׁמוּטָא\">שְׁמוּטָה</a> Hebraism) one of them had an eye taken out (in a quarrel); <span class=\"citation\">Lev. R. s. 8</span>; Tanḥ. Ki Thissa 5 <span dir=\"rtl\">שמיטי</span> (corr. acc.).</div><div class=\"sense\"><b>—2)</b>  (neut. verb) <i>to slip off, glide</i>. <span class=\"citation\">Targ. Y. I Deut. XIX, 5</span> <span dir=\"rtl\">יִשְׁמוֹט</span> (Y. II <span dir=\"rtl\">יִשְׁמֵיט</span>; ed. Vien. <span dir=\"rtl\">יַשְׁמִיט</span>, corr. acc.).— </div><div class=\"sense\"><b>3)</b> <i>to be released, rest, lie fallow</i>. <span class=\"citation\">Targ. O. Lev. XXVI, 35</span> <span dir=\"rtl\">שְׁמַטַת</span> ed. Berl. (oth. ed. <span dir=\"rtl\">שְׁמֵיטַת</span>; ed. Vien. <span dir=\"rtl\">שְׁמָטָא</span>, read: <span dir=\"rtl\">שְׁמָטַת</span>). <span class=\"citation\">Targ. II Chr. XXXVI, 21</span>.</div><div class=\"sense\"><b>—4)</b> <i>to let rest, leave fallow</i>, v. infra.</div><div class=\"sense\"><b>Af. אַשְׁמֵיט</b> <div class=\"sense\"><b>1)</b> <i>to release, remit a debt</i>. <span class=\"citation\">Targ. Deut. XV, 2</span>.</div><div class=\"sense\"><b>—2)</b> <i>to rest, lie fallow</i>. <span class=\"citation\">Targ. O. Lev. XXVI, 34</span>, sq.; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to abandon, let lie fallow</i>. <span class=\"citation\">Targ. O. Ex. XXIII, 11</span> (Y. ed. Vien. <a href=\"#\" data-headword=\"תּוּשְׁבָּחָה\">תִּשְׁ׳</a>, Pe.); a. e.—[<span class=\"citation\">Targ. Y. II, Deut. XIX, 5</span>, v. supra.]</div></div><div class=\"sense\"><b>Pa. שַׁמֵּט</b> <div class=\"sense\"><b>1)</b> <i>to cause remission of debt.</i> <span class=\"citation\">Gitt. 36ᵃ</span> <span dir=\"rtl\">מדאורייתא מְשַׁמְּטָא … דלא משמטא</span> by Biblical law the Sabbatical year brings remission, and how could Hillel ordain that it should not bring remission? <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">ותקינו … דתְשַׁמֵּט וכ׳</span> and the Rabbis had ordained that it should bring remission as a remembrance of the (Biblical) Sabbatical year; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to let go, drop, discard</i>. Tanḥ. Vayishl. 8 [read:] <span dir=\"rtl\">שַׁמְּטֵיה</span> discard it (the vow), v. <a href=\"#\" data-headword=\"שִׁטְפָא\">שִׁטְפָא</a>.</div><div class=\"sense\"><b>—3)</b> <i>to tear off</i>. <span class=\"citation\">B. Kam. 117ᵃ</span> <span dir=\"rtl\">שמטיה וכ׳</span>, v. <a href=\"#\" data-headword=\"קוֹעָא\">קוֹעָא</a>.</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתַּמֵּט</b> </div><div class=\"sense\"><b>Ithpe. אִשְׁתְּמִיט</b> <div class=\"sense\"><b>1)</b> <i>to slip off, be dislocated; to break loose</i>. <span class=\"citation\">Targ. Y. Num. XXV, 8</span>. <span class=\"citation\">Targ. Y. Lev. XXI, 18</span> <span dir=\"rtl\">דמִשְׁתְּמִיט יריכיה</span> (h. text <span dir=\"rtl\">שרוע</span>), v. preced.—<span class=\"citation\">Yoma 87ᵃ</span> bot., v. <a href=\"#\" data-headword=\"קוֹעָא\">קוֹעָא</a>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to relieve one’s self; to escape, get rid</i>. <span class=\"citation\">Targ. II Chr. XXI, 8</span>. <span class=\"citation\">Targ. Ps. CXLI, 6</span>.—<span class=\"citation\">B. Mets. 3ᵇ</span> <span dir=\"rtl\">אִשְׁתַּמּוּטֵי הוא דקא מישתמיט וכ׳</span> he tries to get rid of him (for the moment), thinking, when I have the money, I shall pay him. <span class=\"citation\">Ib. 17ᵃ</span>; a. e.—<span class=\"citation\">B. Bath. 48ᵇ</span> דלא הוה ליה לאישתמוטי Ms. M. (v. Rabb. D. S. a. l. note) when he had no way of getting loose (by some subterfuge). <span class=\"citation\">Ḥull. 120ᵃ</span> <span dir=\"rtl\">אִשְׁתְּמִיטְתֵּיה הא וכ׳</span> that which was said in the West escaped his attention. <span class=\"citation\">B. Kam. 12ᵃ</span> אִישְׁתַּמְּטִין עולא Ulla has escaped us (was afraid to oppose me); a. e.</div></div>","alt":["שְׁמֵיט"]},"31703":{"h":"שְׁמִטָּא","r":"U01455","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁמִטְּתָא\">שְׁמִטְּתָא</a></div>","alt":[]},"31704":{"h":"שְׁמִטָּה","r":"U01456","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שְׁמִטָּא\">preced.</a>) <i>release, rest</i>, esp. <i>cancellation of debts</i>, and <i>rest of the soil</i>, in the Sabbatical year. <span class=\"citation\">M. Kat. 2ᵇ</span>; <span class=\"citation\">Gitt. 36ᵃ</span> <span dir=\"rtl\">שְׁמִיטַּת קרקע</span> the rest of the soil; <span dir=\"rtl\">שמיטת כספים</span> the cancelling of cash debts. <span class=\"citation\">Sifré Deut. 111</span> <span dir=\"rtl\">הש׳ שאין נוהג וכ׳</span> (sub. <span dir=\"rtl\">דבר</span>) the law of the Sabbatical year which applies only to Palestine. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בא&quot;י שאת עושה ש׳</span> in Palestine where you observe the Sabbatical year. <span class=\"citation\">Ib. 112</span> <span dir=\"rtl\">ש׳ משמטת מלוה וכ׳</span> the Sabbatical year causes cancellation of debts, but the year of the jubilee does not; a. fr.—<span class=\"citation\">Ab. V, 9</span> <span dir=\"rtl\">על שמיטת הארץ וכ׳</span> (Mish. ed. <a href=\"#\" data-headword=\"הַשְׁמָטָה\">הַשְׁמָטַת</a>) for the neglect of the laws concerning land in the Sabbatical year and in the year of the jubilee; <span class=\"citation\">Sabb. 33ᵃ</span> <span dir=\"rtl\">השמטת שמטין וכ׳</span>.—Pl. <span dir=\"rtl\">שְׁמִטֹּות</span>, <span dir=\"rtl\">שְׁמִטִּים</span>, <span dir=\"rtl\">שְׁמִטִּין</span>, <a href=\"#\" data-headword=\"שְׁמִטְּתָא\">שְׁמִיטּ׳</a>. M. Kat. l. c.; Gitt. l. c. <span dir=\"rtl\">בשתי ש׳ וכ׳</span> the text (<span class=\"citation\">Deut. XV, 2</span>) speaks of two releases, the release of the land &amp;c., v. supra. <span class=\"citation\">R. Hash. I, 1</span> <span dir=\"rtl\">באחד … ר&quot;ה לשנים לש׳ וכ׳</span> the first of Tishri is the New Year for years, for Sabbatical years, and for jubilees. <span class=\"citation\">Midr. Till. to Ps. LXXXV</span> <span dir=\"rtl\">אם … ועשו את הש׳ וכ׳</span> if they give forth the tithes, and observe the Sabbatical years &amp;c. <span class=\"citation\">Sabb. 33ᵃ</span>, v. supra. <span class=\"citation\">Ab. d’R. N. ch. XXXVIII</span>, v. <a href=\"#\" data-headword=\"שָׁמַט\">שָׁמַט</a>; a. fr.</div>","alt":["שְׁמִיטָּה"]},"31705":{"h":"שַׁמְטוּטִין","r":"U01457","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁמַט\">שָׁמַט</a>) <i>slips, shoots</i>. <span class=\"citation\">Cant. R. to I, 15</span>; <span class=\"citation\">IV, 1</span> <a href=\"#\" data-headword=\"שַׁמְטוּטִין\">שַׁמְטוּטֵי</a>, v. <a href=\"#\" data-headword=\"שַׁבְטוּטִין\">שַׁבְטוּטִין</a>.</div>","alt":[]},"31706":{"h":"שמטי","r":"U01458","html":"<div class=\"sense\">, Tanḥ. Vayishl. 8, read: <span dir=\"rtl\">שַׁמְּטֵיה</span>, v. <a href=\"#\" data-headword=\"שְׁמַט\">שְׁמַט</a></div>","alt":[]},"31707":{"h":"שְׁמִטְּתָא","r":"U01459","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שְׁמִטָּה\">שְׁמִטָּה</a>. <span class=\"citation\">Targ. Y. II, Deut. XXXIII, 24</span>. Targ. ib. XV, 1 (Y. ed. Vien. <a href=\"#\" data-headword=\"שְׁמִיטָּא\">שְׁמִיטָתָא</a>, corr. acc.); a. fr.—Y. Shebi. IV, 35ᵇ; <span class=\"citation\">Y. Ab. Zar. IV, 44ᵇ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"שְׁמִטְּתָא\">שְׁמִטָּתָא</a>, <span dir=\"rtl\">שְׁמִטִּין</span>, <a href=\"#\" data-headword=\"שְׁמִטְּתָא\">שְׁמִיטּ׳</a>. <span class=\"citation\">Targ. Y. I Deut. XXXIII, 24</span>. <span class=\"citation\">Targ. Y. Ex. XII, 40</span> <span dir=\"rtl\">תלתין ש׳ דשנין</span> thirty septennial priods; a. e.</div>","alt":["שְׁמִטְּתָה","שְׁמִטָּא","שְׁמִיטּ׳"]},"31708":{"h":"שַׁמַּי","r":"U01460","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁמַּאי\">שַׁמַּאי</a></div>","alt":[]},"31709":{"h":"שְׁמֵי","r":"U01461","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁמַיִם\">שָׁמַיִם</a>, a. <a href=\"#\" data-headword=\"שְׁמַיָּא\">next w.</a></div>","alt":[]},"31710":{"h":"שְׁמַיָּא","r":"U01462","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שָׁמַיִם\">שָׁמַיִם</a>, </div><div class=\"sense\"><b>1)</b> <i>heaven</i>; trnsf. <i>God.</i> <span class=\"citation\">Targ. Gen. I, 1</span>. <span class=\"citation\">Targ. Deut. X, 14</span>. <span class=\"citation\">Targ. Y. Num. XXV, 19</span> (<span class=\"citation\">XXVI, 1</span>); a. v. fr.—<span class=\"citation\">Ber. 58ᵇ</span> <span dir=\"rtl\">שבילי דש׳</span> (Ms. M. <span dir=\"rtl\">דרקיעא</span>), v. <a href=\"#\" data-headword=\"נְהַר I\"><span dir=\"rtl\">נְהַר</span> I</a>. <span class=\"citation\">Ib. 7ᵇ</span>; <span class=\"citation\">Keth. 105ᵇ</span>, a. fr. <span dir=\"rtl\">מילי דש׳</span>, v. <a href=\"#\" data-headword=\"מִילָּא II\"><span dir=\"rtl\">מִילָּא</span> II</a>. <span class=\"citation\">Ḥag. 12ᵇ</span> <span dir=\"rtl\">חשוכא קמי ש׳</span>, v. <a href=\"#\" data-headword=\"חֲשׁוֹךְ ²\"><span dir=\"rtl\">חֲשֹׁוכָא</span> II</a>. <span class=\"citation\">Snh. 105ᵃ</span> <span dir=\"rtl\">כלפי ש׳</span>, v. <a href=\"#\" data-headword=\"חוֹצַף\">חוּצְפָּא</a>. <span class=\"citation\">Y. Ned. XI, end, 42ᵈ</span>, v. <a href=\"#\" data-headword=\"רָחִיק II\"><span dir=\"rtl\">רָחִיק</span> II</a>; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">שְׁמֵי שַׁרְיָיתָא</span>, <span dir=\"rtl\">שְׁמֵי טְלָלָא</span> <i>arch, ceiling</i>. <span class=\"citation\">Targ. I Kings VI, 15</span>.—<span class=\"citation\">Ber. 48ᵃ</span>, v. <a href=\"#\" data-headword=\"טְלַל III\">טְלָלָא</a>; a. e.</div>","alt":["שְׁמַיָּיא"]},"31711":{"h":"שְׁמִיטָא","r":"U01463","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"שָׁמוּט\">שָׁמוּט</a> <i>nimble, thin.</i> <span class=\"citation\">Bekh. 45ᵇ</span> (expl. <span dir=\"rtl\">קפח</span>, Mish. <span class=\"citation\">ib. VII, 6</span>) <span dir=\"rtl\">באריכא ש׳ סניא</span> it means one disgustingly long and thin.</div><div class=\"sense\"><b>—2)</b> <i>loose, detached</i>, v. <a href=\"#\" data-headword=\"שְׁמַט\">שְׁמַט</a>.</div>","alt":["שְׁמִיטָה"]},"31712":{"h":"שְׁמִיטָּא","r":"U01464","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"שְׁמִטְּתָא\">שְׁמִטּ׳</a>.</div>","alt":["שְׁמִיטָּה","שְׁמִיטְּתָא"]},"31713":{"h":"שַׁמַּיי","r":"U01465","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁמַּאי\">שַׁמַּאי</a></div>","alt":[]},"31714":{"h":"שְׁמַיָּיא","r":"U01466","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁמַיָּא\">שְׁמַיָּא</a></div>","alt":[]},"31715":{"h":"שְׂמִיכָה","r":"U01467","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a heavy cover, cloak</i>. <span class=\"citation\">Lev. R. s. 23</span>; <span class=\"citation\">Yalk. ib. 585</span>; <span class=\"citation\">Yalk. Jud. 44</span> (explained <a href=\"#\" data-headword=\"סוּדָרָא\">סוּדְרָא</a>, <a href=\"#\" data-headword=\"מְשִׁיכְלָא\">מְשִׁיכְלָא</a>); <span class=\"citation\">ib.</span> <span dir=\"rtl\">חזרנו … ש̇מ̇י̇ כ̇ה̇ וכ׳</span> we went over the whole Bible and could not find <i>s’mikhah</i> as the name of a garment, but (it is to be interpreted,) my (God’s) name testifies for her that this man did not touch her.</div>","alt":[]},"31716":{"h":"שָׁמַיִם","r":"U01468","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> du. m. du. (b. h.) </div><div class=\"sense\"><b>1)</b> <i>heaven</i>; trnsf. <i>Heaven, God</i>. <span class=\"citation\">Gen. R. s. 1</span> <span dir=\"rtl\">הש׳ נבראו תחלה</span> the heaven was first created. <span class=\"citation\">Tam. 32ᵃ</span> top <span dir=\"rtl\">מן הש׳ לארץ וכ׳</span> is it farther from heaven to earth, or from east to west? Lam. R. introd. (R. Joh. 1) <span dir=\"rtl\">מִשְּׁמֵי מרום</span> from the high heavens. <span class=\"citation\">Ned. XI, 12</span> (<span class=\"citation\">90ᵇ</span>) <span dir=\"rtl\">ש׳ ביני לביניך</span> heaven is between me and thee (I have an unconquerable aversion to associating with thee, v. Y. ib. 42ᵈ bot., quot. s. v. <a href=\"#\" data-headword=\"רָחִיק II\"><span dir=\"rtl\">רָחִיק</span> II</a>; differ. in comment.). <span class=\"citation\">R. Hash. 19ᵃ</span> <span dir=\"rtl\">אי ש׳</span> by Heaven! <span class=\"citation\">B. Mets. 37ᵃ</span> <span dir=\"rtl\">לצאת ידי ש׳</span> to do his duty towards God (v. <a href=\"#\" data-headword=\"יָצָא\">יָצָא</a>).—<span class=\"citation\">Kidd. 40ᵃ</span>, a. e. <span dir=\"rtl\">רע לש׳</span>, v. <a href=\"#\" data-headword=\"רַע I\">רַע</a>.—<span class=\"citation\">Snh. XI, 5</span>, a. e. <span dir=\"rtl\">בידי ש׳</span>, v. <a href=\"#\" data-headword=\"מִיתָה\">מִיתָה</a>.—<span dir=\"rtl\">ירא ש׳</span>, <span dir=\"rtl\">יראת ש׳</span>, <span dir=\"rtl\">מלכות ש׳</span> &amp;c., v. respective determinants.</div>","alt":[]},"31717":{"h":"שָׁמִין I","r":"U01469","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"שְׁמִינִי\">שְׁמִינִי</a>) <i>Shamin</i>, a coin, one eighth of an Italian Isar (As). <span class=\"citation\">Kidd. 12ᵃ</span> <span dir=\"rtl\">שתי פרוטות לש׳</span> the Shamin has two P’ruṭahs; <span class=\"citation\">Tosef. B. Bath. V, 12</span> <span dir=\"rtl\">לשמן</span> ed. Zuck. (Var. <span dir=\"rtl\">לשווין</span>, corr. acc.); <span class=\"citation\">Y. Kidd. I, 58ᵈ</span> <span dir=\"rtl\">שני פרוטות שמין</span>.—Pl. <a href=\"#\" data-headword=\"שְׁמֹנִין\">שְׁמֹנִין</a>. Kidd. l. c. <span dir=\"rtl\">שני ש׳ להנץ</span> two Shamins make one Hannets (v. <a href=\"#\" data-headword=\"הַנֵּץ\">הַנֵּץ</a>); Tosef. l. c.; Y. Kidd. l. c. <span dir=\"rtl\">שני שמין ניצים</span> (corr. acc.).</div>","alt":[]},"31718":{"h":"שָׁמִין","r":"U01470","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שָׁמֵן\">שָׁמֵן</a>, <i>fat</i>. <span class=\"citation\">Targ. Y. Gen. XVIII, 8</span>. <span class=\"citation\">Ib. 7</span>; v. <a href=\"#\" data-headword=\"שְׁמַן\">שְׁמַן</a>.</div>","alt":["שְׁמֵין"]},"31719":{"h":"שְׁמֵינ־","r":"U01471","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"שְׁמֵן\">שְׁמֵנ׳</a>.</div>","alt":[]},"31720":{"h":"שמינונית","r":"U01472","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁמְנוּנִית\">שַׁמְנוּנִית</a></div>","alt":[]},"31721":{"h":"שְׁמִינִי","r":"U01473","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>eighth; one eighth</i>. Sifra Sh’mini, Milluim, beg. <span dir=\"rtl\">ש׳ למנין</span> the eighth day in the order of counting (from the initiation of the priests); <span dir=\"rtl\">ש׳ לחדש</span> the eighth day of the month. Y. Sabb. VIII, 11ᵃ bot.; <span class=\"citation\">Y. Pes. X, 37ᶜ</span> bot. <span dir=\"rtl\">חצי שמינית</span> half an eighth (of a Log); a. v. fr.—Esp. <a href=\"#\" data-headword=\"שְׁמִינִי\">שמיני</a>, or <span dir=\"rtl\">ש׳ של חג</span> <i>the eighth day of the Succoth festival</i>. <span class=\"citation\">Succ. 47ᵃ</span> <span dir=\"rtl\">אומרים זמן בש׳ של חג</span> we recite the benediction for the entrance of a festival (<a href=\"#\" data-headword=\"זְמָן\">זְמָן</a>) on the eighth day &amp;c. Ib., a. fr. <span dir=\"rtl\">ש׳ רגל וכ׳</span> the eighth day is a festival for itself; a. fr.—<i>Pl. fem.</i> <span dir=\"rtl\">שְׁמִינִיּוֹת</span>. <span class=\"citation\">Yalk. Esth. 1048</span> <span dir=\"rtl\">ארבעים ש׳</span> (not <a href=\"#\" data-headword=\"שמציות\">שמציות</a>) forty eighths (of a Kab), v. <a href=\"#\" data-headword=\"תּוֹמָן\">תּוֹמָן</a>.</div>","alt":["שְׁמִינִית"]},"31722":{"h":"שְׁמִיעַ","r":"U01474","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁמַע I\"><span dir=\"rtl\">שְׁמַע</span> I</a></div>","alt":[]},"31723":{"h":"שָׁמִיעָא","r":"U01475","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <a href=\"#\" data-headword=\"שְׁקִיעַיָּא\">שְׁמִיעַיָּא</a>, v. <a href=\"#\" data-headword=\"שָׁמוֹעָא\">שָׁמוֹעָא</a>.</div>","alt":[]},"31724":{"h":"שְׁמִיעָא","r":"U01476","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"שְׁמִיעָה\">next w.</a> <span class=\"citation\">Targ. Y. I Deut. XXXII, 1</span> <span dir=\"rtl\">יהב ש׳ וכ׳</span> ascribed hearing to &amp;c. (Y. II <a href=\"#\" data-headword=\"שְׁמוּעֲתָא\">שמועתא</a>).</div>","alt":[]},"31725":{"h":"שְׁמִיעָה","r":"U01477","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁמַע\">שָׁמַע</a>) <i>hearing, listening</i>. <span class=\"citation\">R. Hash. 25ᵇ</span> <span dir=\"rtl\">לא תהא ש׳ גדולה מראייה</span> hearing (the statement of witnesses) ought not to be of greater legal value than seeing (if the judges themselves have seen the new phase of the moon). <span class=\"citation\">Y. Sabb. VI, 8ᶜ</span> bot. <span dir=\"rtl\">הולכין אחר שְׁמִיעַת בת קול</span> you may be guided by what you hear, considering it as a divine voice (it is not a divination practice to be forbidden). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נלך בתר שמיעת בת קול</span> let us be guided by what we shall hear. <span class=\"citation\">Cant. R. to II, 3</span> <span dir=\"rtl\">ישראל … הקדימו אמנה לש׳</span> the Israelites in Egypt advanced belief to hearing (<span class=\"citation\">Ex. IV, 31</span>); <span dir=\"rtl\">בסיני … עשייה לש׳</span> at Sinai they advanced doing to hearing (ib. XXIV, 7; <span class=\"citation\">Sabb. 88ᵃ</span>, <span class=\"citation\">Gitt. 7ᵃ</span> <span dir=\"rtl\">נעשה לנשמע</span>). <span class=\"citation\">Nidd. 31ᵃ</span> <span dir=\"rtl\">שמיעת האוזן</span> the faculty of hearing; a. fr.</div>","alt":[]},"31726":{"h":"שָׁמִיר","r":"U01478","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>pointed,</i>] <i>thorn; flint, diamond</i>; (in legend) <i>shamir</i>, a worm that cuts stones with its glance. <span class=\"citation\">Sot. IX, 12</span> <span dir=\"rtl\">משחרב … בטל הש׳</span> with the destruction of the Temple the <i>shamir</i> ceased to exist. <span class=\"citation\">Ib. 48ᵇ</span>; <span class=\"citation\">Tosef. ib. XV, 1</span>; Y. ib. IX, 24ᵇ; a. e.</div>","alt":[]},"31727":{"h":"שָׁמִיר ²","r":"U01479","html":"<div class=\"sense\"><b>1)</b> <i>flint</i>. <span class=\"citation\">Targ. Y. II, Deut. XXXII, 13</span> (h. text <a href=\"#\" data-headword=\"חַלָּמִישׁ\">חלמיש</a>). <span class=\"citation\">Targ. Ps. CXIV, 8</span>. <span class=\"citation\">Targ. Job XXVIII, 9</span>.</div><div class=\"sense\"><b>—2)</b> <i>diamond; shamir</i>. <span class=\"citation\">Targ. Ez. III, 9</span>. <span class=\"citation\">Targ. Zech. VII, 12</span>; a. e.—<span class=\"citation\">Gitt. 68ᵃ</span> <span dir=\"rtl\">איכא ש׳ דאייתיה וכ׳</span> there is the <i>shamir</i> which Moses used for the jewels of the Ephod. <span class=\"citation\">Ib.ᵇ</span> בעינא … ש׳ I want to build the Temple, and want the <i>shamir</i>; a. e.</div>","alt":["שָׁמִירָא"]},"31728":{"h":"שְׁמִירָה I","r":"U01480","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁמַר\">שָׁמַר</a>) <i>watching, guarding</i>. <span class=\"citation\">Y. Maasr. II, 49ᵈ</span> bot. <span dir=\"rtl\">חצר בית ש׳</span> a well-guarded court (= <span dir=\"rtl\">חצר המשתמרת</span>, v. <a href=\"#\" data-headword=\"חָצֵר\">חָצֵר</a>). <span class=\"citation\">Y. Sabb. II, 5ᵇ</span> top <span dir=\"rtl\">אינו צריך ש׳</span> (omit <span dir=\"rtl\">ליה</span>) is not in need of special guard (against dangers). <span class=\"citation\">B. Mets. 42ᵃ</span>; <span class=\"citation\">Pes. 31ᵇ</span>, v. <a href=\"#\" data-headword=\"כֶּסֶף\">כֶּסֶף</a>. <span class=\"citation\">B. Kam. I, 1</span> <span dir=\"rtl\">שְׁמִירָתָן עליך</span> thou art bound to guard them. <span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">כל שחבתי בשְׁמִירָתוֹ</span>, v. <a href=\"#\" data-headword=\"חוּב\">חוּב</a> h. <span class=\"citation\">Ib. 4ᵃ</span> <span dir=\"rtl\">אדם שְׁמִירת גופו עליו הוא</span> a human being is his own guard (the employer has no responsibility for injury done by the employee).—<span class=\"citation\">Num. R. s. 4</span><sup>4</sup> <span dir=\"rtl\">יש פקידה לש׳</span> trust (the root <span dir=\"rtl\">פקד</span>) is used in the sense of guarding (taking charge). <span class=\"citation\">Ex. R. s. 25</span>, end <span dir=\"rtl\">על שמירת יום וכ׳</span> the son of David comes as a reward for the observance of one Sabbath day; a. fr.—Pl. <a href=\"#\" data-headword=\"שְׁמִירָמוֹת\">שְׁמִירוֹת</a>. <span class=\"citation\">Yalk. Ps. 816</span> (ref. to <span dir=\"rtl\">שמרות</span>, <span class=\"citation\">Ps. LXXVII, 5</span>) <span dir=\"rtl\">כל שְׁמִירוֹתַי בלילה</span> all my watchings (waiting for help) are held by night; Midr. Till. to Ps. l. c. <a href=\"#\" data-headword=\"שמרותי\">שמרותי</a> (ed. Bub. <span dir=\"rtl\">מידותי</span>, corr. acc.).</div>","alt":[]},"31729":{"h":"שְׁמִירָה II","r":"U01481","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>Sh’mirah</i>, wife of Nebuchadnezzar. <span class=\"citation\">Lev. R. s. 19</span>, end <span dir=\"rtl\">רב הונא אמר ש׳ שמה</span> Rab H. says, her name was Sh’mirah; R. A. says, <span dir=\"rtl\">שְׁמִירָמוֹת שמה</span> her name was Sh’miramoth; the Rabbis say <span dir=\"rtl\">שְׁמִירַעַם שמה</span> her name was Sh’miraʿam. <span class=\"citation\">Yalk. Jer. 309</span> <span dir=\"rtl\">עד שהגיעו לש׳ אשתו וכ׳</span> (some ed. <a href=\"#\" data-headword=\"שְׁמִירָמוֹת\">שְׁמִירַת</a>) until they came to Sh., the wife &amp;c.; Tanḥ. <span class=\"citation\">Vayikra 6</span> <a href=\"#\" data-headword=\"שְׁמוּרַת\">שְׁמוּרַת</a>.</div>","alt":[]},"31730":{"h":"שמירה","r":"U01482","html":"<div class=\"sense\">, <span class=\"citation\">Y. Dem. I, 21ᵈ</span> top, v. <a href=\"#\" data-headword=\"שׁוּמְּרָה\">שׁוּמְּרָה</a></div>","alt":[]},"31731":{"h":"שמירון","r":"U01483","html":"<div class=\"sense\">, <span class=\"citation\">Y. Keth. II, 26ᶜ</span> bot., v. <a href=\"#\" data-headword=\"סִימִירוֹן\">סִימִירוֹן</a></div>","alt":[]},"31732":{"h":"שְׁמִירָמוֹת","r":"U01484","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁמִירָה II\"><span dir=\"rtl\">שְׁמִירָה</span> II</a></div>","alt":["שְׁמִירַעַם","שְׁמִירַת"]},"31733":{"h":"שַׁמִּית","r":"U01485","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁמַת\">שְׁמַת</a></div>","alt":[]},"31734":{"h":"שַׁמִּיתָא","r":"U01486","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמַת\">שְׁמַת</a>) <i>excommunicated, accursed.</i> <i>—</i> Pl. <span dir=\"rtl\">שַׁמִּיתִין</span>. <span class=\"citation\">Targ. Y. Deut. VII, 26</span>. Ib. <a href=\"#\" data-headword=\"שַׁמְתִּית\">שַׁמְתִּין</a>, v. <a href=\"#\" data-headword=\"שַׁמְתָּא\">שַׁמְתָּא</a>.</div>","alt":[]},"31735":{"h":"שַׁמְכָּא","r":"U01487","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"שׁוּם III\"><span dir=\"rtl\">שׁוּם</span> III</a>) <i>onion</i>. <span class=\"citation\">Keth. 60ᵇ</span> Ar. (ed. <a href=\"#\" data-headword=\"כָּמְכָא\">כמכא</a>; Alf. <span dir=\"rtl\">שמכי</span>).—Pl. <span dir=\"rtl\">שַׁמְכֵּי</span>. <span class=\"citation\">Sabb. 110ᵇ</span> top <span dir=\"rtl\">ש׳ פרסאי</span> Persian (large) onions. <span class=\"citation\">Arakh. 19ᵃ</span> <span dir=\"rtl\">באתרא דתקלי ש׳ וכ׳</span> where they sell onions by the weight, he (that dedicates the weight of a certain person) can acquit himself of his vow even with onions. <span class=\"citation\">Kidd. 52ᵇ</span>, v. <a href=\"#\" data-headword=\"מוֹזָא\">מוֹזָא</a>. <span class=\"citation\">Snh. 109ᵇ</span></div>","alt":[]},"31736":{"h":"שמלאי","r":"U01488","html":"<div class=\"sense\">, <span class=\"citation\">Y. Kidd. I, 61ᵈ</span> top, v. <a href=\"#\" data-headword=\"שַׁלְמָאָה\">שַׁלְמָאָה</a></div>","alt":[]},"31737":{"h":"שַׂמְלַאי","r":"U01489","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Samlai</i>, name of several Amoraim. [Tradit. pronunc. <i>Simlai</i>.] <span class=\"citation\">Y. Sabb. I, 3ᵈ</span>; <span class=\"citation\">Y. Ab. Zar. II, 41ᵈ</span> bot. <span dir=\"rtl\">ש׳ הדרומי</span>; Bab. <span class=\"citation\">Ab. Zar. 36ᵃ</span> <span dir=\"rtl\">ש׳ לודאה</span>; <span class=\"citation\">ib. 37ᵃ</span> (attendant of R. Judah han-Nasi). <span class=\"citation\">Pes. 62ᵇ</span>. <span class=\"citation\">Ib. 121ᵇ</span>. <span class=\"citation\">Y. Shek. IV, 48ᵃ</span> top.—<span class=\"citation\">B. Bath. 111ᵃ</span> (Ms. H. <span dir=\"rtl\">שמלא</span>). <span class=\"citation\">Y. Meg. I, 72ᶜ</span> bot.; <span class=\"citation\">Y. Taan. II, 65ᵈ</span> bot. <a href=\"#\" data-headword=\"שַׂמְלַאי\">שמליי</a>; <span class=\"citation\">Koh. R. to III, 14</span>, v. <a href=\"#\" data-headword=\"בֵּיר\">בֵּירָא</a> 3; a. fr.—V. Fr. M’bo, p. 127ᵃ</div>","alt":["שַׂמְלַיי"]},"31738":{"h":"שִׂמְלָה","r":"U01490","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>sheet, cover, garment</i>. <span class=\"citation\">B. Mets. II, 5</span> (<span class=\"citation\">27ᵃ</span>) (ref. to <span dir=\"rtl\">שלמה</span>, <span class=\"citation\">Ex. XXII, 8</span>) <span dir=\"rtl\">אף הש׳ היתה בכלל וכ׳</span> the case of the garment would have been included (as <a href=\"#\" data-headword=\"אֲבֵדָה\">אֲבֵדָה</a>), and why is it specified? <span dir=\"rtl\">מה ש׳ מיוחדת וכ׳</span> as the garment is individual property and can be identified by certain marks &amp;c. Mekh. Mishp., s. 13, v. <a href=\"#\" data-headword=\"חָוַר\">חָוַר</a>; <span class=\"citation\">Sifré Deut. 237</span>. <span class=\"citation\">Keth. 46ᵃ</span> (ref. to <span class=\"citation\">Deut. XXII, 17</span>), v. <a href=\"#\" data-headword=\"בָּרַר\">בָּרַר</a>. Ib. <span dir=\"rtl\">ש׳ ממש</span> it means the sheet in its real sense. Ib. <span dir=\"rtl\">פרשו מה ששָ֗ם̇ לָ֗הּ֗</span> they spread (the refutation of) what he charged her with. <span class=\"citation\">Midr. Till. to Ps. XIX</span> <span dir=\"rtl\">מה הש׳ הזאת</span> what is this sheet (curtain) made of?; <span class=\"citation\">Yalk. ib. 672</span> <span dir=\"rtl\">מה היא הש׳ זו</span>. <span class=\"citation\">Ḥag. 14ᵃ</span> (ref. to <span class=\"citation\">Is. III, 6</span>) [read:] <span dir=\"rtl\">דברים … מתכסין בהם כש׳ ישנן וכ׳</span> (v. Rabb. D. S. a. l.) things with which people cover themselves as with a garment (faith in divine protection, differ. in Rashi) are in thy possession; <span class=\"citation\">Sabb. 119ᵇ</span>; <span class=\"citation\">Yalk. Is. 261</span>; Yalk. Jer. 275; a. e.—Midr. Sam. ch. XX <span dir=\"rtl\">שמלתם</span>, read: <span dir=\"rtl\">שבול׳</span>, v. <a href=\"#\" data-headword=\"שִׁיבּוֹלֶת\">שִׁיבּוֹלֶת</a>.]—V. <a href=\"#\" data-headword=\"שַׂלְמָה\">שַׂלְמָה</a>.</div>","alt":[]},"31739":{"h":"שָׁמֵם","r":"U01491","html":"<div class=\"sense\"> (b. h.) [<i>to stand still,</i>] <i>to be astonished; to be waste</i>. <span class=\"citation\">Tosef. Sot. XV, 10</span> <span dir=\"rtl\">ונמצא ישראל ש׳ וזרע וכ׳</span> and as a consequence Israel will be laid waste, and the seed of Abraham cease. <span class=\"citation\">Y. Bets. II, 61ᶜ</span> top <span dir=\"rtl\">פעם … ומצא אותה שׁוֹמֶמֶת</span> once he entered the Temple court and found it deserted; <span dir=\"rtl\">יָשֹׁמּוּ בתיהם … שׁהֵשֵׁימּוּ וכ׳</span> (or <span dir=\"rtl\">יִשַּׁמּוּ</span>) deserted be the homes of those who caused the house of our God to be laid waste; <span class=\"citation\">Y. Ḥag. II, 78ᵃ</span> bot. <span dir=\"rtl\">שׁהֵישַׁמּוּ</span>. <span class=\"citation\">Cant. R. to V, 5</span> <span dir=\"rtl\">ראה המדינה שוממת</span> he (Cyrus) saw that the country was ruined. <span class=\"citation\">Y. Ber. IV, 8ᵃ</span> <span dir=\"rtl\">ההרוסה והשׁוֹמֵמָה</span> destroyed and deserted. <span class=\"citation\">Meg. III, 3</span> (ref. to <span class=\"citation\">Lev. XXVI, 31</span>) <span dir=\"rtl\">קדושתן … שׁוֹמֵמִין</span> (Y. ed. <span dir=\"rtl\">שׁוֹמֵימִין</span>) they remain holy, even when they lie in ruins. Lam. R. introd. (R. Joḥ. 1) <span dir=\"rtl\">שָׁמְמָה עלי נפשי</span> my soul within me is waste (mourns); a. fr.</div><div class=\"sense\"><b>Pi. שִׁמֵּם</b> <div class=\"sense\"><i>to lay waste, ruin; to confound</i>. <span class=\"citation\">Yalk. Prov. 959</span> <span dir=\"rtl\">אם זכה משמחו ואם לאו מְשַׁמְּמוֹ</span> if a man is good, it (dreaming of wine) means joy to him, if not, it means confounding.—Part. pass. <a href=\"#\" data-headword=\"מְשׁוּמָּד\">מְשׁוּמָּם</a>; f. <span dir=\"rtl\">מְשׁוּמֶּמֶת</span>. <span class=\"citation\">Tosef. Keth. VII, 10</span> <span dir=\"rtl\">מש׳ היא</span> (ed. Zuck. <a href=\"#\" data-headword=\"שַׁעֲמוּמִית\">שעמומית</a>) she (my daughter) is confused in her mind; v. <a href=\"#\" data-headword=\"שִׁעְמֵם\">שִׁעֲמֵם</a>, <a href=\"#\" data-headword=\"שַׁעֲמוּמִית\">שַׁעֲמוּמִית</a>.</div></div><div class=\"sense\"><b>Hif. הֵשֵׁם</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"שִׂמְלָה\">same</a>. <span class=\"citation\">Gen. R. s. 26</span> (play on <span dir=\"rtl\">אנשי השם</span>, <span class=\"citation\">Gen. IV, 4</span>) <span dir=\"rtl\">שׁהֵשִׁימּוּ את העולם ושהוּשַׁמּוּ … שׁיִשּׁוֹם</span> they confounded the world, and they were ruined (driven) out of the world, and caused the world to be laid waste. Y. Bets. l. c.; Y. Ḥag. l. c., v. supra.</div></div><div class=\"sense\"><b>Nif. נָשַׁם</b> <div class=\"sense\">, <i>Hof.</i> הוּשַׁם <i>to be laid waste, ruined</i>. Gen. R. l. c., v. supra. <span class=\"citation\">Sot. IX, 15</span>; <span class=\"citation\">Cant. R. to II, 13</span> <span dir=\"rtl\">והגבלן יִשּׁוֹם</span>, v. <a href=\"#\" data-headword=\"גַּבְלָן\">גַּבְלָן</a>. Y. Bets. l. c.; Y. Ḥag. l. c., v. supra.</div></div><div class=\"sense\"><b>Hithpol. הִשְׁתּוֹמֵם</b> <div class=\"sense\"><b>1)</b> <i>to be astounded</i>. <span class=\"citation\">Gen. R. s. 4</span>, end (expl. <span dir=\"rtl\">ש̇מ̇י̇ם̇</span>) <span dir=\"rtl\">שהבריות מִשְׁתּוֹמְמִים … של אש̇ הן של מ̇י̇ם̇ הן</span> men wonder at them, (asking) are they of fire? are they of water?</div><div class=\"sense\"><b>—2)</b> <i>to be waste, ruined</i>. <span class=\"citation\">Kidd. 66ᵃ</span> <span dir=\"rtl\">והיה העולם מִשְׁתּוֹמֵם וכ׳</span> and the (Jewish) world was ruined (demoralized), until Simon b. Sh. came and restored the Law &amp;c. <span class=\"citation\">Sabb. 33ᵃ</span> <span dir=\"rtl\">והדרכים מִשְׁתּוֹמְמִין</span> and the roads are desolate; a. e.</div></div>","alt":[]},"31740":{"h":"שְׁמַם","r":"U01492","html":"<div class=\"sense\"><b>Ithpa. אִשְׁתְּמַם</b> <div class=\"sense\"><b>1)</b> <i>to be desolate</i>. <span class=\"citation\">Targ. Lam. IV, 5</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be confounded, mad</i>. <span class=\"citation\">Targ. I Sam. XXI, 14</span> (h. text <span dir=\"rtl\">ויתהלל</span>).</div></div><div class=\"sense\"><b>Ithpol. אִשְׁתּוֹמֵם</b> <div class=\"sense\"><i>to be perplexed</i>. <span class=\"citation\">Ḥull. 21ᵃ</span> <span dir=\"rtl\">א׳ כשעה חדא</span> (fr. <span class=\"citation\">Dan. IV, 16</span>) he was perplexed for a moment (knew not what to answer).</div></div>","alt":[]},"31741":{"h":"שַׁמָּם","r":"U01493","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמַם\">preced.</a>) <i>confounded, demented</i>.—Pl. <span dir=\"rtl\">שַׁמָּמִין</span>. <span class=\"citation\">Cant. R. to IV, 7</span>.</div>","alt":[]},"31742":{"h":"שְׁמָמָה","r":"U01494","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שַׁמָּם\">preced.</a> wds.) <i>waste, desolation</i>. <span class=\"citation\">M. Kat. 17ᵃ</span>, v. <a href=\"#\" data-headword=\"שַׁמְתָּא\">שַׁמְתָּא</a>.—Pl. <span dir=\"rtl\">שְׁמָמוֹת</span>, constr. <span dir=\"rtl\">שִׁמְמוֹת</span>. <span class=\"citation\">Cant. R. to III, 4</span> (ref. to <span class=\"citation\">Is. XXI, 1</span>) <span dir=\"rtl\">דרך ש׳ מדבר בא</span> he (Nebuchadnezzar) came by the way of the deserts of the wilderness. Lam. R. introd., end (in an obscure passage) <span dir=\"rtl\">מש׳ הארץ</span> from the deserts of the land.</div>","alt":[]},"31743":{"h":"שְׂמָמִי","r":"U01495","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְמָמִית\">סְמָמִית</a>, <a href=\"#\" data-headword=\"סְמָמִיתָא\"><a href=\"#\" data-headword=\"סְמָמִיתָא\">סְמָמִיתָא</a>.</a></div>","alt":["שְׂמָמִית","שְׂמָמִיתָא","שְׁ׳"]},"31744":{"h":"שָׁמֵן I","r":"U01496","html":"<div class=\"sense\"> (b. h.) [<i>to be smooth,</i>] <i>to be fat</i>.</div><div class=\"sense\"><b>Hif. הִשְׁמִין</b> <div class=\"sense\"><i>to grow fat, improve</i>. Y. B. Kam. IX, beg. 6ᵈ <span dir=\"rtl\">גזל כחושה והִשְׁמִינָה</span> if he took forcibly a lean animal, and it grew fat (in his possession); <span class=\"citation\">Tosef. B. Kam. VII, 17</span>; Bab. <span class=\"citation\">B. Kam. 65ᵃ</span>; a. e.</div></div><div class=\"sense\"><b>Hithpa. הִשְׁתַּמֵּן</b> <div class=\"sense\"><i>to become smooth, bright; to glisten</i>. <span class=\"citation\">Gen. R. s. 34</span> <span dir=\"rtl\">כל שהוא … היא מִשְׁתַּמֶּנֶת</span> the more he beats it (the flax), the more it will glisten; <span class=\"citation\">Yalk. ib. 95</span>; <span class=\"citation\">Yalk. Ps. 654</span>.</div></div><div class=\"sense\"><b>Pi. שִׁמֵּן</b> <div class=\"sense\"><b>1)</b>  (denom. of (denom. of <a href=\"#\" data-headword=\"שֶׁמֶן\">שֶׁמֶן</a>) <i>to oil</i>. <span class=\"citation\">Men. 23ᵃ</span> <span dir=\"rtl\">קומץ … שׁשִׁמְּנוֹ וכ׳</span> the handful of the sinner’s meal-offering on which he (the priest) put oil, … has become unfit for the altar; <span class=\"citation\">Yalk. Lev. 474</span>.</div><div class=\"sense\"><b>—2)</b> <i>to smooth, level;</i> ש׳ בין <i>to compromise to average</i>. <span class=\"citation\">B. Mets. 87ᵃ</span> <span dir=\"rtl\">השוכר … מְשַׁמְּנִין ביניהם</span> if one hires a laborer, saying, I will pay you as much as one or two of the inhabitants of the place get: he may pay him the lowest wages …; the scholars say, you compromise between them, i.e. you make him pay the average wages. <span class=\"citation\">B. Bath. VII, 4</span> <span dir=\"rtl\">האומר … משמנין ביניהם וכ׳</span> if one says to his neighbor, I sell thee one-half of my field (and one part is better than the other), we compromise between them, i.e. the field is divided into two portions of equal value, but the purchaser must take whichever portion the seller may assign to him; <span dir=\"rtl\">חציה בדרום … משמנין וכ׳</span> if he says, I sell thee half of the field on the south side, we compromise between them, and he gets his portion on the south side; expl. ib. 107ᵇ משמנין … לדמי ‘we compromise’ means according to value. <span class=\"citation\">Bekh. II, 6</span>, sq. <span dir=\"rtl\">משמנין ביניהם</span> we compromise between them, i.e. the priest takes the inferior of the twin animals, and the difference in value remains under litigation; expl. <span class=\"citation\">ib. 18ᵃ</span> מהו משמנין שומן יהא ביניהן <i>m’shamm’nin</i> means, the fat one (the difference of value) remains to be decided &amp;c., v. <a href=\"#\" data-headword=\"שׁוּמָן\">שׁוּמָן</a>.</div></div>","alt":[]},"31745":{"h":"שְׁמֵן","r":"U01497","html":"<div class=\"sense\"><b>Ithpa. אִשְׁתַּמֵּן</b> <div class=\"sense\"><i>to grow fat</i>. <span class=\"citation\">Gen. R. s. 28</span> <span dir=\"rtl\">אמר ליה זיל ואש׳ … ומִשְׁתַּמֵּן וכ׳</span> he said to the bird, go and grow fat, and come again, and it went and grew fat, and came again; Yalk. Zeph. 566.</div></div>","alt":[]},"31746":{"h":"שָׁמֵן","r":"U01498","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שְׁמֵן\">preced.</a>) <i>fat, rich</i>. <span class=\"citation\">Keth. 61ᵃ</span> <span dir=\"rtl\">בשר ש׳</span> fat meat. <span class=\"citation\">Pes. 42ᵃ</span>. <span class=\"citation\">Ḥull. 45ᵇ</span> גדי שמן Rashi (ed. <span dir=\"rtl\">גדי שמינה</span>, v. Rabb. D. S. a. l. note 8) a fat kid. <span class=\"citation\">Y. B. Kam. IX, beg. 6ᵈ</span> <span dir=\"rtl\">גזל ש׳ והכחישה וכ׳</span> if he took by force a fat animal, and it became lean &amp;c., v. <a href=\"#\" data-headword=\"שׁוּמָן\">שׁוּמָן</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"שְׁמֹנִים\">שְׁמֵנִים</a>, <a href=\"#\" data-headword=\"שָׁמֵן\">שְׁמֵי׳</a>; <span dir=\"rtl\">שְׁמֵנוֹת</span>, <a href=\"#\" data-headword=\"שָׁמֵן\">שְׁמֵי׳</a>. <span class=\"citation\">Gen. R. s. 66</span> <span dir=\"rtl\">דגים ש׳ יתיר מדאי</span> exceedingly fat fish. <span class=\"citation\">Num. R. s. 16</span><sup>12</sup> <span dir=\"rtl\">אם … אם ש׳</span> whether its fruits are light or rich; <span class=\"citation\">ib.</span> <span dir=\"rtl\">אם של צונמא … ש׳</span>, v. <a href=\"#\" data-headword=\"צוֹנָם\">צוֹנָם</a>; Tanḥ. Sh’laḥ 6; a. fr.</div>","alt":["שְׁמֵנָה","שְׁמֵי׳"]},"31747":{"h":"שְׁמַן","r":"U01499","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁמֵן\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>cream</i>. <span class=\"citation\">Targ. O. Gen. XVIII, 8</span> (Y. <span dir=\"rtl\">לוואי שָׁמִין</span>; h. text <a href=\"#\" data-headword=\"חֶמְאָה\">חמאה</a>). <span class=\"citation\">Targ. Ps. LV, 22</span> <span dir=\"rtl\">ש׳ דגובנין</span> (h. text <span dir=\"rtl\">מחמאות</span>).</div><div class=\"sense\"><b>—2)</b> <i>fat.</i> <span class=\"citation\">Targ. Is. XXX, 23</span>. <span class=\"citation\">Targ. Y. Gen. XVIII, 7</span> <a href=\"#\" data-headword=\"שָׁמִין\">שְׁמֵין</a>.—V. <a href=\"#\" data-headword=\"שׁוּמְנָא\">שׁוּמְנָא</a>.</div>","alt":[]},"31748":{"h":"שֶׁמֶן","r":"U01500","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שְׁמַן\">preced.</a> wds.) <i>oil, fat</i>. <span class=\"citation\">Sabb. II, 1</span> <span dir=\"rtl\">ש׳ שרפה</span> oil of T’rumah which is condemned to be burnt on account of contamination; <span dir=\"rtl\">ש׳ קיק</span>, v. <a href=\"#\" data-headword=\"קִיק I\">קִיק</a>. Ib. 2 <span dir=\"rtl\">ש׳ דגים</span> fish-oil; <span dir=\"rtl\">ש׳ אגוזים</span> nut-oil &amp;c. Ib. 17ᵇ <span dir=\"rtl\">שׁמְנָן</span> their oil, manufactured by gentiles; <span class=\"citation\">Ab. Zar. 36ᵃ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ש׳ רב יהודה וכ׳</span> as to gentiles’ oil, R. Judah and his court voted on it and permitted it. <span class=\"citation\">Pes. 83ᵇ</span>; <span class=\"citation\">Ḥull. 91ᵃ</span>; <span class=\"citation\">92ᵇ</span> <span dir=\"rtl\">שַׁמְנוֹ</span> the fat surrounding the nervus ischiadicus, v. <a href=\"#\" data-headword=\"שׁוּמָן\">שׁוּמָן</a>; a. fr.—עֵץ ש׳ <i>pine-wood</i>, v. <a href=\"#\" data-headword=\"עֵץ\">עֵץ</a>.—Pl. <a href=\"#\" data-headword=\"שְׁמֹנִים\">שְׁמָנִים</a>, <a href=\"#\" data-headword=\"שְׁמֹנִין\">שְׁמָנִין</a>. <span class=\"citation\">Sabb. II, 2</span> <span dir=\"rtl\">מתירין בכל הש׳</span> allow all kinds of oil to be used for Sabbath lights. Ib. 26ᵃ <span dir=\"rtl\">כל הש׳ יפין וכ׳</span> all oils are good for ink, but olive oil is the best. <span class=\"citation\">Y. Bicc. I, 64ᵇ</span> top; a. fr.</div>","alt":[]},"31749":{"h":"שִׁמָּן","r":"U01501","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Shimmon</i>, v. <a href=\"#\" data-headword=\"שִׁמְעוֹן\">שִׁמְעוֹן</a>.</div>","alt":[]},"31750":{"h":"שְׁמֵנָא","r":"U01502","html":"<div class=\"sense\"> c. (v. <a href=\"#\" data-headword=\"שָׁמִין I\"><span dir=\"rtl\">שָׁמִין</span> II</a>) <i>fat, rich</i>. <span class=\"citation\">Targ. Y. II, Gen. XLIX, 20</span> (ed. Vien. <a href=\"#\" data-headword=\"שְׁמֵנָה\">שְׁמֵינָה</a>); a. e.—<span class=\"citation\">Lam. R. to III, 20</span>, v. <a href=\"#\" data-headword=\"חֲשִׁיךְ ²\"><span dir=\"rtl\">חֲשִׁיךְ</span> II</a>. <span class=\"citation\">B. Bath. 22ᵃ</span> <span dir=\"rtl\">בשרא ש׳</span> fat meat; a. fr.—Pl. <a href=\"#\" data-headword=\"שְׁמֹנִין\">שְׁמֵנִין</a>, <span dir=\"rtl\">שְׁמֵנַיָּא</span>, <a href=\"#\" data-headword=\"שְׁמָנִי\">שְׁמֵנֵי</a>, <a href=\"#\" data-headword=\"שָׁמֵן\">שְׁמֵי׳</a>. <span class=\"citation\">Targ. Y. I Deut. VI, 3</span>. Targ. Y. I Gen. l. c. <span class=\"citation\">Targ. Y. I Deut. XXXII, 14</span>, <span class=\"citation\">Targ. Y. II, Deut. XXXII, 14</span>, v. <a href=\"#\" data-headword=\"לְוָואֵי\">לְוָואֵי</a>. <span class=\"citation\">Targ. I Sam. XV, 9</span> (ed. Wil. <a href=\"#\" data-headword=\"שָׁמִיר\">שַׁמִי׳</a>); a. fr.—<span class=\"citation\">Targ. Gen. IV, 4</span> <span dir=\"rtl\">משְׁמִינֵיהֶן</span> ed. Berl. (ed. Vien. <span dir=\"rtl\">משַׁמִּנְהוֹן</span>; ed. Lsb. <span dir=\"rtl\">משׁמְנִינֵי׳</span>).—<span class=\"citation\">Gen. R. s. 22</span> (interpret. <span dir=\"rtl\">מחלבהן</span>, <span class=\"citation\">Gen. IV, 4</span>) <span dir=\"rtl\">מן שְׁמֵנֵיהוֹן</span> from the fat among them; Yalk. ib. 35; Y. Meg. I, 72ᵇ bot. <span dir=\"rtl\">מן שְׁמֵינֵי׳</span>; <span class=\"citation\">Num. R. s. 13</span>, beg.; <span class=\"citation\">Lev. R. s. 9</span>; <span class=\"citation\">Cant. R. to IV, 16</span>. <span class=\"citation\">Yalk. Gen. 115</span>; <span class=\"citation\">Gen. R. s. 67</span> (ref. to <span dir=\"rtl\">משמני</span>, <span class=\"citation\">Gen. XXVII, 39</span>) <span dir=\"rtl\">מן ש׳ דארעא</span> of the fat (the rulers or the rich men) of the land. Ib. [read:] <span dir=\"rtl\">מן הן מתעבדא ארעא שמינא דעבדא שמינין מן טלא</span> wherefrom does the earth become rich so that it begets rich men? From the dew; a. fr.</div>","alt":["שְׁמֵי׳"]},"31751":{"h":"שְׁמֵנָה","r":"U01503","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁמֵן I\"><span dir=\"rtl\">שָׁמֵן</span> II</a></div>","alt":[]},"31752":{"h":"שְׁמֹנֶה","r":"U01504","html":"<div class=\"sense\"> (b. h.) <i>eight</i>. <span class=\"citation\">Kidd. 30ᵃ</span>, v. <a href=\"#\" data-headword=\"פָּסוּק\">פָּסוּק</a>. <span class=\"citation\">Men. 30ᵃ</span> <span dir=\"rtl\">ש׳ פסוקים שבתורה</span> the last eight verses of the Pentateuch. <span class=\"citation\">Yoma VII, 5</span> <span dir=\"rtl\">כהן … בש׳ כלים וכ׳</span> the high priest officiates in eight garments, and the common priest in four. <span class=\"citation\">Gen. R. s. 98</span> (play on <span dir=\"rtl\">שמנה</span>, <span class=\"citation\">Gen. XLIX, 20</span>) <span dir=\"rtl\">שהוא מעמיד בגדי ש׳</span> he (Asher) raises those who wear eight garments (marrying his dowered daughters into priestly families); a. v. fr.—ש׳ עשרה <i>eighteen</i>. Lam. R. introd. (R. <span class=\"citation\">Josh. 2</span>) <span dir=\"rtl\">ש׳ ע׳ שנה היתה בת וכ׳</span> for eighteen years in succession a voice came forth to Nebuchadnezzar &amp;c.; a. fr.—Esp. <span dir=\"rtl\">ש׳ עשרה</span> (with or sub. <span dir=\"rtl\">ברכות</span>; abbrev. <span dir=\"rtl\">ש&quot;ע</span>) <i>the eighteen benedictions of the daily prayer</i> <span dir=\"rtl\">(תפלה</span>). <span class=\"citation\">Ber. IV, 3</span> <span dir=\"rtl\">בכל יום … ש&quot;ע וכ׳</span> on every ordinary day one must recite the eighteen benedictions &amp;c.; <span dir=\"rtl\">מעין ש&quot;ע</span> an abstract of the eighteen &amp;c. Tosef. ib. III, 25 <span dir=\"rtl\">ש&quot;ע … כנגד ש׳ ע׳ הזכרות וכ׳</span> the eighteen benedictions … correspond to the eighteen invocations of the Divine Name in <i>habu</i> &amp;c. (<span class=\"citation\">Ps. XXIX</span>); <span class=\"citation\">Ber. 28ᵇ</span>. Ib.; <span class=\"citation\">Meg. 17ᵇ</span> <span dir=\"rtl\">הסדיר ש&quot;ע וכ׳</span>, v. <a href=\"#\" data-headword=\"סָדַר\">סָדַר</a>. <span class=\"citation\">Ab. V, 21</span>, v. <a href=\"#\" data-headword=\"חוּפָּה\">חוּפָּה</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"שְׁמֹנִים\">שְׁמֹנִים</a>, <a href=\"#\" data-headword=\"שְׁמוּעָא\">שְׁמוֹ׳</a> <i>eighty</i>. Kidd. l. c. Ab. l. c. <a href=\"#\" data-headword=\"שַׁלְקוּת\">בן ש׳</a> at the age of eighty years; a. fr.</div>","alt":["שְׁמֹנָה","שְׁמוֹ׳"]},"31753":{"h":"שַׁמְנוּנִית","r":"U01505","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁמֵן\">שָׁמֵן</a>) <i>fatty, oily substance</i>. <span class=\"citation\">Y. Meg. I, 71ᵃ</span> <span dir=\"rtl\">כדי להעביר ש׳ וכ׳</span> in order to remove the fat from it (the knife); <span class=\"citation\">Y. Bets. III, end, 62ᵇ</span> <span dir=\"rtl\">שמינ׳</span> (corr. acc.); Bab. <span class=\"citation\">Bets. 28ᵃ</span> <a href=\"#\" data-headword=\"שַׁמְנוּנִיתָא\">שַׁמְנוּנִיתָהּ</a>. <span class=\"citation\">Y. Pes. II, 29ᶜ</span> <span dir=\"rtl\">בשיש בהן ש׳</span> when there is fat in them. <span class=\"citation\">Ḥull. 111ᵃ</span> top Rashi, v. <a href=\"#\" data-headword=\"שַׁמְנוּנִיתָא\">next w.</a>; a. e.</div>","alt":[]},"31754":{"h":"שַׁמְנוּנִיתָא","r":"U01506","html":"<div class=\"sense\">, <i>fat</i>. <span class=\"citation\">Targ. Y. Gen. XLV, 18</span>.—<span class=\"citation\">Ḥull. 111ᵃ</span> top <span dir=\"rtl\">משום ש׳</span> on account of the fat (in the liver which is communicated to the substance boiled with it).</div>","alt":[]},"31755":{"h":"שְׁמָנִי","r":"U01507","html":"<div class=\"sense\"><i>my name</i>, v. <a href=\"#\" data-headword=\"שֵׁם\">שְׁמָא</a>. <span class=\"citation\">Ḥull. 51ᵃ</span> (v. Rabb. D. S. a. l. note 3).</div>","alt":[]},"31756":{"h":"שְׁמֹנִים","r":"U01508","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁמֹנֶה\">שְׁמֹנֶה</a></div>","alt":[]},"31757":{"h":"שְׁמֹנִין","r":"U01509","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"שָׁמִין I\"><span dir=\"rtl\">שָׁמִין</span> I</a>.</div>","alt":["שִׁמְנִין"]},"31758":{"h":"שַׁמְנִינֵי","r":"U01510","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמֵן\">שְׁמֵן</a>) <i>fat animals</i>. <span class=\"citation\">Targ. O. Gen. IV, 4</span> ed. Lsb., v. <a href=\"#\" data-headword=\"שְׁמֵנָא\">שְׁמֵנָא</a>.</div>","alt":[]},"31759":{"h":"שָׁמַע","r":"U01511","html":"<div class=\"sense\"> (b. h.) [<i>to be still,</i>] <i>to hear, listen, obey; to understand</i>. <span class=\"citation\">R. Hash. IV, 2</span> <span dir=\"rtl\">כל עיר … ושׁוֹמַעַת וכ׳</span> every township near Jerusalem from where you can see (the city) and hear (the Shofar) &amp;c. <span class=\"citation\">Ib. 21ᵇ</span> <span dir=\"rtl\">עד שיִשְׁמְעוּ … מקודש</span> until they heard from the mouth of the court <i>m’ḳuddash</i> (v. <a href=\"#\" data-headword=\"קָרַשׁ\">קָרַשׁ</a>). <span class=\"citation\">Snh. 90ᵃ</span> <span dir=\"rtl\">שְׁמַע לו</span> listen to him (obey the prophet’s command); <span dir=\"rtl\">אל תִּשְׁמַע לו</span> listen not to him. <span class=\"citation\">Keth. 5ᵇ</span> <span dir=\"rtl\">אם יִשְׁמַע וכ׳</span> if a man hears an improper word &amp;c., v. <a href=\"#\" data-headword=\"שפי ²\"><span dir=\"rtl\">שָׁפָה</span> II</a>. <span class=\"citation\">Ber. 13ᵃ</span> the text (<span class=\"citation\">Deut. VI, 4</span>) says ‘hear’ (or ‘understand’), <span dir=\"rtl\">בכל לשון שאתה שׁוֹמֵעַ</span> recite the Sh’mʿa in whatever language you understand. <span class=\"citation\">R. Hash. III, 7</span> <span dir=\"rtl\">אם קול שופר ש׳</span> if he heard the sound of a Shofar; <span dir=\"rtl\">ואם קול הברה ש׳</span>, v. <a href=\"#\" data-headword=\"הֲבָרָה\">הֲבָרָה</a>. <span class=\"citation\">Y. Hor. I, 46ᵃ</span> top <span dir=\"rtl\">נותנין לו שהות עד שׁיִשְׁמַע</span> we allow him time enough that he may have heard (the decision of the other court), opp. to <span dir=\"rtl\">עד שישמע</span> (not <span dir=\"rtl\">שישפע</span>) (he is not guilty) until he has really heard it; a. v. fr.</div><div class=\"sense\"><b>Hif. הִשְׁמִיעַ</b> <div class=\"sense\"><b>1)</b> <i>to cause to hear; to announce</i>. Ber. l. c. <span dir=\"rtl\">הַשְׁמַע לאזניך וכ׳</span> let thy ears hear what thou utterest &amp;c. Ib. <span dir=\"rtl\">לא ה׳ לאזנו</span> if he read the Sh’inʿa inaudibly to himself. <span class=\"citation\">R. Hash. 28ᵇ</span> <span dir=\"rtl\">עד שיתכוין שומע ומַשְׁמִיעַ</span> until he that hears (the Shofar) and he that causes to hear (that blows) have the intention to perform a religious act. <span class=\"citation\">Shek. I, 1</span> <span dir=\"rtl\">מַשְׁמִיעִין על השקלים וכ׳</span> (Y. ed. <span dir=\"rtl\">מְשַׁמְּעִין</span>, <i>Pi.</i>) public announcement is made concerning the contribution of the half-Shekels &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b>  (sub. <span dir=\"rtl\">עצמו</span>) <i>to show one’s self obedient, be persuaded, surrender</i>, v. <i>Nif.</i></div></div><div class=\"sense\"><b>Pi. שִׁימֵּעַ</b> <div class=\"sense\"><b>1)</b> <i>to announce</i>, v. supra. Y. Shek. I, beg. 45ᶜ; Y. Meg. I, 71ᵃ.</div><div class=\"sense\"><b>—2)</b> <i>to assemble</i> for mourning services, <i>invite</i>. <span class=\"citation\">Snh. 47ᵃ</span> <span dir=\"rtl\">הלינו לכבודו לשַׁמֵּעַ עליו וכ׳</span></div></div><div class=\"sense\"><b>Nif. נִשְׁמַע</b> <div class=\"sense\"><b>1)</b> <i>to be heard; to be listened to, be obeyed</i>. <span class=\"citation\">Ber. 6ᵃ</span> <span dir=\"rtl\">אין תפלה … נִשְׁמַעַת וכ׳</span> man’s prayer is heard only in the house of prayer. Y. ib. V, end, 9ᵇ <span dir=\"rtl\">שׁנִשְׁמְעָה תפלתו</span> that his prayer will be heard (his petition be granted). <span class=\"citation\">Erub. 18ᵇ</span> <span dir=\"rtl\">כל בית שׁנִשְׁמָעִין וכ׳</span> a house in which the words of the Law are heard by night will never be destroyed. <span class=\"citation\">Yeb. 65ᵇ</span> <span dir=\"rtl\">כשם … דבר הנִשְׁמָע וכ׳</span> as well as it is proper to say a thing that has been heard (to mention one’s authority), so it is proper not to say a thing that has not been heard (for which you cannot cite your authority); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to show one’s self willing; to submit to authority</i>; (of woman) <i>to surrender</i>. <span class=\"citation\">R. Hash. 25ᵇ</span> <span dir=\"rtl\">אשרי הדור שהגדולים נִשְׁמָעִים וכ׳</span> blessed the generation in which the superiors (in wisdom) submit to the authority of their inferiors, and how much more when inferiors acknowledge the authority of their superiors!—<span class=\"citation\">Snh. 82ᵃ</span> <span dir=\"rtl\">הִשָּׁמְעִי לי</span> (ed. <span dir=\"rtl\">הַשְׁמִיעִי לי</span>) surrender thyself to me; <span dir=\"rtl\">לא תִשָּׁמְעִי אלא וכ׳</span> surrender thyself only to a prominent man among them; <span class=\"citation\">Sifré Num. 131</span>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">רצונך שׁאֶשָּׁמַע לך הנזר וכ׳</span> if thou desirest me to surrender myself to thee, renounce the law of Moses; <span class=\"citation\">Yalk. ib. 771</span>. Y. Succ. V, 55ᵇ top <span dir=\"rtl\">נִשְׁמָעוֹת … לליגיונותי וכ׳</span> if you will surrender to my legions, I will not put you to death. <span class=\"citation\">Snh. 93ᵃ</span> <span dir=\"rtl\">הַשְׁמִיעִי אל וכ׳</span> surrender thyself to Zedekiah; a. fr.</div></div>","alt":[]},"31760":{"h":"שְׁמַע I","r":"U01512","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXVII, 5</span>. <span class=\"citation\">Targ. Ex. XVIII, 1</span>. <span class=\"citation\">Targ. Job IV, 16</span>; a. v. fr.—Part. pass. <a href=\"#\" data-headword=\"שְׁמִיעַ\">שְׁמִיעַ</a>; f. <a href=\"#\" data-headword=\"שְׁמִיעָא\">שְׁמִיעָא</a>. <span class=\"citation\">Targ. Ps. XXIX, 3</span>, sq. <span class=\"citation\">Targ. II Chr. VII, 12</span>; a. fr.—<span class=\"citation\">Y. Ter. X, 47ᵇ</span> bot. <span dir=\"rtl\">אנא מה דשַׁמְעִית ואינון מה דשַׁמְעוּן</span> I report what I have heard, and they, what they have heard. <span class=\"citation\">Sabb. 46ᵇ</span> <span dir=\"rtl\">הא שַׁמְעִינָן ליה לר&quot;ש וכ׳</span> have we not heard what R. S. says &amp;c.? <span class=\"citation\">Y. Sot. VII, beg. 21ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲלִנִסְטִי\">אֲלִנִיסְטִי</a>; a. v. fr.—<span dir=\"rtl\">שמיע ל־</span> he has heard, <i>he knows of</i>. <span class=\"citation\">Erub. 9ᵇ</span> <span dir=\"rtl\">ור&quot;י מי לא ש׳ ליה הא</span> but has R. J. not heard that (does he not know that Boraitha of R. Ḥiya)? <span dir=\"rtl\">ש׳ ליה ולא סבר</span> (v. Rabb. D. S. a. l.) he knows of it, but does not accept it. <span class=\"citation\">Ib. 10ᵃ</span>, a. fr. <span dir=\"rtl\">לא ש׳ לי הא שמעתתא</span> this tradition is not known to me. <span class=\"citation\">Pes. 34ᵃ</span> <span dir=\"rtl\">מידי ש׳ לך בהא</span> do you know anything about this (hălakhah)?; a. v. fr.—Esp. <span dir=\"rtl\">שמע מ־</span> <i>to understand from, to infer, prove</i>. <span class=\"citation\">Ab. Zar. 72ᵇ</span>, a. fr. <span dir=\"rtl\">ש׳ מינה וכ׳</span> (abbrev. <span dir=\"rtl\">ש&quot;מ</span>) deduce from this that &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שַׁמְעַת מינה וכ׳</span> wilt thou conclude from this that &amp;c.? Ib., a. fr. <span dir=\"rtl\">אלא מהא ליכא למִשְׁמַע מינה</span> but (the conclusion is,) you can derive nothing from this.—Ib., a. fr. <span dir=\"rtl\">תא שמע</span> (abbrev. <span dir=\"rtl\">ת&quot;ש</span>; v. <a href=\"#\" data-headword=\"אֲתָא\">אֲתָא</a>) come and learn, i.e. derive it from the following. <span class=\"citation\">Sabb. 13ᵇ</span> ת&quot;ש … ש&quot;מ ואלו תנן ש&quot;מ I will prove it (from this Tosefta): ‘you must not …, and those are some of the halakhoth &amp;c.’, which proves that the right version is ‘<i>and</i> those’: it stands proved. <span class=\"citation\">Y. M. Kat. III, 83ᵃ</span> top <span dir=\"rtl\">נִישְׁמְעִינָהּ מן הדא</span> let us prove it from this; a. v. fr.</div><div class=\"sense\"><b>Pa. שַׁמַּע</b> <div class=\"sense\"><b>1)</b> <i>to make music; to sing</i>, v. <i>Af.</i></div><div class=\"sense\"><a href=\"#\" data-headword=\"שַׁמְּעָא\">שַׁמְּעָא</a>) <i>to minister to, be an attendant of</i>. <span class=\"citation\">Ber. 41ᵇ</span> <span dir=\"rtl\">מאן … ונְשַׁמְּעִינָךְ</span> would that we had iron feet, that we could always wait on thee! <span class=\"citation\">Meg. 28ᵇ</span> <span dir=\"rtl\">ניחא לי דאֲשַׁמְּעֵיה למר</span> (Ms. M. <span dir=\"rtl\">דאשתמש ליה למר</span>, v. Rabb. D. S. a. l.) it gives me pleasure to be your servant; a. e.</div></div><div class=\"sense\"><b>Af. אַשְׁמַע</b> <div class=\"sense\"><b>1)</b> <i>to cause to hear, cause to be heard, announce, proclaim</i>. <span class=\"citation\">Targ. Deut. IV, 36</span>. <span class=\"citation\">Targ. Is. LII, 7</span>. <span class=\"citation\">Targ. Ps. XXVI, 7</span>; a. fr.—Esp. (interch. with <i>Pa.</i>) <i>to make music, play; to be a musician</i>. <span class=\"citation\">Targ. I Sam. XXIX, 5</span> (Ms. <i>Pa</i>.). <span class=\"citation\">Targ. I Chr. XV, 16</span>. <span class=\"citation\">Ib. XVI, 42</span> <a href=\"#\" data-headword=\"מִשְׁמְעָא\">מַשְׁמְעַיָּא</a> ed. Lag. (ed. Rahmer <span dir=\"rtl\">משמעייאה</span>, Var. <span dir=\"rtl\">מַשְׁמְעַיָּה</span>; h. text <span dir=\"rtl\">מַשְׁמִיעִים</span>) <i>musicians</i>. <span class=\"citation\">Targ. Ps. CL, 5</span> דמְשַׁמְּעִין לבדוחא Ms. (ed. Lag. <span dir=\"rtl\">דמשמעין בלחודיהון</span>; ed. Wil. a. oth. <span dir=\"rtl\">דשמעין בלחודיהון</span>, corr. acc.). Ib. <span dir=\"rtl\">דמַשְׁ׳ ביבבא</span> (Ms. Pa.).</div><div class=\"sense\"><b>—2)</b> <i>to give to understand; to teach, prove</i>. <span class=\"citation\">Ber. 2ᵃ</span> <span dir=\"rtl\">מילתא … קא מַשְׁמַע לן וכ׳</span> (the Tannai in using such an expression) wants to teach us something by the way: when do the priests eat &amp;c.; <span dir=\"rtl\">והא קמשמע לן וכ׳</span> (abbrev. <span dir=\"rtl\">קמ&quot;ל</span>) and it is this he teaches us, that the sacrifice of atonement is not indispensable &amp;c. Ib. 4ᵇ <span dir=\"rtl\">לאפוקי … קמ&quot;ל דחובה</span> in opposition to the opinion that the evening prayer is optional, he gives us to understand that it is obligatory. <span class=\"citation\">Sabb. 19ᵃ</span> <span dir=\"rtl\">מהו דתימא … קמ&quot;ל</span> you may have thought (that the cases are different, because) this devolves upon him, and the other does not, therefore he teaches us (that they are the same). <span class=\"citation\">Ib. 108ᵃ</span> <span dir=\"rtl\">מאי קמ&quot;ל</span> what does he teach us (is it not a matter of course)? <span class=\"citation\">Ber. 21ᵃ</span> sq. <span dir=\"rtl\">דאי אַשְׁמְעִינָן וכ׳</span>, v. <a href=\"#\" data-headword=\"צְרִיךְ\">צְרִיךְ</a>; a. v. fr.—Part. pass. <a href=\"#\" data-headword=\"מַשְׁמָע\">מַשְׁמֵע</a> <i>a</i>) <i>understood</i>. <span class=\"citation\">Yeb. 102ᵇ</span> <span dir=\"rtl\">מ׳ הכי ומ׳ הכי</span> it may be understood thus (it may mean, ‘to take off’), and may be understood thus (it may mean, ‘to strengthen’); a. fr.—2) <i>inferred, proved; evidence</i>. <span class=\"citation\">Sabb. 84ᵇ</span> <span dir=\"rtl\">מאי מ׳</span> how is this proved (from the verse quoted)? <span class=\"citation\">Erub. 65ᵃ</span> <span dir=\"rtl\">מאי מ׳ וכ׳</span> what evidence is there &amp;c.?, v. <a href=\"#\" data-headword=\"פּוּק\">פּוּק</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מַשְׁמְעֵי</span>, v. infra; a. fr.—V. <a href=\"#\" data-headword=\"מַשְׁמָע\">מַשְׁמָע</a>.</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתַּמַּע</b> </div><div class=\"sense\"><b>Ithpe. אִשְׁתְּמַע</b> <div class=\"sense\"><b>1)</b> <i>to be heard, let one’s self be heard</i>. <span class=\"citation\">Targ. Gen. XLV, 16</span>. <span class=\"citation\">Targ. Job XXXVII, 4</span> Ms. (ed. <span dir=\"rtl\">ישמע</span>). <span class=\"citation\">Targ. Ps. LXXVII, 19</span>; a. fr.—<span class=\"citation\">Snh. 95ᵇ</span> (prov.) <span dir=\"rtl\">אגב אורחך … א׳</span> on thy road let thy enemy hear from thee, i.e. take revenge when occasion offers. <span class=\"citation\">R. Hash. 27ᵃ</span> <span dir=\"rtl\">תרתי … לא מִשְׁתַּמְּעֵי … משתמעי</span> two different sounds produced simultaneously by the same person are not distinctly perceived, but if produced by two persons, they are. Erub. l. c. <span dir=\"rtl\">מכדי קראי מִשְׁתַּמְּעֵי בין למר וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">משמעי</span>, v. Rabb. D. S. a. l. note) since verses may be quoted in favor of the one as well as of the other, what is the practical difference between them?; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to make one’s self subservient, obey; to surrender to the enemy, desert</i>. <span class=\"citation\">Targ. II Kings XXV, 11</span> (h. text <span dir=\"rtl\">נפלו</span>). <span class=\"citation\">Ib. VII, 4</span>. <span class=\"citation\">Targ. Ps. XVIII, 45</span>; <span class=\"citation\">II Sam. XXII, 45</span>; a. fr.</div></div>","alt":[]},"31761":{"h":"שְׁמַע II","r":"U01513","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <span class=\"citation\">Deut. VI, 4</span>) <i>Sh’mʿa, the confession of faith</i> in the morning and evening prayers (recitation of <span class=\"citation\">Deut. VI, 4-9</span>; <span class=\"citation\">XI, 13-21</span>; <span class=\"citation\">Num. XVI, 37-41</span>). <span class=\"citation\">Targ. Y. I Num. XXV, 6</span>. Targ. II Esth. III, 8.—<span class=\"citation\">Ber. I, 1</span> <span dir=\"rtl\">מאימתי קורין את ש׳ וכ׳</span> from what time of the day may we read the Sh’mʿa of the evening prayer? <span class=\"citation\">Ib. II, 2</span> (<span class=\"citation\">13ᵃ</span>) <span dir=\"rtl\"><span dir=\"rtl\">למה קדמה</span> (<span dir=\"rtl\">פרשת</span>) <span dir=\"rtl\">ש׳ וכ׳</span></span> why does the reading of the section of Sh’mʿa (<span class=\"citation\">Deut. VI, 4–9</span>) precede that of <i>v’hayah</i> (ib. XI, 13-21) Ib. <span dir=\"rtl\">בין שניה לש׳ ובין ש׳ וכ׳</span> between the second benediction and Sh’mʿa (the first section), and between Sh’mʿa and <i>v’hayah</i> &amp;c.; a. fr.—<span dir=\"rtl\">קריאת ש׳</span> (abbr. <span dir=\"rtl\">ק&quot;ש</span>), v. <a href=\"#\" data-headword=\"קְרִיאָה\">קְרִיאָה</a>. Ib. 2ᵃ <span dir=\"rtl\">ק&quot;ש דשכיבה</span> the recitation of Sh’mʿa at bed-time. <span class=\"citation\">Num. R. s. 20</span><sup>20</sup> <span dir=\"rtl\">עומדין … וחוטפין ק&quot;ש וכ׳</span> they rise from their sleep like lions, and hasten to read the Sh’mʿa, and proclaim the kingship of the Lord &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">והוא … בק&quot;ש משומרי וכ׳</span> and with the recital of the Sh’mʿa he is handed over from the guards of the day to those of the night. <span class=\"citation\">Ber. 4ᵇ</span> <span dir=\"rtl\">אע&quot;פ שקרא אדם ק&quot;ש וכ׳</span> although one has read the Sh. in synagogue, it is proper to recite it again on going to bed. <span class=\"citation\">Ib. 5ᵃ</span> <span dir=\"rtl\">אם … ואם לאו יקרא ק&quot;ש</span> if he conquers it (the evil thought), it is well, and if not, let him read the Sh.; a. v. fr.</div>","alt":[]},"31762":{"h":"שֵׁמַע","r":"U01514","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>report, fame</i>. <span class=\"citation\">Deut. R. s. 1</span>, end <span dir=\"rtl\">היו … שומעים שִׁמְעֲכֶם וכ׳</span> the nations heard of your fame and were afraid; a. e.</div><div class=\"sense\"><b>—2)</b>  = <a href=\"#\" data-headword=\"מִשְׁמָע\">מִשְׁמָע</a> <i>understanding, meaning</i>. <span class=\"citation\">Sifré Num. 142</span> (ref. to <span class=\"citation\">Num. XXVIII, 3</span>) <span dir=\"rtl\">כשִׁמְעוֹ וכ׳</span> (trad. pronunc. <span dir=\"rtl\">כִּשְׁמָעוֹ</span>) according to its literal meaning, two each day.</div>","alt":[]},"31763":{"h":"שֵׁמַע ²","r":"U01515","html":"<div class=\"sense\">, <i>report, fame</i>. <span class=\"citation\">Targ. Gen. XXIX, 13</span>. <span class=\"citation\">Targ. Ps. XVIII, 45</span>; <span class=\"citation\">II Sam. XXII, 45</span> ed. Lag. (oth. <span dir=\"rtl\">שְׁמוֹעַ</span>, <a href=\"#\" data-headword=\"שָׁמוּעַ\">שְׁמוּעַ</a>). <span class=\"citation\">Targ. Josh. VI, 27</span> <a href=\"#\" data-headword=\"שְׁמַעְיָא\">שִׁמְעֵיה</a> (some ed. <span dir=\"rtl\">שָׁמְ׳</span>); a. e.</div>","alt":["שִׁמְעָא"]},"31764":{"h":"שַׁמְּעָא","r":"U01516","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שֵׁמַע ²\">preced.</a> wds.) <i>servant, attendant</i>, esp. <i>the disciple ministering to the master</i>. <span class=\"citation\">Ber. 62ᵃ</span> א&quot;ל … לשַׁמְּעֵיה R. Z. said to his attendant; <span class=\"citation\">R. Hash. 33ᵇ</span>. <span class=\"citation\">Pes. 103ᵇ</span> <span dir=\"rtl\">ש׳ מדעתיה וכ׳</span> my attendant did it of his own accord; a. fr.</div>","alt":[]},"31765":{"h":"שִׁמְעוֹן","r":"U01517","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Simeon, Simon</i>, </div><div class=\"sense\"><b>1)</b>  the son of Jacob; the tribe of Simeon. <span class=\"citation\">Gen. R. s. 71</span> ש̇מ̇ע̇ון ש̇ומ̇ע בקול וכ׳ Simeon (listener), listening to the voice of his father in heaven. <span class=\"citation\">Num. R. s. 2</span><sup>7</sup> <span dir=\"rtl\">ש׳ פטדה</span> the jewel in the high priest’s breastplate for the tribe of S. was a topaz. <span class=\"citation\">Num. R. s. 13</span><sup>19</sup> <span dir=\"rtl\">נשיא ש׳</span> the prince of the tribe of S.; a. fr.</div><div class=\"sense\"><b>—2)</b>  ש׳ הצדיק <i>Simon the Just</i>, a high priest. <span class=\"citation\">Yoma 69ᵃ</span> <span dir=\"rtl\">כיון שראה לש׳ הצ׳ וכ׳</span> when he (Alexander the Great) saw Simon the Just, he alighted from his chariot &amp;c. <span class=\"citation\">Ab. I, 2</span> ש׳ הצ׳ היה וכ׳ Simon the Just was one of the last members of the Great Assembly; a. fr.</div><div class=\"sense\"><b>—3)</b>  name of several Tannaim, esp. <i>a</i>) S. son of Hillel. <span class=\"citation\">Sabb. 15ᵃ</span>.—<i>b</i>) R. S. son of the Sagan. <span class=\"citation\">Shek. VIII, 5</span>. <span class=\"citation\">Keth. II, 8</span>; a. e.—<i>c</i>) S. ben Sheṭaḥ, chief of the Pharisees under Alexander Jannai. <span class=\"citation\">Ḥag. II, 2</span>. <span class=\"citation\">Tosef. Keth. XII, 1</span>. <span class=\"citation\">Kidd. 66ᵃ</span>; a. fr.—<i>d</i>) R. S. ben Gamliel I (abbrev. <span dir=\"rtl\">רשב&quot;ג</span>) <span class=\"citation\">Ker. I, 7</span>. <span class=\"citation\">Succ. 53ᵃ</span>; <span class=\"citation\">Tosef. ib. IV, 4</span>. <span class=\"citation\">Ab. Zar. 20ᵃ</span>; (Y. ib. I, 40ᵃ bot.; <span class=\"citation\">Y. Ber. IX, 13ᵇ</span> bot. <span dir=\"rtl\">רבן גמליאל</span>); a. e.—<i>e</i>) Rabban S. ben Gamliel II. <span class=\"citation\">Hor. 13ᵇ</span>. <span class=\"citation\">Keth. 77ᵃ</span>, a. fr. <span dir=\"rtl\">כל מקום ששנה רשב&quot;ג וכ׳</span> wherever R. S. b. G. is cited in the Mishnah, his opinion is the adopted law. Ib. VII, 9; a. v. fr.—<i>f</i>) <span dir=\"rtl\">ר׳ ש׳ ברבי</span> R. S. son of R. Judah han-Nasi (B’ribbi). Ib. 103ᵇ. <span class=\"citation\">Ber. 13ᵇ</span>; a. fr.—<span dir=\"rtl\">ש׳ בן זומא</span>, v. <a href=\"#\" data-headword=\"זוֹמָא II\"><span dir=\"rtl\">זוֹמָא</span> II</a>.—<span dir=\"rtl\">ש׳ בן עזאי</span>, v. <a href=\"#\" data-headword=\"עַזַּאי\">עַזַּאי</a>; a. many other Tannaim; v. Fr. Darkhé, Additamenta, p. 64–67.</div><div class=\"sense\"><b>—4)</b>  name of several Amoraim, esp. <i>a</i>) R. S. bar Abba (Ba, Va), in Babli <a href=\"#\" data-headword=\"שִׁמָּן\">שִׁמָּן</a>. <span class=\"citation\">Y. Sabb. VII, 8ᵃ</span> bot.; Bab. <span class=\"citation\">Sabb. 61ᵃ</span>. <span class=\"citation\">Y. Ber. V, 9ᵇ</span> bot.; Bab. <span class=\"citation\">Ber. 33ᵃ</span>; a. fr.—<i>b</i>) R. S. b. Laḳish (abbrev. <span dir=\"rtl\">רשב&quot;ל</span>, a. <span dir=\"rtl\">ריש לקיש</span>, <span dir=\"rtl\">ר&quot;ל</span>). <span class=\"citation\">Keth. 54ᵇ</span>. <span class=\"citation\">Gitt. 47ᵃ</span>. <span class=\"citation\">Y. Yeb. VIII, 9ᵈ</span> bot.; a. v. fr., v. <a href=\"#\" data-headword=\"לָקִישׁ II\"><span dir=\"rtl\">לָקִישׁ</span> I</a>; a. other Amoraim; v. Fr. M’bo p. 127ᵃ–130ᵃ</div>","alt":[]},"31766":{"h":"שִׁמְעִי","r":"U01518","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Shimei</i>, </div><div class=\"sense\"><b>1)</b>  son of Gera the Benjamite, who insulted David on his flight. <span class=\"citation\">Ber. 8ᵃ</span>. <span class=\"citation\">Koh. R. to VII, 15</span>. <span class=\"citation\">Meg. 12ᵇ</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  brother of Onias, the founder of the Temple of Onias (v. <a href=\"#\" data-headword=\"חוֹנְיוּ\">חוֹנְיוּ</a>). <span class=\"citation\">Men. 109ᵇ</span></div>","alt":[]},"31767":{"h":"שְׁמַעְיָא","r":"U01519","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Shemaiah</i>, colleague of Abṭalion (v. <a href=\"#\" data-headword=\"אַבְטַלְיוֹן\">אַבְטַלְיוֹן</a>). <span class=\"citation\">Pes. 66ᵃ</span>. <span class=\"citation\">Ab. I, 10</span>. <span class=\"citation\">Yoma 71ᵇ</span>. <span class=\"citation\">Gitt. 57ᵇ</span>; a. fr.</div>","alt":["שְׁמַעְיָה"]},"31768":{"h":"שְׁמַעְתָּא","r":"U01520","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"שְׁמוּעָה\">שְׁמוּעָה</a>) <i>report, tradition, traditional law; outcome of a discussion, decision</i>. <span class=\"citation\">Targ. I Chr. XI, 11</span> (ed. Rahmer <span dir=\"rtl\">שמעת</span>, corr. acc.). <span class=\"citation\">Ib. II, 55</span>.—<span class=\"citation\">Erub. 9ᵇ</span>; <span class=\"citation\">Kidd. 50ᵇ</span>, a. e. <span dir=\"rtl\">ומותבינן אשְׁמַעְתִּין</span> but we must bring evidence against the tradition which we just cited; <span class=\"citation\">Ber. 33ᵃ</span> <span dir=\"rtl\">אשמעתיה</span> (corr. acc., v. Rabb. D. S. a. l. note 70). <span class=\"citation\">Sot. 21ᵃ</span> <span dir=\"rtl\">דסלקא ליה ש׳ וכ׳</span> a scholar whose final conclusions agree with the adopted practice. <span class=\"citation\">Snh. 38ᵇ</span> ר&quot;מ … תילתא ש׳ וכ׳ R. Meir used to divide his lectures into three parts, one part devoted to legal discussion, one to homily (v. <a href=\"#\" data-headword=\"אַגָּדָה\">אֲגָדָה</a>), and one to parables. <span class=\"citation\">Ber. 6ᵇ</span> <span dir=\"rtl\">אגרא דש׳ סברא</span> the merit of studying traditions lies in the reasoning thereon; a. v. fr.—Pl. <a href=\"#\" data-headword=\"שְׁמַעְתָּא\">שְׁמָעָתָא</a>, <a href=\"#\" data-headword=\"שְׁמַעְתָּא\">שְׁמַעְתָּתָא</a>. <span class=\"citation\">Nidd. 14ᵃ</span> <span dir=\"rtl\">שְׁמַעְתָּתֵיה</span>, v. <a href=\"#\" data-headword=\"חֲדַד\">חֲדַד</a>; <span class=\"citation\">Keth. 62ᵇ</span> <span dir=\"rtl\">שְׁמָעָתֵיה</span>. <span class=\"citation\">Erub. 65ᵃ</span> <span dir=\"rtl\">מחדדן שְׁמָעָתָךְ</span> thou hast thy traditions always ready. <span class=\"citation\">Ber. 42ᵃ</span> <span dir=\"rtl\">לית הילכתא ככל הני ש׳ וכ׳</span> the adopted practice is not in agreement with all these traditions &amp;c.; a. fr.</div>","alt":["שְׁמַעְתְּתָא"]},"31769":{"h":"שֶׁמֶץ","r":"U01521","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , 12; XXVI, 14) [<i>chaff</i>,] </div><div class=\"sense\"><b>1)</b> <i>particle, atom</i>. <span class=\"citation\">Sabb. 119ᵇ</span> <span dir=\"rtl\">אפי׳ יש בו ש׳ של ע&quot;א וכ׳</span> even if there be some idolatry in him, he will be forgiven.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"מוּם\">מוּם</a>) <i>blemish, suspicion</i>. <span class=\"citation\">Kidd. 71ᵇ</span> <span dir=\"rtl\">אם ראית … ש׳ פסול וכ׳</span> when thou seest two men quarrel with each other, there is some blemish of descent in one of them, and heaven does not allow them to become attached to each other. <span class=\"citation\">Pes. 3ᵇ</span> <span dir=\"rtl\">ומצאו בו ש׳ פסול</span> and they found in him a blemish of descent, contrad. to <a href=\"#\" data-headword=\"שַׁחַץ I\">שחץ</a> (v. <a href=\"#\" data-headword=\"שַׁחַץ I\"><span dir=\"rtl\">שַׁחַץ</span> I</a>); <span class=\"citation\">Meg. 25ᵇ</span> (<span class=\"citation\">Treat. Sof’rim ch. IX, 11</span> <span dir=\"rtl\">ונמצא ממזר</span>); a. e.</div>","alt":[]},"31770":{"h":"שִׁמְצָא","r":"U01522","html":"<div class=\"sense\">, <i>slight suspicion</i> of idolatrous manipulation of wine (v. <a href=\"#\" data-headword=\"נֶסֶךְ\">נֶסֵךְ</a>). <span class=\"citation\">Ab. Zar. 31ᵇ</span> <span dir=\"rtl\">חמרא משום ש׳ וכ׳</span> wine (he refused to drink) because of a suspicion, but why did he refuse beer? <span dir=\"rtl\">משום ש׳ דש׳</span> because of a suspicion of a suspicion (it might be suspected to be wine).—V. <a href=\"#\" data-headword=\"שִׁמְצָה\">next w.</a></div>","alt":["שִׁימְ׳"]},"31771":{"h":"שִׁמְצָה","r":"U01523","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שִׁמְצָא\">preced.</a> wds.) <i>blemish, disgrace</i>. <span class=\"citation\">Lev. R. s. 20</span> <span dir=\"rtl\">דבר של ש׳</span> (some ed. <a href=\"#\" data-headword=\"שִׁמְצָא\">שמצא</a>) something disgraceful, v. <a href=\"#\" data-headword=\"זִיטִימָא\">זִיטִימָא</a>.</div>","alt":["שִׁי׳"]},"31772":{"h":"שמציות","r":"U01524","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Esth. 1048</span>, read: <span dir=\"rtl\">שְׁמִינִיּוֹת</span>, v. <a href=\"#\" data-headword=\"שְׁמִינִי\">שְׁמִינִי</a> (v. <a href=\"#\" data-headword=\"תּוֹמָן\">תּוּמָן</a>).</div>","alt":[]},"31773":{"h":"שָׁמַר","r":"U01525","html":"<div class=\"sense\"> (b. h.) [<i>to be still,</i>] <i>to watch, guard, wait; to observe; to keep</i>. <span class=\"citation\">Snh. 63ᵇ</span> <span dir=\"rtl\">לא … שְׁמוֹר לי וכ׳</span> one should not say to his neighbor, wait for me at such and such an idolatrous statue (or temple). <span class=\"citation\">B. Mets. 58ᵃ</span> <span dir=\"rtl\">השוכר … לִשְׁמוֹר את וכ׳</span> if one hires a workingman to guard a cow, a child &amp;c. <span class=\"citation\">Sabb. 118ᵇ</span> <span dir=\"rtl\">אלמלי שָׁמְרוּ ישראל וכ׳</span> if Israel had observed the first Sabbath &amp;c.; a v. fr.—Part. pass. <a href=\"#\" data-headword=\"שִׁמּוּר\">שָׁמוּר</a>; f. <a href=\"#\" data-headword=\"שְׁמוּעָה\">שְׁמוּרָה</a> &amp;c. Ib. XXII, 4 <span dir=\"rtl\">נותנין … בשביל שיהא ש׳</span> you may put a dish into the well that it be kept (cool); a. e.</div><div class=\"sense\"><b>Pi. שִׁמֵּר</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"שמציות\">same</a>. Ib. 118ᵇ <span dir=\"rtl\">אילמלי מְשַׁמְּרִין ישראל וכ׳</span> if Israel would observe two Sabbaths as they ought do, they would at once be redeemed. <span class=\"citation\">Keth. 62ᵇ</span> <span dir=\"rtl\">ענייה זו לשוא שִׁימְּרָה</span> the poor woman has in vain waited (for her husband). <span class=\"citation\">Ab. Zar. IV, 11</span> <span dir=\"rtl\">אין … יושב ומְשַׁמֵּר וכ׳</span> the watchman (guarding wine against idolatrous defilement) need not sit and watch &amp;c. Y. Kidd. I, 58ᵈ top <span dir=\"rtl\">המקום משמר וכ׳</span> God has watched, and such a case has never occurred. Y. M. Kat. III, 82ᶜ <span dir=\"rtl\">שי׳ הקב&quot;ה … שבעה</span> the Lord observed the seven days of mourning for his world (before the flood, ref. to <span class=\"citation\">Gen. VII, 10</span>); a. fr.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"שֶׁמֶר\">שְׁמָרִים</a>) <i>to clear wine from lees, filter, strain</i> (v. <a href=\"#\" data-headword=\"מְשַׁמֶּרֶת\">מְשַׁמֶּרֶת</a>). <span class=\"citation\">Sabb. 138ᵃ</span> <span dir=\"rtl\">שי׳ חייב וכ׳</span> if one filtered wine (on the Sabbath), he is bound to bring a sin-offering; Y. ib. XX, 17ᶜ; VII, 10ᵇ, a. e. <span dir=\"rtl\">המשמר חייב שום בורר</span> he who filters is guilty &amp;c., v. <a href=\"#\" data-headword=\"בָּרַר\">בָּרַר</a>. Ib. <span dir=\"rtl\">המשמר יין למטן וכ׳</span> when one filters, the wine goes down, and the lees remain above (in the filter); a. fr.—Bab. ib. 146ᵇ <span dir=\"rtl\">מקום העשוי לְשַׁמֵּר</span> a place in the keg where a hole has been made for the purpose of letting the wine off, clear of lees (and has been closed again; Ar. s. v. <span dir=\"rtl\">חזק</span>; Rashi: where the hole has been closed in order to <i>preserve</i> the flavor).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מְשׁוּמָּד\">מְשׁוּמָּר</a> <i>a</i>) <i>guarded</i>. <span class=\"citation\">Pes. 109ᵇ</span> (ref. to <a href=\"#\" data-headword=\"שֶׁמֶר\">שמרים</a>, <span class=\"citation\">Ex. XII, 42</span>) <span dir=\"rtl\">ליל המש׳ ובא מן המזיקין</span> a night which is for all time guarded against dangers (v. <a href=\"#\" data-headword=\"מַזִּיק\">מַזִּיק</a>); <span class=\"citation\">R. Hash. 11ᵇ</span>.—<i>b</i>) <i>kept, preserved, designated</i>. Ib. <span dir=\"rtl\">ליל המש׳ ובא מששת וכ׳</span> a night which has been designated for redemption since the six days of creation. <span class=\"citation\">Snh. 99ᵃ</span>; <span class=\"citation\">Ber. 34ᵇ</span> <span dir=\"rtl\">יין המש׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"עֵנָב\">עֵנָב</a>; a. e.</div></div><div class=\"sense\"><b>Hithpa. הִשְׁתַּמֵּר</b> <div class=\"sense\"><b>1)</b> <i>to be on one’s guard, be observant</i>. Mekh. Bo, s. 14 (ref. to <a href=\"#\" data-headword=\"שֶׁמֶר\">שמרים</a>, v. supra) <span dir=\"rtl\">מגיד … צריכין להִשְׁתַּמֵּר בו</span> this intimates that all Israelites must be careful in it (to observe its ceremonies); <span class=\"citation\">Yalk. Ex. 210</span>; Tanḥ. Bo 9.</div><div class=\"sense\"><b>—2)</b> <i>to be guarded</i>. <span class=\"citation\">B. Mets. 11ᵃ</span> <span dir=\"rtl\">המִשְׁתַּמֶּרֶת</span>, v. <a href=\"#\" data-headword=\"חָצֵר\">חָצֵר</a>. <span class=\"citation\">Erub. 54ᵇ</span> <span dir=\"rtl\">אם ראשון … מִשְׁתַּמֵּר וכ׳</span> if the fowler breaks the wings of each bird as he catches it, it is kept (from flying off) &amp;c. <span class=\"citation\">Men. 99ᵇ</span> <span dir=\"rtl\">כל המשמר … נשמתוֹ משתמרת</span> who guards the Law (takes care not to forget it), his soul is guarded; a. e.</div></div><div class=\"sense\"><b>Nif. נִשְׁמַר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"שמציות\">same</a>, <i>to be on one’s guard</i>. Ib. <span dir=\"rtl\">כל מקום שנאמר הִשָּׁמֶר פן ואל וכ׳</span> wherever the Scripture has the words, ‘be on thy guard, lest’, or ‘be on thy guard that not’, it is a prohibitive law; ib. <span dir=\"rtl\">השמר ופן וכ׳</span> ‘be on thy guard’ and ‘lest’ make two prohibitions. Ib. 36ᵇ השמר דלאו לאו <i>hishshamer</i> followed by a negative is a prohibitory law; <span dir=\"rtl\">השמר דעשה עשה</span> <i>hishshamer</i> connected with a positive order, is a positive command (v. <a href=\"#\" data-headword=\"עָשָׂה\">עָשָׂה</a>).—[Tanḥ. Vayḥi 13 <span dir=\"rtl\">ומשמירין</span>, v. <a href=\"#\" data-headword=\"שָׁפַר\">שָׁפַר</a>.]</div></div>","alt":[]},"31774":{"h":"שְׁמַר","r":"U01526","html":"<div class=\"sense\"><i>Ithpa.</i> <a href=\"#\" data-headword=\"שְׁדַר I\">אִשְׁתַּמַּר</a>, v. <a href=\"#\" data-headword=\"סְמַר II\"><span dir=\"rtl\">סְמַר</span> II</a>. <span class=\"citation\">Targ. Is. VII, 4</span> some ed.</div>","alt":[]},"31775":{"h":"שֶׁמֶר","r":"U01527","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמַר\">preced.</a>) <i>sediment, lees</i>. <span class=\"citation\">Sabb. 146ᵇ</span> <span dir=\"rtl\">שניקבה למטה מן הש׳</span> when the jug has a hole below the line of the lees. <span class=\"citation\">B. Bath. 96ᵇ</span> <span dir=\"rtl\">שִׁמְרֵי יין</span> wine lees. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ש׳ … טעם יין</span> lees which have a taste (or flavor) of wine. <span class=\"citation\">B. Mets. IV, 11</span> <span dir=\"rtl\">אין מערבין שמרי … שְׁמָרָיו</span> you dare not mix wine lees (left of one jug) with wine, but you may give the purchaser the lees belonging to the wine sold; a. fr.</div>","alt":["שְׁמָרִים","שְׁמָרִין"]},"31776":{"h":"שְׁמָרָא","r":"U01528","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. XLVIII, 11</span>.—Pl. <span dir=\"rtl\">שְׁמָרַיָּא</span>. <span class=\"citation\">Yalk. Jer. 321</span> <span dir=\"rtl\">ושתי ש׳ דכולהו דרי</span> (not <span dir=\"rtl\">שאריא</span></div>","alt":[]},"31777":{"h":"שַׁמְרַאי","r":"U01529","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁמְרַיי\">שַׁמְרַיי</a></div>","alt":[]},"31778":{"h":"שמרון","r":"U01530","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 36</span> some ed., v. <a href=\"#\" data-headword=\"שְׁמָדוֹן\">שְׁמָדוֹן</a></div>","alt":[]},"31779":{"h":"שֹׁמְרוֹן","r":"U01531","html":"<div class=\"sense\"> (b. h.) <i>Samaria</i>, city and district. <span class=\"citation\">Esth. R. to I, 2</span>. Tanḥ. Vayesheb 2 <span dir=\"rtl\">כשגלו ישראל מש׳ … בש׳ וכ׳</span> when the Israelites were exiled from Samaria, Sennaherib sent his servants and settled them in S. to raise taxes for the kings. <span class=\"citation\">Num. R. s. 10</span><sup>3</sup> (ref. to <span class=\"citation\">Am. VI, 2</span>) <span dir=\"rtl\">זה ציון וש׳</span> ‘these kingdoms’ refers to Zion and Samaria (Judah and Israel); a. fr.</div>","alt":["שׁוֹ׳"]},"31780":{"h":"שֹׁמְרוֹנָאָה","r":"U01532","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁמְרַיי\">שַׁמְרַיי</a></div>","alt":[]},"31781":{"h":"שֹׁמְרוֹנִי","r":"U01533","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>Samaritan.</i> <i>—</i> Pl. <a href=\"#\" data-headword=\"שֹׁמְרוֹנִי\">שֹׁמְרוֹנִים</a>. Tanḥ. Vayesheb 2 <span dir=\"rtl\">באו עליהן הש׳ למלחמה</span> the Samaritans went to war with them; <span dir=\"rtl\">וכי ש׳ היו … נקראו ש׳</span> were they Samaritans? were they not Cuthæans? But they are called Samaritans from the city of Samaria; <span class=\"citation\">Yalk. Kings 234</span>; a. e.</div>","alt":[]},"31782":{"h":"שמרותי","r":"U01534","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. LXXVII, 5</span>, v. <a href=\"#\" data-headword=\"שְׁמִירָה I\"><span dir=\"rtl\">שְׁמִירָה</span> I</a></div>","alt":[]},"31783":{"h":"שַׁמְרַיי","r":"U01535","html":"<div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שֹׁמְרוֹנִי\">שֹׁמְרוֹנִי</a>. <span class=\"citation\">Gen. R. s. 32</span>; s. 81; a. e.—Pl. <span dir=\"rtl\">שַׁמְרָיֵא</span>, <span dir=\"rtl\">שַׁמְרָיֵיא</span>, <a href=\"#\" data-headword=\"שֹׁמְרוֹנָאָה\">שֹׁמְרוֹנָאֵי</a>. <span class=\"citation\">Targ. II Kings XVII, 29</span>.—<span class=\"citation\">Gen. R. s. 94</span> (ref. to <a href=\"#\" data-headword=\"שֹׁמְרוֹן\">שִׁמְרוֹן</a>, <span class=\"citation\">Gen. XLVI, 13</span>) <span dir=\"rtl\">אילין ש׳</span> this refers to the (Jewish) inhabitants of Samaria. <span class=\"citation\">Y. Shebi. IV, 35ᵃ</span> <span dir=\"rtl\">חד משמר</span>; <span class=\"citation\">Y. Snh. III, 21ᵇ</span> top <span dir=\"rtl\">חד משומד</span>, read: <span dir=\"rtl\">משְׁמָרָיֵיא</span>, v. <a href=\"#\" data-headword=\"*הָאַסְטוּ\">הָאַסְטוּ</a>.</div>","alt":["שַׁמְרַאי","שֹׁמְרוֹנָאָה"]},"31784":{"h":"שָׁמְרַיִין","r":"U01536","html":"<div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שֹׁמְרוֹן\">שֹׁמְרוֹן</a>. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> <span dir=\"rtl\">קרייה דש׳</span> the city of Shomron. Ib. I, 39ᶜ [read:] <span dir=\"rtl\">הדא … מש׳ כפלחין הוא</span> the garrison of Cæsaræa, because the majority of them came from Samaria, are considered as worshipping observers (of the Calendæ and Saturnalia); v., however, <a href=\"#\" data-headword=\"סוּגֵי\">סוּגֵי</a>.</div>","alt":[]},"31785":{"h":"שמרין","r":"U01537","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 36</span> some ed., v. <a href=\"#\" data-headword=\"שְׁמָדוֹן\">שְׁמָדוֹן</a></div>","alt":[]},"31786":{"h":"שְׁמַרְקְעִים","r":"U01538","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>truffles</i> (Löw, Aram. Pfl., p. 303); a species of <i>very acrid onions</i> (Maim.). <span class=\"citation\">Uktsin III, 2</span>.</div>","alt":["שְׁמַרְקְעִין"]},"31787":{"h":"שָׁמַשׁ","r":"U01539","html":"<div class=\"sense\"> (Shaf. of <a href=\"#\" data-headword=\"מוּשׁ\">מוש</a>, <a href=\"#\" data-headword=\"מָשַׁשׁ\">משש</a>) </div><div class=\"sense\"><b>1)</b>  [<i>to handle, be busy,</i>] <i>to minister, officiate</i>. <span class=\"citation\">Yoma VII, 5</span> <span dir=\"rtl\">כהן גדול מְשַׁמֵּשׁ וכ׳</span> the high priest officiates in eight garments, and the common priests in four. Y. ib. 44ᵇ bot. <span dir=\"rtl\">מפני מה אינו משמש וכ׳</span> why does he not officiate (on the Day of Atonement) dressed in gold? <span class=\"citation\">Lev. R. s. 21</span> <span dir=\"rtl\">מקדש ראשון ע&quot;י שׁשִׁמְּשׁוּ בו וכ׳</span> during the first Temple, because they ministered in faithfulness, only eighteen high priests officiated in it. <span class=\"citation\">Yoma 47ᵃ</span> <span dir=\"rtl\">ש׳ תחתיו</span> officiated in his place. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">וכולן שמשו בכהונה וכ׳</span> and all of them performed the functions of high priesthood. <span class=\"citation\">Y. Sot. IX, 24ᵃ</span> <span dir=\"rtl\">אלו שימשו פרנסות</span> the former served in an administrative capacity (not merely as scholars). Tanḥ. Bo 4 חשך ואפלה שמשו … ולא עתידין לשַׁמֵּשׁ ‘darkness and mist’ served (as divine agents) in Egypt, but ‘void and waste’ never served, and never shall serve; <span class=\"citation\">Yalk. Is. 360</span>. <span class=\"citation\">Gen. R. s. 33</span>, end <span dir=\"rtl\">לא שמשו מזלות וכ׳</span> the planets did not perform their functions during all the twelve months (of the flood); <span dir=\"rtl\">שמשו אלא … ניכר</span> they did act, only that their mark was not recognizable. <span class=\"citation\">Y. Yoma III, 41ᵃ</span> top <span dir=\"rtl\">חמשה … הסגן משמש</span> the Sagan had five functions to perform. <span class=\"citation\">Tam. V, 5</span> <span dir=\"rtl\">שלשה … מְשַׁמֶּשֶׁת</span> it served three purposes. <span class=\"citation\">Midd. I, 6</span> <span dir=\"rtl\">ומה היו מְשַׁמְּשׁוֹת</span> and what were they used for? <span class=\"citation\">R. Hash. 3ᵃ</span> כי משמש וכ׳ <i>ki</i> serves for four meanings &amp;c., v. <a href=\"#\" data-headword=\"דִּילְמָא ²\"><span dir=\"rtl\">דִּילְמָא</span> I</a>; a. fr.—Euphem. <span dir=\"rtl\">ש׳ מטתו</span>, or only <a href=\"#\" data-headword=\"ש׳\">ש׳</a> <i>to perform the marital duty</i>; in gen. <i>to couple</i> (also of animals). <span class=\"citation\">Nidd. 17ᵃ</span>. <span class=\"citation\">Ib. II, 1</span>. <span class=\"citation\">Bekh. 8ᵃ</span>; <span class=\"citation\">Gen. R. s. 20</span>; a. fr.—<span class=\"citation\">Mikv. VIII, 4</span> <span dir=\"rtl\">שִׁמְּשָׁה את ביתה</span>, v. <a href=\"#\" data-headword=\"בַּיִת\">בַּיִת</a>.—<span class=\"citation\">Ned. II, 1</span> קונם שאיני מְשַׁמְּשָׁךְ I vow that I will not have intercourse with thee. <span class=\"citation\">Ib. 15ᵇ</span>; <span class=\"citation\">Keth. 71ᵇ</span> <span dir=\"rtl\">מְשַׁמַּשְׁתּוֹ</span> she must allow him marital intercourse; a. fr.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"שַׁמָּשׁ\">שַׁמָּשׁ</a>) <i>to attend, serve, wait upon</i>. <span class=\"citation\">Ab. I, 3</span> <span dir=\"rtl\">המְשַׁמְּשִׁין את הרב</span>, v. <a href=\"#\" data-headword=\"עֶבֶד\">עֶבֶד</a>. <span class=\"citation\">Sabb. 32ᵇ</span> <span dir=\"rtl\">זוכה ומשמשין לו וכ׳</span> he will live to see himself waited upon by two thousand … servants. <span class=\"citation\">Kidd. 32ᵇ</span> <span dir=\"rtl\">מצינו גדול ממנו שש׳</span> we find that a greater man than he waited (upon his guests); <span class=\"citation\">Yalk. Ex. 229</span>; a. fr.—Esp. (of students) <i>to be in attendance upon a scholar</i> as a disciple. <span class=\"citation\">Ber. 47ᵇ</span> <span dir=\"rtl\">אפי׳ … ולא ש׳ תלמידי וכ׳</span> even if one has studied the Bible and the Mishnah, but has failed to wait upon scholars, he is considered an <i>ʿam haarets</i> (v. <a href=\"#\" data-headword=\"אֶרֶץ\">אֶרֶץ</a>). <span class=\"citation\">Sot. 47ᵇ</span> <span dir=\"rtl\">שלא שִׁימְּשׁוּ כל צורכן</span> who did not wait upon scholars sufficiently. <span class=\"citation\">Y. Sabb. X, 12ᶜ</span> bot. <span dir=\"rtl\">שִׁמַּשְׁתִּי את אבא וכ׳</span>, v. <a href=\"#\" data-headword=\"יְשִׁיבָה\">יְשִׁיבָה</a> Ib. III, 6ᵃ (in Chald. dict.) <span dir=\"rtl\">ולא שי׳</span>, v. <a href=\"#\" data-headword=\"סָבוֹרָא\">סָבוֹרָא</a>; a. fr.</div><div class=\"sense\"><b>Hithpa. הִשְׁתַּמֵּשׁ</b> </div><div class=\"sense\"><b>Nithpa. נִשְׁתַּמֵּשׁ</b> <div class=\"sense\"> (with <a href=\"#\" data-headword=\"ב\">ב</a>) <i>to be handled, be used for</i>; (of persons) <i>to make use of, be waited upon</i>. <span class=\"citation\">Snh. 48ᵇ</span> <span dir=\"rtl\">נ׳ בהן קודש אסור להִשְׁתַּמֵּשׁ בהן חול</span> having once been used for a sacred purpose, it is forbidden to use them for a secular purpose. <span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">כלי שנ׳ … יִשְׁתַּמֵּשׁ בו חול</span> shall a vessel that has been used for a sacred purpose, be used for a profane purpose (i.e. shall I marry one inferior to my first husband)? <span class=\"citation\">Midr. Till. to Ps. CXIX, 134</span> <span dir=\"rtl\">כלי שנ׳ בו מלך וכ׳</span> a vessel which the king has used &amp;c., v. <a href=\"#\" data-headword=\"סָגָן\">סָגָן</a>. <span class=\"citation\">Ḥull. 60ᵇ</span> <span dir=\"rtl\">שׁיִשְׁתַּמְּשׁוּ בכתר אחד</span>, v. <a href=\"#\" data-headword=\"כֶּתֶר\">כֶּתֶר</a>. <span class=\"citation\">Koh. R. to II, 5</span> ברוחות … מִשְׁתַּמֵשׁ וכ׳ Solomon made use of the spirits, and he sent to India &amp;c. <span class=\"citation\">Ber. 52ᵇ</span> <span dir=\"rtl\">אסור להשתמש בשמש וכ׳</span> you must not be waited upon by an ignorant waiter. <span class=\"citation\">Gen. R. s. 37</span>; <span class=\"citation\">Yalk. ib. 62</span> <span dir=\"rtl\">שהיו מִשְׁתַּמְּשִׁין ברוה&quot;ק</span> (not <span dir=\"rtl\">משמשין</span>) who made use of (acted under) holy inspiration; a. fr.</div></div>","alt":["שִׁימֵּשׁ"]},"31788":{"h":"שְׁמַשׁ","r":"U01540","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"שָׁמַשׁ\">same</a>, <i>to minister, wait upon</i>. <span class=\"citation\">Targ. Gen. XVIII, 8</span>. <span class=\"citation\">Targ. I Kings I, 2</span>; <span class=\"citation\">4</span>. <span class=\"citation\">Targ. I Sam. I, 3</span>. <span class=\"citation\">Targ. Ex. XXVIII, 1</span>; a. fr.—Part. pass. <span dir=\"rtl\">מְשַׁמַּשׁ</span>. <span class=\"citation\">Targ. Koh. X, 6</span> <span dir=\"rtl\">בש׳ באצלחותא וכ׳</span> (not <span dir=\"rtl\">מְשַׁמֵּשׁ</span>) enjoying happiness from above.—<span class=\"citation\">Ab. Zar. 10ᵇ</span> אנטונינוס שַׁמְּשֵׁיה לרבי Antoninus waited upon (entertained) Rabbi; a. e.—Trnsf. <i>to couple</i>. <span class=\"citation\">Targ. Y. Lev. XV, 18</span>; a. fr.</div><div class=\"sense\"><b>Ithpa. אִשְׁתַּמֵּשׁ</b> <div class=\"sense\"><i>to make use of</i>. <span class=\"citation\">Ab. I, 13</span> <span dir=\"rtl\">ודיִשְׁתַּמַּשׁ בתגא חלף</span> he who makes use of the crown (of the Law) goes to ruin. <span class=\"citation\">Meg. 16ᵃ</span> <span dir=\"rtl\">לאו … לאִשְׁתַּמּוּשֵׁי במני וכ׳</span> it is unbecoming to make use of royal garments in such a condition; a. e.</div></div>","alt":["שַׁמֵּשׁ"]},"31789":{"h":"שַׁמָּשׁ","r":"U01541","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמַשׁ\">preced.</a>) <i>attendant, servant, waiter</i>. <span class=\"citation\">Pes. VII, 13</span> <span dir=\"rtl\">כשהש׳ עומד וכ׳</span> when the waiter (at a Passover meal of two parties) rises to serve the wine. <span class=\"citation\">Ber. 52ᵇ</span>, v. <a href=\"#\" data-headword=\"שָׁמַשׁ\">שָׁמַשׁ</a>; a. fr.—<span class=\"citation\">Snh. 59ᵇ</span> <span dir=\"rtl\">חבל על ש׳ גדול וכ׳</span> woe for the great servant (the most useful instrument of comfort) that was lost to the world! for if the serpent had not been cursed &amp;c.—Euphem. <i>membrum virile</i>. <span class=\"citation\">Nidd. 11ᵇ</span>. <span class=\"citation\">Ib. 41ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">שׁמָּשִׁים</span>, <span dir=\"rtl\">שַׁמָּשִׁין</span>. Mekh. Yithro, Baḥod., s. 10; <span class=\"citation\">R. Hash. 24ᵇ</span> (ref. to <span class=\"citation\">Ex. XX, 23</span>) <span dir=\"rtl\">לא תעשון כדמות שַׁמָּשַׁיי המשמשין לפני וכ׳</span> you shall not make an image like any of my servants (angels, Ḥayoth &amp;c.) that are in attendance before me on high. Ib. <span dir=\"rtl\">ש׳ שבמדור העליון</span> the servants of the higher dwelling (angels, Ḥayoth &amp;c.); <span dir=\"rtl\">שבמדור התחתון</span> of the lower dwelling (sun, moon &amp;c.); a. e.</div>","alt":[]},"31790":{"h":"שֶׁמֶשׁ","r":"U01542","html":"<div class=\"sense\"> c. (b. h.;; v. <span class=\"citation\">Gen. I, 16</span> <span dir=\"rtl\">לממשלת וכ׳</span>, a. <span class=\"citation\">Targ. Y. ib. I, 18</span>; cmp. <span class=\"citation\">R. Hash. 24ᵇ</span>, quot. in <a href=\"#\" data-headword=\"שַׁמָּשׁ\">preced.</a>) <i>sun</i>. <span class=\"citation\">Taan. 8ᵇ</span> <span dir=\"rtl\">ש׳ בשבת וכ׳</span> sunshine on the Sabbath is a charity to the poor (who are cheered by it). <span class=\"citation\">Pes. 2ᵃ</span> <span dir=\"rtl\">זריחת ש׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"זְרִיחָה\">זְרִיחָה</a>. Mekh. Mishp., s. 13 (ref. to <span class=\"citation\">Ex. XXII, 2</span>) <span dir=\"rtl\">וכי הש׳ עליו וכ׳</span> did the sun shine on him alone? <span dir=\"rtl\">אלא מה ש׳ שלום וכ׳</span> but (it means,) as the sun signifies peace to the world, so in this case, if it is sure that he has come in peace (without murderous intentions) &amp;c. <span class=\"citation\">Gen. R. s. 58</span>, beg. <span dir=\"rtl\">עד שלא ישקיע הקב&quot;ה שִׁמְשׁוֹ וכ׳</span> before the Lord causes the sun of one righteous man to set, he causes the sun of another to rise. <span class=\"citation\">Cant. R. to I, 6</span> <span dir=\"rtl\">שִׁמְשָׁהּ של ע&quot;ז</span>, v. <a href=\"#\" data-headword=\"שָׁזַף\">שָׁזַף</a>; a. fr.—Pl. <span dir=\"rtl\">שְׁמָשׁוֹת</span>.—<span dir=\"rtl\">בין הש׳</span> (abbrev. <span dir=\"rtl\">בה&quot;ש</span>) [<i>between the two services</i>, between the rulership of the day and that of the night,] <i>at twilight</i>. <span class=\"citation\">Sabb. 34ᵇ</span> <span dir=\"rtl\">איזהו בה&quot;ש … כל זמן שפני מזרח וכ׳</span> what time of the day is called <i>ben-hash-sh’mashoth</i>? From the time that the sun sets (and) as long as the eastern horizon is red (from the reflex); <span dir=\"rtl\">הכסיף … בה&quot;ש</span> when the lower horizon is pale, but the upper horizon is not, it is still <i>ben-hash-sh’mashoth</i> &amp;c.; <span class=\"citation\">Y. Ber. I, 2ᵇ</span> bot. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בה&quot;ש כהרף עין</span>, v. <a href=\"#\" data-headword=\"הֶרֶף\">הֶרֶף</a>. <span class=\"citation\">Ab. V, 6</span> <span dir=\"rtl\">עשרה … בה&quot;ש</span> ten things were created on the Sabbath eve at twilight; a. fr.</div>","alt":[]},"31791":{"h":"שִׁמְשָׁא","r":"U01543","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"שֶׁמֶשׁ\">same</a>. <span class=\"citation\">Targ. Y. Gen. I, 16</span>. <span class=\"citation\">Targ. Y. II ib. XLIX, 27</span>. <span class=\"citation\">Targ. Num. XXV, 4</span>; a. fr.—<span class=\"citation\">B. Bath. 84ᵃ</span>, v. <a href=\"#\" data-headword=\"סוּמַּקְתִּי\">סוּמַּקְתִּי</a>. <span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">ניגני בש׳</span> let him lie in the sun. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דמעלי ביה ש׳</span>, v. <a href=\"#\" data-headword=\"מַעֲלֵי\">מַעֲלֵי</a>. <span class=\"citation\">Gen. R. s. 68</span> (ref. to <span class=\"citation\">Gen. XXVIII, 11</span>) <span dir=\"rtl\">ששמע קולן … אתא ש׳ אתא ש׳</span> he heard the angels say …, the sun has come (Jacob, with ref. to <span class=\"citation\">Gen. XXXVII, 9</span>); a. fr.—<i>Pl.</i> <span dir=\"rtl\">שִׁמְשָׁתָא</span>, <span dir=\"rtl\">שִׁמְשַׁיָּא</span>, <a href=\"#\" data-headword=\"שִׁמְשַׁי\">שִׁמְשֵׁי</a>.—<span dir=\"rtl\">ביני ש׳</span> (<span dir=\"rtl\">בין</span>, <span dir=\"rtl\">בי</span>) <i>at twilight</i> (v. <a href=\"#\" data-headword=\"שֶׁמֶשׁ\">preced.</a>). <span class=\"citation\">Targ. Y. I Gen. XLIX, 27</span>. <span class=\"citation\">Targ. Ex. XII, 6</span> (h. text <span dir=\"rtl\">בין הערבים</span>); a. fr.—Esp. <span dir=\"rtl\">בי שמשא</span>, pl. <span dir=\"rtl\">בי שמשי</span> (sub. <span dir=\"rtl\">דמעלי שבתא</span>) <i>Friday evening, Sabbath eve</i>. <span class=\"citation\">Keth. 103ᵃ</span> <span dir=\"rtl\">כל בי שמשי הוי וכ׳</span> every Sabbath eve he used to come home; <span dir=\"rtl\">ההיא בי שמשא וכ׳</span> one Friday evening a neighbor came &amp;c. <span class=\"citation\">Ber. 43ᵇ</span> <span dir=\"rtl\">בקדושא דבי ש׳</span> by partaking of the wine at the Ḳiddush (v. <a href=\"#\" data-headword=\"קִידּוּשׁ\">קִירּוּשׁ</a>) on Friday night; a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"חַמָּה\">חַמָּה</a>) <i>fever</i>. <span class=\"citation\">Gitt. 67ᵇ</span> <span dir=\"rtl\">ש׳ בת יומא</span> diurnal fever; <span dir=\"rtl\">בת תלתא יומי</span> tertiary fever; <span dir=\"rtl\">ש׳ עתיקתא</span> chronic fever; a. e.—Pl. <span dir=\"rtl\">שִׁמְשִׁין</span> <i>red, inflammation</i>. Esth. R. introd. to II, 1 (R. Azariah) transl. <span dir=\"rtl\">חכללות עינים</span>, <span class=\"citation\">Prov. XXIII, 29</span>) <span dir=\"rtl\">ש׳ דעינין</span> inflammation of the eyes; <span class=\"citation\">Lev. R. s. 12</span> <a href=\"#\" data-headword=\"שִׁמְשְׁמִין\">שמשמין</a>; (<span class=\"citation\">Yalk. Prov. 960</span> <a href=\"#\" data-headword=\"סָמְקָן\">סמקן</a>).</div>","alt":["שִׁי׳"]},"31792":{"h":"שַׁמָּשָׁא","r":"U01544","html":"<div class=\"sense\"> c. = h. <a href=\"#\" data-headword=\"שַׁמָּשׁ\">שַׁמָּשׁ</a>. <span class=\"citation\">Targ. Y. II, Ex. XXXIII, 11</span> (v. <a href=\"#\" data-headword=\"מְשׁוּמְשָׁנָא\">מְשׁוּמְשָׁנָא</a>). <span class=\"citation\">Targ. Ez. XXIII, 20</span> ed. Lag. (oth. ed. <span dir=\"rtl\">שמוטא</span>, corr. acc.) <i>prostitute</i>.—Y. Taan. II, beg. 65ᵃ <span dir=\"rtl\">כל מאן דלא מטא ש׳ וכ׳</span> let him to whom the sexton has not come (to put ashes on his head) take ashes and put &amp;c. <span class=\"citation\">Y. Keth. IV, 28ᵈ</span> bot. <span dir=\"rtl\">לא מסתברא אגרין ליה ש׳ … דהיא ש׳</span> does it not stand to reason that they (the children to whom their father has assigned his property) must hire an attendant for him? So also must they give him a wife (if he desires it), and were it merely as his attendant; a. e.—Pl. <span dir=\"rtl\">שַׁמָּשִׁין</span>, <span dir=\"rtl\">שַׁמָּשַׁיָּא</span>; f. <a href=\"#\" data-headword=\"שַׁמָּשָׁא\">שַׁמָּשָׁן</a> <span class=\"citation\">Targ. Is. VI, 2</span> <span dir=\"rtl\">ש׳ קדישין</span> (h. text <span dir=\"rtl\">שרפים עמדים</span>). <span class=\"citation\">Targ. Ps. XXIX, 9</span>. <span class=\"citation\">Ib. CXXXVII, 6</span> <a href=\"#\" data-headword=\"שִׁמְשַׁי\">שַׁמָּשָׁי</a> (not <a href=\"#\" data-headword=\"שִׁמְשַׁי\">שַׁמְשָׁי</a>) my servants (the angels). <span class=\"citation\">Targ. I Sam. VIII, 13</span> (h. text <span dir=\"rtl\">רקחות</span>); a. e.</div>","alt":[]},"31793":{"h":"שִׁמְשׁוֹךְ","r":"U01545","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שֻׁמְשׁוּם\">next art.</a></div>","alt":[]},"31794":{"h":"שֻׁמְשׁוּם","r":"U01546","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שׁוּמְשׁוּם\">שׁוּמְשׁוּם</a></div>","alt":[]},"31795":{"h":"שִׁמְשׁוֹן","r":"U01547","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Samson</i>. <span class=\"citation\">Sot. I, 8</span> ש׳ הלך וכ׳ S. followed his eyes, therefore they put his eyes out. <span class=\"citation\">B. Bath. 91ᵃ</span>, v. <a href=\"#\" data-headword=\"הַצְּלֶלְפּוֹנִי\">הַצְּלֶלְפּוֹנִי</a>; a. fr.—<span class=\"citation\">Naz. I, 2</span> <span dir=\"rtl\">הריני כש׳ וכ׳</span> if one says, I will be like S., like Manoah’s son &amp;c. Ib., a. fr. <span dir=\"rtl\">נזיר ש׳</span>, v. <a href=\"#\" data-headword=\"נָזִיר\">נָזִיר</a>. Ib. <span dir=\"rtl\">מה בין … לנזיר ש׳</span> what is the difference between a Nazarite for life and a Nazarite like S.? Y. ib. 51ᵇ <span dir=\"rtl\">היידין אינון כינויי ש׳</span> what are the substitutes for Shimshon (in a Nazarite vow)? שמשוך שמשור שמשוץ <i>shimshokh, shimshor, shimshots</i></div>","alt":[]},"31796":{"h":"שִׁמְשׁוֹץ","r":"U01548","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁמְשׁוֹן\">preced.</a></div>","alt":["שִׁמְשׁוֹר"]},"31797":{"h":"שִׁמְשַׁי","r":"U01549","html":"<div class=\"sense\"> (<span class=\"citation\">Ezra IV, 8</span>, a. e.) pr. n. m. <i>Shimshai</i>, a scribe of the Samaritan colony; (in legend) a scribe at the court of Ahasuerus. Targ. II Esth. VI, 1.—<span class=\"citation\">Meg. 15ᵇ</span> sq. (ref. to <span class=\"citation\">Esth. VI, 2</span>) <span dir=\"rtl\">מלמד שש׳ מוחק וכ׳</span> this intimates that Sh. had erased (the record in favor of Mordecai), and Gabriel wrote it over. <span class=\"citation\">Yalk. Esth. 1045</span> המן … הוא ש׳ הסופר כלומר ש׳ בנו וכ׳ Haman the wicked, that is Sh. the scribe, that is to say, Sh. the son of Haman; Esth. R. introd.; a. e.</div>","alt":[]},"31798":{"h":"שִׁמְשְׁמִין","r":"U01550","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁמְשָׁא\">שִׁמְשָׁא</a></div>","alt":[]},"31799":{"h":"שמשק","r":"U01551","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שׁוּמְשׁוּק\">שׁוּמְשׁוּק</a></div>","alt":[]},"31800":{"h":"שְׁמַת","r":"U01552","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">שמם</span>) <i>to be still, desolate</i>.—Denom. <a href=\"#\" data-headword=\"שַׁמְתָּא\">שַׁמְתָּא</a>.</div><div class=\"sense\"><b>Pa. שַׁמֵּית</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שַׁמְתָּא\">שַׁמְתָּא</a>) <i>to excommunicate, accurse</i> <span class=\"citation\">M. Kat. 16ᵃ</span> <span dir=\"rtl\">מנלן דמְשַׁמְּתִינָן</span> whence do we derive the authority to excommunicate (persons refusing to obey the summons of the court)? Ib.; <span class=\"citation\">Shebu. 36ᵃ</span> <span dir=\"rtl\">שַׁמְּתֵיה וכ׳</span>, v. <a href=\"#\" data-headword=\"שִׁיפוֹרָא\">שִׁיפוֹרָא</a>. M. Kat. l. c. <span dir=\"rtl\">הנהו בי תלתא דמְשַׁמְּתֵי לא אתו וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">דשַׁמִּיתוּ</span>) when a court of three has declared a ban, another court of three cannot raise it. Ib. 17ᵃ <span dir=\"rtl\">ברישא מְשַׁמֵּית וכ׳</span> first he banned himself, and then him (the guilty scholar); a. fr.—Part. pass. (h. form) <a href=\"#\" data-headword=\"מְשׁוּמָּת\">מְשׁוּמָּת</a>. <span class=\"citation\">Sabb. 67ᵃ</span> (in an incantation) <span dir=\"rtl\">ליטא תבור ומש׳</span> cursed, broken, and banned.</div></div>","alt":[]},"31801":{"h":"שַׁמְתָּא","r":"U01553","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמַת\">preced.</a>) [<i>desolation</i>,] </div><div class=\"sense\"><b>1)</b> <i>curse, ban</i>. <span class=\"citation\">Targ. Y. Gen. XLII, 37</span>. <span class=\"citation\">Targ. Y. Num. XXI, 24</span>. <span class=\"citation\">Targ. Cant. II, 16</span>.—<span class=\"citation\">M. Kat. 17ᵃ</span> <span dir=\"rtl\">מאי ש׳</span> what is (the etymology of) <i>shamta?</i> Rab said <span dir=\"rtl\">שׁם̇ מ̇ית̇ה</span> there is death; Samuel said, <span dir=\"rtl\">שְׁמָמָה יהיה</span> (Ms. M. <a href=\"#\" data-headword=\"שַׁמָּה\">שַׁמָּה</a>; Ar. <span dir=\"rtl\">שם תהא</span>, read: <span dir=\"rtl\">שמה תהא</span>) he shall be (be thou) a desolation. Ib. <span dir=\"rtl\">ליהוי האי גברא בש׳</span> that man (thou) be excommunicated. Ib. 16ᵃ <span dir=\"rtl\">לא חל ש׳ עליה וכ׳</span> (masc.) the ban has not yet rested on him thirty days. Ib. <span dir=\"rtl\">עד דחיילא ש׳ וכ׳</span> (it cannot be raised) before he has been under the ban thirty days. <span class=\"citation\">Sot. 5ᵃ</span> <span dir=\"rtl\">בש׳ דאית ביה ובש׳ דלית ביה</span> he (the scholar) in whom there is pride deserves excommunication, and also he in whom there is no pride at all. <span class=\"citation\">Kidd. 12ᵇ</span> Rab ordered to be lashed <span dir=\"rtl\">על דחלא ש׳ וכ׳</span> him who allowed excommunication (for contempt of court) to rest on him thirty days (and did not submit to authority). <span class=\"citation\">B. Mets. 70ᵃ</span> ולא מקבל עליה ש׳ דרבנ‌ן Ms. M. and does not bring upon himself the ban of the Rabbis (but obeys their summons); a. fr.</div><div class=\"sense\"><b>—2)</b>  = h. <a href=\"#\" data-headword=\"חֵרֶם\">חֵרֶם</a>, <i>accursed object</i>. <span class=\"citation\">Targ. Y. Deut. XIII, 18</span>.—Pl. <a href=\"#\" data-headword=\"שַׁמְתִּית\">שַׁמְתִּין</a>. <span class=\"citation\">Ib. VII, 26</span>, v. <a href=\"#\" data-headword=\"שַׁמִּיתָא\">שַׁמִּיתָא</a>.</div>","alt":["שַׁמְּתָא","שַׁמַּתָּא"]},"31802":{"h":"שַׁמָּתִי","r":"U01554","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁמּוּתִי\">שַׁמּוּתִי</a></div>","alt":[]},"31803":{"h":"שַׁמְתִּית","r":"U01555","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁחַמְתִּית\">שְׁחַמְתִּית</a></div>","alt":[]},"31804":{"h":"שֵׁן","r":"U01556","html":"<div class=\"sense\"> c. (b. h.; </div><div class=\"sense\"><b>1)</b> <i>tooth, tooth-like projection</i>. <span class=\"citation\">Sabb. VI, 5</span> (<span class=\"citation\">64ᵇ</span>) <span dir=\"rtl\">שן תותבת ושן של זהב</span> an inserted (natural) tooth or an (artificial) gold tooth; (Bab. ed. <span dir=\"rtl\">שן תותכת שן וכ׳</span>, Ms. O. <span dir=\"rtl\">ושן</span>, v. Rashi a. l.). Ib. 10, v. <a href=\"#\" data-headword=\"שׁוּעָל\">שׁוּעָל</a>; a. fr.—Esp. (sub. <span dir=\"rtl\">נזק</span>) <i>the damage done by an animal’s eating</i>. <span class=\"citation\">B. Kam. 2ᵇ</span> <span dir=\"rtl\">שלשה … הקרן והשן והרגל</span> three chief damages are mentioned (in the Scriptural text) with reference to the ox: damage by the horn, by the tooth, and by the foot. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תולדה דשן</span>, v. <a href=\"#\" data-headword=\"נְשִׁיכָה\">נְשִׁיכָה</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שן יש הנאה וכ׳</span>, v. <a href=\"#\" data-headword=\"הֶיזֵּק\">הֶיזֵּק</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אשן ורגל</span> it refers to damages by the tooth and by the foot; <span dir=\"rtl\">שן ורגל היכא כתיבי</span> where is the damage by the tooth or the foot written (in the Biblical text)? Ib. <span dir=\"rtl\">ובער זו השן</span> <i>ubhiʿer</i> (<span class=\"citation\">Ex. XXII, 4</span>) this refers to damage by the tooth; a. fr.—<i>Du</i>. <span dir=\"rtl\">שִׁנַּיִים</span>, <a href=\"#\" data-headword=\"שְׁנַיִם\">שִׁנַּיִם</a>, <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁי׳</a>. <span class=\"citation\">Ḥull. I, 2</span> <span dir=\"rtl\">בכל … והש׳</span> you may cut ritually with anything, except … with teeth in the jaw. Ib. <span dir=\"rtl\">ואם החליקו שִׁינֶּיהָ</span> and if the teeth of the saw have been made smooth. <span class=\"citation\">Keth. 71ᵇ</span> <span dir=\"rtl\">בין שיניה</span>, v. <a href=\"#\" data-headword=\"אֶצְבַּע\">אֶצְבַּע</a>. <span class=\"citation\">Ib. 16ᵃ</span>, v. <a href=\"#\" data-headword=\"כֶּרֶס\">כֶּרֶס</a>. <span class=\"citation\">Kel. XIII, 8</span> <span dir=\"rtl\">שניטלו שִׁינָּיו</span> (a hackle) whose teeth are broken off. <span class=\"citation\">Gen. R. s. 33</span> חשש רבי את שיניו וכ׳ Rabbi suffered from tooth-ache for thirteen years. <span class=\"citation\">Keth. 111ᵇ</span> <span dir=\"rtl\">טוב המלבין ש׳ וכ׳</span> he who causes his neighbor to show the white of his teeth (who makes him cheerful) does better than he who gives him milk to drink. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">א&quot;ת לבן ש׳ אלא לבון ש׳</span> read not <i>l’ben shinnayim</i> (<span class=\"citation\">Gen. XLIX, 12</span>) but <i>libbun shinnayim</i> (whitening of teeth, cheerfulness); a. fr.— <i>any organ of the body resembling teeth, gland.—Du.</i> as ab. <span class=\"citation\">Y. Yeb. VI, beg. 7ᵇ</span> <span dir=\"rtl\">בית הש׳</span> that part of the vagina which has glands; <span dir=\"rtl\">מבין הש׳ ולפנים</span> from the glands and farther inside; <span class=\"citation\">Nidd. 41ᵇ</span>. <span class=\"citation\">Ḥull. 16ᵇ</span> <span dir=\"rtl\">שיניו נושרות</span> the glands of his rectum will fall off; <span class=\"citation\">Sabb. 82ᵃ</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>cliff, peak</i>. <span class=\"citation\">Gen. R. s. 74</span> <span dir=\"rtl\">כשן הזה של וכ׳</span> (the stone which Jacob put up was) as large as the peak of Tiberias; <span class=\"citation\">Yalk. ib. 130</span>; a. e.</div><div class=\"sense\"><b>—4)</b>  (sub. <span dir=\"rtl\">של פיל</span>) <i>ivory</i>. <span class=\"citation\">Num. R. s. 3</span><sup>12</sup> (play on <span dir=\"rtl\">מי יג̇ור̇ … חזק כש̇ן̇</span> (<span dir=\"rtl\">ג̇ר̇ש̇ון̇</span> who can abide snow and hail, and cold and heat? He who is as strong as ivory (or marble?); <span dir=\"rtl\">אין שן אלא לשון חזק וכ׳</span> <i>shen</i> has the meaning <i>of strong</i> (ref. to <span class=\"citation\">Cant. V, 14</span>); a. e</div><div class=\"sense\"><b>—5)</b> <i>marble</i>. <span class=\"citation\">Cant. R. to V, 11</span>; <span class=\"citation\">Yalk. ib. 991</span>, v. <a href=\"#\" data-headword=\"עֶשֶׁת\">עֶשֶׁת</a>.</div>","alt":[]},"31805":{"h":"שֵׁן ²","r":"U01557","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Deut. XXXII, 24</span>. <span class=\"citation\">Targ. Ex. XXI, 24</span>. <span class=\"citation\">Targ. I Kings X, 22</span> (v. <a href=\"#\" data-headword=\"פִּילָא IV\"><span dir=\"rtl\">פִּילָא</span> I</a>). <span class=\"citation\">Ib. 18</span>. <span class=\"citation\">Targ. I Sam. XIV, 4</span>; a. fr.—Y. Kil. IX, 32ᵇ bot; <span dir=\"rtl\">האי שִׁינָּךְ וכ׳</span> how is that tooth of thine?; Y. Keth. XII, 35ᵃ bot.; <span class=\"citation\">Gen. R. s. 33</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יהב ידיה על שִׁינֵּיה וכ׳</span> he put his hand on his (Rabbi’s) tooth, and it was cured.—<span class=\"citation\">Gitt. 68ᵇ</span> <span dir=\"rtl\">ומנח להו אש׳ דטורא וכ׳</span> he puts it (the Shamir) on the peak of a mountain, and the mountain bursts. <span class=\"citation\">Snh. 96ᵇ</span> <span dir=\"rtl\">תא אש׳ דטורא</span> (Rashi <span dir=\"rtl\">דטורי</span>) come (to Jerusalem) even if it be necessary to march over the cliffs of mountains (differ. in Rashi); <span class=\"citation\">Yalk. Is. 287</span>; a. fr.—<span dir=\"rtl\">ש׳ דדור</span>, <span dir=\"rtl\">שן דור</span> pr. n. pl. <i>the Cliff of Dor</i> (v. Hildesh. Beitr. pp. 4; <span class=\"citation\">10</span>). Y. Shebi. VI, 36ᶜ (not <a href=\"#\" data-headword=\"דְּרוֹר\">דרור</a>); <span class=\"citation\">Tosef. Shebi. IV, 11</span> <span dir=\"rtl\">שורא דרור</span> (corr. acc.); <span class=\"citation\">Sifré Deut. 51</span> [read:] <span dir=\"rtl\">מדבר שר שן דור</span>; <span class=\"citation\">Yalk. ib. 874</span> (corr. acc.).—Pl. <a href=\"#\" data-headword=\"שְׁנַן\">שִׁנִּין</a>, <a href=\"#\" data-headword=\"שַׁנְיָא\">שִׁנַּיָּא</a>, <a href=\"#\" data-headword=\"שְׁנֵי\">שִׁנֵּי</a>, <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁי׳</a>. <span class=\"citation\">Targ. Am. IV, 6</span> (not <a href=\"#\" data-headword=\"שְׁנַן\">שְׁנִין</a>). <span class=\"citation\">Targ. Prov. X, 26</span>.—<span class=\"citation\">Targ. Jer. XLIX, 16</span>. <span class=\"citation\">Targ. Y. Gen. XLIX, 21</span> (not <a href=\"#\" data-headword=\"שֵׁינִי\">שֵׁינֵי</a>); a. fr.—Y. Kil. IX, 32ᵇ <span dir=\"rtl\">תלת … חשש</span> (<a href=\"#\" data-headword=\"ב\">ב</a>)<a href=\"#\" data-headword=\"שִׁינּוּי\">שִׁינּוֹי</a> suffered from tooth-ache for thirteen years. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חד שִׁינַּיי וכ׳</span> one of my teeth annoys me; (Y. Keth. l. c. <span dir=\"rtl\">חד שינא</span>).—<span class=\"citation\">Sabb. 82ᵃ</span>, v. <a href=\"#\" data-headword=\"כַּרְכְּשָׁא\">כַּרְכְּשָׁא</a>; a. fr.</div>","alt":["שִׁנָּא","שִׁי׳"]},"31806":{"h":"שִׁנָא","r":"U01558","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שֵׁינְתָא\">שֵׁינְתָא</a></div>","alt":[]},"31807":{"h":"שָׂנֵא","r":"U01559","html":"<div class=\"sense\"> (b. h.) <i>to hate</i>. <span class=\"citation\">Pes. 49ᵇ</span> <span dir=\"rtl\">גדולה שנאה ששׂוֹנְאִין וכ׳</span> great is the hatred with which the ignorant hate the scholar, even greater than that which gentiles bear towards Israel. <span class=\"citation\">Ib. 113ᵇ</span> <span dir=\"rtl\">שלשה שׂוֹנְאָן</span> three classes of men does the Lord hate. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שלשה שונאין זה וכ׳</span> three kinds of creatures hate one another, the dog &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מצוה לִשְׂנֹאתוֹ</span> (Var. <span dir=\"rtl\">מותר</span>) it is right (permitted) to hate him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שִׂנְאוּ את אדניכם</span> hate your masters. <span class=\"citation\">Snh. 108ᵇ</span> the raven said to Noah, <span dir=\"rtl\">רבך שׂוֹנְאֵנִי ואתה שְׂנֵאתַנִי</span> thy master (God) hates me, and thou hatest me. <span class=\"citation\">Ab. I, 10</span> <span dir=\"rtl\">אהוב … ושְׂנָא וכ׳</span> love work and hate office; a. fr.—Part. pass. <a href=\"#\" data-headword=\"שַׂנֹּוא\">שָׂנוּא</a>; f. <span dir=\"rtl\">שְׂנוּאָה</span> &amp;c. <span class=\"citation\">Kidd. 68ᵃ</span>; <span class=\"citation\">Yeb. 23ᵃ</span> (ref. to <span class=\"citation\">Deut. XXI, 15</span>) <span dir=\"rtl\">וכי יש ש׳ לפני המקום וכ׳</span> is there before God a hated one and a beloved one (could it be supposed that the law should allow a discrimination between the children of a favored and of a hated wife)? Ib. <span dir=\"rtl\">ש׳ בנישואיה</span>, v. <a href=\"#\" data-headword=\"נִישּׂוּאִין\">נִישּׂוּאִין</a>; a. e.—Sifra K’doshim, Par. 3, ch. VIII <span dir=\"rtl\">שָׂנְאוּי</span>.</div><div class=\"sense\"><b>Nif. נִשְׂנָא</b> </div><div class=\"sense\"><b>Nithpa. נִשְׂתַּנֵּא</b> <div class=\"sense\"><i>to be hated</i>. <span class=\"citation\">Num. R. s. 4</span><sup>8</sup> <span dir=\"rtl\">הר ס̇ינ̇י שבו נִשְׂנְאוּ וכ׳</span> it is called Mount Sinai, because on it the gentiles became hateful to the Lord &amp;c. (v. <a href=\"#\" data-headword=\"שִׂנְאָה\">שִׂנְאָה</a>); <span class=\"citation\">Yalk. Is. 363</span> <span dir=\"rtl\">נִשְׂתַּנְּאוּ</span>. <span class=\"citation\">Taan. 7ᵇ</span> (ref. to <span dir=\"rtl\">ישנא</span>, <span class=\"citation\">Koh. VIII, 1</span>) <span dir=\"rtl\">א&quot;ת ישונא אלא יִשָּׂנֵא</span> read not <i>y’shunne</i> (shall be changed), but <i>yissane</i> (shall be hated).</div></div><div class=\"sense\"><b>Pu. שׂוּנָּא</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"שִׁנָא\">same</a>. <span class=\"citation\">Pesik. R. s. 14</span> (ref. to Koh. l. c.) <span dir=\"rtl\">יְשׂוּנֶּא יְסוּנֶּה בסמ&quot;ך</span> read <i>y’sunne</i>, with Samekh (v. supra).</div></div>","alt":[]},"31808":{"h":"שְׂנֵא","r":"U01560","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנֵי\">סְנֵי</a></div>","alt":[]},"31809":{"h":"שְׁנָא I","r":"U01561","html":"<div class=\"sense\"><i>to change</i>, v. <a href=\"#\" data-headword=\"שְׁנֵי\">שְׁנֵי</a>.</div>","alt":[]},"31810":{"h":"שְׁנָא II","r":"U01562","html":"<div class=\"sense\"> , <i>year</i>. <span class=\"citation\">Targ. Lev. XXV, 53</span> (O. ed. Vien. <a href=\"#\" data-headword=\"שֵׁנָה\">שְׁנָה</a>); a. fr.—Constr. <span dir=\"rtl\">שְׁנַת</span>. <span class=\"citation\">Ib. 5</span>; a. e.—Pl. <a href=\"#\" data-headword=\"שַׁנְיָא\">שְׁנַיָּא</a>, <a href=\"#\" data-headword=\"שְׁנַן\">שְׁנִין</a>, <a href=\"#\" data-headword=\"שְׁנֵי\">שְׁנֵי</a>, <a href=\"#\" data-headword=\"שְׁבָתָא\">שְׁנָתָא</a>. <span class=\"citation\">Ib. 3</span>; <span class=\"citation\">15</span>; <span class=\"citation\">52</span>; a. fr.—<span class=\"citation\">Targ. Ps. XC, 10</span> שְׁנָתָנָא Ms. (ed. <span dir=\"rtl\">שְׁנוֹתָנָא</span>).—<span class=\"citation\">R. Hash. 31ᵃ</span> <span dir=\"rtl\">שיתא אלפי ש׳ וכ׳</span> the world will last six thousand years. <span class=\"citation\">Ab. Zar. 9ᵃ</span>. <span class=\"citation\">Ib. 9ᵇ</span> sq. <span dir=\"rtl\">ההוא … שית ש׳ יתירתא</span> a document dated six years ahead; a. fr.</div>","alt":[]},"31811":{"h":"שִׁנְאָב","r":"U01563","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנָאָה\">סְנָאָה</a></div>","alt":["שִׂנְאָב"]},"31812":{"h":"שַׂנְאָה","r":"U01564","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">שַׂנְאַיָּיא</span>, v. <a href=\"#\" data-headword=\"סַנְאָה\">סַנְאָה</a>.</div>","alt":[]},"31813":{"h":"שִׂנְאָה","r":"U01565","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>hatred</i>. <span class=\"citation\">Sabb. 32ᵇ</span>, a. fr. <span dir=\"rtl\">שִׂנְאַת חנם</span>, v. <a href=\"#\" data-headword=\"חִנָּם\">חִנָּם</a>. <span class=\"citation\">Ab. II, 11</span> <span dir=\"rtl\">שנאת הבריות</span> misanthropy. <span class=\"citation\">Pes. 49ᵇ</span>, v. <a href=\"#\" data-headword=\"שָׂנֵא\">שָׂנֵא</a>. <span class=\"citation\">Sabb. 89ᵃ</span> (play on <a href=\"#\" data-headword=\"סִינַי\">סִינַי</a>) <span dir=\"rtl\">הר שירדה ש׳ לאו&quot;ה עליו</span> the mountain on which came down hatred to the gentiles (who refused to receive the Law, v. <a href=\"#\" data-headword=\"שָׂנֵא\">שָׂנֵא</a>); <span class=\"citation\">ib.ᵇ</span>; a. fr.</div>","alt":[]},"31814":{"h":"שנאון","r":"U01566","html":"<div class=\"sense\">, <span class=\"citation\">Esth. R. to II, 1</span> <span dir=\"rtl\">(ר׳ עזריה</span>), corrupt dittography of <a href=\"#\" data-headword=\"שְׁפָאִים\">שַׁפָּאין</a>, v. <a href=\"#\" data-headword=\"שַׁפַּיי\">שַׁפַּיי</a></div>","alt":[]},"31815":{"h":"שַׂנְאוּתָא","r":"U01567","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שנאון\">preced. art.</a>) <i>object of hatred, enemies</i>. <span class=\"citation\">Shebu. 35ᵇ</span> <span dir=\"rtl\">שַׂנְאוּתֵיה מאי נינהו</span> (Ms. M. <span dir=\"rtl\">שנאיה מאן וכ׳</span>) who are his (Nebuchadnezzar’s) enemies?; Yalk. Dan. 1060 <span dir=\"rtl\">סַנְיוּתֵיה</span>.</div>","alt":[]},"31816":{"h":"שִׁנְאָן","r":"U01568","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"שָׁנָה II\"><span dir=\"rtl\">שָׁנָה</span> I</a>) <i>repetition, double</i>. Pesik. Baḥod., p. 107ᵇ (ref. to <span class=\"citation\">Ps. LXVIII, 18</span> <span dir=\"rtl\">רבותים אלפי ש׳</span>) <span dir=\"rtl\">ירד … בעשרים ושנים אלף וכ׳</span> the Lord came down on Sinai with twenty and two thousand classes of ministering angels; ib. 108ᵃ (= <span dir=\"rtl\">שנון</span>) <span dir=\"rtl\">וכולן ירדו שנונין לכלות וכ׳</span> and all of them came down (with) sharpened (swords), ready to consume Israel’s enemies (euphem. for Israel) &amp;c.; ib. (as if from <span dir=\"rtl\">נאה</span>) <span dir=\"rtl\">הנאין … שבהם</span> the most beautiful and worthy of them; ib. (= <a href=\"#\" data-headword=\"שַׁאֲנָן\">שאנן</a>) <span dir=\"rtl\">אעפ&quot;כ היה להם ריוח</span> in spite of their large numbers they had room; <span class=\"citation\">Pesik. R. s. 21</span>; <span class=\"citation\">Yalk. Ex. 286</span>; <span class=\"citation\">Yalk. Ps. 796</span>.</div>","alt":[]},"31817":{"h":"שִׁנְדְּפִין","r":"U01569","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁינְדְּפִין\">שִׁינְדְּפִין</a></div>","alt":[]},"31818":{"h":"שָׁנָה","r":"U01570","html":"<div class=\"sense\"> I, v. <a href=\"#\" data-headword=\"שני\">שני</a></div>","alt":[]},"31819":{"h":"שָׁנָה II","r":"U01571","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , Revue des Et. Juives XI, 1885, p. 64) <i>year</i>. <span class=\"citation\">Ber. 55ᵃ</span> <span dir=\"rtl\">שלשה … ש׳ טובה וכ׳</span> three things must be prayed for: a good king, a good year, and a good dream. <span class=\"citation\">R. Hash. I, 1</span>, a. fr. <span dir=\"rtl\">ראש הש׳</span>, v. <a href=\"#\" data-headword=\"רֹאשׁ\">רֹאשׁ</a>. <span class=\"citation\">Ib. 2ᵃ</span> <span dir=\"rtl\">עלתה לו ש׳</span> it is counted as one year of his reign (his second year begins). <span class=\"citation\">Y. Yoma V, 42ᶜ</span> top; Bab. <span class=\"citation\">ib. 53ᵇ</span>, v. <a href=\"#\" data-headword=\"גָּשַׁם\">גָּשַׁם</a>. <span class=\"citation\">Ib. 39ᵇ</span> <span dir=\"rtl\">אותה ש׳ … בש׳ זו הוא מת</span> (on the Day of Atonement of) the year in which Simon the righteous died, he said to them, in this year he (euphem. for I) shall die. <span class=\"citation\">Snh. 97ᵃ</span>; <span class=\"citation\">Ab. Zar. 9ᵃ</span> <span dir=\"rtl\">ששת אלפים ש׳ וכ׳</span> the world will last six thousand years. <span class=\"citation\">Naz. 5ᵃ</span> <span dir=\"rtl\">אותה ש׳ … שנת עשר וכ׳</span> the year in which they asked for a king was the tenth year of office of Samuel &amp;c. <span class=\"citation\">Par. I, 1</span> <span dir=\"rtl\">בת שְׁנָתָהּ</span> in her first year; a. v. fr.—Pl. <a href=\"#\" data-headword=\"שְׁנַיִם\">שָׁנִים</a>, constr. <span dir=\"rtl\"><span dir=\"rtl\">שְׁנוֹת</span> (שְׁנֵי</span>). Naz. l. c. <span dir=\"rtl\">ימים שאין עמהן ש׳</span> ‘days’ in the Scriptures to which the word ‘years’ is not attached; <span dir=\"rtl\">זה שיש עמו ש׳</span> this passage (<span class=\"citation\">Gen. XLI, 1</span>) where ‘years’ is combined with days. <span class=\"citation\">Yoma 71ᵃ</span> (ref. to <span class=\"citation\">Prov. III, 2</span>) <span dir=\"rtl\">וכי יש ש׳ של חיים ויש ש׳ שאינן וכ׳</span> are there years of life, and years of no life? <span dir=\"rtl\">אלו שְׁנוֹתָיו של אדם וכ׳</span> those are a man’s years which are changed for him from evil to good. <span class=\"citation\">Sabb. 89ᵇ</span> (ref. to <span dir=\"rtl\">כשנים</span>, <span class=\"citation\">Is. I, 18</span>) <span dir=\"rtl\">אם יהיו חטאיכם כש׳ הללו וכ׳</span> if your sins were as many as the years that have been arranged and have come down from the six days of creation until now, they shall become white &amp;c.; <span class=\"citation\">Yalk. Is. 256</span>; <span class=\"citation\">Y. Sabb. IX, 12ᵃ</span> bot. <span dir=\"rtl\">כש׳ שבין וכ׳</span> as the years (required for travelling) between the heaven and the earth; <span dir=\"rtl\">כשְׁנֵי אבות</span> as the years of the patriarchs; a. v. fr.—<span dir=\"rtl\">ברכת הש׳</span> (the blessing of the harvests of the year) <i>birkhath hash-shanim</i>, the ninth section of the Prayer of Benedictions <a href=\"#\" data-headword=\"תְּפִלָּה\">(תְּפִלָּה</a>). <span class=\"citation\">Ber. 29ᵃ</span>, v. <a href=\"#\" data-headword=\"שְׁאֵלָה\">שְׁאֵלָה</a>. <span class=\"citation\">Taan. 2ᵃ</span>; a. fr.</div>","alt":[]},"31820":{"h":"שֵׁנָה","r":"U01572","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שֵׁינָה\">שֵׁינָה</a></div>","alt":[]},"31821":{"h":"שְׁנוּ","r":"U01573","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁנֵי\">שְׁנֵי</a>) </div><div class=\"sense\"><b>1)</b> <i>change, reverse</i>. <span class=\"citation\">Targ. Ez. XVI, 34</span>.</div><div class=\"sense\"><b>—2)</b> <i>strangeness, something bewildering</i>. <span class=\"citation\">Targ. Jer. V, 30</span> (h. text <span dir=\"rtl\">שערורה</span>). <span class=\"citation\">Ib. XVIII, 13</span> (ed. Wil. <a href=\"#\" data-headword=\"שְׁנוּי\">שְׁנוּי</a>; h. text <span dir=\"rtl\">שעררת</span>). <span class=\"citation\">Ib. XXIII, 14</span> (ed. Wil. <a href=\"#\" data-headword=\"שְׁנוּ\">שְׁנוֹ</a>). <span class=\"citation\">Targ. Hos. VI, 10</span>.</div>","alt":[]},"31822":{"h":"שַׂנֹּוא","r":"U01574","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנּוֹא\">סַנֹּוא</a></div>","alt":[]},"31823":{"h":"שְׂנוּאֲתָא","r":"U01575","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׂנוּאֲתָא\">שְׂנוּאֲתָא</a></div>","alt":["שְׂנִיאֲתָא","שָׂנֵיתָא"]},"31824":{"h":"שְׁנוּי","r":"U01576","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁנוּ\">שְׁנוּ</a></div>","alt":[]},"31825":{"h":"שְׁנּוּי","r":"U01577","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"שִׁינּ־\">שִׁינּ׳</a>.</div>","alt":["שִׁנּוּיָא","שִׁנּוּן"]},"31826":{"h":"שָׁנוּן","r":"U01578","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁנַן\">שָׁנַן</a></div>","alt":[]},"31827":{"h":"שְׁנוּן","r":"U01579","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁנַן\">שְׁנַן</a></div>","alt":["שְׁנוּנָא"]},"31828":{"h":"שְׁנוּנִית","r":"U01580","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"שׁוּנִּית\">שׁוּנִּית</a>, <i>cliff, bluff, embankment</i>. <span class=\"citation\">Y. B. Kam. X, 7ᵇ</span> bot. <span dir=\"rtl\">המציל … מש׳ הים משלילית הנהר</span> he who rescues things … from the bluff of the sea, or from the alluvium of the river (v. <a href=\"#\" data-headword=\"שְׁלוּלִית\">שְׁלוּלִית</a>); <span class=\"citation\">Y. Shek. VII, 50ᶜ</span> bot. <span dir=\"rtl\">משונת הים ומשונת הנהר</span> (v. <a href=\"#\" data-headword=\"שׁוּנִּית\">שׁוּנִּית</a>); <span class=\"citation\">Tosef. B. Mets. II, 2</span> משֻׁנִּיתוֹ של ים ומשֻׁנִּיתוֹ של נהר Var. (ed. Zuck. <span dir=\"rtl\">משלוליתו … משלוליתו וכ׳</span>); (<span class=\"citation\">B. Mets. 21ᵇ</span> <span dir=\"rtl\">מזוטו וכ׳</span>, v. <a href=\"#\" data-headword=\"זֶוֶט\">זֶוֶט</a>).</div>","alt":[]},"31829":{"h":"שִׁנּוּקָא","r":"U01581","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁינּוּקָא\">שִׁינּוּקא</a></div>","alt":[]},"31830":{"h":"שָׂנַט","r":"U01582","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָנַט\">סָנַט</a></div>","alt":[]},"31831":{"h":"שָׁנֵי","r":"U01583","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Cant. I, 17</span> ed. Vien., read <a href=\"#\" data-headword=\"שְׁגֵי\">שָׁגֵי</a>, v. <a href=\"#\" data-headword=\"שָׁאגָא\">שָׁאגָא</a></div>","alt":[]},"31832":{"h":"שָׁנִי","r":"U01584","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>scarlet</i>; <span dir=\"rtl\">תולעת ש׳</span>, v. <a href=\"#\" data-headword=\"תּוֹלֵעָה\">תֹּולֵעָה</a>.—Pl. <a href=\"#\" data-headword=\"שְׁנַיִם\">שָׁנִים</a>. <span class=\"citation\">Sabb. 89ᵇ</span> (ref. to <span class=\"citation\">Is. I, 18</span>) <span dir=\"rtl\">כשנים כשני מיבעי ליה וכ׳</span> <i>kasshanim?</i> it ought to read <i>kasshani</i> (as scarlet) &amp;c.; <span class=\"citation\">Yalk. Is. 256</span>; a. e., v. <a href=\"#\" data-headword=\"שָׁנָה II\"><span dir=\"rtl\">שָׁנָה</span> II</a>.</div>","alt":[]},"31833":{"h":"שני","r":"U01585","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to repeat, do a second time</i>. <span class=\"citation\">Yoma 86ᵇ</span> <span dir=\"rtl\">ואם ש׳ בהן וכ׳</span> but if he committed the same sins again, he must confess them. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כיון … וש׳ בה וכ׳</span> when a man commits a sin and repeats it, it appears to him permitted; <span class=\"citation\">M. Kat. 27ᵇ</span>. <span class=\"citation\">Ib. 16ᵇ</span>; <span class=\"citation\">Ber. 18ᵃ</span> <span dir=\"rtl\">אם קרית לא שָׁנִיתָ ואם שנית וכ׳</span> if thou hast read (studied), thou hast not repeated, and if thou hast repeated, thou hast not reviewed a third time, and if thou hast done so, they have not explained it to thee (v. <a href=\"#\" data-headword=\"פָּרַשׁ\">פָּרַשׁ</a>). <span class=\"citation\">Sot. 9ᵃ</span> (ref. to <span class=\"citation\">Mal. III, 6</span>) <span dir=\"rtl\">לא … ושָׁנִיתִי לה וכ׳</span> I never struck a nation and had to do it a second time, but you, children of Israel, have not been consumed; <span class=\"citation\">Yalk. Deut. 825</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שהיה מכה … ולא שֹׁונֶה לו</span> who used to strike a man once and no more (killed with one stroke). <span class=\"citation\">Tosef. Toh. IV, 1</span> <span dir=\"rtl\">אומר לו שיִשְׁנֶה</span> we say to him that he should do it again (when it will be seen whether it can be done without touching uncleanness); <span dir=\"rtl\">אין שֹׁונִין בטהרות</span> we must not try again for the purpose of deciding in matters of levitical cleanness; <span class=\"citation\">Nidd. 5ᵇ</span> <span dir=\"rtl\">אומרים לו שְׁנֵה ושונה</span> we say to him, do it again, and he does it again; a. fr.—Part. pass. <a href=\"#\" data-headword=\"שְׁנוּי\">שָׁנוּי</a>; f. <span dir=\"rtl\">שְׁנוּיָה</span> &amp;c. <span class=\"citation\">Meg. 31ᵃ</span>; <span class=\"citation\">Ab. Zar. 19ᵇ</span>, v. <a href=\"#\" data-headword=\"שָׁלַשׁ\">שָׁלַשׁ</a>; a. e.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"מִשְׁנָה\">מִשְׁנָה</a>) <i>to study the Mishnah</i>; in gen. <i>to study; to teach</i>. <span class=\"citation\">Meg. 28ᵇ</span>; <span class=\"citation\">Nidd. 73ᵃ</span> <span dir=\"rtl\">כל השונה וכ׳</span> he who studies (reviews) traditional laws every day. <span class=\"citation\">Meg. 32ᵃ</span>; <span class=\"citation\">Treat. Sof’rim III, 10</span> <span dir=\"rtl\">השונה בלא זמרה</span> who studies (Mishnah and Gemarah) without chant. <span class=\"citation\">B. Mets. 44ᵃ</span> <span dir=\"rtl\">שנית לנו … ותִשְׁנֶה לנו וכ׳</span> in thy earlier days thou taughtest us …, and again in thy old days, thou teachest us &amp;c.?; <span class=\"citation\">Ab. Zar. 52ᵇ</span>. <span class=\"citation\">Erub. 92ᵃ</span> <span dir=\"rtl\">וכי רבי לא שְׁנָאָהּ וכ׳</span> but if Rabbi has not taught that, whence could R. Ḥiyya have it?; <span class=\"citation\">Yeb. 43ᵃ</span>; <span class=\"citation\">Nidd. 62ᵃ</span> רבי לא שנה וכ׳ Rabbi has not taught this? whence &amp;c.? <span class=\"citation\">Yeb. 108ᵇ</span>, a. e. <span dir=\"rtl\">מי שש׳ זו לא ש׳ זו</span> he who taught this, has not taught that, i.e. the two clauses in the Mishnah are from different authors, v. <a href=\"#\" data-headword=\"תְּבַר ²\">תַּבְרָא</a>. <span class=\"citation\">Ḥull. 85ᵃ</span> ראה רבי … ושְׁנָאָן וכ׳ Ms. M. (ed. <span dir=\"rtl\">ושנאו</span>) Rabbi approved of the opinion of R. …, and embodied it in the Mishnah as the opinion of ‘the scholars’. <span class=\"citation\">Pes. 3ᵇ</span>; <span class=\"citation\">Ḥull. 63ᵇ</span> <span dir=\"rtl\">לעולם יִשְׁנֶה אדם לתלמידו וכ׳</span> one should always teach his pupil the shortest way (use the briefest terms). <span class=\"citation\">Ib. 81ᵇ</span>, a. fr. <span dir=\"rtl\">לא שָׁנוּ אלא וכ׳</span> they have taught this only with regard to a case &amp;c., i.e. this is meant only when &amp;c.; a. fr.—Part. pass. as ab. <span class=\"citation\">Nidd. 22ᵇ</span>, a. fr. <span dir=\"rtl\">במחלוקת שנויה</span>, v. <a href=\"#\" data-headword=\"מַחֲלוֹקֶת\">מַחֲלוֹקֶת</a>.</div><div class=\"sense\"><b>Nif. נִשְׁנֶה</b> <div class=\"sense\"><b>1)</b> <i>to be repeated</i>. <span class=\"citation\">Snh. 59ᵃ</span> <span dir=\"rtl\">ונִישְׁנֵית</span>, v. <a href=\"#\" data-headword=\"נֹחַ\">נֹחַ</a>. <span class=\"citation\">Ḥull. 63ᵇ</span> <span dir=\"rtl\">למה נִשְׁנוּ בבהמה וכ׳</span> why are the laws of clean and unclean animals repeated (in Deut.)? With reference to quadrupeds, on account of <i>hassh’suʿah</i> (<span class=\"citation\">Deut. XIV, 7</span>, which is not found in <span class=\"citation\">Lev. XI, 4</span>) &amp;c., v. <a href=\"#\" data-headword=\"שְׁסוּעָה\">שְׁסוּעָה</a>; <span class=\"citation\">Bekh. 6ᵇ</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be taught</i>. <span class=\"citation\">B. Mets. 33ᵇ</span>; <span class=\"citation\">B. Kam. 94ᵇ</span>, a. e. <span dir=\"rtl\">בימי רבי נשנית משנה זו</span> this Mishnah was taught (originated) in Rabbi’s days. <span class=\"citation\">Ber. 28ᵃ</span>, v. <a href=\"#\" data-headword=\"עֵדוּת\">עֵדוּת</a>; a. e.</div></div><div class=\"sense\"><b>Hif. הִשְׁנֶה</b> <div class=\"sense\"><i>to teach</i> (Mishnah &amp;c.). <span class=\"citation\">Lam. R. to I, 6</span> <span dir=\"rtl\">הַשְׁנֵינִי פרק וכ׳</span>, v. <a href=\"#\" data-headword=\"קָרָא II\"><span dir=\"rtl\">קָרָא</span> II</a>; a. e.</div></div><div class=\"sense\"><b>Pi. שִׁנָּה  שִׁינָּה</b> <div class=\"sense\"><b>1)</b> <i>to repeat, to come a second time</i>. Y. Snh. III, 21ᵇ bot. <span dir=\"rtl\">לְשַׁנֹּות</span>, v. <a href=\"#\" data-headword=\"טַעֲנָה\">טַעֲנָה</a>. <span class=\"citation\">Num. R. s. 4</span><sup>20</sup> <span dir=\"rtl\">ולא שִׁינְּתָה</span>, v. <a href=\"#\" data-headword=\"שָׁלַשׁ\">שָׁלַשׁ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to change, vary, modify; to make a distinction</i>. <span class=\"citation\">B. Mets. VI, 2</span> <span dir=\"rtl\">כל המְשַׁנֶּה ידיו וכ׳</span>, v. <a href=\"#\" data-headword=\"יָד\">יָד</a>. <span class=\"citation\">Snh. 92ᵇ</span> <span dir=\"rtl\">אפי׳ … לא יְשַׁנֶּה אדם את עצמו וכ׳</span> even in time of danger (persecution) a man must not change himself from (disguise the insignia of) his office. <span class=\"citation\">Yeb. 65ᵇ</span> <span dir=\"rtl\">מותר … לשנות וכ׳</span> one may modify (the report of a person’s utterances) in the interest of peace. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">גדול … הקב&quot;ה ש׳ בו וכ׳</span> peace is a great thing, for even the Lord modified (Sarah’s words) for its sake (ref. to <span class=\"citation\">Gen. XVIII, 12</span> a. <span class=\"citation\">13</span>). Y. Pes. IV, 30ᵈ top <span dir=\"rtl\">אל תְּשַׁנּוּ מנהג וכ׳</span> change not the usage of your fathers &amp;c. <span class=\"citation\">Gen. R. s. 48</span> <span dir=\"rtl\">זה אחד … שׁשִׁינּוּ וכ׳</span> this is one of the things which they (the seventy translators) changed for king Ptolemee. <span class=\"citation\">Sabb. 10ᵇ</span> <span dir=\"rtl\">לעולם אל יְשַׁנֶּה אדם בנו בין הבנים</span> a man must never distinguish his son among his sons (favor one son more than the others); <span class=\"citation\">Gen. R. s. 84</span>. <span class=\"citation\">Bets. 30ᵃ</span> <span dir=\"rtl\">אם אי אפשר לשנות</span> if it is not possible to do the thing in a different manner (so as to be reminded that it is a Holy Day). Tanḥ. Nitsabim 3 כבר … שלא אֲשׁנֶּה בכם וכ׳ I have sworn to you that I will not change my relation to you &amp;c. <span class=\"citation\">Yalk. Mal. 589</span> <span dir=\"rtl\">מי שי׳ במי</span> which of us changed his conduct towards the other?; <span dir=\"rtl\">המקום לא שי׳ בישראל</span> God has not changed his relation to Israel; a. fr.—Part. pass. <span dir=\"rtl\">מְשׁוּנֶּה</span>; f. <span dir=\"rtl\">מְשׁוּנָּה</span>. Y. Taan. I, end, 64ᵈ <span dir=\"rtl\">עורב יצא מש׳ מן הבריות</span> the raven came out of the ark looking different from all other creatures (black). <span class=\"citation\">Shek. V, 2</span>, v. <a href=\"#\" data-headword=\"רִצְפָה\">רִצְפָה</a>. <span class=\"citation\">Sabb. 56ᵃ</span> (ref. to <span class=\"citation\">II Sam. XII, 9</span>) <span dir=\"rtl\">מש׳ רעה זו וכ׳</span> this evil deed is different from all &amp;c. Ib. 156ᵇ <span dir=\"rtl\">מיתה מש׳</span> a strange (unnatural, sudden) death; <span class=\"citation\">Sot. 35ᵃ</span>; a. fr.—<span class=\"citation\">Deut. R. s. 9</span> <span dir=\"rtl\">ראה אותו מש׳</span> he saw him (the angel of death) looking strange (excited); <span dir=\"rtl\">מפני מה אתה מש׳</span> why art thou excited?</div></div><div class=\"sense\"><b>Hithpa. הִשְׁתַּנֶּה</b> </div><div class=\"sense\"><b>Nithpa. נִשְׁתַּנֶּה</b> <div class=\"sense\"><i>to be changed, different</i>. <span class=\"citation\">Snh. 38ᵃ</span> <span dir=\"rtl\">בשלשה … מִשְׁתַּנֶּה מחבירו וכ׳</span> by three things one man is distinguishable from another: by his voice &amp;c. <span class=\"citation\">Pes. X, 4</span> (<span class=\"citation\">116ᵃ</span>) <span dir=\"rtl\">מה נ׳ הלילה וכ׳</span> why is this night different from all other nights? <span class=\"citation\">Snh. 71ᵇ</span> [read:] <span dir=\"rtl\">הואיל ונ׳ דינו ונִשְׁתַּנֵית מיתתו</span> because his (the proselyte’s) legal status is different, and the mode of capital punishment is different for him. <span class=\"citation\">Sabb. 53ᵇ</span> <span dir=\"rtl\">נִשְׁתַּנּוּ לו סדרי וכ׳</span> the order of nature had to be changed for him. <span class=\"citation\">R. Hash. 19ᵃ</span> <span dir=\"rtl\">מה נִישְׁתַּנִּינוּ מכל וכ׳</span> wherein are we different from any other nation or tongue that you decree for us such hard decrees?; a. e.</div></div>","alt":["שָׁנָה"]},"31834":{"h":"שְׁנֵי","r":"U01586","html":"<div class=\"sense\"><b>1)</b> <i>to repeat</i>. <span class=\"citation\">Targ. I Sam. XXVI, 8</span> ed. Wil. (v. <a href=\"#\" data-headword=\"תְּנֵי\">תְּנֵי</a>).—<span class=\"citation\">Snh. 59ᵃ</span> <span dir=\"rtl\">ולמה לי למִישְׁנֵי בסיני</span> and why is it repeated at Sinai?; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to change; to be different</i>. <span class=\"citation\">Targ. O. Deut. XXXIV, 7</span>.—<span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">כל מאי דהוה הדין ש׳ הדין ש׳</span> as the one (the mosquito) changed, so did the other (Titus) change. <span class=\"citation\">Yeb. 21ᵇ</span> <span dir=\"rtl\">או דילמא לא שנא</span> (abbrev. <span dir=\"rtl\">ל&quot;ש</span>) or is there no difference (between the wife of a brother on the mother’s side and that of a brother on the father’s side)? <span class=\"citation\">Succ. 29ᵇ</span> <span dir=\"rtl\">ל&quot;ש ביו&quot;ט … ול&quot;ש וכ׳</span> no difference whether it is the first Holy Day or the second. <span class=\"citation\">Ib. 30ᵃ</span> <span dir=\"rtl\">ל&quot;ש לפני וכ׳</span> no difference whether before &amp;c. <span class=\"citation\">Sabb. 6ᵃ</span> <span dir=\"rtl\">הכי נמי ל&quot;ש</span> in this case, too, it is the same; a. v. fr.—Yeb. l. c. <span dir=\"rtl\">מאי ש׳ הני מאי ש׳ הא</span> (abbrev. <span dir=\"rtl\">מ&quot;ש</span>) what difference is there between the former and the latter? <span class=\"citation\">Sabb. 4ᵃ</span> <span dir=\"rtl\">ומאי ש׳</span> and wherein lies the difference? <span class=\"citation\">Ib. 2ᵇ</span> <span dir=\"rtl\">מ&quot;ש הכא … ומ&quot;ש התם וכ׳</span> wherein lies the difference (what reason is there) that the Mishnah says here, ‘two which are four within, and two which are four without’, and there (<span class=\"citation\">Shebu. I, 1</span>) only, ‘two which are four’?; a. fr.—<i>Part</i>. <a href=\"#\" data-headword=\"שָׁאנִי\">שָׁאנֵי</a> <i>it is different</i>. <span class=\"citation\">Succ. 21ᵇ</span> <span dir=\"rtl\">ש׳ שוורים הואיל וכ׳</span> it is different in the case of oxen, because &amp;c. <span class=\"citation\">Sabb. 7ᵇ</span> <span dir=\"rtl\">ש׳ צרור וכ׳</span> it is different with bundles and other objects &amp;c. <span class=\"citation\">Ker. 11ᵃ</span> <span dir=\"rtl\">והכא ש׳</span> but here it is different; a. v. fr.—V. <a href=\"#\" data-headword=\"שַׁנְיָא\">שׁנִיא</a>.</div><div class=\"sense\"><b>Pa. שַׁנֵּי</b> <div class=\"sense\"><b>1)</b> <i>to change; to act strangely</i>. <span class=\"citation\">Targ. Gen. XLI, 14</span>. <span class=\"citation\">Targ. Ps. LXXXIX, 35</span>. <span class=\"citation\">Ib. XXXIV, 1</span>. <span class=\"citation\">Targ. Y. II, Deut. XXXII, 5</span>; a. fr.—[<span class=\"citation\">Ib. 41</span> <span dir=\"rtl\">אישני</span>, read: <span dir=\"rtl\">אישנן</span>, v. <a href=\"#\" data-headword=\"שְׁנַן\">שְׁנַן</a>.—<span class=\"citation\">Targ. Jud. XX, 16</span> <span dir=\"rtl\">משנן</span>, read: <span dir=\"rtl\">משגן</span>, v. <a href=\"#\" data-headword=\"שְׁגֵי\">שְׁגֵי</a>.]—<span class=\"citation\">Taan. 24ᵇ</span> <span dir=\"rtl\">שַׁנִּי דוכתיך</span> change thy place; <span dir=\"rtl\">ש׳ דוכתיה</span> he changed his place. <span class=\"citation\">Ker. 11ᵃ</span> <span dir=\"rtl\">לישנא דשׁנּוּיֵי</span>, v. <a href=\"#\" data-headword=\"חָרַף\">חָרַף</a>. <span class=\"citation\">Bets. 30ᵃ</span> <span dir=\"rtl\">כמה דאפשר לשנויי מְשַׁנִּינָן וכ׳</span> as much as it is feasible to change (the mode of doing a thing), we must change on the Holy Day; <span class=\"citation\">Sabb. 128ᵇ</span>; <span class=\"citation\">ib. 117ᵇ</span> <a href=\"#\" data-headword=\"מִשְׁנִים\">מְשַׁנִּין</a>. Bets. l. c. <span dir=\"rtl\">והא הני נשי … ולא מְשַׁנְּיָין וכ׳</span> but there are those women that fill their pitchers … without any change, and we say nothing to them (to interfere)! <span class=\"citation\">Snh. 96ᵃ</span> top <span dir=\"rtl\">שני נפשך</span> (Rashi <a href=\"#\" data-headword=\"שְׁנֵי\">אַשְׁנִי</a>) disguise thyself; <span dir=\"rtl\">במאי אִישַׁנֵּי</span> how shall I disguise (myself)?; <span class=\"citation\">Yalk. Is. 276</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to reply</i>. <span class=\"citation\">Sabb. 7ᵇ</span> <span dir=\"rtl\">זימנין מְשַׁנֵּי לה וכ׳</span> at times he replied to it (met the objection by saying) &amp;c. <span class=\"citation\">Ib. 3ᵇ</span> <span dir=\"rtl\">דמשני לך</span>; <span class=\"citation\">Keth. 98ᵇ</span> <span dir=\"rtl\">דשַׁנִּינָן</span>, v. <a href=\"#\" data-headword=\"שִׁינּוּיָא\">שִׁינּוּיָא</a>. <span class=\"citation\">Pes. 20ᵇ</span> <span dir=\"rtl\">ומְשַׁנֵּי שאני התם וכ׳</span> and he answered, it is different in that case; a. fr.—<span class=\"citation\">Shebu. 21ᵃ</span> top <span dir=\"rtl\">כדשני ליה</span> (Rashi <span dir=\"rtl\">כדמשני</span>) as he (Abayi) replied to him (R. Papa, further below).</div></div><div class=\"sense\"><b>Af. אַשְׁנֵי</b> <div class=\"sense\"><i>to change, act strangely</i>. <span class=\"citation\">Targ. Mal. III, 6</span>. Targ. O. a. Y. I <span class=\"citation\">Deut. XXXII, 5</span>; a. fr.—[<span class=\"citation\">Targ. Ps. LXXI, 17</span> <a href=\"#\" data-headword=\"שְׁנֵי\">אשני</a>, read with ed. Lag. <span dir=\"rtl\">אתני</span>.]—<span class=\"citation\">Snh. 96ᵃ</span> top, v. supra.</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתַּנֵּי</b> </div><div class=\"sense\"><b>Ithpe. אִשְׁתְּנֵי</b> <div class=\"sense\"><b>1)</b> <i>to be changed</i>. Targ. Deut. l. c. <span class=\"citation\">Targ. Lam. IV, 1</span>; a. e.—<span class=\"citation\">Snh. 71ᵇ</span> <span dir=\"rtl\">נימא הואיל וא׳ א׳</span> let us say, because his status has changed, he is a different person (not responsible for acts committed in his previous condition); <span dir=\"rtl\">האי דינו א׳ מיתתו לא א׳</span> this man’s legal status has changed, but the mode of his execution is not affected thereby. Ib. <span dir=\"rtl\">הואיל וא׳ א׳ … דא׳ לגמרי</span> because a change has taken place (by her becoming of age), she is a different person (and the mode of her execution must be different): so much the more here (in the case of a proselyte) where a complete change has taken place. Ib. 96ᵃ <span dir=\"rtl\">א׳ אפיה והוה וכ׳</span> his face changed, and he looked like a dog. <span class=\"citation\">Sabb. 36ᵃ</span> <span dir=\"rtl\">הני … א׳ שמייהו וכ׳</span> the names of the following three things have changed since the destruction of the Temple; <span class=\"citation\">Succ. 34ᵃ</span>; a. e.</div></div>","alt":["שְׁנָא"]},"31835":{"h":"שְׁנֵי ²","r":"U01587","html":"<div class=\"sense\"><i>two</i>, v. <a href=\"#\" data-headword=\"שְׁנַיִם\">שְׁנַיִם</a>.</div>","alt":[]},"31836":{"h":"שְׂנֵי","r":"U01588","html":"<div class=\"sense\"><i>to hate</i>, v. <a href=\"#\" data-headword=\"סְנֵי\">סְנֵי</a>.</div>","alt":[]},"31837":{"h":"שֵׁנִי","r":"U01589","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>second</i>. <span class=\"citation\">Meg. IV, 1</span> <a href=\"#\" data-headword=\"בֹּוסַם\">בש׳</a> on the second day of the week. <span class=\"citation\">Ib. 22ᵃ</span>; <span class=\"citation\">Taan. 27ᵇ</span> <span dir=\"rtl\">הש׳ קורא וכ׳</span> the second (of those called to read from the Law) reads &amp;c. <span class=\"citation\">Bets. 6ᵃ</span>, a. fr. <span dir=\"rtl\">יום טוב ש׳</span> the second (Rabbinical) Holy Day (instituted on account of the uncertainty of the calendar). <span class=\"citation\">Sabb. 40ᵇ</span>, a. fr. <span dir=\"rtl\">כלי ש׳</span> second vessel, i.e. a vessel into which a boiling mass has been poured, contrad. to <span dir=\"rtl\">כלי ראשון</span> a vessel direct from the fire.—<span class=\"citation\">Maas. Sh. I, 1</span>, a. fr. <span dir=\"rtl\">מעשר ש׳</span>, v. <a href=\"#\" data-headword=\"מַעֲשֵׂר\">מַעֲשֵׂר</a>.—Esp. <i>a</i>) (<span dir=\"rtl\">לטומאה</span>) <a href=\"#\" data-headword=\"ש׳\">ש׳</a> <i>the second degree of levitical uncleanness, an object made unclean through contact with uncleanness</i>, v. <a href=\"#\" data-headword=\"רִאשׁוֹן\">רִאשׁוֹן</a>. <span class=\"citation\">Toh. II, 2</span> <span dir=\"rtl\">האוכל … אוכל ש׳ ש׳</span> he that eats food unclean in the second degree, becomes unclean in the second degree. <span class=\"citation\">Pes. 14ᵃ</span> <span dir=\"rtl\">ש׳ וש׳ הוא וכ׳</span> it is a contact between two things both unclean in the second degree, and why do you say that he adds to the degree of uncleanness?; a. fr.—<i>b</i>) <i>relationship in the second degree, second generation</i>. <span class=\"citation\">Snh. 28ᵃ</span> <span dir=\"rtl\">ש׳ בש׳ תנן</span> we have learned that a relative in the second degree (first cousin) cannot testify for or against a relative in the second degree; <span dir=\"rtl\">ש׳ בראשון תנן</span> we have learned that one of the second generation cannot testify for or against one of the first generation, i.e. his uncle. Ib. <span dir=\"rtl\">שלישי בש׳</span> a relative in the third degree against one in the second degree, i.e. his father’s first cousin; a. fr.—Pl. <span dir=\"rtl\">שְׁנִיִּים</span>. <span class=\"citation\">Yad. II, 2</span> <span dir=\"rtl\">ואת הש׳ למקום אחר</span> and water poured over his hands a second time on another place. Ib. <span dir=\"rtl\">ועל הש׳ טהור</span> and a loaf which fell on the place which received the second water is clean. <span class=\"citation\">Gen. R. s. 31</span> <span dir=\"rtl\">ש׳ לו וכ׳</span> the second story of the ark was for him (Noah) and his sons and the clean animals; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"שְׁהִיָּה\">שְׁנִיָּה</a>, <a href=\"#\" data-headword=\"שְׁהִיָּה\">שְׁנִיָּיה</a>. <span class=\"citation\">Shek. III, 4</span>; a. fr.—Pl. <span dir=\"rtl\">שְׁנִיּוֹת</span>. <span class=\"citation\">Yad. III, 2</span> <a href=\"#\" data-headword=\"ש׳\">ש׳</a> (sub. <span dir=\"rtl\">לטומאה</span>), v. supra. <span class=\"citation\">Ab. Zar. 3ᵇ</span> <a href=\"#\" data-headword=\"ש׳\">ש׳</a> during the second three hours of the day; a. fr.—Esp. <span dir=\"rtl\">שניה</span> (sub. <span dir=\"rtl\">לערוה</span>) <i>incest of second degree, intermarriage forbidden by rabbinical enactment</i>. <span class=\"citation\">Yeb. 21ᵇ</span> <span dir=\"rtl\">אמו ערוה אם אמו ש׳</span> connection with one’s mother is incest, with one’s mother’s mother incest in the second degree. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">משום ש׳</span> as incest of the second degree; a. fr.—<i>Pl.</i> as above. <span class=\"citation\">Ib.ᵃ</span> <span dir=\"rtl\">מה הם ש׳</span> what relationships are <i>sh’niyoth?</i> <span class=\"citation\">Ib.</span> (ref. to <span class=\"citation\">Lev. XVIII, 27</span>) <span dir=\"rtl\">האל … מאי נינהו ש׳</span> <i>haël</i> means the severe, which implies that there are milder forms of incest; what are they? The <i>sh’niyoth</i>; a. fr.</div>","alt":["שֵׁינִי"]},"31838":{"h":"שַׁנְיָא","r":"U01590","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁנֵי\">שְׁנֵי</a>) </div><div class=\"sense\"><b>1)</b> <i>different, a different thing</i>.—[<span class=\"citation\">Targ. Prov. X, 14</span> <a href=\"#\" data-headword=\"שַׁנְיָא\">שניא</a> some ed., read: <a href=\"#\" data-headword=\"שֵׁצָא\">שֵׁצְיָא</a>].—<span class=\"citation\">Y. Dem. I, 21ᵈ</span> bot. [read] <span dir=\"rtl\">לא ש׳ הוא דבר … הוא וכ׳</span> it makes no difference, (it is all the same) whether it is a plant the seed of which disappears (must be renewed every year) or &amp;c. <span class=\"citation\">Y. Pes. V, 32ᶜ</span> <span dir=\"rtl\">לא ש׳ היא … היא וכ׳</span> it is all the same whether one slaughters a Passover sacrifice as a peace-offering or the reverse. Ib. X, end, 37ᵈ <span dir=\"rtl\">ש׳ היא</span> it is a different case; a. fr.—[V. <a href=\"#\" data-headword=\"שָׁאנִי\">שָׁאנֵי</a>, s. v. <a href=\"#\" data-headword=\"שְׁנֵי\">שְׁנֵי</a>.]</div><div class=\"sense\"><b>—2)</b> <i>strange thing, folly</i>.—Pl. <a href=\"#\" data-headword=\"שְׁנַן\">שַׁנְיָן</a>, <a href=\"#\" data-headword=\"שַׁנְיָיא\">שַׁנְיָין</a>. <span class=\"citation\">Targ. Is. XXX, 10</span> (h. text <span dir=\"rtl\">מהתלות</span>).</div>","alt":["שַׁנְיָיא"]},"31839":{"h":"שְׂנִיאֲתָא","r":"U01591","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׂנוּאֲתָא\">שְׂנוּאֲתָא</a></div>","alt":[]},"31840":{"h":"שניגור","r":"U01592","html":"<div class=\"sense\">, <span class=\"citation\">Y. Succ. III, beg. 53ᶜ</span>, v. <a href=\"#\" data-headword=\"סְנֵיגוֹר\">סְנֵיגוֹר</a></div>","alt":[]},"31841":{"h":"שניו׳","r":"U01593","html":"<div class=\"sense\">, <span class=\"citation\">Y. Yeb. I, 3ᵇ</span> top <span dir=\"rtl\">ש׳ עוונייא</span>, v. <a href=\"#\" data-headword=\"שׁוּנְיָא\">שׁוּנְיָא</a></div>","alt":[]},"31842":{"h":"שַׁנְיָיא","r":"U01594","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁנְיָא\">שַׁנְיָא</a></div>","alt":[]},"31843":{"h":"שָׁנְיָיא","r":"U01595","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"שׁוּנְיָא\">שׁוּנְיָא</a></div>","alt":[]},"31844":{"h":"שְׁנַיִם","r":"U01596","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>two</i>. <span class=\"citation\">Ber. 8ᵃ</span> <span dir=\"rtl\">ש׳ מקרא ואחד תרגום</span> reading the Scriptural portion of the week twice, and the Targum once. Ib. <span dir=\"rtl\">שיעור ש׳ פתחים</span> a distance of two gates. <span class=\"citation\">Zeb. V, 4</span>, v. <a href=\"#\" data-headword=\"מַתָּנָה\">מַתָּנָה</a>. <span class=\"citation\">Sabb. I, 1</span> <span dir=\"rtl\">ש׳ שהן ארבע</span> two ways of transfer from place to place, which become four (by rabbinical addition). Ib. <span dir=\"rtl\">שְׁנֵיהֶם פטורין</span> both of them are free. <span class=\"citation\">Snh. V, 3</span> <span dir=\"rtl\">בש׳ בחדש</span> on the second day of the month. Ib. <span dir=\"rtl\">בש׳ שעות</span> in the second hour of the day. <span class=\"citation\">Men. III, 3</span>. <span class=\"citation\">Ib. 6</span>; a. v. fr.—<span dir=\"rtl\">שְׁנֵים עָשָׂר</span>, <span dir=\"rtl\">שְׁתֵּים עֶשְׂרֵה</span> <i>twelve</i>. <span class=\"citation\">Nidd. 69ᵇ</span>. <span class=\"citation\">Ab. Zar. 3ᵇ</span>; a. fr.</div>","alt":["שְׁנֵי","שְׁתַּיִם","שְׁתֵּי"]},"31845":{"h":"שניצן","r":"U01597","html":"<div class=\"sense\">, <span class=\"citation\">Mikv. X, 4</span>, v. <a href=\"#\" data-headword=\"שֶׁנֶץ\">שֶׁנֶץ</a>.</div>","alt":[]},"31846":{"h":"שְׂנִיר","r":"U01598","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Senir</i>, a portion of Mount Hermon. <span class=\"citation\">Succ. 12ᵃ</span>, v. <a href=\"#\" data-headword=\"קָרַשׁ\">קָרַשׁ</a>. <span class=\"citation\">Cant. R. to IV, 8</span> [read:] <span dir=\"rtl\">מה זה הש̇נ̇י̇ר̇ ש̇ונא את הנ̇י̇ר̇ ולא נזרע אלא פעם אחד כך וכ׳</span> as Mount Senir hates the plough and can be sown only once, so was Isaac &amp;c. <span class=\"citation\">Ḥull. 60ᵇ</span> ש׳ ושריון מהרי וכ׳ Senir and Sirion belong to the mountains of Palestine; a. e.</div>","alt":[]},"31847":{"h":"שָׂנֵיתָא","r":"U01599","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׂנוּאֲתָא\">שְׂנוּאֲתָא</a></div>","alt":[]},"31848":{"h":"שנמג","r":"U01600","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"(פורסישמנג\">פּוּרְסִישְׁנָמַג</a></div>","alt":[]},"31849":{"h":"שָׁנַן","r":"U01601","html":"<div class=\"sense\"> (b. h.) <i>to be pointed, sharp; to sharpen.</i> <i>—Part. pass</i>. <a href=\"#\" data-headword=\"שָׁנוּן\">שָׁנוּן</a>, pl. <a href=\"#\" data-headword=\"שְׁנוּנִית\">שְׁנוּנִים</a> <i>sharpened</i>; trnsf. <i>ready, quick</i>. Pesik. Baḥod., p. 108ᵃ, a. e., v. <a href=\"#\" data-headword=\"שִׁנְאָן\">שִׁנְאָן</a>.</div><div class=\"sense\"><b>Pi. שִׁנֵּן</b> <div class=\"sense\"><b>1)</b> <i>to sharpen</i>; trnsf. (cmp. <span dir=\"rtl\">חדד</span>) <i>to teach diligently</i>, v. <a href=\"#\" data-headword=\"שִׁינּוּן\">שִׁינּוּן</a>.</div><div class=\"sense\"><b>—2)</b> <i>to brighten, cheer</i>. <span class=\"citation\">Ab. d’R. N. ch. XVIII</span> <span dir=\"rtl\">והיה מְשַׁנֵּן בה כל וכ׳</span> and with this (his disposition) he cheered all Israel’s scholars.</div><div class=\"sense\"><b>—3)</b> <i>to speak distinctly</i>. Y. Ber. III, 6ᵇ bot. <span dir=\"rtl\">לא מסתברא … משנן בפיו</span> is it not evident that in reading the Sh’mʿa every one must recite it distinctly with his own mouth?</div></div>","alt":[]},"31850":{"h":"שְׁנַן","r":"U01602","html":"<div class=\"sense\"> Part. pass. <a href=\"#\" data-headword=\"שְׁנַן\">שָׁנִין</a>, <span dir=\"rtl\"><a href=\"#\" data-headword=\"שְׁכִינָא\">שְׁנִינָא</a> (שְנוּ׳</span>); pl. <span dir=\"rtl\"><span dir=\"rtl\">שְׁנִינִין</span> (שְׁנוּ׳</span>). <span class=\"citation\">Targ. Prov. XXV, 18</span>. <span class=\"citation\">Targ. Y. I Gen. III, 24</span> (Y. II <a href=\"#\" data-headword=\"שְׁנוּ\">שְׁנוּ׳</a>, not <a href=\"#\" data-headword=\"שְׁנּוּי\">שִׁנּוּ׳</a>). <span class=\"citation\">Targ. Y. I Deut. XXXII, 41</span>. <span class=\"citation\">Targ. Ps. CXX, 4</span> <span dir=\"rtl\">שני׳</span> ed. Lag. (oth. ed. <span dir=\"rtl\">שנו׳</span>).</div><div class=\"sense\"><b>Pa. שַׁנֵּין</b> <div class=\"sense\"><i>to sharpen</i>. Ib. LXIV, 4 <span dir=\"rtl\">שַׁנִּינוּ</span> (ed. Wil. <span dir=\"rtl\">שְׁנִי׳</span>). <span class=\"citation\">Targ. Jer. LI, 11</span>. Targ. Y. II, Deut. l. c. <span dir=\"rtl\">אישני בברקא</span>, read: <span dir=\"rtl\">אִישֵׁנֵּין כברקא</span>.</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתַּנֵּין</b> <div class=\"sense\"><i>to be sharpened, polished</i>. <span class=\"citation\">Targ. Ez. XXI, 15</span>; a. e.</div></div>","alt":[]},"31851":{"h":"שָׁנָן","r":"U01603","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁנַן\">preced.</a>) <i>pointed rock, cliff.</i> <i>—</i> Pl. <span dir=\"rtl\">שְׁנָנִים</span>. Ohol. VIII, 2; cmp. <a href=\"#\" data-headword=\"שְׁנוּנִית\">שְׁנוּנִית</a>.</div>","alt":[]},"31852":{"h":"שְׁנָנָא","r":"U01604","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, constr. <a href=\"#\" data-headword=\"שְׁנַן\">שְׁנַן</a> (<a href=\"#\" data-headword=\"שָׁנָן\">preced.</a> wds.) <i>blade, edge</i>. <span class=\"citation\">Targ. O. Gen. III, 24</span> (h. text <span dir=\"rtl\">להט</span>). <span class=\"citation\">Targ. I Sam. XVII, 7</span> <a href=\"#\" data-headword=\"שְׁנָנָא\">שִׁנְנָא</a> (ed. Wil. <a href=\"#\" data-headword=\"שִׁינְדְּפִין\">שִׁנָ׳</a>).—V. <a href=\"#\" data-headword=\"שִׁינְנָא\">שִׁינְנָא</a>.</div>","alt":[]},"31853":{"h":"שְׁנָנָה","r":"U01605","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁנָנָא\">preced.</a>) <i>spear point</i>. <span class=\"citation\">Snh. 82ᵃ</span> bot. <span dir=\"rtl\">שלף ש׳ וכ׳</span> (Rashi <a href=\"#\" data-headword=\"שְׁנָנָא\">שננא</a>), v. <a href=\"#\" data-headword=\"אוּנְקְלַי II\"><span dir=\"rtl\">אוּנְקְלַי</span> II</a>; <span class=\"citation\">Yalk. Num. 771</span>.</div>","alt":[]},"31854":{"h":"שִׁנְעָר","r":"U01606","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Shinear</i>, a part of Babylonia (v. Schr. KAT<sup>2</sup>, p. 118). <span class=\"citation\">Y. Ber. IV, 7ᵇ</span> bot., a. e. <span dir=\"rtl\">למה נקרא שמה ש׳</span> why is Babylonia called Shinear?; v. <a href=\"#\" data-headword=\"נָעַר II\"><span dir=\"rtl\">נָעַר</span> II</a>; <span class=\"citation\">Zeb. 113ᵇ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">למה … ש׳ שמנערת עשיריה</span> it is called Sh., because it shakes out its rich men (makes them poor); a. e.</div>","alt":[]},"31855":{"h":"שְׁנַץ","r":"U01607","html":"<div class=\"sense\"> (Shaf. of <a href=\"#\" data-headword=\"*אֲנַץ\">אֲנַץ</a>; cmp. b. h. <span dir=\"rtl\">שנס</span>) <i>to squeeze in, fasten, lace</i>. <span class=\"citation\">Y. Kil. IX, end, 32ᵈ</span> <span dir=\"rtl\">דהוא ש׳ גרמיה והיא נחתא</span> for when he laces himself (his shoes), it (the purple band) slips down.—Part. pass. <span dir=\"rtl\">שָׁנִיץ</span>; f. <span dir=\"rtl\">שְׁנִיצָא</span>, <span dir=\"rtl\">שְׁנִיצַת</span>. <span class=\"citation\">Y. Meg. III, 74ᵇ</span> bot., v. <a href=\"#\" data-headword=\"קוּנְטְרָא\">קוּנְטְרָא</a>. <span class=\"citation\">Y. Ber. II, 5ᶜ</span> bot. <span dir=\"rtl\">כבר שניצת</span> (not <span dir=\"rtl\">שנצת</span>), v. <a href=\"#\" data-headword=\"עוּנְקְתָא\">עוּנְקְתָא</a>.</div>","alt":[]},"31856":{"h":"שֶׁנֶץ","r":"U01608","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁנַץ\">preced.</a>) <i>strap, lace</i>. <span class=\"citation\">Mikv. X, 4</span> <span dir=\"rtl\">ש׳ של סנדל</span> ed. Dehr. (ed. <a href=\"#\" data-headword=\"שניצן\">שניצן</a>, read: <span dir=\"rtl\">שְׁנָצִין</span>) laces of a sandal, contrad. to <a href=\"#\" data-headword=\"חֶבֶט I\">חֶבֶט</a>.—Pl. <span dir=\"rtl\">שְׁנָצוֹת</span>, with suffix <span dir=\"rtl\">שְׁנָצָיו</span>. <span class=\"citation\">Kel. XXVI, 1</span>, sq. <span dir=\"rtl\">כיס של ש׳</span> a bag which is closed by means of laces.—[<span dir=\"rtl\">שנץ</span> pr. n. pl., v. <a href=\"#\" data-headword=\"שֶׁצֶת\">שֶׁצֶת</a>.]</div>","alt":[]},"31857":{"h":"שִׁנְצָא","r":"U01609","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">שִׁנְצִין</span>, <span dir=\"rtl\">שִׁנְצֵי</span>, <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁי׳</a>. <span class=\"citation\">Targ. Y. Deut. XXV, 9</span> (not <span dir=\"rtl\">צַי …</span>).—<span class=\"citation\">Yeb. 102ᵃ</span> <span dir=\"rtl\">סנדל דאית לה ש׳</span> a sandal which has laces. Y. ib. XII, 12ᶜ bot. <span dir=\"rtl\">דשנצין</span> (not <span dir=\"rtl\">דשנצוי</span>), v. <a href=\"#\" data-headword=\"שׁוּרְצִיפָא\">שׁוּרְצִיפָא</a>. <span class=\"citation\">Sabb. 92ᵃ</span> <span dir=\"rtl\">דאיכא ש׳</span> a bag which has laces with which to close it.</div>","alt":["שִׁי׳"]},"31858":{"h":"שָׁנַק","r":"U01610","html":"<div class=\"sense\"> (Shaf. of <a href=\"#\" data-headword=\"אנק\">אנק</a> or <span dir=\"rtl\">חנק</span>), <i>Pi.</i> שִׁנֵּק <i>to strangle, choke</i>. <span class=\"citation\">Pesik. R. s. 36</span>; <span class=\"citation\">Yalk. Is. 359</span> <span dir=\"rtl\">ומְשַׁנְּקִין את רוחך בעול</span> and they shall choke thy spirit (curb thy energies) with a yoke.</div><div class=\"sense\"><b>Hithpa. הִשְׁתַּנֵּק</b> <div class=\"sense\"><i>to be strangled</i>. Pesik. Zutr., Ḥuck., p. 244 <span dir=\"rtl\">ולא היינו מִשְׁתַּנְּקִין בצמא</span> and we should not have been choked by thirst.</div></div>","alt":[]},"31859":{"h":"שְׁנַק","r":"U01611","html":"<div class=\"sense\">, <i>Pa.</i> <span dir=\"rtl\">שַׁנֵּיק</span>, <span dir=\"rtl\">שַׁנֵּק</span> </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"שָׁנַק\">same</a>. <span class=\"citation\">Targ. O. Ex. XIV, 27</span> (h. text <a href=\"#\" data-headword=\"נָעַר I\">נער</a>); <span class=\"citation\">Targ. Ps. CXXXVI, 15</span> (Ms. <a href=\"#\" data-headword=\"שַׁרְנֵיק\">שַׁרְנֵיק</a>).). <span class=\"citation\">Targ. Cant. I, 9</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to trouble, confound</i>. <span class=\"citation\">Targ. Mal. I, 13</span> (h. text <span dir=\"rtl\">והפחתם</span>; some ed. <span dir=\"rtl\">ושביק׳</span>). <span class=\"citation\">Targ. Y. Ex. X, 2</span> ית מה דשַׁנִּיקִית Ar. (ed. <span dir=\"rtl\">ית ניסין דעבדית</span>; h. text <span dir=\"rtl\">התעללתי</span>).</div><div class=\"sense\"><b>Af. אַשְׁנֵיק</b> <div class=\"sense\"><i>to be narrow</i>. <span class=\"citation\">Targ. Prov. IV, 12</span> Ar. (ed., v. <a href=\"#\" data-headword=\"*טְעַק\">טְעַק</a>).</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתַּנֵּיק</b> </div><div class=\"sense\"><b>Ithpe. אִשְׁתְּנִיק</b> <div class=\"sense\"><b>1)</b> <i>to be strangled, suffocated</i>. <span class=\"citation\">Targ. Job VII, 12</span>. <span class=\"citation\">Targ. Y. Num. XIV, 13</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be distressed</i>. <span class=\"citation\">Targ. Y. Gen. XXII, 20</span>.</div></div>","alt":[]},"31860":{"h":"שֵׁנְתָא","r":"U01612","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שֵׁינְתָא\">שֵׁינְתָא</a></div>","alt":[]},"31861":{"h":"שְׁנָתוֹת","r":"U01613","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"שֵׁן\">שׁן</a>) <i>teeth-like marks</i>. <span class=\"citation\">Men. IX, 2</span> (<span class=\"citation\">87ᵇ</span>) <span dir=\"rtl\">ש׳ היו בהין וכ׳</span> the Hin measure in the Temple had marks: so far for the meal-offering to go with the bullock &amp;c.; <span class=\"citation\">B. Bath. 86ᵇ</span>. <span class=\"citation\">Sabb. 80ᵇ</span> <span dir=\"rtl\">אלא אמר … ש׳</span> but, said R. K., (the <i>andifé</i> of the Mishnah means, enough time to whiten) the marks of a vessel.</div>","alt":[]},"31862":{"h":"ש\"ס","r":"U01614","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (abbrev. of <span dir=\"rtl\">ש̇שה סדרים</span> the six orders of the Talmud) <i>the Talmud</i>. <span class=\"citation\">Zeb. 5ᵃ</span> <span dir=\"rtl\">ונסיב לה הש&quot;ס וכ׳</span> (Ms. M. <a href=\"#\" data-headword=\"תַּלְמוּדָא\">תלמודא</a>) and the Talmud applies to it the verse &amp;c.; <span class=\"citation\">M. Kat. 3ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"תַּלְמוּדָא\">תלמודא</a>). <span class=\"citation\">Ḥag. 10ᵃ</span> <span dir=\"rtl\">אפילו מש&quot;ס לש&quot;ס</span> (Ms. M. <span dir=\"rtl\">מתלמוד לתלמוד</span>) even he that goes from Talmud (Babli) to Talmud (Y’rushalmi). <span class=\"citation\">Treat. Sof’rim XV, 5</span>, sq.; <span class=\"citation\">7</span>, sq.; (<span class=\"citation\">B. Mets. 33ᵃ</span>, sq. <a href=\"#\" data-headword=\"גְּמָרָא\">גמרא</a>, Ms. M. <a href=\"#\" data-headword=\"תַּלְמוּד\">תלמוד</a>; Y. Hor. III, 48ᶜ top <a href=\"#\" data-headword=\"תַּלְמוּד\">תלמוד</a>); a. e.</div>","alt":[]},"31863":{"h":"שָׁסָה","r":"U01615","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שסי\">שסי</a></div>","alt":[]},"31864":{"h":"שִׁסּוּעַ","r":"U01616","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁיסּוּעַ\">שִׁיסּוּעַ</a></div>","alt":[]},"31865":{"h":"שְׁסוּעָה","r":"U01617","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>divided</i>. <span class=\"citation\">Ḥull. 60ᵇ</span>; <span class=\"citation\">Nidd. 24ᵃ</span> (ref. to <span class=\"citation\">Deut. XIV, 7</span>) <span dir=\"rtl\">הש׳ בריה וכ׳</span> the <i>sh’suʿah</i> is a creature with two backs and two spinal columns. <span class=\"citation\">Ḥull. 63ᵇ</span>; <span class=\"citation\">Bekh. 6ᵇ</span>; <span class=\"citation\">Yalk. Lev. 537</span>, v. <a href=\"#\" data-headword=\"שָׁנָה\">שָׁנָה</a> <i>Nif.</i></div>","alt":[]},"31866":{"h":"שסי","r":"U01618","html":"<div class=\"sense\"> (onomatop.) <i>to hiss</i>.</div><div class=\"sense\"><b>Pi. שִׁיסָּה</b> <div class=\"sense\"><i>to set on</i> (a dog, serpent &amp;c.). <span class=\"citation\">Snh. IX, 1</span>, v. <a href=\"#\" data-headword=\"נָשַךְ\">נָשַׁךְ</a>; <span class=\"citation\">B. Kam. 23ᵇ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מאן פטור מְשַׁסֶּה וכ׳</span> who is exempt from responsibility? Is he exempt that set the dog on, and is the owner of the dog responsible? <span class=\"citation\">Ib. 24ᵇ</span> <span dir=\"rtl\">המשסה … חבירו בחבירו</span> he who sets his neighbor’s dog on a neighbor; <span dir=\"rtl\">שִׁיסָּהוּ הוא בעצמו</span> if he incited the neighbor’s dog against himself. <span class=\"citation\">Gen. R. s. 84</span> <span dir=\"rtl\">באו ונְשַׁסֶּה בו וכ׳</span> come, let us set on the dogs against him (Joseph); a. e.—[Bibl. Hebr. <span dir=\"rtl\">שסה</span> <i>to plunder</i>, cmp. <a href=\"#\" data-headword=\"שָׁסַע\">שָׁסַע</a>.]</div></div>","alt":["שָׁסָה"]},"31867":{"h":"שְׁסֵי","r":"U01619","html":"<div class=\"sense\">, <i>Pa.</i> <span dir=\"rtl\">שַׁסֵּי</span> <a href=\"#\" data-headword=\"שסי\">same</a>. <span class=\"citation\">B. Kam. 24ᵇ</span> <span dir=\"rtl\">כיין … דמְשַׁסֵּי ליה ומִשְׁתַּסֵּי וכ׳</span> (Ms. R. <span dir=\"rtl\">דמְשַׁסּוּ</span>) since thou knowest of thy dog, that one can set him on and he will bite, thou oughtest not to have kept him.</div><div class=\"sense\"><b>Ithpa. אִשְׁתַּסֵּי</b> <div class=\"sense\"><i>to be set on, to bite</i>, v. supra.</div></div>","alt":[]},"31868":{"h":"שָׁסַע","r":"U01620","html":"<div class=\"sense\"> (b. h.) <i>to rend, split.</i> <i>—Part. pass</i>. <a href=\"#\" data-headword=\"שִׁסּוּעַ\">שָׁסוּעַ</a>; pl. <span dir=\"rtl\">שְׁסוּעִים</span>, <span dir=\"rtl\">שְׁסוּעִין</span> <i>cloven-footed</i>. <span class=\"citation\">Yalk. Lev. 537</span> (ref. to <span class=\"citation\">Lev. XI, 26</span>) <span dir=\"rtl\">לש׳ מנין</span> whence do we learn that the laws of uncleanness apply to the cloven-footed animals?; <span dir=\"rtl\">לשאין ש׳ מנין</span> that it applies to those not cloven-footed?; Sifra Sh’mini, ch. V, Par. 4 <span dir=\"rtl\">שיסועים</span> (corr. acc.).</div><div class=\"sense\"><b>Pi. שִׁיסַּע</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"שְׁסֵי\">same</a>. <span class=\"citation\">Zeb. VI, 5</span> <span dir=\"rtl\">שי׳ ולא וכ׳</span> he rent (the sacrificial bird), but did not sever it entirely. <span class=\"citation\">Tosef. ib. VII, 10</span> <span dir=\"rtl\">היה מְשַׁסְּעוֹ ביד וכ׳</span> he rent it with his hand, but not with a knife; a. e.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מְשׁוּקָּע\">מְשׁוּסָּע</a> <i>cloven-footed</i>. Sifra l. c. <span dir=\"rtl\">מפריס ומש׳</span>, v. <a href=\"#\" data-headword=\"פָּרַס I\">פָּרַס</a>; Yalk. l. c. <span dir=\"rtl\">ומשסע</span> (corr. acc.).</div></div>","alt":[]},"31869":{"h":"שְׁסַע","r":"U01621","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"שָׁסַע\">שַׁסַּע</a> same. <span class=\"citation\">Targ. Lam. III, 11</span> (h. text <span dir=\"rtl\">פשח</span>).</div>","alt":[]},"31870":{"h":"שָׁסַף","r":"U01622","html":"<div class=\"sense\"> (b. h.), <i>Pi.</i> <a href=\"#\" data-headword=\"שָׁסַף\">שִׁסֵּף</a> (cmp. <a href=\"#\" data-headword=\"שְׁסַע\">preced.</a>) <i>to split, to hew in pieces</i>. <span class=\"citation\">Lam. R. to III, 64</span> (ref. to <span dir=\"rtl\">וישסף</span>, <span class=\"citation\">I Sam. XV, 33</span>) <span dir=\"rtl\">שחתכו וכ׳</span> he cut him in four pieces. Sifra Thazriʿa Par. 5, ch. XVI יְשַׁסְּפֶנּוּ Rabad, v. <a href=\"#\" data-headword=\"*שָׁצַף\">שָׁצַף</a>.</div>","alt":[]},"31871":{"h":"שִׁסְקִי","r":"U01623","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁיסְקֵי\">שִׁיסְקֵי</a></div>","alt":[]},"31872":{"h":"שַׁסְתֵּם","r":"U01624","html":"<div class=\"sense\"> (Shaf. of <span dir=\"rtl\">סתם</span>) <i>to enclose, lock up</i>. <span class=\"citation\">Gitt. 68ᵃ</span> שדא ביה … שַׁסְתְּמֵיה Ar. (ed. <span dir=\"rtl\">סתמיה</span>) he threw a chain (looped rope) over him and enclosed his head; [Ar. ‘drew it up’, when we should expect <span dir=\"rtl\">ושַׁסְתְּמָהּ</span>].</div>","alt":[]},"31873":{"h":"שַׁע","r":"U01625","html":"<div class=\"sense\"><i>shʿa</i>, the first element of the word <a href=\"#\" data-headword=\"שַׁעַטְנֵז\">שַׁעַטְנֵז</a>, phonetically representing the act of carding (v. <a href=\"#\" data-headword=\"שׁוּעַ\">שׁוּעַ</a>). <span class=\"citation\">Y. Kil. IX, end, 32ᵈ</span>, v. <a href=\"#\" data-headword=\"שַׁעַטְנֵז\">שַׁעַטְנֵז</a>, a. <a href=\"#\" data-headword=\"נוּז\">נוּז</a>.</div>","alt":[]},"31874":{"h":"שׁע׳","r":"U01626","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"*שִׁשְׁעָה\">שִׁשְׁעָה</a></div>","alt":[]},"31875":{"h":"שְׁעָא","r":"U01627","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁעֵי\">שְׁעִי</a></div>","alt":[]},"31876":{"h":"שִׁעְבֵּד","r":"U01628","html":"<div class=\"sense\"> (Shafel of <a href=\"#\" data-headword=\"עָבַד\">עָבַד</a>) </div><div class=\"sense\"><b>1)</b> <i>to subject, subjugate, surrender; to obligate, pledge</i>. <span class=\"citation\">Gen. R. s. 44</span> (ref. to <span class=\"citation\">Gen. XV, 13</span>) <span dir=\"rtl\">ידוע שאני מְשׁעְבְּדָן וכ׳</span> ‘knowing’ means that I will surrender them as slaves, ‘thou shalt know’, that I will redeem them. <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">לא כך … שהוא מְשַׁעְבְּדֵינוּ בשבעים וכ׳</span> has not the Lord said, that he will make us the subjects of seventy nations? Ib. [read:] <span dir=\"rtl\">גותי אחד בא ומְשַׁעְבֵּד באחד ממנו כגון שׁשִׁיעְבְּדָה כל אומתו</span> one Goth comes and enslaves one of us, that is as much as if she (Rome) had enslaved all of us; <span class=\"citation\">Cant. R. to II, 8</span>. <span class=\"citation\">Gen. R. s. 85</span> (ref. to <span class=\"citation\">Is. LXVI, 7</span>) <span dir=\"rtl\">קודם … מְשַׁעְבֵּד ראשון וכ׳</span> before yet the first oppressor (of Israel) was born, the last redeemer was born. <span class=\"citation\">R. Hash. III, 8</span> (ref. to <span class=\"citation\">Num. XXI, 8</span>) <span dir=\"rtl\">בזמן … ומְשַׁעְבְּדִין את לבם לאביהם וכ׳</span> when the Israelites looked upward and pledged their hearts to their Father in heaven, they were healed; a. fr.—Part. pass. <span dir=\"rtl\">מְשׁוּעְבָּד</span>; pl. <span dir=\"rtl\">מְשׁוּעְבָּדִים</span>, <span dir=\"rtl\">מְשׁוּעְבָּדִין</span>. <span class=\"citation\">Num. R. s. 5</span><sup>8</sup> <span dir=\"rtl\">שלא … אלא מש׳ לפני הארון</span> they were not haughty, but bore themselves like servants before the Ark. <span class=\"citation\">Y. Ḥag. III, 79ᵇ</span> <span dir=\"rtl\">שיהא הכל מש׳ להלכה</span> so that everything be made subject to the law; a. e.—<span dir=\"rtl\">נכסים מש׳</span>, or <span dir=\"rtl\">משועבדין</span> (sub. <a href=\"#\" data-headword=\"נְכָסִים\">נכסים</a>) <i>mortgaged property</i>, i.e. property bought from a person who owes a debt collectible from his landed estate in whatever hands it may be, opp. <span dir=\"rtl\">בני חורין</span> property in the hands of the debtor. <span class=\"citation\">B. Mets. 13ᵇ</span>. <span class=\"citation\">Gitt. 50ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to vex, persecute, attempt to destroy</i>. <span class=\"citation\">Ex. R. s. 22</span> <span dir=\"rtl\">נראה … מְשַׁעְבְּדִין את ישראל בדבר וכ׳</span> (not <span dir=\"rtl\">על ישראל</span>) let us see how we can persecute Israel by means of something which the Lord cannot bring upon us in the same manner; <span class=\"citation\">Yalk. ib. 208</span> <span dir=\"rtl\">אם מְשַׁעְבְּדִים אנו אותם באש וכ׳</span> if we destroy them through fire, their God can bring fire upon us &amp;c.; <span dir=\"rtl\">בואו ונְשַׁעְבְּדֵם במים</span> (not <span dir=\"rtl\">ונשתעבדם</span>) come, let us destroy them through water; <span class=\"citation\">Yalk. Ps. 786</span>; a. e.</div><div class=\"sense\"><b>Hithpa. הִשְׁתַּעְבֵּד</b> </div><div class=\"sense\"><b>Nithpa. נִשְׁתַּעְבֵּד</b> <div class=\"sense\"><b>1)</b>  (with (with <a href=\"#\" data-headword=\"ל\">ל</a>) <i>to be subjugated, be the slave</i> or <i>subject of</i>. <span class=\"citation\">Gitt. IV, 4</span> <span dir=\"rtl\">עבד … אם לשום עבד יִשְׁתַּעְבֵּד וכ׳</span> a slave that was captured and redeemed, if he was redeemed as a slave, remains a slave; if as a freeman, he cannot be made a slave. <span class=\"citation\">Ib. 37ᵇ</span> <span dir=\"rtl\">ישתעבד לרבו ראשון</span> he is the slave of his first (original) master; <span dir=\"rtl\">לא ישתעבד … לרבו שני</span> he is the slave neither of his first master, nor of his second master (his redeemer). <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">במה … או שׁיִשְׁתַּעְבְּדו למלכיות</span> which wilt thou choose? that thy children go down to Gehenna, or that they be subjected to successive empires? <span class=\"citation\">Sabb. 88ᵇ</span> <span dir=\"rtl\">אמר … לפרעה הִשְׁתַּעְבַּדְתֶּם</span> (Ms. M. <span dir=\"rtl\">נִשְׁתַּעְבַּדְתֶּם</span>) he (Moses) said to them (the angels), did you go down to Egypt? have you been slaves to Pharaoh? <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 32</span> (insert from <span class=\"citation\">Yalk. ib. 819</span>) <span dir=\"rtl\">זה יעקב … שאילו עלה לא ירד עוד ולא היה לנו להִשְׁתַּעְבֵּד שיעבוד זה שאנו משועבדין</span> (v. ed. Bub.) this refers to Jacob …, for if he had gone up, he would not have gone down again, and we should not have to suffer the servitude to which we are now subjected; a. fr.</div><div class=\"sense\"><b>—2)</b>  (with <a href=\"#\" data-headword=\"ב\">ב</a>) <i>to use as slave, enslave</i>. <span class=\"citation\">Pes. 118ᵇ</span> <span dir=\"rtl\">מה הללו שנִשְׁתַּעְבְּדוּ בהן כך אני שלא נִשְׁתַּעְבַּדְתִּי וכ׳</span> if they (the Egyptians) who treated them as slaves, fare thus, I (Cush) who did not enslave them &amp;c. <span class=\"citation\">Gitt. 40ᵃ</span> <span dir=\"rtl\">פלונית … אל ישתעבדו בה וכ׳</span> that handmaid of mine, they (my heirs) shall not treat her as a slave after my death. <span class=\"citation\">Keth. 111ᵃ</span> <span dir=\"rtl\">השביע … שלא ישתעבדו בהן וכ׳</span> the Lord adjured the nations not to oppress Israel too hard. <span class=\"citation\">Men. 53ᵇ</span>; <span class=\"citation\">Yalk. Jer. 289</span> [read:] <span dir=\"rtl\">ישתעבדו בהם ארבע מלכיות וכ׳</span> (v. Rabb. D. S. to Men. l. c., note) four successive empires shall treat them as slaves, each as long &amp;c.; a. fr.—[<span class=\"citation\">Yalk. Ex. 208</span>, v. supra.]</div></div>","alt":[]},"31877":{"h":"שַׁעְבֵּד","r":"U01629","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XII, 5</span>. <span class=\"citation\">Targ. Jud. X, 8</span>. <span class=\"citation\">Targ. Nah. I, 12</span>. <span class=\"citation\">Targ. Y. Ex. III, 7</span>; a. fr.—<span class=\"citation\">B. Mets. 13ᵃ</span> <span dir=\"rtl\">שַׁעְבֵּיד נפשיה</span> he bound himself (made himself responsible). <span class=\"citation\">Gitt. 49ᵇ</span> <span dir=\"rtl\">כל לגביה בריה שַׁעְבּוּרֵי מְשַׁעְבֵּד נפשיה</span> for his son’s sake a man makes himself responsible. <span class=\"citation\">Ab. Zar. 2ᵇ</span>, v. infra; a. fr.—Part. pass. <span dir=\"rtl\">מְשַׁעְבַּד</span>; f. <span dir=\"rtl\">מְשַׁעְבְּדָא</span>; pl. <span dir=\"rtl\">מְשַׁעְבְּדִין</span>, <span dir=\"rtl\">מְשַׁעְבְּדֵי</span>; <span dir=\"rtl\">מְשַׁעְבְּדָן</span>. <span class=\"citation\">Targ. Y. Gen. IX, 25</span>. <span class=\"citation\">Targ. Ez. XVI, 7</span>; a. e.—<span class=\"citation\">B. Mets. 73ᵇ</span> <span dir=\"rtl\">לטסקא מש׳</span>, v. <a href=\"#\" data-headword=\"טַסְקָא\">טַסְקָא</a>. <span class=\"citation\">Lev. R. s. 16</span> <span dir=\"rtl\">אמהן מש׳</span> maiden forced into servitude, v. <a href=\"#\" data-headword=\"כָּדַן\">כָּדַן</a>; Pesik. Vattom., p. 133ᵇ <span dir=\"rtl\">חמרין משעבדין</span> (corr. acc.); <span class=\"citation\">Lam. R. to IV, 15</span>; a. fr.—<span dir=\"rtl\">משעבדי</span> (sub. <a href=\"#\" data-headword=\"נִכְסִין\">נכסין</a>) <i>encumbered property</i>, opp. <span dir=\"rtl\">בני חרי</span>, v. <a href=\"#\" data-headword=\"שִׁעְבֵּד\">preced.</a> <span class=\"citation\">B. Mets. 12ᵇ</span>. <span class=\"citation\">Ib. 13ᵇ</span>; a. fr.</div><div class=\"sense\"><b>Ithpa. אִשְׁתַּעְבֵּד</b> <div class=\"sense\"><b>1)</b>  (with (with <a href=\"#\" data-headword=\"ל\">ל</a>) <i>to be subjected, enslaved, to serve; to be pledged, responsible</i>. <span class=\"citation\">Targ. II Chr. XXXIII, 13</span>. <span class=\"citation\">Targ. Gen. XXV, 23</span>. <span class=\"citation\">Ib. XXVII, 29</span>; a. fr.—<span class=\"citation\">B. Kam. 20ᵇ</span> <span dir=\"rtl\">ביתא לעלייה מִשְׁתַּעְבַּד</span> the house (the lower story) is pledged to the upper story, i.e. the owner of the lower story is bound to keep it in a condition to support the upper story. <span class=\"citation\">Ib. 40ᵇ</span> <span dir=\"rtl\">כי היכא דמִשְׁתַּעְבַּדְנָא לדידך וכ׳</span> as well as I am obliged to pay thee, I am obliged to pay him. <span class=\"citation\">Gitt. 49ᵇ</span> <span dir=\"rtl\">משתעבד</span> he is responsible. <span class=\"citation\">B. Bath. 55ᵃ</span> <span dir=\"rtl\">מִשְׁתַּעְבְּדֵי לכרגא</span>, v. <a href=\"#\" data-headword=\"כַּרְגָּא\">כַּרְגָּא</a>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (with <a href=\"#\" data-headword=\"ב\">ב</a>) <i>to enslave, oppress</i>. <span class=\"citation\">Ab. Zar. 2ᵇ</span> הנך אִישְׁתַּעְבְּדוּ בישראל אנן לא שַׁעְבְּדָן בישראל Ms. M. (ed. <span dir=\"rtl\">שִׁעְבַּדְנוּ</span> h. form) these nations have persecuted Israel, we have not &amp;c. <span class=\"citation\">B. Mets. 73ᵇ</span> ומִשְׁתַּעְבְּדֵי בהו וכ׳ Tosaf. (ed. <span dir=\"rtl\">ומשעבדי</span>), v. <a href=\"#\" data-headword=\"כַּרְגָּא\">כַּרְגָּא</a>. <span class=\"citation\">B. Bath. 55ᵃ</span> <span dir=\"rtl\">משתעבדי</span>, v. <a href=\"#\" data-headword=\"כַּרְגָּא\">כרגא</a>; a. e.</div></div>","alt":["שַׁעְבֵּיד"]},"31878":{"h":"שִׁעְבּוּד","r":"U01630","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שַׁעְבֵּד\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>subjection, servitude, oppression</i>. <span class=\"citation\">Ber. 12ᵇ</span> שיהא ש׳ מלכיות וכ׳ Ms. M. (ed. <span dir=\"rtl\">שתהא</span>) that the delivery from servitude to the empires &amp;c., v. <a href=\"#\" data-headword=\"עִיקָּר\">עִיקָּר</a>. <span class=\"citation\">Ib. 34ᵇ</span>, a. e. <span dir=\"rtl\">ש׳ מלכיות</span>, v. <a href=\"#\" data-headword=\"מַלְכוּת\">מַלְכוּת</a>. <span class=\"citation\">Cant. R. to II, 14</span> <span dir=\"rtl\">מפני מה … כדי שיצאו … בלא ש׳</span> why were the wives of the patriarchs barren (for a time)? In order that many (of the four-hundred) years (<span class=\"citation\">Gen. XV, 13</span>) might pass without servitude; <span class=\"citation\">Gen. R. s. 45</span>. <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">אף אני בש׳</span> shall I, too, be in slavery?; a. fr.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">ש׳ קרקעות</span> (or <a href=\"#\" data-headword=\"ש׳\">ש׳</a> only) <i>pledge, hypothecary obligation, landed security</i>. <span class=\"citation\">B. Mets. 4ᵇ</span> <span dir=\"rtl\">משום דהוה ליה שטר ש׳ ק׳ … כפירת ש׳ ק׳</span> because a note of indebtedness implies a hypothecary obligation (that the debtor’s landed property is pledged to the creditor), and no oath is assigned on a disputed hypothecary obligation; <span class=\"citation\">Shebu. 37ᵇ</span>; <span class=\"citation\">Keth. 87ᵇ</span>. <span class=\"citation\">B. Mets. 14ᵃ</span> <span dir=\"rtl\">שבח שְׁפַר וש׳ וכ׳</span> the scribe must ask for authorization to insert, in a deed of sale of land, ‘amelioration’, ‘best land’ and ‘pledge’, i.e. that the seller pledges his land, and this the best portions of it, for indemnity to the buyer in case of seizure for the seller’s debt, this indemnity to include the improvements eventually made by the buyer; a. fr.</div>","alt":["שִׁי׳"]},"31879":{"h":"שִׁעְבּוּד ²","r":"U01631","html":"<div class=\"sense\"><b>1)</b> <i>servitude, oppression</i>. Targ. II Esth. I, 2. <span class=\"citation\">Targ. II Chr. XII, 8</span>. <span class=\"citation\">Targ. Y. Gen. XXXVII, 17</span>. <span class=\"citation\">Targ. Y. Deut. V, 6</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"שִׁעְבּוּד ²\">שִׁעְבּוּדַיָּא</a>, <a href=\"#\" data-headword=\"שִׁבְהוֹר\">שִׁי׳</a>. <span class=\"citation\">Targ. Y. Gen. XL, 18</span>.</div><div class=\"sense\"><b>—2)</b> <i>pledge, obligation</i>. [In post-Talmudic literature <span dir=\"rtl\">ש׳ דר׳ נתן</span> the obligation introduced by R. Nathan, whereby the court can collect a debt in favor of the creditor’s debtor; v. <span class=\"citation\">B. Kam. 40ᵇ</span>; <span class=\"citation\">Keth. 19ᵃ</span>; a. fr.]</div>","alt":["שִׁעְבּוּדָא","שִׁי׳"]},"31880":{"h":"שִׁעְבֵּז","r":"U01632","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"שַׁעְבְּזִין\">next w.</a>), part. pass. <span dir=\"rtl\">מְשׁוּעְבָּז</span> <i>one who has abnormally large testicles</i> or <i>an abnormally long scrotum</i>. <span class=\"citation\">Bekh. VII, 5</span> (<span class=\"citation\">44ᵇ</span>) Ar. (Mish. ed. <a href=\"#\" data-headword=\"מאושבן\">מאושכן</a>, Talm. ed. <a href=\"#\" data-headword=\"מאושבן\">מאושבן</a>), v. <a href=\"#\" data-headword=\"אֶשֶׁךְ\">אֶשֶׁךְ</a>.</div>","alt":[]},"31881":{"h":"שַׁעְבְּזִין","r":"U01633","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Shaf. of <span dir=\"rtl\">עבז</span>, v. <a href=\"#\" data-headword=\"*אֵבוּז\">אֵבוּז</a>) <i>extremities, testicles, scrotum</i>. <span class=\"citation\">Targ. Y. Gen. XXXIX, 1</span>. <span class=\"citation\">Targ. Job XL, 17</span> שעבזוהי Ms. a. Ar. (ed. <span dir=\"rtl\">פחדוי</span>).</div>","alt":[]},"31882":{"h":"שָׁעָה","r":"U01634","html":"<div class=\"sense\"> I, v. <a href=\"#\" data-headword=\"שעי\">שעי</a></div>","alt":[]},"31883":{"h":"שָׁעָה II","r":"U01635","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span class=\"citation\">Dan. IV, 16</span>; <a href=\"#\" data-headword=\"שָׁעָה\">preced.</a>, v. Del. Proleg. p. 39 sq.) <i>moment, while; hour</i>, esp. <i>the twelfth portion</i> of the day and of the night, varying according to the season. <span class=\"citation\">Tosef. Ber. I, 1</span>, a. e., v. <a href=\"#\" data-headword=\"עוֹנָה IV\"><span dir=\"rtl\">עוֹנָה</span> I</a>. <span class=\"citation\">Ber. 7ᵃ</span>, v. <a href=\"#\" data-headword=\"רֶגַע\">רֶגַע</a>. <span class=\"citation\">Ib. 7ᵇ</span>, a. e. <span dir=\"rtl\">הש׳ משחקת</span>, v. <a href=\"#\" data-headword=\"שָׂחַק\">שָׂחַק</a>. <span class=\"citation\">Lam. R. to III, 37</span> <span dir=\"rtl\">מש׳ שאמר וכ׳</span> from the moment that the Lord said &amp;c. <span class=\"citation\">Ber. I, 1</span> <span dir=\"rtl\">מש׳ שהכהנים וכ׳</span> from the time of day when the priests go in &amp;c. <span class=\"citation\">Pes. II, 1</span> <span dir=\"rtl\">כל ש׳</span> as long. <span class=\"citation\">Keth. 104ᵃ</span> <span dir=\"rtl\">בש׳ שהצדיק וכ׳</span> when a righteous man is called away &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בשְׁעַת פטירתו וכ׳</span> when Rabbi died &amp;c. <span class=\"citation\">Ber. 64ᵃ</span> <span dir=\"rtl\">הדוחק את הש׳</span>, v. <a href=\"#\" data-headword=\"דָּחַק\">דָּחַק</a>; <span dir=\"rtl\">נדחה מפני הש׳</span>, v. <a href=\"#\" data-headword=\"דָּחָה\">דָּחָה</a>. <span class=\"citation\">Sabb. 10ᵃ</span>, a. e. <span dir=\"rtl\">מניחין … ועוסקין בחיי ש׳</span> they neglect the life everlasting, and busy themselves with the life of the hour (earthly affairs). <span class=\"citation\">Y. Taan. III, 67ᵃ</span> (expl. <span dir=\"rtl\">יולדתך</span>, <span class=\"citation\">Prov. XXIII, 25</span>) <span dir=\"rtl\">שַׁעַתְךָ</span> (or <span dir=\"rtl\">שַׁעְתְּךָ</span>) thy hour (of birth). <span class=\"citation\">Cant. R. to I, 1</span>, a. e. <span dir=\"rtl\">בשַׁעְתּוֹ</span> in its due time, v. <a href=\"#\" data-headword=\"סֵפֶל\">סֵפֶל</a>; <span class=\"citation\">Num. R. s. 10</span><sup>4</sup> <span dir=\"rtl\">בין שעתו</span>. <span class=\"citation\">Ex. R. s. 19</span>, a. fr. <span dir=\"rtl\">לש׳ קלה</span>, v. <a href=\"#\" data-headword=\"קַל II\"><span dir=\"rtl\">קַל</span> II</a>; a. v. fr.—<span dir=\"rtl\">הוראת ש׳</span>, or <a href=\"#\" data-headword=\"ש׳\">ש׳</a> temporary, special legislation, opp. <span dir=\"rtl\">דורות</span>. <span class=\"citation\">Yoma 69ᵇ</span>. <span class=\"citation\">Men. 19ᵇ</span> <span dir=\"rtl\">דורות מש׳</span>, v. <a href=\"#\" data-headword=\"דּוֹר\">דּוֹר</a>. <span class=\"citation\">Ib. 56ᵃ</span> <span dir=\"rtl\">ש׳ מדורות וכ׳</span> we cannot derive the modes of a temporary act (e.g. the offerings of the princes, <span class=\"citation\">Num. VII, 12-83</span>) from the laws concerning a permanent institution; a. fr.—Pl. <a href=\"#\" data-headword=\"שָׁעוּת\">שָׁעוֹת</a>. <span class=\"citation\">Ber. 3ᵃ</span> <span dir=\"rtl\">עד ארבע ש׳</span> to four hours (the fourth hour of the night). <span class=\"citation\">Pes. 58ᵃ</span> <span dir=\"rtl\">שתי ש׳ ומחצה</span> two hours and a half. <span class=\"citation\">Snh. V, 3</span> <span dir=\"rtl\">אחד אומר בשתי ש׳ וכ׳</span> if one witness testifies that the act under consideration was committed at the second hour of the day &amp;c. <span class=\"citation\">Kel. XII, 4</span> <span dir=\"rtl\">אבן הש׳</span>, v. <a href=\"#\" data-headword=\"אֶבֶן\">אֶבֶן</a>; a. v. fr.</div>","alt":[]},"31884":{"h":"שַׁעֲוָא","r":"U01636","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"שַׁעֲוָה\">next w.</a> <span class=\"citation\">Targ. Ps. LXVIII, 3</span>. <span class=\"citation\">Ib. XXII, 15</span>; a. e., v. <a href=\"#\" data-headword=\"שַׁעַוְתָּא\">שַׁעַוְתָּא</a>.—<span class=\"citation\">Targ. Y. Gen. XXXVII, 25</span>; <span class=\"citation\">XLIII, 11</span> <a href=\"#\" data-headword=\"שַׁעֲוָה\">שַׁעֲוָה</a> (O. <a href=\"#\" data-headword=\"שְׁעַף\">שְׁעַף</a>; h. text <span dir=\"rtl\">נכאת</span>).</div>","alt":[]},"31885":{"h":"שַׁעֲוָה","r":"U01637","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שעי\">שעי</a> = <a href=\"#\" data-headword=\"שׁוּעַ\">שׁוּעַ</a>) <i>wax</i>. <span class=\"citation\">Sabb. II, 1</span> <span dir=\"rtl\">ולא בש׳</span> nor must you use wax in place of oil for the Sabbath light, v. <a href=\"#\" data-headword=\"קִירוּתָא\">קִירוּתָא</a>. <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">היה לבו רפה כש׳</span>, v. <a href=\"#\" data-headword=\"שׁוּעַ ²\"><span dir=\"rtl\">שׁוּעַ</span> I</a>. <span class=\"citation\">Gen. R. s. 91</span>, end (expl. <span dir=\"rtl\">נכאת</span>, <span class=\"citation\">Gen. XLIII, 11</span>) <a href=\"#\" data-headword=\"ש׳\">ש׳</a> (perhaps <i>a gum</i>, v. <a href=\"#\" data-headword=\"שַׁעֲוָא\">preced.</a>). <span class=\"citation\">Ex. R. s. 35</span> <span dir=\"rtl\">כש׳ הנתונה וכ׳</span> like wax that is put on the writing tablet; a. fr.</div>","alt":[]},"31886":{"h":"שְׁעוֹלָא","r":"U01638","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שֹׁעַל\">שֹׁעַל</a>, </div><div class=\"sense\"><b>1)</b> <i>hollow of the hand, palm</i>. <span class=\"citation\">Targ. Is. XL, 12</span>.—Pl. constr. <span dir=\"rtl\">שַׁעֲלֵי</span>. <span class=\"citation\">Targ. Ez. XIII, 19</span>.</div><div class=\"sense\"><b>—2)</b> <i>hollow of the sole, step.</i> <i>—</i> Pl. constr. <span dir=\"rtl\">שְׁעוֹלֵי</span>. <span class=\"citation\">Targ. I Kings XX, 10</span>.</div>","alt":["שַׁעֲלָא"]},"31887":{"h":"שעועים","r":"U01639","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁעוּעִית\">next w.</a></div>","alt":[]},"31888":{"h":"שְׁעוּעִית","r":"U01640","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">שעע</span>; cmp. <a href=\"#\" data-headword=\"שַׁעֲוָה\">שַׁעֲוָה</a>) a species of <i>beans</i>, prob. <i>kidney-bean</i> (Phaseolus Vulgaris), v. <a href=\"#\" data-headword=\"פְּסִילְתָּא\">פְּסִילְתָּא</a>, a. <a href=\"#\" data-headword=\"*חֲלוּקָה\">חֲלוּקָה</a>. <span class=\"citation\">Kil. I, 1</span> פול הלבן והש׳ וכ׳ Y. ed. a. Ms. M. (Mish. a. Bab. ed. <a href=\"#\" data-headword=\"שעועים\">שעועים</a>, corr. acc.; v. Rabb. D. S. a. l. note) the white bean and the kidney-bean are not heterogeneous. Y. ib. 27ᵃ top expl. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"פתילתה\">פתילתה</a>) <a href=\"#\" data-headword=\"פְּסִילְתָּא\">פסילתא</a></span>. Ib. <span dir=\"rtl\">למה שמה ש׳ שמשעשעת את הלב וכ׳</span> (some ed. <a href=\"#\" data-headword=\"שַׁעֲשׁוּעִית\">שעשועית</a>) why is it called <i>sh’ʿuʿith</i> (pasty)? Because it pastes up (dulls) the heart, and loosens the bowels.</div>","alt":[]},"31889":{"h":"שִׁעוּר","r":"U01641","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁיעוּר\">שִׁיעוּר</a>, <a href=\"#\" data-headword=\"שִׁיעוּרָא\"><a href=\"#\" data-headword=\"שִׁיעוּרָא\">שִׁיעוּרָא</a>.</a></div>","alt":["שִׁעוּרָא"]},"31890":{"h":"שְׂעוֹרָה","r":"U01642","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"*סָעַר I\">סָעַר</a>) </div><div class=\"sense\"><b>1)</b> <i>panicle</i>, v. <a href=\"#\" data-headword=\"שַׂעֲרָה\">שַׂעֲרָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>barley, barley-corn</i>.—<span dir=\"rtl\">כש׳</span> the size of a barley-corn. <span class=\"citation\">Kel. XVII, 8</span> <span dir=\"rtl\">כש׳ שאמרו לא וכ׳</span> where the scholars make the barley-corn the ritual standard measure, neither the large sort is meant nor &amp;c. <span class=\"citation\">Ex. R. s. 10</span>, end; <span class=\"citation\">Snh. 67ᵇ</span>, v. <a href=\"#\" data-headword=\"שֵׁד\">שֵׁד</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"שְׂעוֹרִים\">שְׂעוֹרִים</a>, <a href=\"#\" data-headword=\"שְׂעוֹרִין\">שְׂעוֹרִין</a>. <span class=\"citation\">Pes. II, 5</span>. <span class=\"citation\">Ib. 35ᵃ</span> <span dir=\"rtl\">מין ש׳</span> a species of barley, v. <a href=\"#\" data-headword=\"שִׁיפוֹן\">שִׁיפוֹן</a>. <span class=\"citation\">Ib. 42ᵇ</span> <span dir=\"rtl\">לא היה יינם … ש׳</span> the wine of Judæa would not get sour (to be used for vinegar) until they put barley into it. <span class=\"citation\">B. Kam. 60ᵇ</span> <span dir=\"rtl\">גדישין של ש׳</span> stacks of barley. <span class=\"citation\">Peah VI, 7</span>; <span class=\"citation\">Y. Snh. II, 20ᵇ</span> bot., a. e., v. <a href=\"#\" data-headword=\"עֲנָבָה\">עֲנָבָה</a>; a. fr.</div>","alt":[]},"31891":{"h":"שְׂעוֹרִים","r":"U01643","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"סְעוֹרִים\">סְעוֹרִים</a></div>","alt":[]},"31892":{"h":"שְׂעוֹרִין","r":"U01644","html":"<div class=\"sense\"><i>barley</i>, v. <a href=\"#\" data-headword=\"סְעַרְתָּא\">סְעַרְתָּא</a>.</div>","alt":[]},"31893":{"h":"שָׁעוּת","r":"U01645","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שָׁעָה\">שָׁעָה</a>) <i>a while, time</i>. <span class=\"citation\">Meïl. 6ᵃ</span>, v. <a href=\"#\" data-headword=\"שָׁהוּת\">שָׁהוּת</a>.</div>","alt":[]},"31894":{"h":"שַׁעַוְתָּא","r":"U01646","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שַׁעֲוָה\">שַׁעֲוָה</a>, <i>wax</i>. <span class=\"citation\">Targ. Ps. XXII, 15</span> Ms. (ed. <a href=\"#\" data-headword=\"שַׁעֲוָא\">שַׁעֲוָא</a>). <span class=\"citation\">Targ. Mic. I, 4</span> <a href=\"#\" data-headword=\"שָׁעִיתָא\">שָׁעִיתָא</a>.—V. <a href=\"#\" data-headword=\"שַׁעֲוָא\">שַׁעֲוָא</a>.</div>","alt":[]},"31895":{"h":"שַׁעַז","r":"U01647","html":"<div class=\"sense\"> (= <span dir=\"rtl\">שענז</span>) <i>shaʿaz</i>, the first and the last element of <a href=\"#\" data-headword=\"שַׁעַטְנֵז\">שַׁעַטְנֵז</a>, representing the act of <i>carding</i> <span dir=\"rtl\">(שוע</span>), and that of <i>twining</i> or <i>weaving</i> <a href=\"#\" data-headword=\"נוּז\">(נוז</a>). <span class=\"citation\">Y. Kil. IX, end, 32ᵈ</span>, v. <a href=\"#\" data-headword=\"נוּז\">נוּז</a>.</div>","alt":[]},"31896":{"h":"שַׁעַט","r":"U01648","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"שַׁעַז\">preced.</a>) <i>shaʿaṭ</i>, the first and the middle element of <a href=\"#\" data-headword=\"שַׁעַטְנֵז\">שַׁעַטְנֵז</a>, representing the act of <i>carding</i> <span dir=\"rtl\">(שוע</span>), and that of <i>spinning</i> <a href=\"#\" data-headword=\"טוי\">(טוי</a>). <span class=\"citation\">Y. Kil. IX, end, 32ᵈ</span></div>","alt":[]},"31897":{"h":"שעטנ\"ז","r":"U01649","html":"<div class=\"sense\"><i>the seven letters which require crownlets</i> in the Pentateuch scrolls. <span class=\"citation\">Men. 29ᵇ</span>, v. <a href=\"#\" data-headword=\"זִיּוּן\">זִיּוּן</a>.</div>","alt":["ש׳ ג\"ץ"]},"31898":{"h":"שַׁעַטְנֵז","r":"U01650","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>a web mixed of wool and linen</i>. <span class=\"citation\">Kil. IX, 8</span>, expl. as acrostic, <span dir=\"rtl\">דבר שהוא ש̇וע̇ ט̇ווי ונ̇וז̇</span>, v. <a href=\"#\" data-headword=\"נוּז\">נוּז</a>.</div>","alt":[]},"31899":{"h":"שַׁעַטְנֵזָא","r":"U01651","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Lev. XIX, 19</span>; <span class=\"citation\">Deut. XXII, 11</span>.</div>","alt":["שַׁעַטְנֵיזָא"]},"31900":{"h":"שעי","r":"U01652","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b>  (cmp. <a href=\"#\" data-headword=\"חֲמִישַׁי\">שָׁאָה</a>, <a href=\"#\" data-headword=\"שָׁהָה\">שָׁהָה</a>) <i>to dwell, linger</i>, denom. <a href=\"#\" data-headword=\"שָׁעָה\">שָׁעָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>to look, care for, mind</i>. <span class=\"citation\">Sifré Deut. 318</span> (ref. to <span class=\"citation\">Deut. XXXII, 17</span>) <span dir=\"rtl\">אל תקרי לא שערום אלא לא שָׁעוּם וכ׳</span> read not <i>lo s’ʿarum</i>, but <i>lo shaʿum</i> (whom they did not regard); although they sacrificed and burnt incense to them, they were not afraid of them (with ref. to <span class=\"citation\">Gen. IV, 5</span>); Yalk. ib. 945.</div>","alt":["שָׁעָה"]},"31901":{"h":"שְׁעֵי","r":"U01653","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">שוע</span>, <span dir=\"rtl\">שעע</span>) <i>to smooth, paste over, daub</i>. <span class=\"citation\">Succ. 51ᵇ</span>; <span class=\"citation\">B. Bath. 4ᵃ</span> <span dir=\"rtl\">סבר למִשְׁעֲיָין בדהבא</span> he (Herod) intended to cover them (the Temple walls) with gold.</div><div class=\"sense\"><b>Pa. שַׁעֵי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"שעי\">same</a>. <span class=\"citation\">Targ. Ps. V, 10</span> <span dir=\"rtl\">מְשַׁעֲיִין</span>. Ms. (ed. <span dir=\"rtl\">משעעין</span>).—Part. pass. <span dir=\"rtl\">מְשָׁעָא</span>. <span class=\"citation\">Targ. Y. II, Num. XIX, 15</span> <span dir=\"rtl\">מִשְׁעָא</span> (corr. acc., or <span dir=\"rtl\">מַשְׁעָא</span>, Part. pass. <i>Af.</i>).</div></div><div class=\"sense\"><b>Ithpa. אִשְׁתָּעֵי</b> </div><div class=\"sense\"><b>Ithpe. אִשְׁתְּעֵי</b> <div class=\"sense\"> [<i>to make one’s self pleasant</i>,] <i>to converse, talk; to tell a story</i>. <span class=\"citation\">Targ. O. Gen. XXIV, 66</span>. <span class=\"citation\">Targ. Jud. VI, 13</span>. <span class=\"citation\">Targ. Is. XXX, 10</span>. <span class=\"citation\">Targ. Ps. L, 16</span>; <span class=\"citation\">19</span>; a. fr.—<span class=\"citation\">B. Bath. 73ᵃ</span> <span dir=\"rtl\">אִשְׁתָּעוּ לי נחותי וכ׳</span> (not <a href=\"#\" data-headword=\"שְׁעֵי\">אשתעי</a>) seafarers told me. <span class=\"citation\">Ib. 74ᵃ</span> ר׳ יוחנן מִשְׁתָּעֵי וכ׳ R. J. told a story: once upon a time &amp;c. Y. Ber. II, 4ᵈ bot. <span dir=\"rtl\">כמה דאי׳ … אִשְׁתָּעְיָיא וכ׳</span> as the Scripture talks, so does the Mishnah, i.e. the Mishnah applies the Biblical phraseology; a. fr.—א׳ דינא בהדי <i>to talk about the law with, to sue</i>. <span class=\"citation\">B. Mets. 14ᵃ</span> <span dir=\"rtl\">דינא … ומשתעי דינא בהדיה</span> the law is that R. may go and sue him. <span class=\"citation\">Bekh. 47ᵇ</span> <span dir=\"rtl\">גברא דלא מצית לאִשְׁתָּעוּיֵי וכ׳</span> a man with whom thou canst not go to law; a. e.</div></div>","alt":["שְׁעָא"]},"31902":{"h":"שַׁעֲיוּתָא","r":"U01654","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁעֵי\">preced.</a>) <i>smoothness</i>, v. <a href=\"#\" data-headword=\"שְׁעִיעוּתָא\">שְׁעִיעוּתָא</a>.</div>","alt":[]},"31903":{"h":"שעייא","r":"U01655","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. B. Bath. IV, 5</span>, v. <a href=\"#\" data-headword=\"שַׁעֲמוּמִית\">שַׁעֲמוּמִית</a></div>","alt":[]},"31904":{"h":"שְׁעִיעַ","r":"U01656","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁעַע\">שְׁעַע</a>) <i>smooth</i>. <span class=\"citation\">Targ. Gen. XXVII, 11</span>. <span class=\"citation\">Targ. Cant. V, 12</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"שְׁקִיעַיָּא\">שְׁעִיעַיָּא</a>, <a href=\"#\" data-headword=\"שְׁקִיעַיָּא\">שְׁעִיעִין</a>; <a href=\"#\" data-headword=\"שְׁעִיעַ\">שְׁעִיעָן</a>, <a href=\"#\" data-headword=\"שְׁעִיעוּתָא\">שְׁעִיעָתָא</a>. <span class=\"citation\">Targ. I Sam. XVII, 40</span> <span dir=\"rtl\">שְׁעִיעֵי אבניא</span> (h. text <span dir=\"rtl\">חלקי אבנים</span>). <span class=\"citation\">Targ. Y. Lev. XIX, 17</span>. <span class=\"citation\">Targ. Ps. XII, 3</span>. <span class=\"citation\">Ib. XXXV, 16</span> שעיעתא Ms. (ed. <a href=\"#\" data-headword=\"שְׁעִיעוּתָא\">שעיעותא</a>); a. e.</div>","alt":["שְׁעִיעָא"]},"31905":{"h":"שְׁעִיעוּתָא","r":"U01657","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁעִיעַ\">preced.</a>) <i>smoothness</i>. <span class=\"citation\">Targ. Gen. XXVII, 16</span>. <span class=\"citation\">Targ. Ez. XXVI, 4</span>; <span class=\"citation\">14</span> (h. text <span dir=\"rtl\">צחיח</span>). <span class=\"citation\">Targ. Prov. VI, 24</span>. <span class=\"citation\">Targ. Is. LVII, 6</span> (some ed. <a href=\"#\" data-headword=\"שַׁעֲיוּתָא\">שַׁעֲיוּת</a>); a. e.</div>","alt":[]},"31906":{"h":"שְׁעִיף","r":"U01658","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"שְׁעַף\">שְׁעַף</a>) <i>gum, balm</i>. <span class=\"citation\">Targ. Ez. XXVII, 17</span> (h. text <a href=\"#\" data-headword=\"צְרֵי I\">צרי</a>). <span class=\"citation\">Targ. Jer. XLVI, 11</span>; <span class=\"citation\">LI, 8</span> (not <a href=\"#\" data-headword=\"שְׁעִיף\">שֵׁעִיף</a>).</div>","alt":[]},"31907":{"h":"שָׂעִיר","r":"U01659","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>goat</i>. <span class=\"citation\">Yoma VI, 2</span> <span dir=\"rtl\">ש׳ המשתלח</span>, v. <a href=\"#\" data-headword=\"שָׁלַח\">שָׁלַח</a>. <span class=\"citation\">Ib. 7</span> <span dir=\"rtl\">פר וש׳ הנשרפין</span> the bullock and the goat designated to be burnt. <span class=\"citation\">Zeb. V, 1</span>; a. fr.—Pl. <span dir=\"rtl\">שְׂעִירִים</span>, <span dir=\"rtl\">שְׂעִירִין</span>. <span class=\"citation\">Ib. 2</span>. <span class=\"citation\">Yoma VI, 1</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>demon</i>. <span class=\"citation\">B. Bath. 25ᵃ</span>, v. <a href=\"#\" data-headword=\"סָעַר II\"><span dir=\"rtl\">סָעַר</span> II</a>. <span class=\"citation\">Ber. 64ᵃ</span> <span dir=\"rtl\">ש׳ בש׳ מיחלף</span> goat and demon may interchange (both going by the name of <i>saʿir).—</i> Pl. as ab. <span class=\"citation\">Lev. R. s. 22</span>, v. <a href=\"#\" data-headword=\"שֵׁד\">שֵׁד</a>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>shower</i>. Pl. as ab. <span class=\"citation\">Sifré Deut. 306</span> (ref. to <span class=\"citation\">Deut. XXXII, 2</span>) <span dir=\"rtl\">מה ש׳ הללו וכ׳</span> as the showers come down on the plants &amp;c.; Yalk. ib. 942, v. <a href=\"#\" data-headword=\"סָעַר II\"><span dir=\"rtl\">סָעַר</span> II</a>.</div><div class=\"sense\"><b>—4)</b> <i>hairy</i>. <span class=\"citation\">Gen. R. s. 65</span>.</div>","alt":[]},"31908":{"h":"שֵׂעִיר","r":"U01660","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Seir</i> (<i>Idumæa</i>). <span class=\"citation\">Y. Taan. I, 64ᵃ</span> top (ref. to <span class=\"citation\">Is. XXI, 11</span>) <span dir=\"rtl\">אֵלִי קורא מפני ש׳</span> my God cries out on account of Seir (Rome, v. <a href=\"#\" data-headword=\"אֱדוֹם\">אֱדוֹם</a>); ib. <span dir=\"rtl\">אלי איכן נזדווג לי מש׳</span> whence did my God come to join me? From Seir (<span class=\"citation\">Deut. XXXIII, 2</span>). <span class=\"citation\">Sifré Deut. 343</span> <span dir=\"rtl\">כשעתיד … ליפרע מש׳</span> when the Lord shall punish Seir (Rome). <span class=\"citation\">Ber. 62ᵇ</span> <span dir=\"rtl\">עד השתא … לש׳ וגמרת מילי דש׳</span> thou hast not yet gone to Seir (Rome), and hast already learned the things of Seir (indecent manners); <span class=\"citation\">Tam. 27ᵇ</span>; a. fr.</div>","alt":[]},"31909":{"h":"שְׂעִירַן","r":"U01661","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַעֲרָן\">סַעֲרָן</a></div>","alt":[]},"31910":{"h":"שָׁעִיתָא","r":"U01662","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁעַוְתָּא\">שַׁעַוְתָּא</a></div>","alt":[]},"31911":{"h":"שְׁעִיתָא","r":"U01663","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"שְׁעוּעִית\">שְׁעוּעִית</a>) a species of <i>beans</i>, prob. <i>the Egyptian bean</i> (v. Sm. Ant. s. v. Colocasia). [The definition given <span class=\"citation\">Ab. Zar. 38ᵇ</span> is fabulous and obviously founded on confusion with the colocasia bean, which is sown on moist earth and sinks into the water.] <span class=\"citation\">Ab. Zar. 38ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"שִׁיעֲתָא\">שִׁיעֲתָא</a>), v. <a href=\"#\" data-headword=\"פְּסִילְיָא\">פְּסִילְיָא</a>.</div>","alt":[]},"31912":{"h":"שֹׁעַל","r":"U01664","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>hollow of the hand, palm, handful</i>. Tanḥ. <span class=\"citation\">B’resh. 5</span> (ref. to <span class=\"citation\">Is. XL, 12</span>) <span dir=\"rtl\">מן שָׁעֳלוֹ אתה יודע וכ׳</span> by the size of his handful canst thou know who he himself is; ib. Ḥayé 3 <span dir=\"rtl\">וכל … בשעלו</span> all the seas and rivers did he measure with his palm; ib. Emor 15 <span dir=\"rtl\">וכל … מלא שעלו וכ׳</span> all the waters of the world fill the palm of the Lord; Pesik. Eth Korb., p. 57ᵇ <span dir=\"rtl\">מלא שׁוֹעֳלוֹ</span>; Tanḥ. Pinḥ. 12 <span dir=\"rtl\">מלא שָׁעֳלִי</span> my handful; <span class=\"citation\">Num. R. s. 21</span><sup>17</sup>; Pesik. R. addit. s. 1 <span dir=\"rtl\">כל … לתוך שעלי</span> all the waters of creation did I compress into my palm.—Pl. <span dir=\"rtl\">שָׁעֲלִים</span>. Ib. <span dir=\"rtl\">גבור … פחות מעשרה ש׳</span> a mighty man … drinks no less than ten handfuls; a. e.—2) <span dir=\"rtl\">ש׳ של ים</span> <i>the hollow of the sea, depth</i>. <span class=\"citation\">Cant. R. to II, 15</span> (ref. to Cant. l. c.; v. ed. Baer et Del. Notae criticae a. l.) <span dir=\"rtl\">קדמאה מלא … שירדו לשעלו של ים</span> the first <i>shuʿalim</i> is written <i>plene</i>, the second <i>defective</i>, which may be read <span dir=\"rtl\">שָׁעֳלִים</span>; they (the Egyptians) were the foxes that went down to the bottom of the sea; <span class=\"citation\">Ex. R. s. 22</span> <span dir=\"rtl\">על שם שעלו של ים</span> an allusion to the bottom of the sea; <span class=\"citation\">Yalk. Ps. 786</span> <span dir=\"rtl\">שעלים</span> (read: <span dir=\"rtl\">שעל ים</span>).</div>","alt":[]},"31913":{"h":"שַׁעֲלָא","r":"U01665","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁעוֹלָא\">שְׁעוֹלָא</a></div>","alt":[]},"31914":{"h":"שַׁעַם","r":"U01666","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>bamboo</i> (Maim., identifying our w. with <a href=\"#\" data-headword=\"שָׁגַם\">שֶׁגֶם</a>); [oth. opin. <i>cork-tree, cork</i>]. <span class=\"citation\">Kel. XIV, 5</span> shoes for cattle <span dir=\"rtl\">של ש׳</span> made of <i>shaʿam</i>. <span class=\"citation\">Tosef. Kel. B. Bath. IV, 14</span>; <span class=\"citation\">Succ. 20ᵇ</span> <span dir=\"rtl\">חוצלות של ש׳ וכ׳</span> mats made of <i>sh.</i>, or of reeds &amp;c.; a. e.</div>","alt":[]},"31915":{"h":"שִׁעֲמוּם","r":"U01667","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שִׁעְמֵם\">שִׁעֲמֵם</a>) </div><div class=\"sense\"><b>1)</b> <i>dullness, idiocy</i>. <span class=\"citation\">Keth. V, 5</span> <span dir=\"rtl\">הבטלה מביאתה לידי ש׳</span> idleness may lead her to idiocy; [corr. acc. quot. s. v. <a href=\"#\" data-headword=\"בַּטָּלָה\">בַּטָּלָה</a>].</div><div class=\"sense\"><b>—2)</b>  (= <span dir=\"rtl\">בעל ש׳</span>) <i>dull-minded man, idiot</i>. <span class=\"citation\">Sot. 24ᵃ</span> sq.; <span class=\"citation\">27ᵃ</span>; <span class=\"citation\">Num. R. s. 9</span><sup>28</sup> <span dir=\"rtl\">אשת ש׳</span> the wife of an idiot.</div>","alt":["שִׁי׳"]},"31916":{"h":"שִׁעֲמוּם ²","r":"U01668","html":"<div class=\"sense\">, <i>stupefaction</i>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 37</span> (h. text <a href=\"#\" data-headword=\"שַׁמָּה\">שַׁמָּה</a>).</div>","alt":["שִׁי׳"]},"31917":{"h":"שַׁעֲמוּמִית","r":"U01669","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שִׁעֲמוּם ²\">preced.</a>) <i>a dull-minded woman, idiot</i>. <span class=\"citation\">Tosef. Keth. VII, 10</span> ed. Zuck. (oth. ed. <span dir=\"rtl\">משוממת</span>), v. <a href=\"#\" data-headword=\"שָׁמֵם\">שָׁמַם</a>. <span class=\"citation\">Tosef. B. Bath. IV, 5</span> <span dir=\"rtl\">ש׳ היא</span> (ed. Zuck. <a href=\"#\" data-headword=\"שעייא\">שעייא</a>, corr. acc.) she (the slave) is an idiot; <span class=\"citation\">B. Mets. 80ᵃ</span> <span dir=\"rtl\">מְשׁוּעֲמֶמֶת</span>.</div>","alt":[]},"31918":{"h":"שַׁעֲמוּמִיתָא","r":"U01670","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שַׁעֲמוּמִית\">preced.</a>) <i>dullness, idiocy</i>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 20</span> Ar. (ed. <a href=\"#\" data-headword=\"עִרְבּוּב ²\">ערבובא</a>; h. text <a href=\"#\" data-headword=\"מְהוּמָה\">מהומה</a>); v. <a href=\"#\" data-headword=\"שַׁעֲמָמוּתָא\">שַׁעֲמָמוּתָא</a>.—<span class=\"citation\">Ned. 81ᵃ</span> scabs arising from neglected clothes <span dir=\"rtl\">מתיא לידי ש׳</span> lead to idiocy.</div>","alt":["שַׁעֲמִי׳"]},"31919":{"h":"שִׁעְמֵם","r":"U01671","html":"<div class=\"sense\"> (Shaf. of <a href=\"#\" data-headword=\"עָמַם\">עָמַם</a>) <i>to make dull, stupefy</i>.—Part. pass. <span dir=\"rtl\">מְשׁוּעֲמָם</span>; f. <span dir=\"rtl\">מְשׁוּעֲמֶמֶת</span>. <span class=\"citation\">B. Mets. 80ᵃ</span>, v. <a href=\"#\" data-headword=\"שַׁעֲמוּמִית\">שַׁעֲמוּמִית</a>.</div><div class=\"sense\"><b>Nithpa. נִשְׁתַּעֲמֵם</b> <div class=\"sense\"><i>to be made dull, be stupefied</i>. <span class=\"citation\">Num. R. s. 10</span><sup>8</sup> <span dir=\"rtl\">יצא כל דעתו נִשְׁתַּעַמְמוּ כל הכליות וכ׳</span></div></div>","alt":[]},"31920":{"h":"שַׁעֲמֵם","r":"U01672","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"שִׁעְמֵם\">same</a>. <span class=\"citation\">Targ. Y. Ex. XIV, 24</span> (some ed. <span dir=\"rtl\">שא׳</span>; h. text <span dir=\"rtl\">ויהם</span>).). <span class=\"citation\">Targ. Hos. IX, 7</span>.—</div><div class=\"sense\"><b>*2)</b> <i>to lay waste</i>. <span class=\"citation\">Targ. Y. Lev. XXVI, 31</span>.</div><div class=\"sense\"><b>Ithpa. אִשְׁתַּעֲמֵם</b> <div class=\"sense\"><i>to be stupefied</i>. <span class=\"citation\">Targ. Esth. VII, 6</span> (h. text <a href=\"#\" data-headword=\"בָּעַת\">נבעת</a>). <span class=\"citation\">Targ. Ps. CXLIII, 4</span> (h. text <span dir=\"rtl\">ישתומם</span>). <span class=\"citation\">Targ. Jer. IV, 9</span> (h. text <span dir=\"rtl\">יתמהו</span>).</div></div>","alt":[]},"31921":{"h":"שַׁעֲמָמוּתָא","r":"U01673","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שַׁעֲמֵם\">preced.</a>) <i>stupefaction</i>. <span class=\"citation\">Targ. O. Deut. XXVIII, 28</span> <span dir=\"rtl\">שְׁעַמְמוּת לבא</span> ed. Berl. (ed. Vien. <span dir=\"rtl\">שַׁעֲמָ׳</span>; Ms. <a href=\"#\" data-headword=\"שַׁעֲמוּמִיתָא\">שַׁעֲמִימ׳</a>; some ed. <a href=\"#\" data-headword=\"מִשְׁעֲמָמוּתָא\">מִשְׁעֲמָמוּת</a>; Y. <a href=\"#\" data-headword=\"שִׁיעֲמוּם\">שִׁיעֲמָמוּת</a>; h. text <a href=\"#\" data-headword=\"תִּמָּהוֹן\">תמהון</a>). <span class=\"citation\">Targ. Zech. XII, 4</span> <a href=\"#\" data-headword=\"שִׁיעוּרָא\">שִׁעֲ׳</a> (h. text <span dir=\"rtl\">שגעון</span>).</div>","alt":[]},"31922":{"h":"שָׁעַן","r":"U01674","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"שאן\">שאן</a>, P. Sm. 401</div><div class=\"sense\"><b>2)</b> <i>to be smooth, be quiet</i>.</div><div class=\"sense\"><b>Nif. נִשְׁעַן</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בָּטַח\">בטח</a>) <i>to rely on, lean, be supported</i>. <span class=\"citation\">Lev. R. s. 36</span> <span dir=\"rtl\">מה גפן זו נִשְׁעֶנֶת … נִשְׁעָנִין בזכות התורה וכ׳</span> as the vine is supported by a reed, so Israel relies on the merit of studying the Law which is written with a reed. Y. Bets. V, 63ᵃ top <span dir=\"rtl\">נשענים בבהמה</span> you may lean against an animal (on the Sabbath or Holy Day, it is not considered work for the animal); <span dir=\"rtl\">מאן דאמר אין נשענין בתש</span> he that says, you dare not lean, has reference to a weak animal; a. e.</div></div>","alt":[]},"31923":{"h":"*שְׁעַן","r":"U01675","html":"<div class=\"sense\"> (Shaf. of <a href=\"#\" data-headword=\"עני\">עני</a>, cmp. Syr. <span dir=\"rtl\">שעננו</span> = ψάλατε, P. Sm. 4255) <i>to shout, sing</i>. <span class=\"citation\">Targ. Is. LV, 12</span> <span dir=\"rtl\">ישענון בענפיהון</span> (h. text <span dir=\"rtl\">ימחאו כף</span>).</div>","alt":[]},"31924":{"h":"שָׁעַע","r":"U01676","html":"<div class=\"sense\"><i>to smooth, paste</i>.</div><div class=\"sense\"><b>Pilp. שִׁעֲשֵׁעַ</b> <div class=\"sense\"><b>1)</b> <i>to smooth, paste over</i>. Y. Kil. I, 27ᵃ top <span dir=\"rtl\">מְשׁעֲשֶׁעֶת את הלב</span>, v. <a href=\"#\" data-headword=\"שְׁעוּעִית\">שְׁעוּעִית</a>.</div><div class=\"sense\"><b>—2)</b> <i>to appease, console</i>. Pesik. Naḥămu, p. 126ᵇ <span dir=\"rtl\">ומְשַׁעְשְׁעָהּ בזו</span>, v. <a href=\"#\" data-headword=\"פִּיד\">פִּיד</a>; ib. <span dir=\"rtl\">ושִׁיעְשְׁעָהּ במצרים</span> consoled her (Assyria) with Egypt; ib. <span dir=\"rtl\">ושיעשעה באשור</span> (not <span dir=\"rtl\">לאשור</span>); <span class=\"citation\">Yalk. Job 918</span>; <span class=\"citation\">Pesik. R. s. 33</span> <span dir=\"rtl\">ואם הביא עליהם שבר הוא מְשַׁעֲשֵׁעַ וכ׳</span> when he brings misfortune upon them, he consoles them one with the other.</div></div><div class=\"sense\"><b>Hithpa. הִשְׁתַּעֲשֵׁעַ</b> </div><div class=\"sense\"><b>Nithpa. נִשְׁתַּעְשֵׁעַ</b> <div class=\"sense\"><b>1)</b> <i>to be appeased, enjoy one’s self</i>. <span class=\"citation\">Ex. R. s. 5</span> (ref. to <span dir=\"rtl\">ישעו</span>, <span class=\"citation\">Ex. V, 9</span>) <span dir=\"rtl\">שהיו בידן … מִשְׁתַּעְשְׁעִין בהן וכ׳</span> they had scrolls with them, in reading which they consoled themselves from Sabbath to Sabbath; <span dir=\"rtl\">אל יהו משתעשעין וכ׳</span> they shall not enjoy themselves, and they shall not rest on the Sabbath; Tanḥ. Vaëra 6; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be a pleasure</i>. Tanḥ. T’tsavveh 1 (ref. to <span class=\"citation\">Jer. XXXI, 19</span>) <span dir=\"rtl\">מהו ילד שעשועים … ומִשְׁתַּעְשֵׁעַ לאביו</span> what is ‘a child of delight’? Three or four years old, when it begins to talk and becomes a pleasure to his father.</div></div>","alt":[]},"31925":{"h":"שְׁעַע","r":"U01677","html":"<div class=\"sense\"><b>1)</b> <i>to smooth, paste over, daub</i>. <span class=\"citation\">Targ. Ez. XIII, 10</span>, sq. <span class=\"citation\">Ib. 12</span> <span dir=\"rtl\">שַׁעְתּוּן</span> (some ed. <span dir=\"rtl\">שַׁעִיתוּן</span>, <i>Pa.</i> of <a href=\"#\" data-headword=\"שְׁעֵי\">שְׁעֵי</a>). <span class=\"citation\">Ib. XXII, 28</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to make smooth, flatter</i>. <span class=\"citation\">Targ. Ps. XXXVI, 3</span>.</div><div class=\"sense\"><b>—3)</b>  (of skin) <i>to be smooth, bright</i>. <span class=\"citation\">Targ. Lam. IV, 7</span> (h. text <span dir=\"rtl\">צחו</span>).</div><div class=\"sense\"><b>Pa. שַׁעֵעַ</b> <div class=\"sense\"><i>to smooth</i>. <span class=\"citation\">Targ. Ps. V, 10</span> (v. <a href=\"#\" data-headword=\"שְׁעֵי\">שְׁעֵי</a>).</div></div><div class=\"sense\"><b>Ithpa. אִתָּשַׁע</b> <div class=\"sense\"><i>to be pasted, daubed</i>, v. <a href=\"#\" data-headword=\"שׁוּעַ\">שׁוּעַ</a> ch.</div></div>","alt":["שְׁעִיעַ"]},"31926":{"h":"שְׁעַף","r":"U01678","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"שַׁעֲוָא\">שַׁעֲוָא</a>) <i>a gum</i> used as a spice, <i>tragacanth</i>. <span class=\"citation\">Targ. O. Gen. XXXVII, 25</span>; <span class=\"citation\">XLIII, 11</span> (h. text <span dir=\"rtl\">נכאת</span>).</div>","alt":[]},"31927":{"h":"שָׁעַר I","r":"U01679","html":"<div class=\"sense\"><i>to keep the gate</i>.—V. <a href=\"#\" data-headword=\"שׁוֹעֵר\">שׁוֹעֵר</a>.</div><div class=\"sense\"><b>Pi. שִׁיעֵר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"שְׁעַף\">same</a>. <span class=\"citation\">Arakh. 11ᵇ</span> <span dir=\"rtl\">משורר ששי׳ בשל חבירו</span> a Levite chorister that helped in attending to the gate in his neighbor’s stead.—Part. <span dir=\"rtl\">מְשׁוֹעֵר</span>; pl. <span dir=\"rtl\">מְשׁוֹעֲרִים</span> (formed by analogy to <a href=\"#\" data-headword=\"מְשֹׁורֵר\">מְשׁוֹרֵר</a>, v. <a href=\"#\" data-headword=\"שִׁיר I\"><span dir=\"rtl\">שִׁיר</span> I</a>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מש׳ ששורר</span>, v. <a href=\"#\" data-headword=\"שִׁיר I\"><span dir=\"rtl\">שִׁיר</span> I</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ולא מן המש׳</span> (<span class=\"citation\">Sifré Num. 116</span>; <span class=\"citation\">Yalk. ib. 752</span> <span dir=\"rtl\">השׁוֹעֲרִים</span>), v. <a href=\"#\" data-headword=\"שִׁיר I\"><span dir=\"rtl\">שִׁיר</span> I</a>.</div></div>","alt":[]},"31928":{"h":"שָׁעַר II","r":"U01680","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"שַׁעַר\">שַׁעַר</a>) <i>to divide, distribute</i>. [<span class=\"citation\">Midr. Till. to Ps. XIV</span> <span dir=\"rtl\">שיערו</span>, v. infra.]</div><div class=\"sense\"><b>Pi. שִׁיעֵר  שִׁעֵר</b> <div class=\"sense\"><b>1)</b> <i>to apportion, estimate, measure, calculate</i>. <span class=\"citation\">Ḥull. VII, 4</span> <span dir=\"rtl\">כיצד מְשׁעֲרִין אותה וכ׳</span> how do we define the proportions of the mixture (to find out whether the forbidden admixture is large enough to impart its taste to the permitted portion)? As if it were an admixture of meat in a vegetable dish. <span class=\"citation\">Ib. 97ᵇ</span> <span dir=\"rtl\">כשהן משערין משערין וכ׳</span> when we define the proportions, we include in the calculation the broth &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל איסורין … מְשַׁעֲרִינָן וכ׳</span> in all admixtures of Biblically forbidden matter we assume for calculation that the forbidden matter was onions or porret. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שִׁיעֲרוּ חכמים וכ׳</span> the scholars have calculated that of all forbidden substances none give a stronger taste than onions &amp;c. <span class=\"citation\">Lev. R. s. 37</span> <span dir=\"rtl\">מְשָׁעֵר את … באיטלקית</span> (some ed. <a href=\"#\" data-headword=\"מְשָׁעֵר\">מְשָׁעֵיר</a>) do you estimate that in all I drank at my meal there would have been a quarter of a Log of Italian (unmixed) wine? <span class=\"citation\">Koh. R. to V, 8</span> <span dir=\"rtl\">שיערו אותה</span>, v. <a href=\"#\" data-headword=\"שְׁעַר\">next w.</a>; a. fr.—<span class=\"citation\">Midr. Till. to Ps. CXIV</span> (expl. <span dir=\"rtl\">סֹלּוּ</span>, <span class=\"citation\">Ps. LXVIII, 5</span>) <span dir=\"rtl\">שַׁעֲרוּ לפניו דרכיכם</span> (not <span dir=\"rtl\">שיע׳</span>; ed. Bub. <span dir=\"rtl\">שפרו</span>, a glossator’s emendation) measure your ways before the Lord (cmp. <a href=\"#\" data-headword=\"שׁוּם I\"><span dir=\"rtl\">שׁוּם</span> I</a>). Pesik. Zutr. Haaz. (ed. Bub. p. 114) (ref. to <span dir=\"rtl\">שערום</span>, <span class=\"citation\">Deut. XXXII, 17</span>) <span dir=\"rtl\">לא שִׁיעֲרוּם וכ׳</span> whom your fathers never appraised, to find out whether or not they are of use; <span class=\"citation\">Yalk. Deut. 545</span> <span dir=\"rtl\">לא שערום</span>.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"שַׁעַר\">שַׁעַר</a>) <i>to superintend the market</i>, v. <a href=\"#\" data-headword=\"מְשָׁעֵר\">מְשָׁעֵר</a>.</div></div><div class=\"sense\"><b>Hithpa. הִשְׁתַּעֵר</b> <div class=\"sense\"><i>to be estimated, measured</i>. <span class=\"citation\">Ukts. II, 8</span> <span dir=\"rtl\">מִשְׁתַּעֲרִין בכמות שהן</span> are measured as they are (not compressed); <span dir=\"rtl\">מִשְׁתַּעֶרֶת בכמות שהיא</span> is measured as it is.</div></div>","alt":[]},"31929":{"h":"שְׁעַר","r":"U01681","html":"<div class=\"sense\"><i>Pa.</i> <a href=\"#\" data-headword=\"שְׁעֵי\">שַׁעֵיר</a> same, <i>to measure, calculate</i>. <span class=\"citation\">Targ. O. Gen. XXVI, 12</span> <span dir=\"rtl\">בדשַׁעֲרוּהִי</span> ed. Berl. (oth. ed. <span dir=\"rtl\">בדשַׁעֲרוֹהִי</span>; Y. <span dir=\"rtl\">בדשַׁעֲרוֹי</span>; h. text <a href=\"#\" data-headword=\"שְׁעָרִים\">שערים</a>).—<span class=\"citation\">Ḥull. 97ᵇ</span> <span dir=\"rtl\">ולִישַׁעֲרִינְהוּ בפלפלין וכ׳</span> why not use as a standard (for calculation in the case of admixtures of forbidden substances) pepper or spices which are not neutralized in a mass of a thousand times their quantity? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בדידיה מְשַׁעֲרִינָן או בדנפיק מיניה משערינן</span> do we calculate the proportions by the actual size of the admixture, or by the quantity that has come out of it (has been absorbed in the dish)? Y. Kil. IX, 32ᵈ top <span dir=\"rtl\">שַׁעֲרוּנָהּ רבנין וכ׳</span> the Rabbis made the calculation, and it (the well of Miriam) was exactly opposite the middle gate &amp;c.; <span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">שערותא</span> (corr. acc.); <span class=\"citation\">Koh. R. to V, 8</span> <span dir=\"rtl\">שיערו אותה וכ׳</span> (Hebr.).</div>","alt":[]},"31930":{"h":"שָׂעַר","r":"U01682","html":"<div class=\"sense\"><i>to be rough</i>, denom. <a href=\"#\" data-headword=\"שֵׂעָר\">שֵׂעָר</a>; <i>to shudder, fear</i>. <span class=\"citation\">Sifré Deut. 318</span> (expl. <span dir=\"rtl\">שערום</span>, <span class=\"citation\">Deut. XXXII, 17</span>) <span dir=\"rtl\">שלא עמדה שערת וכ׳</span> your fathers’ hair did not stand on end before them (v. <a href=\"#\" data-headword=\"שָׁעַר II\"><span dir=\"rtl\">שָׁעַר</span> II</a>); Yalk. ib. 545.</div><div class=\"sense\"><b>Hif. הִשְׂעִיר</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שֵׂעָר\">שֵׂעָר</a>) <i>to grow hair, be hairy</i>. <span class=\"citation\">Ḥull. 44ᵃ</span> עד מקום שיַשְׂעִיר Ms. M. a Rashi (ed. <span dir=\"rtl\">כדי</span>, corr. acc.) to the place (of the stomach) where it becomes covered with hair. <span class=\"citation\">Ib.</span> (Chald. diction) <span dir=\"rtl\">תורא דמַשְׂעִיר טפי</span> an ox, which is more hairy (on the stomach). <span class=\"citation\">Nidd. 25ᵇ</span> <span dir=\"rtl\">עד שישעיר</span> until the embryo has hair.</div></div>","alt":[]},"31931":{"h":"שְׂעַר","r":"U01683","html":"<div class=\"sense\">, <i>Af.</i> <span dir=\"rtl\">אַשְׂעִיר</span>, v. <a href=\"#\" data-headword=\"שָׂעַר\">preced.</a></div>","alt":[]},"31932":{"h":"שֵׂעָר","r":"U01684","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שְׂעַר\">preced.</a>) <i>hair</i>. <span class=\"citation\">Meg. 18ᵃ</span>, a. e. <span dir=\"rtl\">מסלסל בשׂעַרְךָ</span>, v. <a href=\"#\" data-headword=\"סִלְסֵל\">סִלְסֵל</a>. <span class=\"citation\">Naz. I, 2</span> <span dir=\"rtl\">הכביד שַׂעֲרוֹ</span>, v. <a href=\"#\" data-headword=\"כָּבֵד I\"><span dir=\"rtl\">כָּבֵד</span> I</a>. <span class=\"citation\">Ib. 4ᵇ</span> <span dir=\"rtl\">לשחת ש׳ וכ׳</span> to ruin such fine hair; <span class=\"citation\">Tosef. ib. IV, 7</span>. <span class=\"citation\">Yoma 47ᵃ</span> <span dir=\"rtl\">קלעי שַׂעֲרִי</span>, v. <a href=\"#\" data-headword=\"קֶלַע II\"><span dir=\"rtl\">קֶלַע</span> II</a>; a. fr.—Trnsf. <i>crown, ramification</i> of a tree; <i>panicle, stem and pod</i> of leguminous plants. <span class=\"citation\">Peah II, 3</span>, a. e. <span dir=\"rtl\">ש׳ כותש</span>, v. <a href=\"#\" data-headword=\"כָּתַשׁ\">כָּתַשׁ</a>; Y. ib. 17ᵃ top <a href=\"#\" data-headword=\"סֵעָר\">סֵעָר</a>. <span class=\"citation\">Kil. IV, 9</span> <span dir=\"rtl\">היה הופך ש׳ שתי וכ׳</span> he turned the branches of two rows of vines towards one side; <span class=\"citation\">B. Bath. 82ᵇ</span>. <span class=\"citation\">Sabb. XXI, 3</span> <span dir=\"rtl\">ש׳ של אפונין וש׳ וכ׳</span> the panicles (pods) of beans and of lentils. <span class=\"citation\">Tosef. Ukts. I, 8</span> <a href=\"#\" data-headword=\"סֵיאָר\">סֵיאָר</a> ed. Zuck. (Var. <span dir=\"rtl\">שיע</span>, read as ed. <span class=\"citation\">T’bul Yom III</span>: <span dir=\"rtl\">שיער</span>) the panicle of a pomegranate; a. fr.—Pl., v. <a href=\"#\" data-headword=\"שַׂעֲרָה\">שַׂעֲרָה</a></div>","alt":["שֵׂי׳"]},"31933":{"h":"שְׂעַר ²","r":"U01685","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"שַׂעֲרָא\">שַׂעֲרָא</a></div>","alt":["שֵׂעָר"]},"31934":{"h":"שַׁעַר","r":"U01686","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> שער <i>to divide, break open</i>) </div><div class=\"sense\"><b>1)</b> <i>gate, open place</i> for public and private transactions. <span class=\"citation\">Sifré Deut. 242</span> (ref. to <span class=\"citation\">Deut. XXII, 24</span> <span dir=\"rtl\">ש׳ שנמצאת בו וכ׳</span> the gate (of the place) where she was found, and not the gate where she was judged. <span class=\"citation\">Keth. 45ᵇ</span> (ref. to <span class=\"citation\">Deut. XVII, 5</span>) <span dir=\"rtl\">ש׳ שעבד בו</span> the gate (of the place) where he worshipped the idol. <span class=\"citation\">Midd. I, 3</span> <span dir=\"rtl\">ש׳ המזרחי</span> the eastern Temple gate; a. v. fr.—Pl. <a href=\"#\" data-headword=\"שְׁעָרִים\">שְׁעָרִים</a>, <a href=\"#\" data-headword=\"שְׂעָרֵי\">שְׁעָרִין</a>; constr. <a href=\"#\" data-headword=\"שְׂעָרֵי\">שַׁעֲרֵי</a>. Ib. <span dir=\"rtl\">חמשה ש׳ היו וכ׳</span> the Temple mount had five gates; <span dir=\"rtl\">שני ש׳ חולדה</span> two <i>ḥuldah</i> gates, v. <a href=\"#\" data-headword=\"חוּלְדָּה II\"><span dir=\"rtl\">חוּלְדָּה</span> II</a>. Ib. 4; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>market, market price</i>. <span class=\"citation\">B. Mets. V, 7</span> <span dir=\"rtl\">שיצא הש׳</span>, v. <a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>. Ib. (72ᵇ) <span dir=\"rtl\">כש׳ הגבוה</span> (Bab. ed. <a href=\"#\" data-headword=\"בֹּוסַם\">בש׳</a>) according to the price at the height of the market, i.e. the lowest price. Ib. 8 <span dir=\"rtl\">כש׳ הזול</span> according to the lowest market price. Ib. 1 <span dir=\"rtl\">לקח … וכן הש׳</span> if he bought wheat of him, at a gold Denar a Kor, and such was the market price. <span class=\"citation\">Gitt. 57ᵃ</span> <span dir=\"rtl\">נחסר הש׳ מודיא אחת</span> the price went down one Modius, i.e. from forty Modii to thirty-nine for a Denar; <span dir=\"rtl\">וחזר הש׳ למקומו</span> the price went back to its former figure; a. fr.—<i>Pl.</i> as ab. <span class=\"citation\">B. Bath. 89ᵃ</span> <a href=\"#\" data-headword=\"לִישָׁן\">לש׳</a> for the regulation of market prices, v. <a href=\"#\" data-headword=\"אֲגַרְדְּמִיס\">אֲגַרְדְּמִיס</a>; Y. ib. V, end, 15ᵇ <span dir=\"rtl\">שִׁיעוּרִין</span>, a. <span dir=\"rtl\">שִׁיעוּרַיָּיא</span>.</div>","alt":[]},"31935":{"h":"שַׁעַר II","r":"U01687","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>estimation, proportion.</i> <i>—</i> Pl. <a href=\"#\" data-headword=\"שְׁעָרִים\">שְׁעָרִים</a>. <span class=\"citation\">Gen. R. s. 64</span> (ref. to <span class=\"citation\">Gen. XXVI, 12</span>) <span dir=\"rtl\">מאה כורים מאה ש׳ מאה מניינים מאה ש׳ וכ׳</span> one hundred Kor; one hundred proportions, one hundred quantities; one hundred <i>sh’ʿarim</i>, this shows that they had made an estimate of it (the crop of the field), and it brought a hundred times the estimated quantity; Yalk. ib. 111 (corr. acc.); <span class=\"citation\">Pirké d’R. El. ch. XXXIII</span> <span dir=\"rtl\">וכל דבר … מאה ש׳ של ממון וכ׳</span> and for every thing that he gave tithes of, the Lord sent him one hundred times the value, and he blessed him.</div>","alt":[]},"31936":{"h":"שַׁעֲרָא I","r":"U01688","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"שַׁעַר II\">same</a>, esp. <i>percent.</i> <i>, interest</i>. <span class=\"citation\">Targ. Y. Ex. XXII, 24</span> (h. text <span dir=\"rtl\">נשך</span>). <span class=\"citation\">Targ. Y. I Lev. XXV, 36</span>, sq. (ed. Vien. <a href=\"#\" data-headword=\"שְׂעָרֵי\">שַׁעַרְיָן</a>, corr. acc.); Y. II <a href=\"#\" data-headword=\"שְׂעוֹרִין\">שִׁעוּרִין</a>.</div>","alt":[]},"31937":{"h":"שַׁעֲרָא II","r":"U01689","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שָׁעַר I\"><span dir=\"rtl\">שַׁעַר</span> I</a>, 2, <i>market price</i>. Ruth R. introd. <span dir=\"rtl\">שַׁעֲרֵיהוֹן דפוריא</span>, v. <a href=\"#\" data-headword=\"פּוֹרָא\">פּוֹרָא</a>.</div>","alt":[]},"31938":{"h":"שַׂעֲרָא","r":"U01690","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שָׁעַר I\">שׂעָר</a>, <i>hair</i>. <span class=\"citation\">Targ. Gen. XXV, 25</span>, v. <a href=\"#\" data-headword=\"סְעָר\">סְעָר</a>. <span class=\"citation\">Targ. Lev. XIII, 3</span>; a. fr.—<span class=\"citation\">Lev. R. s. 15</span>, v. <a href=\"#\" data-headword=\"שִׁטְפָא\">שִׁטְפָא</a>; <span class=\"citation\">Yalk. ib. 554</span> <a href=\"#\" data-headword=\"שַׂעֲרָה\">שַׂעֲרָה</a>. Midr. Sam. ch. II (v. <a href=\"#\" data-headword=\"מוֹרָא I\">מוֹרָא</a> I a. <a href=\"#\" data-headword=\"מוֹרָה II\"><span dir=\"rtl\">מוֹרָה</span> II</a>) <span dir=\"rtl\">מה הדין סירא … אף הדין ש׳ וכ׳</span> as the thorn is afraid of nothing but the iron, so is the hair &amp;c.; <span class=\"citation\">Yalk. Sam. 78</span> (corr. acc.); <span class=\"citation\">Y. Naz. IX, end, 58ᵃ</span> <span dir=\"rtl\">ביזרא … סַעֲרָה</span>; a. e.—Pl. <a href=\"#\" data-headword=\"שַׂעֲרָן\">שַׂעֲרָן</a> (fem.). <span class=\"citation\">Targ. Ps. LXIX, 5</span> Levita (ed. <a href=\"#\" data-headword=\"סַעֲרָן\">סַעֲרָן</a>, <a href=\"#\" data-headword=\"סְעָרַיָּא\">סַעֲרִין</a>).</div>","alt":["שַׂעְרָא","שְׂעַר","שֵׂעָר"]},"31939":{"h":"שַׂעֲרָה","r":"U01691","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שַׂעֲרָא\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>hair</i>. <span class=\"citation\">Y. Sot. I, 16ᶜ</span> top <span dir=\"rtl\">ש׳ אחת</span> one hair; a. e.—Pl. <span dir=\"rtl\">שׂעֲרוֹת</span>. Ib., a. fr. <span dir=\"rtl\">שתי ש׳</span> (not <a href=\"#\" data-headword=\"שני\">שני</a>) two hairs (symptom of maturity). <span class=\"citation\">Lev. R. s. 20</span> <span dir=\"rtl\">מעולם לא ראו … ש׳ ראשי</span> the beams of my house never saw the hair of my head (v. <a href=\"#\" data-headword=\"קֶלַע II\"><span dir=\"rtl\">קֶלַע</span> II</a>); <span class=\"citation\">Y. Yoma I, 38ᵈ</span> top; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>ear, panicle</i>. <span class=\"citation\">Y. Ter. I, 40ᵈ</span> top <span dir=\"rtl\">ש׳ של אורז</span> (ed. Krot. <a href=\"#\" data-headword=\"שְׂעוֹרָה\">שְׂעוֹרָה</a>) the panicles of rice.</div>","alt":[]},"31940":{"h":"שְׂעָרֵי","r":"U01692","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>barley</i>, v. <a href=\"#\" data-headword=\"סְעַרְתָּא\">סְעַרְתָּא</a>.</div>","alt":["שַׂעֲרִין"]},"31941":{"h":"שְׁעָרִים","r":"U01693","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Beth-Sh’ʿarim</i>, near Sepphoris (v. Neub. Géogr. p. 200), one of the seats of the Sanhedrin. <span class=\"citation\">R. Hash. 31ᵇ</span>. Sanh. 32ᵇ <span dir=\"rtl\">אחר רבי לב׳ ש׳</span> follow up Rabbi to B. Sh. <span class=\"citation\">Tosef. Ter. VII, 14</span>; <span class=\"citation\">Tosef. Succ. II, 2</span> (the seat of R. Johanan ben Nuri). <span class=\"citation\">Tosef. Par. V</span> (<span class=\"citation\">IV), 6</span>; a. e.</div>","alt":["בֵּית שְׁ׳"]},"31942":{"h":"שַׂעֲרָן","r":"U01694","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַעֲרָן\">סַעֲרָן</a></div>","alt":["שַׂעֲרַנְיָין"]},"31943":{"h":"שַׁעֲשׁוּעַ","r":"U01695","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>delight, pleasure</i>. <span class=\"citation\">Cant. R. to VI, 11</span>, v. <a href=\"#\" data-headword=\"שְׂחוֹק\">שְׂחוֹק</a>; (<span class=\"citation\">Pesik. R. s. 11</span> <a href=\"#\" data-headword=\"תַּענוּג\">תענוג</a>).—Pl. <a href=\"#\" data-headword=\"שַׁעֲשׁוּעִית\">שַׁעֲשׁוּעִים</a>. Tanḥ. T’tsavveh 1; <span class=\"citation\">Yalk. Jer. 315</span> <span dir=\"rtl\">ילד של ש׳</span> a child of delight, v. <a href=\"#\" data-headword=\"שָׁעַע\">שָׁעַע</a>.—Trnsf. (sub. <span dir=\"rtl\">ילד</span>, <span dir=\"rtl\">ילדי</span>) <i>beloved child</i> or <i>children</i>. <span class=\"citation\">M. Kat. 25ᵇ</span> (in a eulogy) <span dir=\"rtl\">ארץ … גידלה שַׁעֲשׁוּעֶיהָ</span> the land of Shinear (Babylonia) conceived and gave birth to, the land of beauty (Palestine) raised her beloved child.</div>","alt":[]},"31944":{"h":"שַׁעֲשׁוּעִית","r":"U01696","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁעוּעִית\">שְׁעוּעִית</a></div>","alt":[]},"31945":{"h":"שַׁעֲשִׁיעֲתָא","r":"U01697","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"שְׁעִיעוּתָא\">שְׁעִיעוּתָא</a>, <i>smoothness</i>. <span class=\"citation\">Targ. Y. II, Gen. XXXIII, 4</span>.</div>","alt":[]},"31946":{"h":"שִׁעֲשֵׁעַ","r":"U01698","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁעַע\">שָׁעַע</a>, <a href=\"#\" data-headword=\"שְׁעַע\"><a href=\"#\" data-headword=\"שְׁעַע\">שְׁעַע</a>.</a></div>","alt":["שַׁעְשַׁע"]},"31947":{"h":"שַׁעְתָּא","r":"U01699","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שָׁעָה\">שָׁעָה</a>, <i>while, time; hour</i>. <span class=\"citation\">Targ. II Kings V, 26</span> (ed. Wil. <span dir=\"rtl\">שעה</span>). <span class=\"citation\">Targ. Ex. XXXIII, 5</span>. <span class=\"citation\">Targ. Y. ib. XXIII, 5</span>; a. fr.—<span class=\"citation\">Ber. 64ᵃ</span> <span dir=\"rtl\">אצטריכא להו ש׳</span> the time needed them (circumstances required one of them as chief of the college); <span class=\"citation\">Bekh. 31ᵃ</span>, v. <a href=\"#\" data-headword=\"צָרַךְ\">צְרֵךְ</a>. <span class=\"citation\">Y. Bets. II, 61ᶜ</span> top, a. e. <span dir=\"rtl\">בשַׁעְתָּהּ</span> in its proper time, v. <a href=\"#\" data-headword=\"גּוּמְרָא\">גּוּמְרָא</a>. <span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">כי … ש׳ אלטייה</span> when that moment comes, I will curse him; <span dir=\"rtl\">כי … ש׳ ניים</span> when that moment came, he was asleep. Ib. <span dir=\"rtl\">כל ש׳ וש׳</span> at all times. Ib. <span dir=\"rtl\">כל ש׳</span> any other time; <span dir=\"rtl\">בההיא ש׳</span> but at that special time; <span class=\"citation\">Ab. Zar. 4ᵇ</span>. <span class=\"citation\">Pes. 11ᵇ</span> <span dir=\"rtl\">פלגא דש׳</span> half an hour; a. fr.—Pl. <span dir=\"rtl\">שָׁעַיָּא</span>, <span dir=\"rtl\">שָׁעִין</span>, <a href=\"#\" data-headword=\"שְׁעֵי\">שָׁעֵי</a>; <a href=\"#\" data-headword=\"שַׁעְתָּא\">(שָׁעָתָא</a>). <span class=\"citation\">Targ. II Kings XX, 11</span>. <span class=\"citation\">Targ. Job VII, 18</span> (not <a href=\"#\" data-headword=\"שַׁעְתָּא\">שָׁעֲתָא</a>); a. fr.—Ber. l. c.; Ab. Zar. l. c. <span dir=\"rtl\">בהנך תלת ש׳ וכ׳</span> during those first three hours (of the day) &amp;c.; a. fr.</div>","alt":["שַׁעֲתָא","שָׁעָא","(שָׁעָה)"]},"31948":{"h":"שָׁף","r":"U01700","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שׁוּף\">שׁוּף</a>.—<span dir=\"rtl\"><a href=\"#\" data-headword=\"יתֵב\">יתיב</a>(<a href=\"#\" data-headword=\"ו\">ו</a>) <span dir=\"rtl\">שף</span></span>, v. <a href=\"#\" data-headword=\"שׁוּף\">שׁוּף</a> I ch.</div>","alt":[]},"31949":{"h":"שַׁף","r":"U01701","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁפַף\">שְׁפַף</a></div>","alt":[]},"31950":{"h":"שָׁפָא","r":"U01702","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שפי\">שפי</a></div>","alt":["שְׁפָא"]},"31951":{"h":"שָׁפָא ²","r":"U01703","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (שׁוּף I) [<i>slip, the place from which something slipped,</i>] <i>socket</i>. <span class=\"citation\">Macc. 11ᵇ</span> <span dir=\"rtl\">עאל איבריה לש׳</span> each limb (bone) of his went into its socket; <span class=\"citation\">Yalk. Gen. 149</span>.</div>","alt":[]},"31952":{"h":"שִׁפָּא I","r":"U01704","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"שִׁפָּא\">next w.</a>) <i>block of hewn stone</i>, v. <a href=\"#\" data-headword=\"סִפָּא\">סִפָּא</a>.</div>","alt":[]},"31953":{"h":"שִׁפָּא","r":"U01705","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁפַף\">שְׁפַף</a>) <i>chip, pin</i>. Targ. <span class=\"citation\">Hab. II, 11</span> (h. text <a href=\"#\" data-headword=\"כָּפִיס\">כפיס</a>).</div>","alt":["שִׁי׳"]},"31954":{"h":"שְׁפָאִים","r":"U01706","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (שָׁפָה I) <a href=\"#\" data-headword=\"שִׁפָּא\">same</a>, <i>chips</i>. <span class=\"citation\">Ab. Zar. 49ᵇ</span> <span dir=\"rtl\">אותן ש׳ מה וכ׳</span> what is the law about those chips? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שְׁפָאֶיהָ</span> (Ms. M. <span dir=\"rtl\">שִׁיפּוּיֶיהָ</span>, v. <a href=\"#\" data-headword=\"שִׁיפּוּי ²\"><span dir=\"rtl\">שִׁיפּוּי</span> I</a>).—Trnsf. <span dir=\"rtl\">שְׁפָאֵי עידית</span> (cmp. <a href=\"#\" data-headword=\"בִּיזְלֵי\">בִּיזְלֵי</a>) <i>disconnected strips</i> of a first class field. <span class=\"citation\">Gitt. 50ᵃ</span> (v. Tosaf. a. l.); [Rashi takes <span dir=\"rtl\">שפאי</span> as verb, fr. <a href=\"#\" data-headword=\"שפי\">שפי</a> = <a href=\"#\" data-headword=\"שׁוּף\">שׁוּף</a> <i>to slip</i>].</div>","alt":["שְׁפָאִין"]},"31955":{"h":"שַׁפַּאי","r":"U01707","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁפַּיי\">שַׁפַּיי</a></div>","alt":[]},"31956":{"h":"שָׁפַד","r":"U01708","html":"<div class=\"sense\"><i>to chip, point</i>.—Denom. <a href=\"#\" data-headword=\"שְׁפוּד\">שְׁפוּד</a>.</div><div class=\"sense\"><b>Pi. שִׁפֵּד</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שְׁפוּד\">שְׁפוּד</a>) <i>to pierce</i>. <span class=\"citation\">Snh. 41ᵃ</span> <span dir=\"rtl\">שִׁפְּדוֹ בייחור וכ׳</span> (or <span dir=\"rtl\">שְׁפָדוֹ</span>) he pierced him with the shoot of a fig tree.</div></div>","alt":[]},"31957":{"h":"שְׁפַד","r":"U01709","html":"<div class=\"sense\"><b>1)</b> <i>to point</i>.—Part. pass. <span dir=\"rtl\">שָׁפִיד</span>. <span class=\"citation\">Bekh. 40ᵃ</span>, v. <a href=\"#\" data-headword=\"פְּרַס I\"><span dir=\"rtl\">פְּרַס</span> I</a>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"שַׁפּוּדָא\">שפודא</a>) <i>to put on the spit, roast</i>. <span class=\"citation\">Ḥull. 111ᵃ</span> sq. <span dir=\"rtl\">חזייה … דקא שָׁפֵיד וכ׳</span> he saw the son of R. b. A. put a liver on the spit over a piece of meat. <span class=\"citation\">Pes. 74ᵇ</span> <span dir=\"rtl\">שַׁפְדֵּיה בשפודא</span> (or <span dir=\"rtl\">שַׁפְּדֵיה</span> <i>Pa.</i>) if he put it on the spit (and roasted it).</div>","alt":[]},"31958":{"h":"שִׁפָּה","r":"U01710","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִפָּא\">סִפָּא</a></div>","alt":[]},"31959":{"h":"שָׂפָה","r":"U01711","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"סְפָי\">סְפָי</a>) </div><div class=\"sense\"><b>1)</b> <i>rim, border, binding</i>. <span class=\"citation\">B. Bath. II, 1</span> <span dir=\"rtl\">ארבעה מן הש׳</span> four handbreadths from the rim of the stove. <span class=\"citation\">Ib. 19ᵃ</span> <span dir=\"rtl\">שְׂפַת מחמצן</span> the border of the wash-pit; a. fr.—<span dir=\"rtl\">קמי ש׳</span>, <span dir=\"rtl\">קנה ש׳</span>, v. <a href=\"#\" data-headword=\"קָמָה\">קָמָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>lip; speech</i>. <span class=\"citation\">Y. Sabb. VII, 10ᶜ</span> top <span dir=\"rtl\">המאדם אודם בש׳</span> he who reddens his lips (v. <a href=\"#\" data-headword=\"אָדַם\">אָדַם</a>; Naḥmanides reads: <span dir=\"rtl\">בטפה</span>). Ib. XIV, 14ᵈ top <span dir=\"rtl\">כל שהוא מן הש׳ ולפנים</span> any wound on the lip and further inside (in the mouth, opp. <a href=\"#\" data-headword=\"חָלָל III\"><span dir=\"rtl\">חָלָל</span> III</a>). Y. Macc. II, end, 32ᵃ, a. fr. <span dir=\"rtl\">בש׳ רפה</span> with lax lips, with low indistinct speech; a. fr.—Pl. <a href=\"#\" data-headword=\"שְׂפָתוֹת\">שְׂפָתוֹת</a>, <span dir=\"rtl\"><a href=\"#\" data-headword=\"שִׁפְיוּת\">שְׂפָיוֹת</a> (סְפָי</span>); <i>Du.</i> <a href=\"#\" data-headword=\"שְׂפָתוֹת\">שְׂפָתַיִם</a>. <span class=\"citation\">Tosef. Kel. B. Kam. VI, 15</span> <span dir=\"rtl\">שְׂפָתָיו</span>, v. <a href=\"#\" data-headword=\"שָׁפַע\">שָׁפַע</a>. <span class=\"citation\">M. Kat. 15ᵃ</span> (expl. <span dir=\"rtl\">ועל שפם וכ׳</span>, <span class=\"citation\">Lev. XIII, 45</span>) <span dir=\"rtl\">שיהו שִׂפְתוֹתָיו מדובקות וכ׳</span> his lips should cleave to each other (he must not greet or answer greeting). <span class=\"citation\">Koh. R. to XII, 4</span> בנות השיר אלו הש׳ ‘the daughters of song’, that means the lips; <span class=\"citation\">Lev. R. s. 18</span> <span dir=\"rtl\">שִׂפְתוֹתָיו</span>. <span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">שִׂפְתוֹתֵיהֶן וכ׳</span>, v. <a href=\"#\" data-headword=\"רָפַט\">רָפַט</a>. <span class=\"citation\">Ab. Zar. 35ᵃ</span> <span dir=\"rtl\">שִׂפְתוֹתֶיךָ</span>, v. <a href=\"#\" data-headword=\"חָשַׁק\">חָשַׁק</a>. <span class=\"citation\">Keth. 61ᵇ</span> <span dir=\"rtl\">את השפתים</span>, v. <a href=\"#\" data-headword=\"שִׁרְבֵּט\">שִׁרְבֵּט</a>; <span class=\"citation\">Y. Keth. V, 30ᵃ</span> bot. <span dir=\"rtl\">השפיות</span>, v. <a href=\"#\" data-headword=\"שִׁלְבֵּק\">שִׁלְבֵּק</a>; a. fr.—<span class=\"citation\">Y. Yeb. VI, beg. 7ᵇ</span> <span dir=\"rtl\">בין הש׳</span> between the lips (of the vagina).</div>","alt":[]},"31960":{"h":"שָׁפָה","r":"U01712","html":"<div class=\"sense\"> verb, v. <a href=\"#\" data-headword=\"שפי\">שפי</a></div>","alt":[]},"31961":{"h":"שָׁפָה ²","r":"U01713","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (שָׁפָה II) <i>overflow, additional measure</i>; v. <a href=\"#\" data-headword=\"שֶׁפַע\">שֶׁפַע</a>.</div>","alt":[]},"31962":{"h":"שְׁפוּד","r":"U01714","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁפַד\">שָׁפַד</a>) <i>spit</i>. <span class=\"citation\">Pes. VII, 1</span> <span dir=\"rtl\">ש׳ של רימון</span> a spit made of pomegranate wood. <span class=\"citation\">Ib. 74ᵃ</span> <span dir=\"rtl\">ש׳ של מתכת</span> a metal spit. <span class=\"citation\">Y. Naz. VI, 55ᵇ</span> <span dir=\"rtl\">ש׳ אחד של נבילה</span> one spit with forbidden meat. <span class=\"citation\">Bets. 28ᵇ</span>; a. fr.—[<span class=\"citation\">Tosef. Meïl. I, 25</span>, v. <a href=\"#\" data-headword=\"שִׁיפּוּי ²\"><span dir=\"rtl\">שִׁיפּוּי</span> I</a>.]—Pl. <span dir=\"rtl\">שְׁפוּדִין</span>. Y. Naz. l. c.; a. e.</div>","alt":[]},"31963":{"h":"שַׁפּוּדָא","r":"U01715","html":"<div class=\"sense\"> <span class=\"citation\">Pes. 74ᵇ</span> <span dir=\"rtl\">שפדיה בש׳</span>, v. <a href=\"#\" data-headword=\"שְׁפַד\">שְׁפַד</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תלנהו בש׳</span> if he suspended them from the spit; a. e.—Pl. <span dir=\"rtl\">שַׁפּוּדַיָּא</span>. <span class=\"citation\">Targ. Y. Num. XXXI, 23</span> (ed. Vien. <a href=\"#\" data-headword=\"שִׁופּוּט\">שִׁפּ׳</a>).—V. <a href=\"#\" data-headword=\"*שִׁיפּוּדָא\">שִׁיפּוּדָא</a>.</div>","alt":[]},"31964":{"h":"*שַׁפְוָונָא","r":"U01716","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (שְׁפֵי I) <i>crushing, destruction</i>. <span class=\"citation\">Targ. Prov. XXIV, 22</span> Ms. (ed. <a href=\"#\" data-headword=\"סוֹף ²\">סופא</a>; some ed., a. Var. ed. Lag. <a href=\"#\" data-headword=\"סִפְוָון\">ספוותא</a>; h. text <a href=\"#\" data-headword=\"פִּיד\">פיד</a>).</div>","alt":[]},"31965":{"h":"שִׁפּוּט","r":"U01717","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"שִׁופּוּט\">שִׁיפּ׳</a>.</div>","alt":["שִׁפּוּי"]},"31966":{"h":"שָׁפוּי","r":"U01718","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שפי\"><span dir=\"rtl\">שָׁפָה</span> I</a>, III.</div>","alt":[]},"31967":{"h":"שְׁפוּיָיתָא","r":"U01719","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁפִיּוּתָא\">שְׁפִיּוּתָא</a></div>","alt":[]},"31968":{"h":"שָׁפוֹךְ","r":"U01720","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁפַךְ\">שְׁפַךְ</a>) <i>gutter, slope, spout</i>. <span class=\"citation\">Targ. O. Num. XXI, 15</span> <span dir=\"rtl\">שָׁ׳ לנחליא</span> ed. Berl. (oth. ed. <span dir=\"rtl\">שָׁפוּךְ נחל׳</span>, read: <a href=\"#\" data-headword=\"שָׁפוֹךְ\">שְׁפוּךְ</a>; Ms. <a href=\"#\" data-headword=\"שָׁפוֹךְ\">שְׁפוּךְ</a>, <a href=\"#\" data-headword=\"שְׁפִיךְ\">שְׁפִיךְ</a>; h. text <a href=\"#\" data-headword=\"אֲשַׁד\">אשד</a>).—<span class=\"citation\">B. Bath. 3ᵇ</span> Ar. ed. Koh., v. <a href=\"#\" data-headword=\"שָׁפְכָא\">שָׁפְכָא</a>.—V. <a href=\"#\" data-headword=\"שִׁפְכוּתָא\">שִׁפְכוּתָא</a>.</div>","alt":["שְׁפוֹכָא"]},"31969":{"h":"שְׁפוֹכָאָה","r":"U01721","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁפוֹךְ\">preced.</a>) <i>a laborer engaged in pouring wine</i> to fill up vessels.—Pl. <a href=\"#\" data-headword=\"שָׁפוֹךְ\">שְׁפוֹכָאֵי</a>. <span class=\"citation\">Ab. Zar. 72ᵇ</span>.—[<span class=\"citation\">B. Bath. 3ᵇ</span> Ar., v. <a href=\"#\" data-headword=\"שָׁפְכָא\">שָׁפְכָא</a>.]</div>","alt":[]},"31970":{"h":"שִׁפּוּל","r":"U01722","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"שִׁופּוּט\">שִׁיפּ׳</a>.</div>","alt":["שִׁפּוּלָא","שִׁפּוּעַ","שִׁפּוּעָא"]},"31971":{"h":"שפופינא","r":"U01723","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁפִיפוֹנָא\">שְׁפִיפוֹנָא</a></div>","alt":[]},"31972":{"h":"שְׁפוֹפֶרֶת","r":"U01724","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"שְׁפַרְפָּרָא\">שפרפ׳</a>, v. <a href=\"#\" data-headword=\"שֹׁופָר\">שׁוֹפָר</a>) [<i>something round</i>.] <i>tube</i>; <span dir=\"rtl\">ש׳ של ביצה</span> <i>egg-shell</i>. <span class=\"citation\">Nidd. 21ᵇ</span> <span class=\"citation\">Erub. 43ᵇ</span>, v. <a href=\"#\" data-headword=\"מְצוֹפוֹת\">מְצוֹפוֹת</a>. <span class=\"citation\">Lev. R. s. 16</span>, beg. <span dir=\"rtl\">היתה מביאה ש׳ וכ׳</span> she took an egg-shell and filled it with balsam, v. <a href=\"#\" data-headword=\"שַׁלְפּוּחִית\">שַׁלְפּוּחִית</a>. <span class=\"citation\">Ḥull. 57ᵇ</span> <span dir=\"rtl\">עשו לה ש׳ של קנה וכ׳</span> they made for it (the dislocated and detached hip-bone) a tube of reed (to support it), and the hen recovered. <span class=\"citation\">Kel. XVII, 17</span> <span dir=\"rtl\">ש׳ הקש</span> a straw tube. <span class=\"citation\">Snh. 68ᵃ</span>, a. fr. <span dir=\"rtl\">כמכחול בש׳</span>, v. <a href=\"#\" data-headword=\"מַכְחוֹל\">מַכְחוֹל</a>; a. fr.—<span dir=\"rtl\">ש׳ הנוד</span> or <a href=\"#\" data-headword=\"ש׳\">ש׳</a> <i>the tube</i> (mouth-piece) of the leather bottle. <span class=\"citation\">Par. V, 8</span>. <span class=\"citation\">Ib. VI, 1</span>; a. fr.</div>","alt":[]},"31973":{"h":"שִׁפּוּצָא","r":"U01725","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁיפּוּצָא\">שִׁיפּוּצָא</a></div>","alt":[]},"31974":{"h":"שפותה","r":"U01726","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ned. I, 37ᵃ</span> top, read: <a href=\"#\" data-headword=\"שְׁבִיתָה\">שְׁבִיתָה</a>, v. <a href=\"#\" data-headword=\"שְׁבוּתָה\">שְׁבוּתָה</a></div>","alt":[]},"31975":{"h":"שָׂפַח","r":"U01727","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָפַח\">סָפַח</a></div>","alt":[]},"31976":{"h":"שִׁפְחָה","r":"U01728","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"מִשְׁפָּחָה\">מִשְׁפָּחָה</a>) [<i>attached to the household,</i>] <i>handmaid, slave</i>.—<span dir=\"rtl\">ש׳ חרופה</span>, v. <a href=\"#\" data-headword=\"חֲרוּפָה\">חֲרוּפָה</a>.—<span class=\"citation\">Snh. 39ᵃ</span> <span dir=\"rtl\">נטלו … לו ש׳ לשמשו</span> they took a rib from him (Adam), and gave him a handmaid to wait on him. <span class=\"citation\">Ib. 99ᵇ</span> <span dir=\"rtl\">מוטב תהא ש׳ לאומה זו וכ׳</span> better for her to be a handmaid to this nation than a mistress to any other nation. <span class=\"citation\">Kidd. III, 12</span> <span dir=\"rtl\">ולד ש׳ ונכרית</span> the child of a slave or of a gentile woman. <span class=\"citation\">Ib. 13</span> <span dir=\"rtl\">ממזר שנשא ש׳ וכ׳</span> if a bastard married a slave, their child is a slave. <span class=\"citation\">Ib. 69ᵃ</span> <span dir=\"rtl\">האומר לשִׁפְחָתוֹ וכ׳</span> if one says to his bondwoman, be thou free, but thy child (with which thou goest) shall be a slave, the child follows her status (is free). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ש׳ כנענית</span> a Canaanite slave. <span class=\"citation\">Keth. V, 5</span> <span dir=\"rtl\">הכניסה לו ש׳ אחת וכ׳</span> if the wife brought him one slave, she need not grind, or bake &amp;c.; a. v. fr.—Pl. <a href=\"#\" data-headword=\"שִׁפְחוּת\">שְׁפָחוֹת</a>. Ib. <span dir=\"rtl\">אפי׳ … מאה ש׳ וכ׳</span> even if she brought him a hundred slaves, he may force her (his wife) to work in wool &amp;c. <span class=\"citation\">Ker. 9ᵃ</span> <span dir=\"rtl\">ש׳ חרופות</span>, v. <a href=\"#\" data-headword=\"חֲרוּפָה\">חֲרוּפָה</a>. <span class=\"citation\">Lev. R. s. 16</span>, a. e. <span dir=\"rtl\">ש׳ מכודנות</span>, v. <a href=\"#\" data-headword=\"כָּדַן\">כָּדַן</a>. Tanḥ. Vayetsé 8 <span dir=\"rtl\">לא תהא … הש׳</span> should not my sister Rachel be at least like one of the handmaids (Bilhah and Zilpah)? <span class=\"citation\">Ab. II, 7</span>; a. fr.</div>","alt":[]},"31977":{"h":"שִׁפְחוּת","r":"U01729","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שִׁפְחָה\">preced.</a>) <i>status of a handmaid</i>. <span class=\"citation\">Y. Kidd. I, 59ᶜ</span> bot., v. <a href=\"#\" data-headword=\"אִישׁוּת\">אִישׁוּת</a>; Bab. <span class=\"citation\">Kidd. 18ᵇ</span>. <span class=\"citation\">Ib. 19ᵃ</span>; a. e.</div>","alt":[]},"31978":{"h":"שָׁפַט","r":"U01730","html":"<div class=\"sense\"> v. <span dir=\"rtl\">פטט</span>, s. v. <a href=\"#\" data-headword=\"פַּטָּטָא\">פַּטָּטָא</a>) [<i>to divide</i>; cmp. <span dir=\"rtl\">גזר</span>,] <i>to decree, decide, judge</i>. <span class=\"citation\">Ruth R. to I, 1</span> <span dir=\"rtl\">אוי לדור שׁשָׁפְטוּ … צריכין להִשָּׁפט</span> woe to the generation that judge (criticise) their judges, and woe to the generation whose judges need to be judged; <span class=\"citation\">B. Bath. 15ᵇ</span> (ref. to Ruth l. c.) <span dir=\"rtl\">דור שׁשׁוֹפֵט וכ׳</span> it was a generation that judged its judges &amp;c., v. <a href=\"#\" data-headword=\"קִיסָּם\">קִיסָּם</a>. <span class=\"citation\">Sot. 10ᵃ</span> <span dir=\"rtl\">זכור לי … שׁשָׁפַטְתִּי וכ׳</span> remember unto me the twenty (-two) years that I judged Israel, and never did I say to them, carry a stick for me from one place to another; a. fr.—V. <a href=\"#\" data-headword=\"שׁוֹפֵט\">שׁוֹפֵט</a>.</div><div class=\"sense\"><b>Nif. נִשְׁפַּט</b> <div class=\"sense\"><i>to be judged, criticised</i>. Ruth R. l. c., v. supra.</div></div>","alt":[]},"31979":{"h":"שֶׁפֶט","r":"U01731","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">שְׁפָטִים</span>(b. h.; <a href=\"#\" data-headword=\"שָׁפַט\">preced.</a>) <i>judgments, punishments</i>. Mekh. B’shall., Shir., s. 8 <span dir=\"rtl\">נעשו ש׳ בע&quot;ז</span> judgment was executed on the idols; a. e.</div>","alt":[]},"31980":{"h":"שִׁפְטָא","r":"U01732","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">שפט</span>; v. <a href=\"#\" data-headword=\"פַּטָּטָא\">פַּטָּטָא</a>, <a href=\"#\" data-headword=\"פַּיּוֹטוֹת\"><a href=\"#\" data-headword=\"פַּיּוֹטוֹת\">פַּיּוֹטוֹת</a>)</a><i>childish</i>. <span class=\"citation\">Targ. Y. II, Deut. XXXII, 6</span> Ar. (ed. <a href=\"#\" data-headword=\"טִפֵּשׁ ²\">טפשא</a>; h. text <a href=\"#\" data-headword=\"נָבָל I\">נבל</a>).</div>","alt":[]},"31981":{"h":"שֻׁפְטָנָא","r":"U01733","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שׁוּפְטָנָא\">שׁוּפְטָנָא</a></div>","alt":[]},"31982":{"h":"שפי","r":"U01734","html":"<div class=\"sense\"><b>1)</b> <i>to crush.</i> <i>—Part. pass</i>. <a href=\"#\" data-headword=\"שָׁפוּי\">שָׁפוּי</a>, pl. <span dir=\"rtl\">שְׁפוּיִין</span> <i>crushed, humble, contrite</i> (= b. h. <a href=\"#\" data-headword=\"דָּכָא\">דַּכָּא</a>). <span class=\"citation\">Tosef. Ḥag. II, 9</span> <span dir=\"rtl\">עניו וש׳</span> humble and contrite; <span class=\"citation\">Tosef. Snh. VII, 1</span> <span dir=\"rtl\">וש׳</span> (only); Y. ib. I, 19ᶜ. <span class=\"citation\">Gen. R. s. 60</span> דווין וש׳ Ar. (ed. <span dir=\"rtl\">ושפופין</span>) broken down and crushed (poor); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to rub, smooth, plane.</i> <i>—Part. pass</i>. as ab. <i>a</i>) <i>smooth</i>. <span class=\"citation\">Koh. R. to XII, 14</span> two paths <span dir=\"rtl\">אחד ש׳ ואחד מלא וכ׳</span> one smooth, and the other full of thorns and pebbles.—<span class=\"citation\">Yalk. Gen. 62</span> <span dir=\"rtl\">בור ש׳</span> (<span class=\"citation\">Snh. 109ᵃ</span> <a href=\"#\" data-headword=\"שָׁאפֵי\">שָׁאפֵי</a>; Ar. <a href=\"#\" data-headword=\"שָׁפַת\">שפת</a>, corr. acc.) a smooth (blank, empty) pit, v. <a href=\"#\" data-headword=\"בּוֹרְסִיף\">בּוֹרְסִיף</a>.—<i>b</i>) (cmp. <a href=\"#\" data-headword=\"חָלָק\">חָלָק</a>) <i>unimpaired, unscathed</i>. <span class=\"citation\">Gen. R. s. 45</span>, v. <a href=\"#\" data-headword=\"רָתַק\">רָתַק</a>.</div><div class=\"sense\"><b>Pi. שִׁפָּה  שִׁי׳</b> <div class=\"sense\"><b>1)</b> <i>to plane, saw, trim</i>. <span class=\"citation\">Ḥull. 125ᵃ</span> <span dir=\"rtl\">קולית שש׳ וכ׳</span> a thigh-bone which one sawed through lengthwise. <span class=\"citation\">Ab. Zar. 42ᵃ</span> <span dir=\"rtl\">ישראל שש׳ ע&quot;ז וכ׳</span> if an Israelite chipped off an idol whether for his own purpose (to use the wood) or for its sake (to improve its appearance). <span class=\"citation\">Ib. 49ᵇ</span>. Y. Gitt. V, 47ᵃ bot. <span dir=\"rtl\">גזלו ושִׁיפָּהוּ</span> if he took a block by force and planed it. <span class=\"citation\">Tosef. Kel. B. Mets. III, 1</span> <span dir=\"rtl\">שפת הימנה וכ׳</span> (read: <a href=\"#\" data-headword=\"שפי\">שפה</a>) if he filed off a part of it and made of it &amp;c.; a. e.—Part. pass. <span dir=\"rtl\">מְשׁוּפֶּה</span>; pl. <span dir=\"rtl\">מְשׁוּפִּים</span>, <span dir=\"rtl\">מְשׁוּפִּין</span>. Y. Gitt. l. c. <span dir=\"rtl\">גזלו מש׳</span> if he took it planed. Y. Succ. I, 52ᶜ top <span dir=\"rtl\">במש׳ לכלים</span> (not <span dir=\"rtl\">בכלים</span>) when the boards are planed preparatory to making them into utensils; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to smooth, polish</i>, <span class=\"citation\">Kel. XIV, 5</span> משׁיְשַׁפֶּנּוּ Ar.; <span class=\"citation\">Ned. 56ᵇ</span> <span dir=\"rtl\">משׁיְשַׁפֵּם</span>, v. <a href=\"#\" data-headword=\"שׁוּף II\"><span dir=\"rtl\">שׁוּף</span> II</a>.—Trnsf. <i>to pacify, give satisfaction</i>. Y. B. Mets. V, 10ᵇ <span dir=\"rtl\">המבטל … חייב לשַׁפּוֹת לו</span> if a tenant or an agent neglects his neighbor’s field, he must indemnify him; ib. IX, beg. 12ᵃ</div><div class=\"sense\"><b>—3)</b> <i>to leave smooth places</i>, (cmp. <a href=\"#\" data-headword=\"חָלַק\">חָלַק</a> <i>Hif.</i>) <i>to plant wide apart</i>. Y. Orl. I, beg. 60ᶜ <span dir=\"rtl\">לקורות במְשַׁפֶּה</span> (or <span dir=\"rtl\">במַשְׁפֶּה</span> <i>Hif.</i>) when he plants the trees wide apart, it is an indication that he wants to raise them for beams, opp. <a href=\"#\" data-headword=\"רָצַף\">רָצַף</a>. <span class=\"citation\">B. Bath. V, 4</span> <span dir=\"rtl\">הגדילו לא יְשַׁפֶּה</span> (or <a href=\"#\" data-headword=\"יָשְׁפֵּה\">יַשְׁפֶּה</a>) if they (the trees bought in a person’s field) grew large, he (the owner of the field) has no right to smooth the field (cut the trees down). Ib. <span dir=\"rtl\">הגדילו ישפה</span> when they are grown large, he (the owner of the trees) may cut them (in order to use the ground they occupy); a. e.</div></div>","alt":["שָׁפָה I"]},"31983":{"h":"שְׁפֵי","r":"U01735","html":"<div class=\"sense\"><b>1)</b> <i>to crush, rub, grind</i>. <span class=\"citation\">Targ. Ps. LVI, 2</span> (h. text <a href=\"#\" data-headword=\"שָׁאַף I\">שאף</a>). <span class=\"citation\">Ib. 3</span>.—Part. pass. <a href=\"#\" data-headword=\"שָׁאפֵי\">שָׁפֵי</a>; f. <span dir=\"rtl\">שַׁפְיָא</span>; pl. <span dir=\"rtl\">שַׁפְיָין</span>, <span dir=\"rtl\">שַׁפְיָן</span>. <span class=\"citation\">Ib. LI, 19</span> (h. text <span dir=\"rtl\">נדכה</span>). <span class=\"citation\">Targ. Job XXXIII, 21</span>.</div><div class=\"sense\"><b>—2)</b> <i>to plane, smooth, paste over</i>. <span class=\"citation\">Yeb. 75ᵇ</span> <span dir=\"rtl\">שַׁפְיֵיה וכ׳</span> he trimmed it (cut off the protuberances) like a writing reed. <span class=\"citation\">Sabb. 98ᵇ</span>, v. <a href=\"#\" data-headword=\"*טָרִיז\">טָרִיז</a> (v. <a href=\"#\" data-headword=\"שְׁחֵי II\"><span dir=\"rtl\">שְׁפֵי</span> II</a>). <span class=\"citation\">B. Kam. 98ᵃ</span> Ms. M., v. <a href=\"#\" data-headword=\"שׁוּף\">שׁוּף</a> II ch. <span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">שַׁפְיוּהָ דובשא וכ׳</span> they smeared her body with honey, and placed her on the roof &amp;c.; a. e.—<i>Part. pass</i>. as ab, <i>smooth, level</i>. <span class=\"citation\">Targ. Prov. XV, 19</span>. <span class=\"citation\">Targ. Y. Gen. XXXI, 2</span>; <span class=\"citation\">5</span> (<i>friendly</i>).—<span class=\"citation\">Snh. 109ᵃ</span> <span dir=\"rtl\">בור שָׁאפֵי</span>, v. <a href=\"#\" data-headword=\"שפי\">preced.</a></div><div class=\"sense\"><b>Pa. שַׁפֵּי</b> <div class=\"sense\"><b>1)</b> <i>to crush</i>. <span class=\"citation\">Targ. Esth. I, 10</span>. <span class=\"citation\">Targ. Ps. LI, 10</span> דשַׁפְּיֵיתָא Ms. (ed. Lag. <span dir=\"rtl\">דשיפייתא</span>, corr. acc.; ed. Wil. <span dir=\"rtl\">דשָׁפִיתָא</span> <i>Pe.</i>; h. text <span dir=\"rtl\">דכית</span>). <span class=\"citation\">Ib. LXXXIX, 11</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to plane, trim</i>.—Part. pass. <span dir=\"rtl\">מְשַׁפִּי</span>; f. <span dir=\"rtl\">מְשַׁפְּיָא</span>; pl. <span dir=\"rtl\">מְשַׁפְּיָין</span>, <span dir=\"rtl\">מְשַׁפְּיָן</span>. <span class=\"citation\">B. Bath. 3ᵃ</span> אבני דלא משפיין Ms. M. (ed. <span dir=\"rtl\">משפיא</span>, corr. acc.), v. <a href=\"#\" data-headword=\"גְּוִיל\">גְּוִיל</a>.</div></div>","alt":["שְׁפָא"]},"31984":{"h":"שפי ²","r":"U01736","html":"<div class=\"sense\"> (v.<a href=\"#\" data-headword=\"שָׁפַע\">שָׁפַע</a>) </div><div class=\"sense\"><b>1)</b> <i>to incline</i>, v. <a href=\"#\" data-headword=\"שִׁיפּוּי ²\"><span dir=\"rtl\">שִׁיפּוּי</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>to tilt, pour out slowly</i> (so as to leave the sediment behind). <span class=\"citation\">Midr. Till. to Ps. XVIII, 12</span> <span dir=\"rtl\">כדקים … שׁוֹפִין אלו באלו</span> ed. Bub. (oth. ed. <a href=\"#\" data-headword=\"שֹׁופְכִים\">שופכין</a>) as the small bowels of an animal that pour their contents from one to the other. <span class=\"citation\">Esth. R. to II, 3</span>; a. e.—Esp. <i>to sell wine</i>. <span class=\"citation\">B. Mets. 60ᵃ</span> השׁוֹפֶה יין לחמרים Ms. H. (v. Rabb. D. S. a. l. note 10; ed. <span dir=\"rtl\">לחבירו</span>; Ar. <span dir=\"rtl\">לשמרים</span>, corr. acc.) if one sells wine to ass-drivers (caravan at an inn); Tosef. ib. III, 27 <span dir=\"rtl\">היה שׁוֹפֵא וכ׳</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"שׁוֹפָה\">שופה</a>); a. e.</div><div class=\"sense\"><b>Pi. שִׁיפָּה</b> <div class=\"sense\"><i>to make slanting, whittle to a point</i>.—Part. pass. <span dir=\"rtl\">מְשׁוּפֶּה</span>; f. <span dir=\"rtl\">מְשׁוּפָּה</span>; pl. <span dir=\"rtl\">מְשׁוּפִּים</span>, <span dir=\"rtl\">מְשׁוּפִּין</span>; <span dir=\"rtl\">מְשׁוּפּוֹת</span>. <span class=\"citation\">Keth. 5ᵇ</span> <span dir=\"rtl\">מש׳ כיתדות</span> (the fingers) pointed like pegs.</div></div>","alt":["שָׁפָה II"]},"31985":{"h":"שְׁפֵי ²","r":"U01737","html":"<div class=\"sense\"><b>1)</b> <i>to incline, make slanting</i>. <span class=\"citation\">Sabb. 98ᵇ</span> <span dir=\"rtl\">דשָׁפֵי להו כי טורין</span> they made the boards slanting like mountain sides (bringing to a point; Ar. <a href=\"#\" data-headword=\"*טָרִיז\">טָרִיז</a> q. v.); Yalk. Ex. 370.</div><div class=\"sense\"><b>—2)</b> <i>to pour out slowly</i>. <span class=\"citation\">Ḥull. 67ᵃ</span> <span dir=\"rtl\">לא לִשְׁפֵּי וכ׳</span>, v. <a href=\"#\" data-headword=\"צִיבְּתָא\">צִיבְּתָא</a>. <span class=\"citation\">B. Kam. 115ᵇ</span> <span dir=\"rtl\">אפשר … וש׳ ליה</span> (not <span dir=\"rtl\">דש׳</span>) one may put something (a piece of cloth &amp;c.) over the mouth of a jug, and pour (strain) the liquid through. <span class=\"citation\">Sabb. 139ᵇ</span> שָׁפוּ שיכרא וכ׳ Rashi (ed. <span dir=\"rtl\">שָׁאפוּ</span>) they poured beer slowly from vessel to vessel (leaving the dregs behind); a. e.—<span class=\"citation\">Kidd. 71ᵇ</span> <span dir=\"rtl\">שָׁפֵי חלא</span> vinegar dealer, v. <a href=\"#\" data-headword=\"שָׁפֵיחָלָא\">שָׁפֵיחָלָא</a>.—Trnsf. <i>to let the blood flow after bloodletting</i>. <span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">דלמא ש׳ ליה וכ׳</span></div>","alt":["שְׁפָא"]},"31986":{"h":"שפי ³","r":"U01738","html":"<div class=\"sense\"> (v.<a href=\"#\" data-headword=\"שפי\"><span dir=\"rtl\">שָׁפָה</span> I</a>) [<i>to be smooth,</i>] <i>to be quiet, at ease; to be relieved</i>. <span class=\"citation\">Nidd. IV, 4</span> <span dir=\"rtl\">ושָׁפְתָה מעת לעת</span> and was relieved for a full day, opp. <span dir=\"rtl\">קשתה</span>, v. <a href=\"#\" data-headword=\"קָשָׁה\">קָשָׁה</a>. Ib. <span dir=\"rtl\">שפתה מן הצער וכ׳</span> she was relieved from pain, but not from the flux of blood; a. e.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"שָׁפוּי\">שָׁפוּי</a> <i>quiet, sane</i>. <span class=\"citation\">Arakh. 17ᵇ</span>, sq. <span dir=\"rtl\">ש׳ ונשתטה</span> if he was sane and became mad; <span class=\"citation\">B. Bath. 128ᵃ</span>.—V. <a href=\"#\" data-headword=\"שֹׁופִי II\"><span dir=\"rtl\">שׁוֹפִי</span> II</a>.</div><div class=\"sense\"><b>Hithpa. הִשְׁתַּפֶּה</b> </div><div class=\"sense\"><b>Nithpa. נִשְׁתַּפֶּה</b> <div class=\"sense\"> (of a delirious person) <i>to become quiet, conscious, sane</i>. <span class=\"citation\">B. Kam. IV, 4</span> <span dir=\"rtl\">נש׳ השוטה</span> if the madman became sane again; <span class=\"citation\">Tosef. ib. IV, 4</span>. Y. Ter. I, 40ᵇ bot. <span dir=\"rtl\">לכשׁיִשְׁתַּפֶּה</span> when he is sane again (we may write a letter of divorce at his order); Y. Gitt. VII, beg. 48ᶜ. Y. Keth. I, 25ᵇ; a. e.</div></div>","alt":["שָׁפָה III"]},"31987":{"h":"שְׁפֵי ³","r":"U01739","html":"<div class=\"sense\">, <i>to be quiet, at ease</i>.—V. <a href=\"#\" data-headword=\"שֶׁפִי\">שֶׁפִי</a>.</div><div class=\"sense\"><b>Pa. שַׁפֵּי</b> <div class=\"sense\"><i>to quiet, pacify, satisfy</i>. <span class=\"citation\">Gitt. 73ᵃ</span> <span dir=\"rtl\">זיל שַׁפֵּי ליה</span> go and pacify (settle with) him. <span class=\"citation\">B. Mets. 15ᵃ</span> <span dir=\"rtl\">ואֲשׁפֵּי וכ׳</span> (Ms. H. a. R. <span dir=\"rtl\">ואֵישַׁפֵּי</span>), v. <a href=\"#\" data-headword=\"מְרַק\">מְרַק</a>.—Part. pass. <span dir=\"rtl\">מְשַׁפֵּי</span>; pl. <span dir=\"rtl\">מְשַׁפָּן</span>. <span class=\"citation\">Ib. 70ᵃ</span> <span dir=\"rtl\">דמש׳ ניכסיה</span> (not <span dir=\"rtl\">דמשפו</span>) one whose property is at peace (undisputed by any claimants).</div></div>","alt":["שְׁפָא"]},"31988":{"h":"שֶׁפִי","r":"U01740","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁפֵי ³\">preced.</a>) <i>quiet, ease</i>. <span class=\"citation\">Targ. Y. II, Num. XXIII, 3</span>; <span class=\"citation\">Targ. Y. II, Gen. XXII, 8</span> <span dir=\"rtl\">בלב ש׳</span> with an easy heart.</div>","alt":[]},"31989":{"h":"שִׁפְיוּת","r":"U01741","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁיפְיוּת\">שִׁיפְיוּת</a></div>","alt":[]},"31990":{"h":"שְׁפִיּוּתָא","r":"U01742","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שִׁפְיוּת\">preced.</a>) <i>compromise, peace</i>. <span class=\"citation\">Targ. Y. I Gen. III, 15</span> (Y. II <a href=\"#\" data-headword=\"שְׁפוּיָיתָא\">שְׁפוּיָיתָא</a>).</div>","alt":[]},"31991":{"h":"שָׁפֵיחָלָא","r":"U01743","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"שַׁרְיֵי\">בֵּי שָׁ׳</a> <i>the family of Shafekala</i> (vinegar dealer). <span class=\"citation\">Kidd. 71ᵇ</span> Ar. (ed. <span dir=\"rtl\">בי בר שפי חלא</span>, v. <a href=\"#\" data-headword=\"שְׁחֵי II\"><span dir=\"rtl\">שְׁפֵי</span> II</a>).</div>","alt":[]},"31992":{"h":"שְׁפִיטָה","r":"U01744","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁפַט\">שָׁפַט</a>) <i>judging, judgeship</i>. <span class=\"citation\">Snh. 3ᵇ</span> (ref. to <span class=\"citation\">Num. XXXV, 24</span> sq.) <span dir=\"rtl\">משעת שְׁפִיטַת העדה</span> from the time that the assembly meets for judging (from the beginning of the legal proceedings, the court consists of twenty-three). <span class=\"citation\">Num. R. s. 14</span><sup>9</sup> <span dir=\"rtl\">על שפיטת שמשון</span> the verse (<span class=\"citation\">Gen. XLIX, 16</span>) refers to Samson’s judgeship.</div>","alt":[]},"31993":{"h":"שַׁפַּיי","r":"U01745","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (שְׁפֵי II) <i>wine merchant.</i> <i>—</i> Pl. <span dir=\"rtl\">שַׁפָּיִין</span>, <a href=\"#\" data-headword=\"שְׁפָאִים\">שַׁפָּאִין</a>, <span dir=\"rtl\">שַׁפָּיֵיא</span>. <span class=\"citation\">Lev. R. s. 12</span> <span dir=\"rtl\">עברון ש׳ בתרע וכ׳</span> wine merchants passed the gate of the cemetery; <span class=\"citation\">Esth. R. to II, 1</span> <span dir=\"rtl\">(<span dir=\"rtl\">ר׳ עזריה</span>) <span dir=\"rtl\">ש׳ שנאון</span></span> (strike out <a href=\"#\" data-headword=\"שנאון\">שנאון</a>, a corrupt dittogr. of <a href=\"#\" data-headword=\"שְׁפָאִים\">שפאין</a>); <span class=\"citation\">Yalk. Prov. 960</span>. <span class=\"citation\">Y. Dem. V, 24ᵈ</span> <span dir=\"rtl\">ברם באילין ש׳ וכ׳</span> but as to wine dealers, they are used to empty from vessel to vessel. <span class=\"citation\">Y. Shek. VII, 50ᶜ</span> bot., v. <a href=\"#\" data-headword=\"חֲכַם\">חֲכַם</a>.</div>","alt":["שַׁפַּאי"]},"31994":{"h":"שְׁפֵיךְ","r":"U01746","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁפַךְ\">שְׁפַךְ</a></div>","alt":[]},"31995":{"h":"שְׁפִיךְ","r":"U01747","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁפוֹךְ\">שָׁפוֹךְ</a></div>","alt":[]},"31996":{"h":"שְׁפִיכָא","r":"U01748","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">שְׁפִיכֵי</span>, v. <a href=\"#\" data-headword=\"שָׁפְכָא\">שָׁפְכָא</a>.</div>","alt":[]},"31997":{"h":"שְׁפִיכָה","r":"U01749","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁפַךְ\">שָׁפַךְ</a>) <i>pouring out</i>. <span class=\"citation\">T’bul Yom IV, 7</span>, v. <a href=\"#\" data-headword=\"שֶׁבֶר I\"><span dir=\"rtl\">שֶׁבֶר</span> I</a>. <span class=\"citation\">Y. Pes. I, end, 28ᵇ</span> (ref. to <span class=\"citation\">Deut. XII, 24</span>) <span dir=\"rtl\">לא … אלא בש׳</span> I have allowed thee no other use of its blood than pouring it out (but you must not bleed a consecrated animal). <span class=\"citation\">Y. Yoma V, 43ᵃ</span> top (ref. to <span class=\"citation\">Lev. IV, 7</span>) <span dir=\"rtl\">לרבות … לש׳</span> this includes the blood of the bullock for the Day of Atonement, that it must be poured out (at the bottom of the altar); a. fr.—Pl. <a href=\"#\" data-headword=\"שְׁפִיכוּת\">שְׁפִיכוֹת</a>. <span class=\"citation\">Lam. R. to IV, 11</span> <span dir=\"rtl\">ארבע ש׳ לטובה וכ׳</span> four times is pouring out mentioned for good, and four times for evil.</div>","alt":[]},"31998":{"h":"שְׁפִיכוּת","r":"U01750","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שְׁפִיכָה\">same</a>. <span class=\"citation\">Makhsh. II, 3</span> <span dir=\"rtl\">מי ש׳</span> water that is poured out, dirty water, opp. <span dir=\"rtl\">מי גשמים</span> rain water.—Esp. <span dir=\"rtl\">ש׳ דמים</span> <i>shedding of blood</i>. <span class=\"citation\">Arakh. 15ᵇ</span> <span dir=\"rtl\">כל המספר … וש׳ ד׳</span> he that talks slander commits great sins to be compared to the three great crimes: idolatry, incest, and bloodshed. <span class=\"citation\">Snh. 57ᵇ</span> (ref. to <span class=\"citation\">Gen. IX, 6</span>) <span dir=\"rtl\">איזהו ש׳ ד׳ של אדם שהוא בגופו וכ׳</span> what way of killing is a shedding of blood within a man’s body? It is strangulation. Ib. 74ᵃ <span dir=\"rtl\">כל … חוץ … וש׳ ד׳</span> regarding all sins … one may transgress in order to escape death, except idolatry, incest, and murder; a. fr.</div>","alt":[]},"31999":{"h":"שְׁפִיכוּתָא","r":"U01751","html":"<div class=\"sense\"> ch., constr. <a href=\"#\" data-headword=\"שְׁפִיכוּת\">שְׁפִיכוּת</a>, same. <span class=\"citation\">Targ. Y. II, Lev. I, 16</span>. <span class=\"citation\">Targ. Y. II, Deut. III, 17</span> <span dir=\"rtl\">ש׳ קיטמא</span> (read <span dir=\"rtl\">מיא</span>), v. <a href=\"#\" data-headword=\"שִׁפְכוּתָא\">שִׁפְכוּתָא</a>. <span class=\"citation\">Targ. Y. Gen. XXVIII, 20</span> (not <a href=\"#\" data-headword=\"שְׁפִיכוּת\">שְׁפִיכוֹת</a>).—<span class=\"citation\">B. Bath. 25ᵇ</span> <a href=\"#\" data-headword=\"בֹּוסַם\">בש׳</a> when the rain comes pouring, opp. <span dir=\"rtl\">בניחותא</span> gently.</div>","alt":[]}};
